int add_network_stat(int network_id, long timestamp, const char *event_data[]) {
    int i = 0;
    while (i < MAX_EVENTS && event_data[i]) {
        NetworkStats *stats = malloc(sizeof(NetworkStats));
        stats->network_id = network_id;
        stats->timestamp = timestamp;
        stats->event_data[i] = strdup(event_data[i]);
        network_stats[network_id % MAX_NETWORKS] = stats;
        i++;
    }
    return i;
}

int get_network_stat(int network_id, long start_timestamp, long end_timestamp) {
    NetworkStats *stats = network_stats[network_id % MAX_NETWORKS];
    while (stats && stats->timestamp < start_timestamp) {
        free(stats);
        stats = network_stats[network_id % MAX_NETWORKS];
    }
    while (stats && stats->timestamp >= end_timestamp) {
        free(stats);
        stats = network_stats[network_id % MAX_NETWORKS];
    }
    return 0;
}

