    pthread_create(&thread, NULL, parse_raw_data, NULL);
    pthread_join(thread, NULL);

    for (int i = 0; i < MAX_NETWORKS; i++) {
        free(network_stats[i]->event_data[0]);
        free(network_stats[i]);
    }

    return 0;
