#include <pthread.h>

typedef struct {
    int key;
} record;

record *records = NULL;
long *offsets = NULL;
int *keys = NULL;

void *init_data_processing_pipeline() {
    // Allocate memory for arrays
    records = (record *)malloc(512 * sizeof(record));
    offsets = (long *)malloc(1024 * sizeof(long));
    keys = (int *)malloc(1024 * sizeof(int));

    if (!records || !offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(-1);
    }
}

void populate_records() {
    int i;
    for (i = 0; i < 512; i++) {
        records[i].key = rand() % 90 + 10;
    }
}

void sort_records() {
    qsort(records, 512, sizeof(record), compare_records);
}

int compare_records(const void *a, const void *b) {
    record *record_a = (record *)a;
    record *record_b = (record *)b;

    return record_a->key - record_b->key;
}

void cleanup() {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}

int main() {
    pthread_t thread[2];

    // Create threads
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&thread[i], NULL, &init_data_processing_pipeline, NULL)) {
            fprintf(stderr, "Thread creation failed.\n");
            exit(-1);
        }
    }

    // Wait for threads to finish
    for (int i = 0; i < 2; i++) {
        pthread_join(thread[i], NULL);
    }

    populate_records();
    sort_records();

    cleanup();

    return 0;
}
