#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16
#define MAX_LINE_LENGTH 1024
#define MAX_FILE_SIZE 1000000

int g_max_dns_retries = 3;
int g_dns_retry_timeout = 1; // seconds
FILE *g_log_file;

struct dns_query {
    char hostname[MAX_HOSTNAME];
    char ip_address[MAX_IP_ADDRESS];
};

void* dns_resolve(void* data) {
    struct sockaddr_in* addr = (struct sockaddr_in*)data;
    struct hostent* host = gethostbyaddr(addr->sin_addr.s_addr, sizeof(struct in_addr), 0);
    if (!host) {
        return NULL;
    }
    char ip_address[MAX_IP_ADDRESS];
    inet_ntop(AF_INET, &host->h_addr_list[0], ip_address, MAX_IP_ADDRESS);
    sprintf(((struct dns_query*)data)->ip_address, "%s", ip_address);
    freeaddrinfo(host);
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    g_log_file = fopen("log.txt", "w");
    if (!g_log_file) {
        perror("Error creating log file");
        fclose(file);
        return 2;
    }

    pthread_t threads[100];
    int i = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char* token = strtok(line, ",");
        if (!token) {
            continue;
        }
        struct dns_query* query = (struct dns_query*)malloc(sizeof(struct dns_query));
        strcpy(query->hostname, token);

        // Perform DNS resolution
        for (int retry = 0; retry < g_max_dns_retries; ++retry) {
            struct sockaddr_in addr;
            addr.sin_family = AF_INET;
            inet_pton(AF_INET, "8.8.8.8", &addr.sin_addr);
            pthread_create(&threads[i], NULL, dns_resolve, &addr);
            pthread_join(threads[i], NULL);
            // Handle DNS resolution failure or timeout
            if (/* check for error */) {
                if (retry < g_max_dns_retries - 1) {
                    sleep(g_dns_retry_timeout);
                    continue;
                }
                free(query);
                break;
            }
            ++i;

            token = strtok(NULL, ",");
            if (!token) {
                break;
            }
            int num = atoi(token);
            double average = (num + atof(token)) / 2.0;
            fprintf(g_log_file, "%f,", average);

            free(query);
        }
    }

    fclose(file);
    fclose(g_log_file);

    return 0;
}
