#define MAX_INTS 10000
#define INT_SIZE sizeof(int)

void read_integers(int *max_ints) {
    int i, n;
    printf("Enter the maximum number of integers (up to %d): ", MAX_INTS);
    scanf("%d", &n);

    if (n > *max_ints || n < 0) {
        printf("Invalid input. Maximum number should be between 1 and %d.\n", *max_ints);
        return;
    }

    int *arr = (int *) malloc(n * INT_SIZE);
    if (!arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    for (i = 0; i < n; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &arr[i]);
    }

    free(arr);
}

void find_largest(int *arr, int n) {
    if (!arr || n == 0) {
        printf("Empty list.\n");
        return;
    }

    int largest = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    printf("The largest integer is: %d\n", largest);
}

int main() {
    read_integers(&MAX_INTS);
    return 0;
}
