#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

#define MAX_LOG_FILE_SIZE (10 * 1024 * 1024)
#define MAX_NUM_LOG_FILES 30
#define LOG_DIR "/path/to/logs"

typedef struct {
    char filename[64];
    FILE* file;
    size_t size;
} LogFile;

void rotate_logs() {
    int num_files = 0, total_size = 0;
    LogFile files[MAX_NUM_LOG_FILES];

    DIR* dir = opendir(LOG_DIR);
    if (dir) {
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            char path[128];
            sprintf(path, "%s/%s", LOG_DIR, ent->d_name);

            LogFile* file = &files[num_files++];
            strcpy(file->filename, ent->d_name);
            file->file = fopen(path, "a");
            total_size += file->size;
        }
        closedir(dir);

        if (total_size > MAX_LOG_FILE_SIZE) {
            for (int i = 0; i < num_files; ++i) {
                LogFile* file = &files[i];
                if (file->size > MAX_LOG_FILE_SIZE) {
                    fclose(file->file);
                    file->file = fopen(path, "w");
                }
            }
        }

        for (int i = 0; i < num_files; ++i) {
            LogFile* file = &files[i];
            fclose(file->file);
            free(file);
        }
    }
}

void manage_log_file(LogFile* file, char* message) {
    size_t new_size = strlen(message) + 1;
    fwrite(&new_size, sizeof(size_t), 1, file->file);
    fwrite(message, 1, new_size, file->file);
    fflush(file->file);

    if (file->size + new_size > MAX_LOG_FILE_SIZE) {
        rotate_logs();
    }

    file->size += new_size;
}

int main() {
    // Initialize log files
    LogFile files[MAX_NUM_LOG_FILES];
    for (int i = 0; i < MAX_NUM_LOG_FILES; ++i) {
        char path[128];
        sprintf(path, "%s/log_%d.log", LOG_DIR, i);
        LogFile* file = &files[i];
        strcpy(file->filename, "log_0.log");
        file->file = fopen(path, "w");
        file->size = 0;
    }

    // Simulate log entries
    for (int i = 0; i < 100; ++i) {
        char message[1024];
        sprintf(message, "Log entry %d", i);
        manage_log_file(&files[i % MAX_NUM_LOG_FILES], message);
    }

    return 0;
}

