#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <cryptography/aes.h>

// Define a struct to hold the cipher context
typedef struct {
    int mode;
    unsigned char* key;
    size_t key_len;
} CipherContext;

// Function prototypes
CipherContext* cipher_init(int mode, const unsigned char* key, size_t key_len);
int cipher_set_iv(CipherContext* ctx, const unsigned char* iv);
int cipher_encrypt(CipherContext* ctx, const unsigned char* plaintext, unsigned char** ciphertext);
int cipher_decrypt(CipherContext* ctx, const unsigned char* ciphertext, unsigned char** plaintext);

// Define the callback function for user-defined modes
typedef int (*cipher_mode_callback)(CipherContext*, const unsigned char*, unsigned char**, const unsigned char*);

// Function to initialize and manage cipher contexts
CipherContext* cipher_init(int mode, const unsigned char* key, size_t key_len) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->mode = mode;
    ctx->key = key;
    ctx->key_len = key_len;

    // Initialize the AES context based on the selected cipher mode
    switch (ctx->mode) {
        case 0: // ECB mode
            aes_ecb_init(ctx);
            break;
        case 1: // CBC mode
            aes_cbc_init(ctx);
            break;
        case 2: // GCM mode
            aes_gcm_init(ctx);
            break;
        default:
            // User-defined mode, call the callback function
            ctx->mode_callback = (cipher_mode_callback)malloc(sizeof(*ctx->mode_callback));
            *ctx->mode_callback = key;
            break;
    }

    return ctx;
}

// Set the initialization vector for the cipher context
int cipher_set_iv(CipherContext* ctx, const unsigned char* iv) {
    // Implement IV setting logic based on the selected cipher mode
    switch (ctx->mode) {
        case 0: // ECB mode, no IV needed
            return 0;
        case 1: // CBC mode, set the IV
            aes_cbc_set_iv(ctx, iv);
            break;
        case 2: // GCM mode, set the IV and nonce
            aes_gcm_set_iv_nonce(ctx, iv);
            break;
        default:
            // User-defined mode, callback function handles IV setting
            return ctx->mode_callback(ctx, iv, NULL, NULL);
    }
}

// Perform encryption using the selected cipher context
int cipher_encrypt(CipherContext* ctx, const unsigned char* plaintext, unsigned char** ciphertext) {
    // Implement encryption logic based on the selected cipher mode
    switch (ctx->mode) {
        case 0: // ECB mode, perform AES-ECB encryption
            return aes_ecb_encrypt(ctx, plaintext, ciphertext);
        case 1: // CBC mode, perform AES-CBC encryption
            return aes_cbc_encrypt(ctx, plaintext, ciphertext);
        case 2: // GCM mode, perform AES-GCM encryption
            return aes_gcm_encrypt(ctx, plaintext, ciphertext);
        default:
            // User-defined mode, callback function handles encryption
            return ctx->mode_callback(ctx, plaintext, ciphertext, NULL);
    }
}

// Perform decryption using the selected cipher context
int cipher_decrypt(CipherContext* ctx, const unsigned char* ciphertext, unsigned char** plaintext) {
    // Implement decryption logic based on the selected cipher mode
    switch (ctx->mode) {
        case 0: // ECB mode, perform AES-ECB decryption
            return aes_ecb_decrypt(ctx, ciphertext, plaintext);
        case 1: // CBC mode, perform AES-CBC decryption
            return aes_cbc_decrypt(ctx, ciphertext, plaintext);
        case 2: // GCM mode, perform AES-GCM decryption
            return aes_gcm_decrypt(ctx, ciphertext, plaintext);
        default:
            // User-defined mode, callback function handles decryption
            return ctx->mode_callback(ctx, ciphertext, plaintext, NULL);
    }
}

// Clean up cipher context and free allocated memory
void cipher_free(CipherContext* ctx) {
    if (ctx == NULL)
        return;

    switch (ctx->mode) {
        case 0: // ECB mode
            aes_ecb_free(ctx);
            break;
        case 1: // CBC mode
            aes_cbc_free(ctx);
            break;
        case 2: // GCM mode
            aes_gcm_free(ctx);
            break;
        default:
            // User-defined mode, callback function handles cleanup
            ctx->mode_callback(ctx, NULL, NULL, NULL);
    }

    free(ctx);
}
