import json
import os
import secrets
from pathlib import Path
import logging

logging.basicConfig(level=logging.INFO)

def generate_config_file(template_file, region_configs):
    try:
        with open(template_file, 'r') as f:
            template_content = f.read()

        for region, config in region_configs.items():
            new_content = template_content.replace('<REGION>', region)
            new_content = new_content.replace('<API_KEY>', secrets.token_hex(16))
            for key, value in config.items():
                new_content = new_content.replace(f'<{key}>', str(value))

            with open(f'{region}.config.json', 'w') as f:
                f.write(new_content)

        logging.info('Configuration files generated successfully')

    except Exception as e:
        logging.error(f'Error generating configuration file: {str(e)}')

if __name__ == '__main__':
    template_file = 'template.config.json'
    region_configs = {
        'us-east-1': {'bucket_name': 'my-bucket', 'database_url': 'jdbc:mysql://localhost'},
        'eu-central-1': {'bucket_name': 'my-other-bucket', 'database_url': 'jdbc:postgresql://example.com'}
    }

    generate_config_file(template_file, region_configs)
