// Function to process files according to specified cryptographic operations
int process_file(const char *file_path, const char *operation) {
    // Validate file path and perform necessary checks
    if (!validate_file_path(file_path)) {
        return -1;  // Return error code with detailed feedback
    }

    FILE *file = fopen(file_path, "rb+");
    if (file == NULL) {
        return -2;  // File not found or inaccessible
    }

    size_t file_size;
    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    rewind(file);

    // Load file contents into memory (or stream/paginate for large files)
    char *file_contents = malloc(file_size + 1);
    fread(file_contents, 1, file_size, file);
    fclose(file);

    // Perform cryptographic operation using OpenSSL library
    if (strcmp(operation, "AES-encrypt") == 0) {
        AES_encrypt(file_contents, file_size);
    } else if (strcmp(operation, "AES-decrypt") == 0) {
        AES_decrypt(file_contents, file_size);
    } else if (strcmp(operation, "SHA-256-hash") == 0) {
        SHA_256_hash(file_contents, file_size);
    } else {
        return -3;  // Invalid operation specified
    }

    free(file_contents);

    // Log operation result and details
    log_operation_result(operation);

    return 0;
}

