#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t* semaphores;
    int num_semaphores;
} semaphore_pool;

semaphore_pool* create_semaphore_pool(int num_semaphores) {
    semaphore_pool* pool = malloc(sizeof(semaphore_pool));
    if (!pool) return NULL;

    pool->num_semaphores = num_semaphores;
    pool->semaphores = malloc(num_semaphores * sizeof(sem_t));
    if (!pool->semaphores) {
        free(pool);
        return NULL;
    }

    for (int i = 0; i < num_semaphores; i++) {
        sem_init(&pool->semaphores[i], 1, 0);
    }

    return pool;
}

void release_semaphore(semaphore_pool* pool, int index) {
    sem_post(&pool->semaphores[index]);
}

int acquire_semaphore(semaphore_pool* pool, int index) {
    return sem_wait(&pool->semaphores[index]);
}

void destroy_semaphore_pool(semaphore_pool* pool) {
    for (int i = 0; i < pool->num_semaphores; i++) {
        sem_destroy(&pool->semaphores[i]);
    }
    free(pool->semaphores);
    free(pool);
}
