#include <forward_list>
void insertAndMaintain(std::forward_list<int>& list, int target, int value, size_t capacity = 0) {
    auto it = list.begin();
    while (it != list.end() && *it != target) {
        ++it;
    }
    if (it == list.end()) {
        list.push_back(value);
    } else {
        list.insert_after(it, value);
    }
    if (capacity > 0 && list.size() > capacity) {
        list.pop_front();
    }
}
