#include <boost/log.hpp>
#include <boost/log/utility/setup/file.hpp>
#include <boost/log/utility/setup/console.hpp>

namespace logging = boost::log;

// Define a custom log format with timestamp, module name, and message
struct CustomLogFormat : public logging::record_ostream {
    template<typename T>
    void operator<<(T const& val) const {
        *this << "[" << logging::get_timepoint().format("%Y-%m-%dT%H:%M:%S.%N%Z") << "] "
             << "[" << logging::current_thread().name() << "] "
             << "Module: [" << logging::current_module().name() << "] "
             << val;
    }
};

// Define a custom log severity with levels for debug, info, warning, and error
enum class LogSeverity {
    Debug,
    Info,
    Warning,
    Error
};

// Define a logging configuration with multiple output targets
struct LoggingConfig {
    std::string console_target = "console";
    std::string file_target = "logs/app.log";

    int min_level = static_cast<int>(LogSeverity::Info);
    bool enable_file_logging = true;
};

// Create a logging factory to manage configurations and outputs
class LoggingFactory {
public:
    LoggingFactory(const LoggingConfig& config)
        : config_(config) {
        // Initialize the logging framework with the given configuration
        boost::log::add_common_attributes();
        boost::log::core::get()->set_filter(boost::log::expressions::satisfies(
            [this](const boost::log::record & rec) {
                return rec.level() >= config_.min_level;
            }));

        // Add console and file targets
        add_target(boost::log::add_console_log(std::cout, boost::log::keywords::format = CustomLogFormat()));
        if (config_.enable_file_logging) {
            add_target(boost::log::add_file_log(
                config_.file_target,
                boost::log::keywords::rotation_size = 1048576,
                boost::log::keywords::auto_flush = true,
                boost::log::keywords::format = CustomLogFormat()
            ));
        }
    }

    // Get the logging core instance
    boost::log::core& get_core() { return boost::log::core::get(); }

private:
    LoggingConfig config_;
};

// Define a logging interface for modules to use
class ILogger {
public:
    virtual void log(LogSeverity severity, const std::string& message) = 0;
};

// Implement a module-specific logger using the LoggingFactory
class MyModuleLogger : public ILogger {
public:
    MyModuleLogger(const LoggingConfig& config)
        : factory_(new LoggingFactory(config)) {}

    ~MyModuleLogger() { delete factory_; }

    void log(LogSeverity severity, const std::string& message) override {
        factory_->get_core().log(boost::log::keywords::severity = severity, message);
    }

private:
    LoggingFactory* factory_;
};
