using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class DatabaseProcessor
{
    public async Task<List<Dictionary<string, object>>> ProcessDatabaseAsync(string tableName, List<string> columnsToSelect, string connectionString, CacheConfiguration? cacheConfig = null)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();

            SqlCommand command = new SqlCommand($"SELECT {string.Join(", ", columnsToSelect)} FROM {tableName}", connection);
            SqlDataReader reader = await command.ExecuteReaderAsync();

            List<Dictionary<string, object>> rows = new List<Dictionary<string, object>>();

            while (await reader.ReadAsync())
            {
                Dictionary<string, object> row = new Dictionary<string, object>();

                for (int i = 0; i < columnsToSelect.Count; i++)
                {
                    string columnName = columnsToSelect[i];
                    object value = reader[columnName];

                    row.Add(columnName, value);
                }

                rows.Add(row);
            }

            reader.Close();

            if (cacheConfig.HasValue)
            {
                // Implement caching mechanism with expiration and eviction policies
                using (MemoryCache cache = new MemoryCache())
                {
                    await cache.Set(tableName, rows, TimeSpan.FromDays(1), CacheEvictionPolicy.OnChange);
                }
            }

            return rows;
        }
    }
}

public class CacheConfiguration
{
    public TimeSpan ExpirationTime { get; set; } = TimeSpan.FromDays(1);
    public CacheEvictionPolicy EvictionPolicy { get; set; } = CacheEvictionPolicy.OnChange;

    public enum CacheEvictionPolicy
    {
        OnChange,
        EveryMinute,
        EveryHour
    }
}
