    public string Path { get; set; }
    public int RotationSizeMb { get; set; }
    public int RotationCount { get; set; }
}

public class LoggerService : ILogger
{
    private readonly LogConfiguration _logConfig;
    private readonly List<LogDestination> _destinations;

    public LoggerService(LogConfiguration logConfig)
    {
        _logConfig = logConfig;
        _destinations = logConfig.Destinations;
    }

    public void Log<TState>(LogLevel logLevel, EventId eventId, TState state, Exception exception, Func<TState, Exception, string> formatter)
    {
        var message = formatter(state, exception);

        foreach (var destination in _destinations)
        {
            switch (destination.Type)
            {
                case DestinationType.Console:
                    Console.WriteLine($"[{logLevel}] {message}");
                    break;
                case DestinationType.File:
                    FileLogger.Log(message, logLevel);
                    break;
                case DestinationType.Database:
                    DbLogger.Log(message, logLevel);
                    break;
            }
        }
    }

