    {
        var filename = $"{DateTime.Now:yyyy-MM-dd_HH-mm-ss}_{logLevel.ToString()}.log";
        var filepath = Path.Combine(GetLogFilePath(), filename);

        using (var fileStream = File.Create(filepath))
        {
            using (var streamWriter = new StreamWriter(fileStream))
            {
                streamWriter.WriteLine(message);
            }
        }

        RotateLogs();
    }

    private static string GetLogFilePath()
    {
        // Implement your own logic to determine the log file path
        return Environment.GetEnvironmentVariable("LOG_FILE_PATH");
    }

    public static void RotateLogs()
    {
        // Implement your own logic to rotate logs based on size and count
        // For this example, just simulate rotation by deleting old files
        var directoryInfo = new DirectoryInfo(GetLogFilePath());
        foreach (var file in directoryInfo.GetFiles())
        {
            if (file.Length > _logConfig.RotationSizeMb * 1024 * 1024)
            {
                file.Delete();
            }
            else if (directoryInfo.GetFiles().Count() >= _logConfig.RotationCount)
            {
                file.Delete();
            }
        }
    }

    public static void Log(string message, LogLevel logLevel) { } // Not implemented for this example
}

public class DbLogger : ILogger
{
    public void Log(string message, LogLevel logLevel) { } // Not implemented for this example
