using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Xml;

public static class XmlConfigParser
{
    public static void ParseXmlConfig(string xmlFilepath, string tagName)
    {
        XmlDocument xmlDoc = new XmlDocument();
        try
        {
            xmlDoc.Load(xmlFilepath);
            XmlElement root = xmlDoc.DocumentElement;
            XmlNodeList nodes = root.SelectNodes($"//{tagName}");
            if (nodes == null || nodes.Count != 1)
                throw new Exception($"Tag '{tagName}' not found or found more than once in the XML file");

            string dirPath = Environment.GetEnvironmentVariable(tagName);
            if (!string.IsNullOrEmpty(dirPath) && Directory.Exists(dirPath))
                dirPath = dirPath;
            else
            {
                dirPath = Path.Combine(Path.GetTempPath(), tagName);
                try
                {
                    Directory.CreateDirectory(dirPath);
                }
                catch (Exception ex)
                {
                    throw new Exception($"Failed to create directory '{tagName}' with error: {ex.Message}");
                }

                Environment.SetEnvironmentVariable(tagName, dirPath);
            }

            // Log the result
            Console.WriteLine($"Parsed XML config and created directory '{dirPath}'");
        }
        catch (XmlException ex)
        {
            throw new Exception("Invalid XML structure", ex);
        }
    }
}
