    private readonly ICacheManager _cacheManager;

    public UpdateElementController(IPageService pageService, ICacheManager cacheManager)
    {
        _pageService = pageService;
        _cacheManager = cacheManager;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement([FromBody]UpdateElementRequest request)
    {
        if (!ValidateRequest(request))
        {
            return BadRequest("Invalid request");
        }

        await UpdateElementInternal(request.PageSectionId, request.ElementId, request.HtmlContent);

        return Ok();
    }

    private bool ValidateRequest(UpdateElementRequest request)
    {
        // validate page section ID and element ID lengths
        if (request.PageSectionId.Length > 255 || request.ElementId.Length > 255)
        {
            return false;
        }

        // validate HTML content format
        if (!new HtmlAgilityPack.HtmlDocument(request.HtmlContent).IsValid())
        {
            return false;
        }

        return true;
    }

    private async Task UpdateElementInternal(string pageSectionId, string elementId, string htmlContent)
    {
        var exists = await _pageService.ElementExists(pageSectionId, elementId);

        if (!exists)
        {
            // handle non-existent element
            return;
        }

        await _pageService.UpdateElementHtmlContent(pageSectionId, elementId, htmlContent);

        // log change
        await LogChangeAsync(pageSectionId, elementId, htmlContent);
    }

    private async Task LogChangeAsync(string pageSectionId, string elementId, string htmlContent)
    {
        // implement logging mechanism
        await Task.Delay(0); // simulate logging time
    }
}

