async function readFiles(directory, extension, fileSizeFilter = null, lastModifiedFilter = null, {
  concurrency = 10,
  timeout = 30000
} = {}) {
  const files = [];
  const fs = require('fs').promises;
  const regex = new RegExp(extension.replace('.', '') + '$', 'i');

  async function readFile(file) {
    try {
      const stats = await fs.stat(file);
      if (fileSizeFilter && fileSizeFilter(stats.size)) return;
      if (lastModifiedFilter && !lastModifiedFilter(stats.mtime)) return;

      const content = await fs.readFile(file, 'utf8');
      files.push({ path: file, size: stats.size, content });
    } catch (error) {
      // retry on transient failures
      if (error.code === 'ENOENT' || error.code === 'EBUSY') {
        setTimeout(() => readFiles([file], regex, fileSizeFilter, lastModifiedFilter, { concurrency, timeout }), timeout);
      }
    }
  }

  const filePromises = [];
  try {
    await fs.readdir(directory).forEach(file => {
      if (regex.test(file)) {
        filePromises.push(readFile(`${directory}/${file}`));
      }
    });
  } catch (error) {
    // handle errors
  }

  await Promise.all(filePromises);
  return files;
}
