const require = require('require');
const blueslip = require('blueslip');
const monitoringService = require('monitoring-service');

function testModule(moduleName, tests) {
  let attempts = 0;
  const maxAttempts = 3;

  function runTest(test) {
    console.log(`Testing ${moduleName} - ${test.name}`);
    const startTime = Date.now();

    try {
      module.exports = require(moduleName);
      blueslip.reset();
      test();
      console.log(`Test ${test.name} passed in ${Date.now() - startTime}ms`);
    } catch (error) {
      attempts++;
      if (attempts <= maxAttempts) {
        console.error(`Test ${test.name} failed after ${attempts} attempt(s). Retrying...`);
        setTimeout(() => runTest(test), Math.pow(2, attempts));
      } else {
        console.error(`Test ${test.name} failed after 3 attempts. Aborting.`);
      }
    } finally {
      monitoringService.report({
        moduleName,
        test: test.name,
        outcome: attempts <= maxAttempts ? 'passed' : 'failed',
        health: blueslip.getHealth(),
      });
    }
  }

  tests.forEach((test) => runTest(test));
}

module.exports = testModule;
