function renderFooterScripts(scripts) {
  const sanitizedScripts = scripts.map(script => {
    if (!script.key || !script.innerHTML) {
      throw new Error('Invalid script object');
    }
    return `<script src="${script.key}" defer>${script.innerHTML}</script>`;
  });

  let renderedHTML = '';
  for (const script of sanitizedScripts.slice(0, Math.min(sanitizedScripts.length, 10))) {
    renderedHTML += script;
  }

  if (sanitizedScripts.length > 10) {
    console.warn(`Warning: Excess scripts detected (${sanitizedScripts.length - 10}). Only rendering up to 10.`);
  }

  return renderedHTML;
}
