class BinaryDataHandler {
  constructor(bufferSize = 1024 * 1024) {
    this.buffer = Buffer.alloc(0);
    this.maxLength = bufferSize;
    this.throttleRate = 100; // in milliseconds
    this.inProgress = false;
    this.fallbackMode = false;
  }

  async handleStream(stream) {
    try {
      const streamLength = await getLength(stream);
      if (this.inProgress && this.buffer.length + streamLength > this.maxLength) {
        await flush();
      }
      this.inProgress = true;

      for await (const chunk of stream) {
        if (this.fallbackMode) {
          // fallback strategy implementation
          break;
        }

        if (!this.inProgress) {
          throw new Error('Stream interrupted');
        }

        const bufferOffset = this.buffer.length;
        this.buffer = Buffer.concat([this.buffer, chunk]);

        if (this.buffer.length + streamLength > this.maxLength) {
          await flush();
        }
      }
    } finally {
      this.inProgress = false;
      await flush();
    }
  }

  async getBuffer() {
    return this.buffer;
  }

  async throttle(throttleMs) {
    setTimeout(() => {
      this.throttleRate = throttleMs;
    }, throttleMs);
  }

  async drain() {
    await flush();
    this.buffer = Buffer.alloc(0);
  }

  async flush() {
    if (!this.inProgress && this.buffer.length > 0) {
      // fallback strategy implementation
      this.fallbackMode = true;
    }
  }
}

