function loadScript(src) {
  const fileId = createFileId(src);
  let script;
  try {
    script = document.createElement('script');
    script.src = src;
    script.onload = () => {
      console.log(`Script ${fileId} loaded`);
    };
    script.onerror = (error) => {
      console.error(`Error loading script ${fileId}: ${error}`);
    };
    document.body.appendChild(script);
  } catch (error) {
    console.error(`Error loading script ${fileId}: ${error}`);
  }
}

function createFileId(src) {
  const alphanumericChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let fileId = '';
  for (let i = 0; i < 10; i++) {
    fileId += alphanumericChars.charAt(Math.floor(Math.random() * alphanumericChars.length));
  }
  return `${src.substring(src.lastIndexOf('/') + 1)}_${fileId}`;
}

function loadScripts(scripts) {
  const promises = scripts.map((script) => loadScript(script));
  Promise.all(promises).then(() => {
    console.log('All scripts loaded');
  }).catch((error) => {
    console.error(`Error loading scripts: ${error}`);
  });
}

// Example usage
const scriptsToLoad = ['script1.js', 'script2.js', 'script3.js'];
loadScripts(scriptsToLoad);
