import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ResilientConnection {
    private static final int PORT = 8080;
    private static final int MAX_CONCURRENT_CONNECTIONS = 100;
    private static final int RETRY_DELAY_MILLIS = 30000; // 30 seconds
    private static final int ALERT_THRESHOLD_MILLIS = 600000; // 10 minutes

    public static void establishConnection() throws IOException {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_CONNECTIONS);
        Selector selector = Selector.open();
        ServerSocketChannel server = ServerSocketChannel.open();
        server.bind(new InetSocketAddress(PORT));
        server.configureBlocking(false);
        SelectionKey key = server.keyFor(selector);
        key.interestOps(SelectionKey.OP_ACCEPT);

        List<Connection> connections = new ArrayList<>();
        while (true) {
            selector.select();
            for (SelectionKey k : selector.selectedKeys()) {
                if (k.isAcceptable()) {
                    Connection connection = acceptConnection(server, executor, selector);
                    connections.add(connection);
                    executeTasks(connections);
                }
            }
            selector selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> iterator = selectedKeys.iterator();
            while (iterator.hasNext()) {
                iterator.next().cancelled();
            }
            selectedKeys.clear();

            // Handle connection failures
            for (Connection connection : connections) {
                if (!connection.isConnected()) {
                    try {
                        connection.reconnect();
                    } catch (IOException e) {
                        // Log and alert on prolonged failure
                        if (System.currentTimeMillis() - connection.getLastFailureTime() > ALERT_THRESHOLD_MILLIS) {
                            sendAlert(connection);
                        }
                    }
                }
            }

            // Close terminated connections
            for (Connection connection : connections) {
                if (!connection.isConnected()) {
                    connection.close();
                    connections.remove(connection);
                }
            }
        }
    }

    private static Connection acceptConnection(ServerSocketChannel server, ExecutorService executor, Selector selector) throws IOException {
        // Accept and handle new connections in separate threads
        return (Connection) executor.submit(() -> {
            try {
                // Handle incoming data transmission and reception
                // ...
            } catch (IOException e) {
                // Log and retry on connection failure
                // ...
            }
        });
    }

    private static void executeTasks(List<Connection> connections) {
        for (Connection connection : connections) {
            if (connection.isConnected()) {
                executor.submit(connection::executeTask);
            }
        }
    }

    private static void sendAlert(Connection connection) {
        // Integrate with external monitoring service to alert administrators
        // ...
    }
}

class Connection {
    private ServerSocketChannel channel;
    private ExecutorService executor;
    private Selector selector;

    public Connection() {
        this.executor = Executors.newSingleThreadExecutor();
        this.selector = Selector.open();
    }

    public void close() {
