package com.example.theme;

import android.app.Service;
import android.content.Intent;
import android.os.Bundle;
import android.os.IBinder;
import android.util.Log;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;

public class ThemeManagerService extends Service {

    private static final String TAG = "ThemeManagerService";
    private static final int CLEANUP_INTERVAL = 1000 * 60; // 1 minute

    private ConcurrentHashMap<String, BitmapCache> themeCaches;
    private Map<String, File> themeDirectories;
    private AtomicBoolean isCleaningUp;

    @Override
    public void onCreate() {
        super.onCreate();
        Log.d(TAG, "ThemeManagerService created");

        themeCaches = new ConcurrentHashMap<>();
        themeDirectories = new HashMap<>();
        isCleaningUp = new AtomicBoolean(false);

        // Initialize the theme cache and directory
        initThemeCache();

        // Start a background task to clean up unused themes periodically
        new Thread(() -> {
            while (true) {
                try {
                    if (!isCleaningUp.getAndSet(true)) {
                        cleanupUnusedThemes();
                        isCleaningUp.set(false);
                    }
                    Thread.sleep(CLEANUP_INTERVAL);
                } catch (InterruptedException e) {
                    Log.e(TAG, "Error cleaning up unused themes", e);
                }
            }
        }).start();
    }

    @Override
    public IBinder onBind(Intent intent) {
        return null;
    }

    private void initThemeCache() {
        // Load theme directories from external configuration service
        ConfigurationService config = new ConfigurationService(this);
        Map<String, String> themeDirs = config.getThemeDirectories();

        for (Map.Entry<String, String> entry : themeDirs.entrySet()) {
            File directory = new File(entry.getValue());
            if (!directory.exists()) {
                // Create the directory if it doesn't exist
                directory.mkdirs();
            }
            themeDirectories.put(entry.getKey(), directory);
        }

        // Load cached bitmaps from disk
        File cacheDir = getCacheDir();
        File[] files = cacheDir.listFiles();
        for (File file : files) {
            try (InputStream is = new FileInputStream(file)) {
                Bitmap bitmap = BitmapFactory.decodeStream(is);
                themeCaches.put(file.getName(), new BitmapCache(bitmap));
            } catch (FileNotFoundException e) {
                // Ignore
            }
        }
    }

    private void cleanupUnusedThemes() {
        Log.d(TAG, "Cleaning up unused themes");

        for (Map.Entry<String, File> entry : themeDirectories.entrySet()) {
            File directory = entry.getValue();
            File[] files = directory.listFiles();
            for (File file : files) {
                boolean isUsed = false;
                for (BitmapCache cache : themeCaches.values()) {
                    if (cache.getBitmap().getAbsolutePath().equals(file.getAbsolutePath())) {
                        isUsed = true;
                        break;
                    }
                }
                if (!isUsed) {
                    try (InputStream is = new FileInputStream(file)) {
                        Bitmap bitmap = BitmapFactory.decodeStream(is);
                        // Recycle the bitmap
                        bitmap.recycle();
                    } catch (FileNotFoundException e) {
                        // Ignore
                    }
                    file.delete();
                }
            }
        }
    }

    public class ConfigurationService {

        private Context context;

        public ConfigurationService(Context context) {
            this.context = context;
        }

        public Map<String, String> getThemeDirectories() {
            // Load theme directories from external configuration service
            // ...
        }
    }

    public class BitmapCache {

        private Bitmap bitmap;

        public BitmapCache(Bitmap bitmap) {
            this.bitmap = bitmap;
        }

        public Bitmap getBitmap() {
            return bitmap;
        }
    }
}
