public class ServiceLifecycle {
    private static final Logger logger = Logger.getLogger(ServiceLifecycle.class.getName());
    private AtomicInteger startCount = new AtomicInteger(0);
    private AtomicInteger stopCount = new AtomicInteger(0);
    private int minStopDuration;
    private int maxStopDuration;
    private String monitoringSystemUrl;
    private XMLConfiguration config;

    public ServiceLifecycle(String configFile) throws ConfigurationException {
        this.config = new XMLConfiguration(configFile);
        this.minStopDuration = config.getInt("minStopDuration");
        this.maxStopDuration = config.getInt("maxStopDuration");
        this.monitoringSystemUrl = config.getString("monitoringSystemUrl");
    }

    public void startService() {
        // Start service logic here
        logger.log(Level.INFO, "Service started at {0}", new Date());
        startCount.incrementAndGet();
    }

    public void stopService() {
        int duration = (int) Math.round((Math.random() * (maxStopDuration - minStopDuration)) + minStopDuration);
        // Stop service logic here
        logger.log(Level.INFO, "Service stopped at {0} for {1} seconds", new Object[]{new Date(), duration});
        stopCount.incrementAndGet();
    }

    public void sendMonitoringData() {
        // Send aggregated data to monitoring system
        int totalStarts = startCount.get();
        int totalStops = stopCount.get();
        logger.log(Level.INFO, "Sending {0} starts and {1} stops to {2}", new Object[]{totalStarts, totalStops, monitoringSystemUrl});
    }

    public void handleFailure() {
        // Failure handling logic here
        logger.log(Level.SEVERE, "Service failure detected. Restarting service...");
        startService();
    }

    public static void main(String[] args) {
        ServiceLifecycle service = new ServiceLifecycle("config.xml");
        try {
            // Start the service on demand or at regular intervals
            while (true) {
                if (Math.random() < 0.5) {
                    service.startService();
                } else {
                    service.stopService();
                }
                Thread.sleep(10000);
            }
        } catch (InterruptedException e) {
            logger.log(Level.SEVERE, "Interrupted", e);
        }
    }
}
