use std::process::{Command, Output};
use std::fs::read_dir;
use std::path::{Path, PathBuf};

pub fn compile_with_metrics(project_path: &str, log_detailed: bool) -> (i32, String) {
    let mut output = Output::new();
    let project_dir = Path::new(project_path);
    let cargo_toml_file = project_dir.join("Cargo.toml");

    if !cargo_toml_file.exists() {
        return (-1, "Error: Missing Cargo.toml file. Please ensure the project has a valid Cargo.toml file.".to_string());
    }

    let mut dependencies_missing = false;
    for entry in read_dir(project_dir).unwrap() {
        let path = entry.unwrap().path();
        if !path.is_dir() && path.ends_with("Cargo.toml") {
            continue;
        }
        if !Path::new(&format!("{}/{}", project_path, path.file_name().unwrap())).exists() {
            dependencies_missing = true;
            break;
        }
    }

    if dependencies_missing {
        return (-1, "Error: Missing dependencies. Please ensure all necessary libraries are present in the Cargo.toml file.".to_string());
    }

    let compile_cmd = format!("cargo build --color always");
    if log_detailed {
        println!("Starting compilation at {:?}", chrono::Local::now());
    }
    Command::new("cargo")
        .arg("build")
        .arg("--color")
        .arg("always")
        .output(&mut output)
        .unwrap_or_else(|e| {
            panic!("Failed to execute command: {}", e);
        });

    let mut metrics_report = String::from("Compilation Metrics:\n");
    metrics_report.push_str(&format!("  Compilation Time: {:.2?}", chrono::Duration::from_std(output.stdout.clone()).unwrap().num_seconds()));
    metrics_report.push_str("\n");

    (output.status.code(), metrics_report)
}
