<?php

function fileAndStringHandler($params) {
    $error = false;
    $result = array();

    if (!isset($params['length']) || !is_int($params['length'])) {
        $error = 'Invalid length parameter';
    } elseif (!isset($params['characters']) || !is_string($params['characters'])) {
        $error = 'Invalid character set parameter';
    } elseif (!isset($params['password']) || !is_string($params['password'])) {
        $error = 'Invalid password parameter';
    } elseif (!isset($params['file']) || !is_string($params['file'])) {
        $error = 'Invalid file parameter';
    }

    if (!$error) {
        try {
            // Generate random string
            $randomString = str_replace(array("\r\n", "\n"), '', implode('', array_map('chr', range(ord($params['characters'][0]), ord($params['characters'][strlen($params['characters'])-1])))));
            for ($i=0; $i < $params['length']; $i++) {
                $randomString .= $params['characters'][rand(0, strlen($params['characters'])-1)];
            }

            // Hash password
            $hashedPassword = hash('SHA256', $params['password'], true);

            // Read file
            $fileContents = @file_get_contents($params['file']);
            if (!$fileContents) {
                $error = 'Failed to read file: ' . $params['file'];
            }

            $result = array(
                'randomString' => $randomString,
                'hashedPassword' => $hashedPassword,
                'fileContents' => $fileContents
            );
        } catch (Exception $e) {
            $error = 'An error occurred: ' . $e->getMessage();
        }
    }

    if ($error) {
        return array('error' => $error);
    } else {
        return $result;
    }
}

