function generateCertificate(oauthRequest) {
  const privatekey = fs.readFileSync(oauthRequest.privateKeyPath);
  const cert = fs.readFileSync(oauthRequest.certificatePath);

  let certificate = '';
  let chunks = [];

  function fetchChunkedData(url, cb) {
    const request = https.get(url, (response) => {
      response.setEncoding('utf8');
      response.on('data', (chunk) => {
        chunks.push(chunk);
      });
      response.on('end', () => {
        const data = Buffer.concat(chunks).toString();
        cb(null, data);
      });
    }).on('error', (err) => {
      cb(err);
    });
  }

  function resumeFetch(url, offset, length, cb) {
    const request = https.get(`${url}?offset=${offset}&length=${length}`);
    request.setEncoding('utf8');
    let chunk;
    request.on('data', (chunk) => {
      chunks.push(chunk);
    });
    request.on('end', () => {
      const data = Buffer.concat(chunks).toString();
      cb(null, data);
    });
  }

  fetchChunkedData(oauthRequest.dataSourceUrl, (err, data) => {
    if (err) {
      // handle error
    } else {
      let chunk;
      for (let i = 0; i < chunks.length; i++) {
        chunk = Buffer.concat([Buffer.from(cert), Buffer.from(chunks[i])]);
        certificate += `-----BEGIN CERTIFICATE-----\n${chunk.toString('base64')}==\n-----END CERTIFICATE-----`;
      }
    }
  });
}
