    public function update_password($user_id, $old_password, $new_password) {
        // Validate old password
        if (!validate_password($old_password)) {
            return 'Invalid old password';
        }

        // Validate new password strength
        if (!validate_password_strength($new_password)) {
            return 'New password does not meet the minimum strength requirements';
        }

        // Rate limiting
        $attempt_count = get_attempt_count($user_id);
        if ($attempt_count >= MAX_ATTEMPTS_PER_USER) {
            return 'Too many attempts, please try again later';
        }

        // Distributed caching
        $cached_user_data = cache_get('user_data_' . $user_id);
        if ($cached_user_data) {
            // Update cached data
            $cached_user_data['password'] = $new_password;
            cache_set('user_data_' . $user_id, $cached_user_data);
        } else {
            // Fetch user data from database
            $query = "SELECT * FROM users WHERE id = '$user_id'";
            if ($result = mysqli_query($this->conn, $query)) {
                $user_data = mysqli_fetch_assoc($result);
                mysqli_free_result($result);

                // Update password in database
                $query = "UPDATE users SET password = '" . hash('sha256', $new_password) . "' WHERE id = '$user_id'";
                if (!mysqli_query($this->conn, $query)) {
                    return 'Failed to update password';
                }

                // Update cached data
                cache_set('user_data_' . $user_id, array('password' => $new_password));
            } else {
                return 'Failed to fetch user data';
            }
        }

        // Commit or roll back transaction
        if (mysqli_query($this->conn, "COMMIT")) {
            log_event('Password updated successfully');
        } else {
            log_event('Error updating password', mysqli_error());
            rollback_transaction();
        }
    }
