#include <string.h>

// Define a struct to represent the FSA state
typedef struct {
    int state;
    struct {
        int next_state;
        int is_accepting;
    } transitions[];
} FSAState;

// Function to dynamically manage a list of states derived from an FSA
FSAState** manage_states(FSAState* fsa, int num_states, int last_state, int max_size) {
    // Check for empty input arrays
    if (fsa == NULL || num_states <= 0) {
        return NULL;
    }

    // Initialize the state list and pointers
    FSAState** states = (FSAState**)malloc((num_states + 1)*sizeof(FSAState*));
    states[0] = fsa;

    for (int i = 1; i <= last_state; i++) {
        if (states[i-1]->transitions[i].state != -1) {
            // Add the new state to the list
            states[i] = malloc(sizeof(FSAState));
            *states[i] = fsa->transitions[i];
        } else {
            break;
        }
    }

    // Truncate the list if it exceeds the maximum size
    if (i > max_size) {
        for (int j = i; j > max_size; j--) {
            free(states[j-1]);
            states[j-1] = states[j];
        }
        states[max_size]->next = NULL;
    }

    // Ensure the output is unique and sorted
    if (i > 0) {
        for (int j = 0; j < i; j++) {
            for (int k = j + 1; k < i; k++) {
                if (states[k]->state == states[j]->state) {
                    free(states[k]);
                    for (int l = k; l < i - 1; l++) {
                        states[l] = states[l+1];
                    }
                    i--;
                    break;
                }
            }
        }
    }

    // Sort the state list
    for (int j = 0; j < i; j++) {
        for (int k = j + 1; k < i; k++) {
            if (states[k]->state < states[j]->state) {
                FSAState* temp = states[j];
                states[j] = states[k];
                states[k] = temp;
            }
        }
    }

    return states;
}
