    octreeNode* root = nullptr;

    try {
        // Calculate initial node count and required memory
        size_t nodeCount = calculateInitialNodeCount(featureSize, numLeafNodes, maxDepth);
        size_t totalMemoryNeeded = calculateTotalMemoryNeeded(nodeCount);

