            // Handle insufficient memory by reducing complexity or limiting leaf nodes
            size_t reducedMaxDepth = reduceMaxDepthForMemoryConstraints(maxDepth);
            size_t reducedNumLeafNodes = reduceNumLeafNodesForMemoryConstraints(numLeafNodes);

            nodeCount = calculateInitialNodeCount(featureSize, reducedNumLeafNodes, reducedMaxDepth);
            totalMemoryNeeded = calculateTotalMemoryNeeded(nodeCount);
        }

        // Allocate memory for the octree
        if (allocateMemory(totalMemoryNeeded)) {
            root = createOctreeNode(0);  // Create initial node

            // Initialize octree structure
            initializeOctreeStructure(root, featureSize, numLeafNodes, maxDepth);

            return root;
