// Function to process sensor data stream and identify anomalies
SensorData* identifyAnomalies(SensorData* liveStream, int liveStreamSize, int thresholdAge, int thresholdFrequency, int thresholdScore) {
    // Initialize rolling window with default values
    RollingWindow window = {NULL, 60, 0};

    // Process each data point in the live stream
    for (int i = 0; i < liveStreamSize; i++) {
        SensorData* current = &liveStream[i];

        // Check if the data is within the age threshold
        if (difftime(current->timestamp, time(NULL)) > thresholdAge) {
            continue;
        }

        // Add data to rolling window and update metrics
        int index = window.size++;
        window.data[index] = current;

        // Calculate frequency of data points
        int frequency = 0;
        for (int j = 0; j < window.size; j++) {
            if (difftime(window.data[j]->timestamp, time(NULL)) < thresholdAge) {
                frequency++;
            }
        }

        // Calculate anomaly score based on frequency and age
        double score = pow(frequency, 2) * difftime(current->timestamp, time(NULL));

        // Update highest anomaly score and corresponding sensor ID
        if (score > window.data[0]->id) {
            window.data[0] = current;
        }
    }

    return window.data;
}

