class Character {
public:
    Character(int characterId) : id(characterId), cooldownTimer(0) {}

    void performAttackSequence() {
        int sequenceNumber = 0;
        while (true) {
            if (cooldownTimer > 0) {
                std::this_thread::sleep_for(std::chrono::milliseconds(cooldownTimer));
                cooldownTimer = 0;
            }

            for (int i = 1; i <= 3; ++i) {
                int attackNumber = (sequenceNumber + i - 1) % 3 + 1;
                std::cout << "Character " << id << ": Attack sequence # " << sequenceNumber << " - Attack " << attackNumber << std::endl;

                // Simulate attack processing
                std::this_thread::sleep_for(std::chrono::milliseconds(500));

                ++sequenceNumber;
            }

            cooldownTimer = 1800; // Set cooldown timer to 18 seconds
        }
    }

private:
    int id;
    int cooldownTimer;
};

int main() {
    std::vector<Character> characters;

    for (int i = 1; i <= 5; ++i) {
        characters.emplace_back(i);
        std::thread(t([&c = characters.back()] { c.performAttackSequence(); })).detach();
    }

    return 0;
}
