using UnityEngine;

public class ValueGeneratorService
{
    private float minValue;
    private float maxValue;
    private readonly IDataStore _dataStore;

    public ValueGeneratorService(float min, float max, IDataStore dataStore)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot exceed maximum value.");

        minValue = min;
        maxValue = max;
        _dataStore = dataStore ?? throw new ArgumentNullException(nameof(dataStore));

        // Validate and update dataStore with initial configuration
        if (!_dataStore.SetConfiguration("valueRange", $"[{minValue}, {maxValue}]"))
        {
            Debug.LogError("Failed to save initial configuration to data store.");
        }
    }

    public float GenerateRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GenerateRandomInt()
    {
        return UnityEngine.Random.Range((int)Mathf.Floor(minValue), (int)Mathf.Ceil(maxValue));
    }

    public float GenerateRandomFloatInclusive()
