["```javascript
class Aggregator {
  constructor(initialBalance) {
    this.balance = initialBalance;
    this.batchSize = 1000; // adjust according to your needs
    this.transactions = [];
  }

  async processTransactions(transactions, callback) {
    const batchPromises = [];
    for (let i = 0; i < transactions.length; i += this.batchSize) {
      const batch = transactions.slice(i, i + this.batchSize);
      batchPromises.push(this.processBatch(batch, callback));
    }
    await Promise.all(batchPromises);
    return this.balance;
  }

  async processBatch(transactions, callback) {
    for (const transaction of transactions) {
      this.balance += transaction;
      await callback(transaction); // process each transaction
    }
  }
}

// Example usage:
async function main() {
  const aggregator = new Aggregator(0);
  const transactions = [10.5, -20, 30.75, -15, ...]; // assume a large dataset

  aggregator.processTransactions(transactions, (transaction) => console.log(`Processed: ${transaction}`));

  try {
    const finalBalance = await aggregator.balance;
    console.log(`Final balance: ${finalBalance}`);
  } catch (error) {
    console.error('Error:', error);
  }
}

main();
```"]

