function traverseDOMTree(node, selector, callback) {
    const matches = [];
    const traverse = (node) => {
        if (!node) return;
        if (node.nodeName.match(new RegExp(selector))) {
            callback(node);
            matches.push(node);
        }
        Array.from(node.children).forEach(traverse);
    };
    traverse(node);
    return matches;
}
