public static string ProcessImageMetadataAndChecksum(string filePath)
{
    using (var fileStream = File.OpenRead(filePath))
    {
        var tiffReader = new TiffReader(fileStream);
        var metadata = new ImageMetadata();

        if (!tiffReader.ReadMetadata(out metadata.BitsPerSample, out metadata.SamplesPerPixel, out metadata.ExtraSamplesCount, out metadata.ExtraSamples))
            return "Unsupported bit depth or corrupted file.";

        try
        {
            using (var md5 = MD5.Create())
            {
                var buffer = new byte[32768];
                int bytesRead;
                using (var ms = new MemoryStream())
                {
                    while ((bytesRead = fileStream.Read(buffer, 0, buffer.Length)) > 0)
                        ms.Write(buffer, 0, bytesRead);
                    return md5.ComputeHash(ms.ToArray()).Aggregate("", (s, b) => s + b.ToString("x2"));
                }
            }
        }
        catch
        {
            return "Error processing file.";
        }
    }
}

