#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* generateNewFilename(char* filename) {
    char *dirPath = strtok(filename, "/");
    char *baseName = strtok(NULL, ".");
    char *extension = strtok(NULL, ".");

    int numDigits = 0;
    int i = 0;
    while (i < strlen(dirPath)) {
        if (isdigit(dirPath[i])) {
            numDigits++;
        } else {
            break;
        }
        i++;
    }

    int fileTypeIndex = 0;
    for (int j = strlen(dirPath) - 1; j >= 0; j--) {
        if (dirPath[j] == '.') {
            fileTypeIndex = j;
            break;
        }
    }

    char *newFilename = malloc(strlen(baseName) + numDigits + strlen(extension) + 2);
    strcpy(newFilename, baseName);

    for (int k = 0; k < numDigits; k++) {
        sprintf(newFilename + strlen(baseName), "%d", (rand() % 10));
    }

    strcat(newFilename, ".");
    strcat(newFilename, extension);

    return newFilename;
}

void freeNewFilename(char* filename) {
    free(filename);
}
