#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define MAX_CMD_PATH 256
#define MAX_TIMEOUT 3600 // 1 hour in seconds
#define MAX_SIGNAL 31

typedef struct {
    int delay;
} retry_config;

void sig_handler(int signal) {
    if (signal == SIGCHLD) {
        int status;
        waitpid(-1, &status, WNOHANG);
    }
}

int execute_command(const char* command, int timeout, int signal, retry_config config) {
    pid_t child_pid = fork();

    if (child_pid < 0) {
        return -1; // fork failed
    } else if (child_pid > 0) {
        // parent process
        struct timespec timeout_spec;
        timeout_spec.tv_sec = timeout / 1000; 
        timeout_spec.tv_nsec = (timeout % 1000) * 1000000;

        nanosleep(&timeout_spec, NULL);

        int status;
        waitpid(child_pid, &status, WNOHANG);
    } else {
        // child process
        signal(signal);

        if (execlp(command, command, (char*)NULL) < 0) {
            return -2; // exec failed
        }
    }

    return 0;
}

int main() {
    const char* cmd = "/usr/bin/my_command";
    int timeout = 300; // 5 minutes
    int signal = SIGTERM;
    retry_config config = {2}; // retry every 2 seconds

    execute_command(cmd, timeout, signal, config);
}
