    // Step 1: Decode and validate Base64-encoded password
    char *decoded_password = base64_decode(user_auth_data->password);
    if (!decoded_password || strlen(decoded_password) == 0) {
        error_code = EINVAL;
        free(decoded_password); // Cleanup temporary resource
        return error_code;
    }

    // Step 2: Validate ConnectionInfo and provide fallback if necessary
    if (!user_auth_data->conn_info || !user_auth_data->conn_info->title) {
        user_auth_data->conn_info = default_conn_info(); // Set default connection info
    }

    // Step 3: Verify callback function is not NULL
    if (!user_auth_data->log_func) {
        error_code = EINVAL;
        return error_code;
    }

    // Step 4: Decrypt password using Triple DES encryption
    char *decrypted_password = triple_des_decrypt(decoded_password, user_auth_data->password_key, user_auth_data->iv);
    free(decoded_password); // Cleanup temporary resource

    if (!decrypted_password) {
        error_code = ECRYPT; // Decryption failed

        // Attempt to decrypt with secondary key
        decrypted_password = triple_des_decrypt(decoded_password, secondary_password_key, user_auth_data->iv);
        if (!decrypted_password) {
            error_code = ECRYPT; // Secondary decryption also failed
            return error_code;
        }
    } else {
        free(user_auth_data->password); // Cleanup original password
        user_auth_data->password = decrypted_password;
    }

