using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Base64EncryptionProcessor
{
    private const string DELIMITER = "--DELIMITER--";
    private const string DECryption_LOG_FILE = "decryption_log.txt";

    public List<string> ProcessBase64Messages(string inputString)
    {
        List<string> decryptedMessages = new List<string>();
        string[] messages = inputString.Split(new[] { DELIMITER }, StringSplitOptions.None);

        foreach (string message in messages)
        {
            if (message.Contains("Key:"))
            {
                string[] parts = message.Split(new[] { "Key:" }, StringSplitOptions.None);
                string key = parts[1].Trim();
                string iv = message.Substring(message.IndexOf("IV:") + 3).Trim();

                if (IsValidKey(key) && IsValidIV(iv))
                {
                    try
                    {
                        byte[] encryptedBytes = Convert.FromBase64String(message.Substring(0, message.Length - message.Split(new[] { DELIMITER }, StringSplitOptions.None)[1].Length));
                        using (TripleDES tripleDES = TripleDES.Create())
                        {
                            tripleDES.Key = Encoding.ASCII.GetBytes(key);
                            tripleDES.IV = Encoding.ASCII.GetBytes(iv);

                            byte[] decryptedBytes = tripleDES.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                            string decryptedMessage = Encoding.ASCII.GetString(decryptedBytes);

                            File.AppendAllText(DECryption_LOG_FILE, $"Decryption successful for message: {decryptedMessage}\n");
                            decryptedMessages.Add(decryptedMessage);
                        }
                    }
                    catch (Exception ex)
                    {
                        File.AppendAllText(DECryption_LOG_FILE, $"Decryption failed: {ex.Message}\n");
                    }
                }
            }
        }

        return decryptedMessages;
    }

    private bool IsValidKey(string key)
    {
        // Validate the length and format of the provided key
        if (key.Length < 16 || key.Length > 32) return false;

        foreach (char c in key)
        {
            if (!Char.IsLetterOrDigit(c)) return false;
        }

        return true;
    }

    private bool IsValidIV(string iv)
    {
        // Validate the length and format of the provided IV
        if (iv.Length < 8 || iv.Length > 16) return false;

        foreach (char c in iv)
        {
            if (!Char.IsLetterOrDigit(c)) return false;
        }

        return true;
    }
}
