using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class Sha256ChecksumGenerator
{
    private readonly int _chunkSize = 1024 * 1024; // Default chunk size in bytes (1MB)

    public Dictionary<long, byte[]> GenerateChecksums(string filePath)
    {
        var checksums = new Dictionary<long, byte[]>();
        using (var fileStream = File.OpenRead(filePath))
        {
            long lineNumber = 0;
            byte[] buffer = new byte[_chunkSize];
            while (fileStream.Position < fileStream.Length)
            {
                int bytesRead = fileStream.Read(buffer, 0, _chunkSize);
                if (bytesRead == 0) break;

                for (int i = 0; i < bytesRead; i++)
                {
                    SHA256 sha256 = SHA256.Create();
                    byte[] lineData = new byte[i + 1];
                    Array.Copy(buffer, i, lineData, 0, lineData.Length);
                    using (var memoryStream = new MemoryStream(lineData))
                    {
                        using (var cryptoStream = new CryptoStream(memoryStream, sha256.CreateHash()))
                        {
                            cryptoStream.Write(lineData, 0, lineData.Length);
                            cryptoStream.Flush();
                            var checksum = sha256.Hash.Value;
                            checksums.Add(lineNumber++, checksum);
                        }
                    }
                }
            }
        }
        return checksums;
    }

    public async Task<Dictionary<long, byte[]>> GenerateChecksumsAsync(string filePath)
    {
        var checksums = new Dictionary<long, byte[]>();
        using (var fileStream = File.OpenRead(filePath))
        {
            long lineNumber = 0;
            byte[] buffer = new byte[_chunkSize];
            while (fileStream.Position < fileStream.Length)
            {
                int bytesRead = await fileStream.ReadAsync(buffer, 0, _chunkSize);
                if (bytesRead == 0) break;

                for (int i = 0; i < bytesRead; i++)
                {
                    SHA256 sha256 = SHA256.Create();
                    byte[] lineData = new byte[i + 1];
                    Array.Copy(buffer, i, lineData, 0, lineData.Length);
                    using (var memoryStream = new MemoryStream(lineData))
                    {
                        using (var cryptoStream = new CryptoStream(memoryStream, sha256.CreateHash()))
                        {
                            await cryptoStream.WriteAsync(lineData, 0, lineData.Length);
                            cryptoStream.Flush();
                            var checksum = sha256.Hash.Value;
                            checksums.Add(lineNumber++, checksum);
                        }
                    }
                }
            }
        }
        return checksums;
    }

    public void SetChunkSize(int chunkSizeInBytes)
    {
        _chunkSize = chunkSizeInBytes;
    }
}
