using System;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    private readonly byte[] _decryptionKey;
    private readonly byte[] _initializationVector;
    private readonly int _paddingSize;

    public AesCbcDecryptor(byte[] decryptionKey, byte[] initializationVector, int paddingSize)
    {
        _decryptionKey = decryptionKey;
        _initializationVector = initializationVector;
        _paddingSize = paddingSize;
    }

    public byte[] Decrypt(byte[] ciphertext)
    {
        using (var aesAlg = Aes.Create())
        {
            aesAlg.Key = _decryptionKey;
            aesAlg.IV = _initializationVector;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor();
            using (var ms = new MemoryStream(ciphertext))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    byte[] plainBytes = new byte[ciphertext.Length - (_paddingSize * 2)];
                    int bytesRead = cs.Read(plainBytes, 0, plainBytes.Length);
                    return plainBytes.Take(bytesRead).ToArray();
                }
            }
        }
    }

    public void LogDecryptionEvent(byte[] plaintext, Exception ex)
    {
        // Integrate with logging framework to log decryption events
    }
