    return Promise.all(
      files.map(async (file) => {
        try {
          const csvData = await fs.readFile(file.path, 'utf8');
          const jsonData = await csvtojson().byLine(csvData);
          const report = this.generateReport(jsonData);

          // Stream the processing progress and report generation status
          this.eventEmitter.emit('progress', {
            file,
            report,
          });

          return report;
        } catch (error) {
          console.error(`Error processing file: ${file.path}`);
          throw error;
        }
      })
    );
  }

  generateReport(jsonData) {
    // Implement your aggregation logic here
    // ...
  }

  startProcessing(files) {
    const childProcess = ChildProcess.spawn('node', ['report_generator.js'], {
      stdio: 'inherit',
    });

    files.forEach((file) => {
      fs.createReadStream(file.path)
        .pipe(zlib.compress())
        .pipe(childProcess.stdin);
    });

    // Stream the processing progress and report generation status
    childProcess.stdout.on('data', (data) => {
      this.eventEmitter.emit('progress', data.toString());
    });

    childProcess.stderr.on('data', (data) => {
      console.error(data.toString());
    });

    childProcess.on('exit', () => {
      console.log('Report generation completed');
    });
  }

