from functools import lru_cache
from collections import defaultdict

class JSONParser:
    _registry = defaultdict(dict)
    _config_service = None

    def __init__(self):
        self._logger = logging.getLogger(__name__)

    @lru_cache(maxsize=None)
    def get_factory(self, id: str) -> callable:
        return self._registry[id].get('factory')

    def register_factory(self, id: str, factory_func: callable):
        self._registry[id]['factory'] = factory_func

    def parse_json(self, json_data: str) -> dict:
        try:
            data = json.loads(json_data)
        except json.JSONDecodeError as e:
            self._logger.error(f"Invalid JSON: {e}")
            return None
        else:
            factory_id = 'default'
            if 'type' in data and isinstance(data['type'], str):
                factory_id = data.pop('type')
            factory_func = self.get_factory(factory_id)
            if factory_func is not None:
                return factory_func(**data)
            else:
                self._logger.warning(f"Unknown type '{factory_id}' - falling back to default")
                return {'error': 'Unknown type'}

    def update_registry(self, new_config: dict):
        for id, config in new_config.items():
            if 'factory' in config:
                self.register_factory(id, config['factory'])

    def set_config_service(self, service):
        self._config_service = service
