typedef struct {
    int key;
} Record;

// Function to process and find the maximum value
void* processAndFindMax(void* arg) {
    // Get the input file descriptor
    FILE* input = (FILE*)arg;

    // Initialize arrays
    int* longOffsets = (int*)malloc(1024 * sizeof(int));
    int* intKeys = (int*)malloc(1024 * sizeof(int));
    Record* records = (Record*)malloc(512 * sizeof(Record));

    if (!longOffsets || !intKeys || !records) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    pthread_init(longOffsets, intKeys);

    // Read integers from standard input and populate the array
    for (int i = 0; i < 512; i++) {
        records[i].key = rand() % 90 + 10;
    }

    // Sort the records based on their key values
    pthread_sort(records, 512);

    // Find and print the maximum integer stored in the array
    int maxKey = records[0].key;
    for (int i = 1; i < 512; i++) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
        }
    }

    printf("Maximum key value: %d\n", maxKey);

    // Release allocated memory
    free(longOffsets);
    free(intKeys);
    free(records);

    return NULL;
}

int main() {
    FILE* input = stdin;

    pthread_t thread;
    pthread_create(&thread, NULL, processAndFindMax, (void*)input);

    pthread_join(thread, NULL);

    return 0;
}
