// Structure to represent a record
typedef struct {
    int value;
} record;

// Function to allocate and initialize arrays from file
int manage_memory(int n, int fd) {
    long *offsets = (long *)malloc(n * sizeof(long));
    int *keys = (int *)malloc(n * sizeof(int));

    // Read values from file
    for (int i = 0; i < n; i++) {
        long offset;
        int key;

        // Check for end of file and invalid integers
        if (read(fd, &offset, sizeof(long)) != sizeof(long) || read(fd, &key, sizeof(int)) != sizeof(int)) {
            free(offsets);
            free(keys);
            return -1;  // File truncated or invalid data
        }

        offsets[i] = offset;
        keys[i] = key;
    }

    // Allocate and initialize array of records
    record *records = (record *)malloc(n * sizeof(record));
    for (int i = 0; i < n; i++) {
        int value = rand() % 100 + 1;  // Random integer within [1, 100]
        records[i].value = value;
    }

    // Monitor memory usage dynamically
    size_t total_memory = sizeof(long) * n + sizeof(int) * n + sizeof(record) * n;

    return total_memory;
}

// Function to sort records based on offset values
void sort_records(record *records, long *offsets, int n) {
    qsort(records, n, sizeof(record), compare_records);
}

int compare_records(const void *a, const void *b) {
    record *record_a = (record *)a;
    record *record_b = (record *)b;

    return offsets[0] - offsets[n-1];  // Sort in ascending order
}

// Function to free allocated memory
void cleanup_memory(int n) {
    free((long *)malloc(n * sizeof(long)));
    free((int *)malloc(n * sizeof(int)));
    free((record *)malloc(n * sizeof(record)));
}

// Function to record start and end of each operation with logging library
