#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int network_id;
    time_t timestamp;
    char *events;
} NetworkStats;

typedef struct {
    NetworkStats **stats;
    pthread_mutex_t lock;
    size_t capacity;
    size_t used;
} DynamicList;

DynamicList *create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = malloc(sizeof(DynamicList));
    list->stats = malloc(initial_capacity * sizeof(NetworkStats *));
    list->capacity = initial_capacity;
    list->used = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_dynamic_list(DynamicList *list) {
    for (size_t i = 0; i < list->used; i++) {
        free(list->stats[i]->events);
        free(list->stats[i]);
    }
    free(list->stats);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_stats(DynamicList *list, NetworkStats **stats, size_t num_stats) {
    for (size_t i = 0; i < num_stats; i++) {
        if (list->used >= list->capacity) {
            list->capacity *= 2;
            list->stats = realloc(list->stats, list->capacity * sizeof(NetworkStats *));
        }
        list->stats[list->used++] = stats[i];
    }
}

NetworkStats *get_stat_by_id(DynamicList *list, int network_id) {
    for (size_t i = 0; i < list->used; i++) {
        if (list->stats[i]->network_id == network_id) {
            return list->stats[i];
        }
    }
    return NULL;
}

void print_stats(DynamicList *list) {
    for (size_t i = 0; i < list->used; i++) {
        printf("Network ID: %d, Timestamp: %lu, Events: %s\n", 
               list->stats[i]->network_id, list->stats[i]->timestamp, 
               list->stats[i]->events);
    }
}

int main() {
    DynamicList *list = create_dynamic_list(10);

    NetworkStats *stat1 = malloc(sizeof(NetworkStats));
    stat1->network_id = 1;
    stat1->timestamp = time(NULL);
    stat1->events = "traffic_event_1";

    NetworkStats *stat2 = malloc(sizeof(NetworkStats));
    stat2->network_id = 2;
    stat2->timestamp = time(NULL) + 10;
    stat2->events = "traffic_event_2";

    add_stats(list, &stat1, 1);
    add_stats(list, &stat2, 1);

    NetworkStats *found_stat = get_stat_by_id(list, 1);
    if (found_stat != NULL) {
        printf("Found stat: %s\n", found_stat->events);
    } else {
        printf("Stat not found\n");
    }

    print_stats(list);

    free_dynamic_list(list);

    return 0;
}
