            std::condition_variable cv;
            int numThreads;
            std::vector<std::thread> threads;

            FileProcessor(int numThreads) : numThreads(numThreads) {}

            void processFile(const std::string& filename, const std::string& hostname) {
                std::ifstream file(filename);
                if (!file.is_open()) {
                    // Handle error
                    return;
                }

                std::random_device rd;
                std::mt19937 gen(rd());
                std::uniform_int_distribution<> dis(1, 100);

                for (int i = 0; i < numThreads; ++i) {
                    threads.emplace_back([this, &file, hostname, &dis]() {
                        int linesProcessed = 0;
                        while (file && linesProcessed < 10) {
                            std::string line;
                            std::getline(file, line);
                            if (line.empty()) {
                                continue;
                            }
                            std::istringstream iss(line);
                            double sum = 0.0;
                            for (int j = 0; j < 3; ++j) {
                                iss >> sum;
                            }
                            double avg = sum / 3.0;
                            // Perform DNS resolution and calculate average
                            std::cout << "Resolved IP: " << hostname << " | Average: " << avg << std::endl;
                            linesProcessed++;
                        }
                    });
                }

                for (auto& thread : threads) {
                    thread.join();
                }
            }
    };

    class NetworkProcessor {
        public:
            std::mutex mtx;
            std::condition_variable cv;
            int numThreads;
