typedef struct {
    char path[1024];
    size_t fileSize;
} FileData;

void processFiles(int maxFiles) {
    int i = 0;
    FileData* files = (FileData*)malloc(maxFiles * sizeof(FileData));

    while (i < maxFiles && !feof(stdin)) {
        FILE* file = fopen("input.txt", "r");
        if (!file) {
            printf("Error opening file\n");
            continue;
        }

        char line[1024];
        fgets(line, 1024, stdin);
        fclose(file);

        if (strlen(line) > 1000) {
            printf("File path too long. Please try again.\n");
            continue;
        }

        strncpy(files[i].path, line, 1023);
        files[i].path[1023] = '\0';

        file = fopen(files[i].path, "r");
        if (!file) {
            printf("File does not exist\n");
            free(files);
            return;
        }

        fseek(file, 0L, SEEK_END);
        files[i].fileSize = ftell(file);
        rewind(file);
        fclose(file);

        i++;
    }

    for (int j = 0; j < i; j++) {
        printf("Path: %s\nFileSize: %ld bytes\n", files[j].path, files[j].fileSize);
    }

    if (i == 0) {
        printf("No valid files found");
    } else {
        FILE* file = fopen("output.txt", "w");
        for (int j = 0; j < i; j++) {
            fprintf(file, "%s\n", files[j].path);
        }
        fclose(file);

        printf("Total size: %ld bytes\n", sizeof(FileData) * i);
    }

    free(files);
}

int main() {
    int maxFiles;
    printf("Enter the maximum number of file paths (up to 1000): ");
    scanf("%d", &maxFiles);
    processFiles(maxFiles);

    return 0;
}
