#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>

#define LOG_FILE_SIZE_LIMIT 1024 * 1024 * 10 // 10MB
#define BUFFER_SIZE 1024 * 128 // 128KB
#define MAX_LOG_FILES 1000

typedef struct {
    FILE* file;
    size_t size;
} LogFile;

LogFiles log_files[MAX_LOG_FILES];
int num_log_files = 0;

void rotate_logs() {
    int i;
    for (i = 0; i < num_log_files; i++) {
        if (log_files[i].size >= LOG_FILE_SIZE_LIMIT) {
            fclose(log_files[i].file);
            log_files[i] = log_files[num_log_files - 1];
            num_log_files--;
            i--;
        }
    }
}

void write_to_log(const char* format, ...) {
    va_list args;
    va_start(args, format);

    size_t buffer_size = BUFFER_SIZE;
    char buffer[buffer_size];

    size_t bytes_written = 0;
    while (1) {
        size_t remaining_space = buffer_size - bytes_written;
        vsnprintf(buffer + bytes_written, remaining_space, format, args);
        if (bytes_written + strlen(buffer) >= LOG_FILE_SIZE_LIMIT) break;
        bytes_written += strlen(buffer);

        // Write to the current log file
        LogFile* current_log_file = &log_files[num_log_files - 1];
        if (fwrite(buffer, 1, strlen(buffer), current_log_file->file) != strlen(buffer)) {
            perror("Error writing to log");
            return;
        }

        buffer_size *= 2; // Increase the buffer size
    }

    va_end(args);

    // If the buffer is full or a new log file needs to be created, rotate logs
    if (bytes_written >= LOG_FILE_SIZE_LIMIT || num_log_files >= MAX_LOG_FILES) {
        rotate_logs();
    }
}

void init_log_system() {
    for (int i = 0; i < MAX_LOG_FILES; i++) {
        log_files[i].file = fopen("log_file_%d.log", i + 1);
        if (!log_files[i].file) {
            perror("Error opening log file");
            exit(1);
        }
        log_files[i].size = 0;
    }
}

void close_log_system() {
    for (int i = 0; i < num_log_files; i++) {
        fclose(log_files[i].file);
    }
}
