use std::sync::{Arc, Mutex};
use std::thread;
use reqwest::{blocking::get, ClientBuilder};

struct SemaphorePool {
    semaphores: Arc<Mutex<Vec<std::sync::Semaphore>>>,
}

impl SemaphorePool {
    fn new(num_semaphores: usize) -> Self {
        let mut semaphores = Vec::new();
        for _ in 0..num_semaphores {
            semaphores.push(std::sync::Semaphore::new(0));
        }
        SemaphorePool { semaphores: Arc::new(Mutex::new(semaphores)) }
    }

    fn acquire(&self, semaphore_index: usize) -> Result<(), std::sync::PoisonError<std::sync::Semaphore>> {
        let mut semaphores = self.semaphores.lock().unwrap();
        (*semaphores.get_mut(semaphore_index)).try_acquire()?
    }

    fn release(&self, semaphore_index: usize) -> Result<(), std::sync::PoisonError<std::sync::Semaphore>> {
        let mut semaphores = self.semaphores.lock().unwrap();
        (*semaphores.get_mut(semaphore_index)).release(1)?;
        Ok(())
    }
}

struct HttpPool {
    client: Arc<Mutex<ClientBuilder>>,
    request_pool: Vec<reqwest::blocking::Request>,
}

impl HttpPool {
    fn new() -> Self {
        let client = Arc::new(Mutex::new(ClientBuilder::new()));
        HttpPool { client, request_pool: Vec::new() }
    }

    fn get_request(&self) -> reqwest::blocking::RequestBuilder {
        let mut client = self.client.lock().unwrap();
        let request = client.get("https://example.com");
        let request_builder = request.build()?;
        request_builder
    }

    fn close(&mut self) {
        for request in self.request_pool.drain(0..self.request_pool.len()) {
            request.close();
        }
        *self.client.lock().unwrap() = ClientBuilder::new();
    }
}

fn main() {
    let semaphore_pool = SemaphorePool::new(5);
    let http_pool = HttpPool::new();

    // Initialize HTTP client with optional certificate validation
    let mut client = http_pool.client.lock().unwrap();
    *client = client
        .danger_accept_invalid_certs(true)
        .timeout(None);

    // Acquire semaphore and make an HTTP request
    if let Ok(_) = semaphore_pool.acquire(0) {
        let request_builder = http_pool.get_request();
        // Set custom headers and body parameters
        request_builder.header("Custom-Header", "Value");
        request_builder.body("Request Body");

        match blocking::get(&request_builder) {
            Ok(_) => println!("HTTP Request Successful"),
            Err(err) => println!("HTTP Request Failed: {}", err),
        };

        // Release semaphore after completing the HTTP request
        http_pool.close();
    } else {
        eprintln!("Semaphore Pool Exhausted");
    }
}
