using System;
using System.IO;
using System.Environment;
using System.Xml.Linq;
using System.Threading;
using System.Diagnostics;

public class XmlParser
{
    public void ParseXml(string url)
    {
        if (!Directory.Exists(GetEnvironmentVariable("MyDir")))
        {
            try
            {
                Directory.CreateDirectory(GetEnvironmentVariable("MyDir"));
            }
            catch (Exception ex)
            {
                File.AppendAllText("errors.txt", $"Error creating directory: {ex.Message}");
            }
        }

        XDocument xmlDoc = XDocument.Load(url);

        if (!xmlDoc.Root.HasAttribute("myTag"))
        {
            throw new Exception("Element does not exist or appears more than once");
        }

        UnionFind uf = new UnionFind();
        foreach (XElement el in xmlDoc.Descendants())
        {
            foreach (XAttribute attr in el.Attributes())
            {
                if (!uf.Union(attr.Name.LocalName, attr.Value))
                {
                    Console.WriteLine($"Disjoint pair found: {attr.Name} - {attr.Value}");
                    Console.WriteLine($"Time taken: {(int)DateTime.Now.Ticks / 10000} ms");
                }
            }
        }

        int attempts = 0;
        while (attempts < 3)
        {
            try
            {
                xmlDoc.Load(url);
                return;
            }
            catch (Exception ex)
            {
                if (ex is WebException we && we.Status == WebExceptionStatus.SendFailure)
                {
                    attempts++;
                    Thread.Sleep(new TimeSpan(0, 0, (int)Math.Pow(2, attempts) * 5));
                }
                else
                {
                    throw;
                }
            }
        }

        throw new Exception("Failed to retrieve document");
    }

    string GetEnvironmentVariable(string name)
    {
        return Environment.GetEnvironmentVariable(name);
    }
}

public class UnionFind
{
    private Dictionary<string, int> parent = new Dictionary<string, int>();
    private Dictionary<string, int> rank = new Dictionary<string, int>();

    public bool Union(string a, string b)
    {
        if (!parent.ContainsKey(a) || !parent.ContainsKey(b))
            return false;

        int rootA = Find(a);
        int rootB = Find(b);

        if (rootA == rootB)
            return true;

        if (rank[rootA] < rank[rootB])
        {
            parent[a] = b;
            return true;
        }
        else
        {
            parent[b] = a;
            if (rank[rootA] == rank[rootB])
                rank[rootA]++;
            return true;
        }
    }

    private int Find(string v)
    {
        if (!parent.ContainsKey(v))
            return 0;

        if (parent[v] != v)
            parent[v] = Find(parent[v]);

        return parent[v];
    }
}
