#include <sys/wait.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

#define MAX_CMD 1024
#define MAX_FILE_SIZE 1048576

typedef struct {
    char* keyword;
    int frequency;
} Keyword;

void execute_command(char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    }
    if (pid > 0) {
        waitpid(pid, NULL, 0);
    } else {
        if (execve(command, NULL, NULL) == -1) {
            perror("execve");
            _exit(1);
        }
    }
}

char* generate_random_string(int length, char** chars) {
    srand(time(NULL));
    char* random_str = (char*)malloc((length + 1) * sizeof(char));
    for (int i = 0; i < length; i++) {
        random_str[i] = chars[rand() % strlen(*chars)];
    }
    random_str[length] = '\0';
    return random_str;
}

Keyword* parse_file(const char* file_path, int* num_keywords) {
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        perror("fopen");
        return NULL;
    }
    char line[1024];
    *num_keywords = 0;
    Keyword* keywords = (Keyword*)malloc(MAX_FILE_SIZE * sizeof(Keyword));
    while (fgets(line, sizeof(line), file)) {
        size_t len = strlen(line);
        if (line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }
        char keyword[32];
        sscanf(line, "%31s", keyword);
        keywords[*num_keywords].keyword = (char*)malloc((strlen(keyword) + 1) * sizeof(char));
        strcpy(keywords[*num_keywords].keyword, keyword);
        keywords[*num_keywords].frequency = 0;
        (*num_keywords)++;
    }
    fclose(file);
    return keywords;
}

void read_file_and_extract_keywords(const char* file_path, int* num_keywords, Keyword** keywords) {
    struct stat sb;
    if (stat(file_path, &sb) == -1 || sb.st_size > MAX_FILE_SIZE) {
        perror("stat");
        return;
    }
    *keywords = parse_file(file_path, num_keywords);
}

void logging Mechanism(int code) {
    time_t now = time(NULL);
    struct tm* tm = localtime(&now);
    printf("[%04d-%02d-%02d %02d:%02d:%02d] Code: %d\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, code);
}

