    std::function<int(int)> strategy = [numRequests = 0]() mutable {
        return (rand() % numRequests) + 1;
    };

    // Start API requests
    boost::asio::async_result<void(boost::system::error_code)>(
            io.async_connect("api-service.com", boost::asio::bind_executor(
