typedef struct state {
    int id;
    struct state* next;
} state;

state* manageStateList(int** states, int statesNum, int** fsa, int lastState) {
    // Create a new list of states
    state* newList = (state*)malloc(sizeof(state) * (statesNum + 1));

    for (int i = 0; i < statesNum; i++) {
        newList[i].id = (*states)[i];
        newList[i].next = &newList[i+1];
    }

    // Update the last state's next pointer
    if (statesNum > 0) {
        newList[statesNum-1].next = NULL;
    } else {
        free(newList);
        return NULL;
    }

    // Check for memory allocation failures
    if (newList == NULL) {
        printf("Memory allocation failure\n");
        return NULL;
    }

    // Sort and deduplicate the list of states
    state* current = newList;
    while (current != NULL) {
        int found = 0;
        state* prev = current;
        current = current->next;
        while (current != NULL) {
            if (current->id == prev->id) {
                found = 1;
                break;
            }
            prev = current;
            current = current->next;
        }
        if (!found) {
            prev->next = current;
        } else {
            state* temp = current;
            free(temp);
        }
    }

    // Update the last state's next pointer
    current = newList;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = NULL;

    return newList;
}

int main() {
    int statesNum = 5;
    int** fsa = malloc(statesNum * sizeof(int*));
    for (int i = 0; i < statesNum; i++) {
        fsa[i] = malloc(sizeof(int));
        *fsa[i] = i+1;
    }

    state* newStateList = manageStateList(fsa, statesNum, fsa, 4);

    // Free the memory
    for (int i = 0; i < statesNum; i++) {
        free(fsa[i]);
    }
    free(fsa);

    return 0;
}
