#define TRANSACTION_THRESHOLD 10
#define MAX_WEIGHTED_SUM 1000

typedef struct {
    int id;
    double value;
} Transaction;

Transaction transactions[10000];
int transaction_count = 0;

double total_value = 0.0;
int max_weighted_sum = 0;
int highest_id = 0;
int processed_transactions = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* process_transactions(void*) {
    while (1) {
        pthread_mutex_lock(&mutex);

        if (transaction_count > 0 && clock() - transactions[0].timestamp < 300000) {
            for (int i = 0; i < transaction_count; i++) {
                if (clock() - transactions[i].timestamp >= 30 * 1000) {
                    double weighted_sum = calculate_weighted_sum(transactions[i]);
                    pthread_mutex_unlock(&mutex);

                    if (weighted_sum > max_weighted_sum && processed_transactions <= TRANSACTION_THRESHOLD) {
                        printf("Max weighted sum: %f, Transaction ID: %d\n", weighted_sum, transactions[i].id);
                    }

                    total_value += transactions[i].value;
                    if (transactions[i].value > highest_id) {
                        highest_id = transactions[i].value;
                    }
                    processed_transactions++;

                    pthread_mutex_lock(&mutex);
                } else {
                    pthread_cond_wait(&cond, &mutex);
                    i--;
                }
            }
        }

        pthread_mutex_unlock(&mutex);
    }
}

double calculate_weighted_sum(Transaction t) {
    // Custom algorithm to calculate weighted sum
    double random_factor = (rand() / (double)RAND_MAX) * 0.1;
    return t.value + random_factor;
}

void log_transactions(void) {
    // Log transactions and metrics periodically
}

int main() {
    pthread_t thread;

    srand(time(NULL));

    pthread_create(&thread, NULL, process_transactions, NULL);

    while (1) {
        printf("Enter transaction ID: ");
        int id;
        scanf("%d", &id);

        Transaction t = { .id = id, .value = 100.0 };
        transactions[transaction_count++] = t;

        pthread_mutex_lock(&mutex);
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&mutex);
    }

    return 0;
}
