#include <stdlib.h>
#include <stdio.h>
#include <string.h>

char* generateDynamicFilename(const char *filename) {
    char *directory = NULL;
    char *basename = NULL;
    char *extension = NULL;

    // Split the filename into directory, basename, and extension
    for (int i = 0; ; i++) {
        if (filename[i] == '\0') break;
        if (filename[i] == '/') {
            if (!directory) directory = malloc(i + 1);
            memcpy(directory, filename, i);
            directory[i] = '\0';
            filename += i + 1;
            i = -1; // reset loop
        }
    }

    for (int i = 0; ; i++) {
        if (filename[i] == '.') break;
        if (!basename) basename = malloc(i + 1);
        memcpy(basename, filename, i);
        basename[i] = '\0';
        filename += i + 1;
        i = -1; // reset loop
    }

    for (int i = 0; ; i++) {
        if (filename[i] == '\0') break;
        extension = &filename[i];
        break;
    }

    int length = strlen(basename);
    char *newextension = malloc(length + 20); // allocate space for dynamic extension

    sprintf(newextension, "%s_%x", basename, rand());
    free(basename);

    // generate file type based on directory path
    if (!directory) {
        free(extension);
        return NULL;
    }

    const char *lastsegment = strrchr(directory, '/');
    if (lastsegment && strlen(lastsegment) > 0) {
        char *filetype = malloc(strlen(lastsegment) + 5); // allocate space for file type
        sprintf(filetype, "._%s", lastsegment);
        free(directory);

        // construct new filename
        char *newfilename = malloc(length + strlen(newextension) + strlen(filetype) + 2);
        sprintf(newfilename, "%s%s.%s", newextension, filetype, extension ? extension : "");
        free(newextension);
        free(filetype);
        return newfilename;
    } else {
        free(extension);
        return NULL;
    }
}
