#define MAX_CACHE_DURATION 3600 // 1 hour in seconds

typedef struct {
    char *api_key;
    char *endpoint_url;
    int api_version;
    char **query_strings;
    size_t query_string_count;
    char **headers;
    size_t header_count;
} Config;

Config *parse_config(const char *json_data) {
    json_object *config_json = json_object_from_string(json_data);

    if (!config_json) {
        return NULL;
    }

    Config *config = (Config *)malloc(sizeof(Config));

    config->api_key = json_object_get_string(config_json, "api_key");
    if (!config->api_key || strlen(config->api_key) == 0) {
        free(config);
        return NULL;
    }

    config->endpoint_url = json_object_get_string(config_json, "endpoint_url");
    if (!config->endpoint_url || strlen(config->endpoint_url) == 0) {
        free(config);
        return NULL;
    }

    config->api_version = json_object_get_int(config_json, "api_version");
    if (config->api_version < 1 || config->api_version > 2) { // supported versions: 1.0, 1.1
        free(config);
        return NULL;
    }

    size_t query_string_count = json_object_array_length(config_json, "query_strings");
    config->query_string_count = query_string_count;
    config->query_strings = (char **)malloc(query_string_count * sizeof(char *));
    for (size_t i = 0; i < query_string_count; i++) {
        config->query_strings[i] = json_object_get_string(config_json, fmt("query_strings[%zu]", i));
    }

    size_t header_count = json_object_array_length(config_json, "headers");
    config->header_count = header_count;
    config->headers = (char **)malloc(header_count * sizeof(char *));
    for (size_t i = 0; i < header_count; i++) {
        config->headers[i] = json_object_get_string(config_json, fmt("headers[%zu]", i));
    }

    free(json_object_get_string(config_json, "query_strings"));
    free(json_object_get_string(config_json, "headers"));
    json_object_put(config_json);

    return config;
}

int validate_config(const Config *config) {
    if (!config->api_key || strlen(config->api_key) == 0) {
        return 0; // missing or empty API key
    }

    if (!config->endpoint_url || strlen(config->endpoint_url) == 0) {
        return 0; // missing or empty endpoint URL
    }

    if (config->api_version < 1 || config->api_version > 2) { // unsupported API version
        return 0;
    }

    for (size_t i = 0; i < config->query_string_count; i++) {
        if (!config->query_strings[i] || strlen(config->query_strings[i]) == 0) {
            return 0; // missing or empty query string
        }
    }

    for (size_t i = 0; i < config->header_count; i++) {
        if (!config->headers[i] || strlen(config->headers[i]) == 0) {
            return 0; // missing or empty header
        }
    }

    return 1;
}

void cache_config(Config *config, time_t expiration_time) {
    // implement caching mechanism here
}

