void* parseAndProcessRecords(void* arg) {
    FILE* file = fopen("transactions.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening file.\n");
        exit(EXIT_FAILURE);
    }

    int* transaction_ids = malloc(sizeof(int) * TRANSACTION_ID_ARRAY_SIZE);
    double* transaction_amounts = malloc(sizeof(double) * TRANSACTION_AMOUNT_ARRAY_SIZE);
    transaction_record* records = malloc(sizeof(transaction_record) * TRANSACTION_RECORD_ARRAY_SIZE);

    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    int record_index = 0;
    while (fgets(line, MAX_FILE_SIZE, file)) {
        // Parse and validate transaction data
        char* token = strtok(line, "\t");
        if (!token) continue;

        transaction_ids[record_index] = atoi(token);
        token = strtok(NULL, "\t");
        if (!token) continue;
        strcpy(records[record_index].date, token);

        token = strtok(NULL, "\t");
        if (!token) continue;
        records[record_index].amount = atof(token);

        token = strtok(NULL, "\t");
        if (!token) continue;
        strcpy(records[record_index].status, token);

        record_index++;
    }

    fclose(file);

    // Normalize dates and filter invalid transactions
    for (int i = 0; i < record_index; i++) {
        // Normalize date fields
        // ...

        // Filter out invalid transactions
        if (...) {
            transaction_ids[i] = -1;
            records[i].amount = -1.0;
        }
    }

    // Sort transactions by date in ascending order
    pthread_sort(records, record_index);

    free(transaction_ids);
    free(transaction_amounts);
    free(records);

    return NULL;
}

int main() {
    int num_threads = 20;

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, parseAndProcessRecords, NULL);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
