#define ID_SIZE 2048

struct dataPoint {
    double value;
    float id;
};

void* batchProcessAndAggregateResults(void* arg) {
    int i, j;
    struct dataPoint* dataPoints = (struct dataPoint*)malloc(NUM_DATAPOINTS * sizeof(struct dataPoint));
    double* offsetValues = (double*)malloc(OFFSET_SIZE * sizeof(double));
    float* identifiers = (float*)malloc(ID_SIZE * sizeof(float));

    if (!dataPoints || !offsetValues || !identifiers) {
        printf("Error: Memory allocation failed!\n");
        exit(-1);
    }

    // Populate data points
    for (i = 0; i < NUM_DATAPOINTS; i++) {
        dataPoints[i].id = (float)(rand() / (RAND_MAX + 1.0f));
    }

    // Calculate mean and standard deviation of offset values
    double sum = 0;
    double sumSquare = 0;
    for (i = 0; i < OFFSET_SIZE; i++) {
        sum += offsetValues[i];
        sumSquare += pow(offsetValues[i], 2);
    }
    double mean = sum / OFFSET_SIZE;
    double variance = (sumSquare / OFFSET_SIZE) - pow(mean, 2);

    // Print results
    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", sqrt(variance));

    free(dataPoints);
    free(offsetValues);
    free(identifiers);

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, batchProcessAndAggregateResults, NULL);
    pthread_join(thread, NULL);
    return 0;
}
