    if (n == 0) {
        printf("No integers provided.\n");
    } else {
        int max = integers[0];

        for (int i = 1; i < n; i++) {
            if (integers[i] > max) {
                max = integers[i];
            }
        }

        printf("Largest integer: %d\n", max);
    }
}

