    stats->events = malloc(event_count * sizeof(void*));

    // Populate the NetworkStatistics structure from the raw data buffer
    for (int i = 0; i < event_count; i++) {
        stats->events[i] = (void*)malloc(sizeof(int)); // Assuming each event is an int
        *(int*)stats->events[i] = buffer[i];
    }

    return stats;
}

// Function to filter and retrieve statistics by network ID or timestamp range
NetworkStatistics* get_statistics(NetworkStatistics* stats, char* target_id, time_t start_timestamp, time_t end_timestamp) {
    // Iterate over the events array in the NetworkStatistics structure
    for (int i = 0; i < *(size_t*)stats->events; i++) {
        if (strcmp(stats->id, target_id) == 0 || stats->timestamp >= start_timestamp && stats->timestamp <= end_timestamp) {
            // Return a new NetworkStatistics structure containing the filtered event
            return (NetworkStatistics*)malloc(sizeof(NetworkStatistics));
        }
    }

    return NULL;
}

