void* grow_array(void** arr, size_t* size, size_t max_size) {
    if (*size >= max_size)
        return *arr;

    *size *= 2;
    void* new_arr = realloc(*arr, *size * sizeof(int));
    if (!new_arr) {
        printf("Error: Array resizing failed.\n");
        exit(1);
    }
    *arr = new_arr;
