namespace CSVProcessor {
    class FactorialCSVHandler {
    public:
        static const int MAX_LINE_SIZE = 1024;
        static std::mt19937 randomGenerator;

        void processCSV(const char* filename) {
            std::ifstream file(filename);
            if (!file.is_open()) {
                std::cerr << "Error opening file: " << filename << std::endl;
                return;
            }

            int lineCount = 0;
            while (file.good()) {
                std::string line;
                getline(file, line, '\n');
                if (line.empty()) break;

                lineCount++;
                double sum = 0.0;
                size_t pos = 0;
                std::vector<double> rowData(MAX_LINE_SIZE / sizeof(double));
                sscanf(line.c_str(), "%lf%*c", &rowData[0]);
                for (size_t i = 1; i < rowData.size(); ++i) {
                    sscanf(&line[pos], "%lf%n", &rowData[i], &pos);
                    sum += rowData[i];
                }

                double factorial = calculateFactorial(lineCount);
                double integratedResult = factorial * sum;
                std::cout << "Integrated result for row " << lineCount << ": " << integratedResult << std::endl;

                delete[] rowData.data();
            }
        }

    private:
        static double calculateFactorial(int n) {
            double result = 1.0;
            for (int i = 2; i <= n; ++i) {
                result *= i;
            }
            return result;
        }
    };

    std::mt19937 CSVProcessor::FactorialCSVHandler::randomGenerator(std::time(nullptr));
}

int main() {
    CSVProcessor::FactorialCSVHandler handler;
    handler.processCSV("input.csv");
    return 0;
}
