#define NUM_RECORDS 512
#define NUM_THREADS 10
#define MIN_KEY 10
#define MAX_KEY 100
#define ALLOC_SIZE 1024

typedef struct {
    int key;
    int value;
    time_t timestamp;
    pthread_mutex_t lock;
} record_t;

record_t *records = NULL;
int *long_offsets = NULL;
int *keys = NULL;
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

void processAndFindMax() {
    // Step 1: Allocate memory for arrays
    long_offsets = (int *)malloc(ALLOC_SIZE * sizeof(int));
    keys = (int *)malloc(ALLOC_SIZE * sizeof(int));
    records = (record_t *)calloc(NUM_RECORDS, sizeof(record_t));

    if (!long_offsets || !keys || !records) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Step 2: Initialize arrays
    for (int i = 0; i < ALLOC_SIZE; i++) {
        long_offsets[i] = i;
        keys[i] = rand() % (MAX_KEY - MIN_KEY) + MIN_KEY;
    }

    // Step 3: Populate record structures
    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].key = rand() % (MAX_KEY - MIN_KEY) + MIN_KEY;
        records[i].timestamp = time(NULL);
    }
    pthread_mutex_unlock(&records_lock);

    // Step 4: Sort records
    int (*sort_func)(void *) = &mergeSort;
    void *args[2] = {&keys, NULL};
    pthread_create(&pthread_sort, NULL, (void *(*)(void *))sort_func, args);
    pthread_join(pthread_sort, NULL);

    // Step 5: Release resources
    free(long_offsets);
    free(keys);
    free(records);
}

int mergeSort(void *args) {
    int *arr = (int *)args;
    int left = 0;
    int right = ALLOC_SIZE - 1;

    while (left < right) {
        int mid = (left + right) / 2;
        int temp[ALLOC_SIZE];
        int k = 0;
        for (int i = left; i <= mid; i++) {
            temp[k] = arr[i];
            k++;
        }
        for (int i = mid + 1; i <= right; i++) {
            temp[k] = arr[i];
            k++;
        }

        // Merge
        int i = 0, j = k - 1;
        for (k--; i <= j; i++, j--) {
            if (temp[i] < temp[j]) {
                arr[left++] = temp[i];
                i++;
            } else {
                arr[left++] = temp[j];
                j--;
            }
        }

        while (i <= k) {
            arr[left++] = temp[i++];
        }
    }

    return 0;
}
