#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define JOB_QUEUE_SIZE 1000
#define MEMORY_CAP 1024 * 1024 * 10 // 10MB
#define WORKER_META_SIZE sizeof(struct worker_metadata)
#define LOG_FORMAT "%s: %d - %s\n"

typedef struct {
    int id;
    time_t last_completion_timestamp;
    int status; // 0: available, 1: busy
} worker_metadata;

struct job_queue {
    int size;
    int head;
    int tail;
    struct job *jobs[JOB_QUEUE_SIZE];
};

struct job {
    int id;
    char *data;
    time_t start_time;
    time_t end_time;
    int status; // 0: pending, 1: in_progress, 2: completed
};

void init_job_queue(struct job_queue *queue) {
    queue->size = JOB_QUEUE_SIZE;
    queue->head = 0;
    queue->tail = 0;
}

worker_metadata* allocate_worker_metadata(int num_workers) {
    worker_metadata *metadata = (worker_metadata *)malloc(num_workers * WORKER_META_SIZE);
    for (int i = 0; i < num_workers; i++) {
        metadata[i].id = i;
        metadata[i].last_completion_timestamp = time(NULL);
        metadata[i].status = 0; // available
    }
    return metadata;
}

void init_worker_metadata(worker_metadata *metadata, int num_workers) {
    for (int i = 0; i < num_workers; i++) {
        metadata[i].current_load = 0;
    }
}

struct job_queue* allocate_job_queue(int num_jobs) {
    struct job_queue *queue = (struct job_queue *)malloc(sizeof(struct job_queue));
    queue->size = num_jobs;
    queue->head = 0;
    queue->tail = 0;
    return queue;
}

void enqueue_job(struct job_queue *queue, int job_id, char *data) {
    struct job *job = (struct job *)malloc(sizeof(struct job));
    job->id = job_id;
    job->data = data;
    job->start_time = time(NULL);
    job->end_time = 0;
    job->status = 0; // pending
    queue->jobs[queue->tail] = job;
    queue->tail = (queue->tail + 1) % queue->size;
}

int dequeue_job(struct job_queue *queue) {
    if (queue->head == queue->tail) return -1; // empty queue
    struct job *job = queue->jobs[queue->head];
    queue->head = (queue->head + 1) % queue->size;
    free(job);
    return 0;
}

void shutdown_job_queue(struct job_queue *queue) {
    while (!is_empty(queue)) dequeue_job(queue);
}
