// Sort Records based on their 'int' Key Values Function
void sort_records(int** records, int record_count) {
    // Custom sorting algorithm optimized for minimizing cache misses
    for (int i = 0; i < record_count - 1; i++) {
        for (int j = 0; j < record_count - i - 1; j++) {
            if (records[j][1] > records[j + 1][1]) {
                // Swap elements
                int temp = records[j][1];
                records[j][1] = records[j + 1][1];
                records[j + 1][1] = temp;
            }
        }
    }
}

