Item* addItem(Item* head, char* str, int num) {
    Item* newNode = (Item*)malloc(sizeof(Item));
    newNode->str = strdup(str);
    newNode->num = num;
    newNode->next = head;
    return newNode;
}

Processor* initItems(Processor* processors, int numItemsPerProcessor) {
    for (int i = 0; i < numProcessors; i++) {
        Processor* processor = &processors[i];
        Item* current = NULL;
        for (int j = 0; j < numItemsPerProcessor; j++) {
            char str[10];
            sprintf(str, "Item %d", j);
            current = addItem(current, str, rand() % 100);
        }
        processor->head = current;
    }
    return processors;
}

void freeSystem(Processor* processors) {
    for (int i = 0; i < numProcessors; i++) {
        Processor* processor = &processors[i];
        Item* current = processor->head;
        while (current != NULL) {
            Item* next = current->next;
            free(current->str);
            free(current);
            current = next;
        }
    }
    free(processors);
}
