                // Handle error
                std::cerr << "Error: " << ec.message() << std::endl;
            }
        };
        timer.expires_after(std::chrono::milliseconds(100));
        timer.async_wait(callback);
    }

    // Deallocate memory
    delete[] offsets;
    delete[] keys;
    delete[] records;

    return 0;
}
