// Custom memory pool management
typedef struct {
    void* ptr;
    size_t size;
} MemoryBlock;

MemoryBlock* mem_pool = NULL;
size_t mem_pool_size = 0;
size_t mem_block_count = 0;

void* mem_alloc(size_t size) {
    if (mem_pool == NULL || mem_pool_size < size) {
        // Reallocate memory pool if necessary
        mem_pool = realloc(mem_pool, (mem_pool_size + size) * sizeof(MemoryBlock));
        mem_pool_size += size;
        mem_block_count++;
    }
    return (void*) ((char*) mem_pool + mem_pool_size - size);
}

int mem_free(void* ptr) {
    // Find the corresponding memory block in the pool
    for (size_t i = 0; i < mem_block_count; i++) {
        if (((char*) mem_pool + i * sizeof(MemoryBlock)) == (char*) ptr) {
            // Mark the block as free and move remaining blocks forward
            ((MemoryBlock*) ptr)->ptr = NULL;
            mem_pool_size -= sizeof(MemoryBlock);
            for (size_t j = i; j < mem_block_count - 1; j++) {
                mem_pool[j] = mem_pool[j + 1];
            }
            mem_block_count--;
            return 0;
        }
    }
    // Error: pointer not found in memory pool
    return -1;
}

// Struct node definition
typedef struct Node {
    double value;
    char identifier;
    struct Node* next;
} Node;

Node* head = NULL;

void insert_node(double value, char identifier) {
    Node* new_node = (Node*) mem_alloc(sizeof(Node));
    new_node->value = value;
    new_node->identifier = identifier;
    if (head == NULL || value < head->value) {
        new_node->next = head;
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->value >= value) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

int init_memory() {
    if (mem_alloc(sizeof(Node)) == NULL) {
        // Log allocation failure and handle fallback
        printf("Memory allocation failed. Fallback mechanism activated.\n");
        return -1;
    }
    return 0;
}

