#define MAX_RECORDS 1000

// Define the record structure with an int value and a reference to an offset
typedef struct {
    int value;
    long offset;
} record;

// Initialize the pool of offset values
long* initOffsetPool(int maxOffset) {
    long* offsets = (long*)malloc((maxOffset + 1) * sizeof(long));
    for (int i = 0; i <= maxOffset; i++) {
        offsets[i] = i;
    }
    return offsets;
}

// Allocate memory for an array of int keys
int** allocateKeyArray(int numKeys, long* offsets) {
    int** keyArray = (int**)malloc(numKeys * sizeof(int*));
    for (int i = 0; i < numKeys; i++) {
        keyArray[i] = (int*)malloc(sizeof(int));
        *keyArray[i] = offsets[i];
    }
    return keyArray;
}

// Allocate memory for an array of record structures
record** allocateRecordArray(int numRecords, long* offsets) {
    record** recordArray = (record**)malloc(numRecords * sizeof(record*));
    for (int i = 0; i < numRecords; i++) {
        recordArray[i] = (record*)malloc(sizeof(record));
        recordArray[i]->value = rand() % 100;
        recordArray[i]->offset = offsets[i];
    }
    return recordArray;
}

// Thread-safe mechanism for concurrent access
pthread_mutex_t lock;

void* allocateMemory(void* arg) {
    pthread_mutex_lock(&lock);
    // Allocate memory and perform operations
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    int maxOffset = 1000;
    long* offsets = initOffsetPool(maxOffset);
    int numKeys = 500;
    int** keyArray = allocateKeyArray(numKeys, offsets);
    int numRecords = 1000;
    record** recordArray = allocateRecordArray(numRecords, offsets);

    pthread_mutex_init(&lock, NULL);
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, allocateMemory, NULL);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    free(offsets);
    for (int i = 0; i < numKeys; i++) {
        free(keyArray[i]);
    }
    free(keyArray);
    for (int i = 0; i < numRecords; i++) {
        free(recordArray[i]);
    }
    free(recordArray);

    pthread_mutex_destroy(&lock);
    return 0;
}
