void aggregateMetrics(struct node** head, struct metric_data* data) {
    // Group metrics by type and calculate summary statistics
    for (int i = 0; i < 3; i++) {
        int sum = 0;
        double avg = 0;

        // Calculate average and median for each group
        for (struct node* current = *head; current != NULL; current = current->next) {
            if (current->type == i) {
                sum += current->value;
                avg = (double)sum / (i + 1);
            }
        }

        // Print daily summary
        printf("Summary for type %d: average=%f, median=%f\n", i, avg, avg);
    }

    return;
}

