typedef struct {
    double x;
    double y;
} point;

typedef struct {
    double value;
    char str[MAX_STRING_LENGTH];
    point pnt;
} record;

record* records = NULL;
int num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void read_records_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return;

    pthread_mutex_lock(&mutex);
    int i = 0;
    while (1) {
        record temp;
        fscanf(file, "%lf,%s,(%lf,%lf)", &temp.value, temp.str, &temp.pnt.x, &temp.pnt.y);
        if (ferror(file)) break;

        records = realloc(records, (num_records + 1) * sizeof(record));
        memcpy(&records[num_records], &temp, sizeof(temp));
        num_records++;
    }
    pthread_mutex_unlock(&mutex);

    fclose(file);
}

void filter_records(double threshold) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].value >= threshold)
            printf("%lf,%s,(%lf,%lf)\n", records[i].value, records[i].str, records[i].pnt.x, records[i].pnt.y);
    }
}

void free_resources() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_records; i++) {
        free(records[i].str);
        free(&records[i]);
    }
    free(records);
    pthread_mutex_unlock(&mutex);
}

int main(int argc, char* argv[]) {
    read_records_from_file("input.txt");
    filter_records(3.5);

    free_resources();
    return 0;
}
