        array_double[i] = 0.0;
        array_char[i] = (char*)malloc(33 * sizeof(char));
        array_point[i].x = 0.0;
        array_point[i].y = 0.0;
    }

    // Print confirmation
    printf("Arrays allocated and initialized successfully.\n");

    free(array_double);
    free(array_char);
    for(int i=0; i<*size; i++) {
        free(array_char[i]);
    }
}

int allocate_and_initialize_records(record** records, int* size) {
    // Allocate memory for array of 'record' structures
    *records = (record*)malloc(*size * sizeof(record));

    if(*records == NULL) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Initialize array
    for(int i=0; i<*size; i++) {
        (*records)[i].value = 0.0;
        strcpy((*records)[i].str, "");
        (*records)[i].p.x = 0.0;
        (*records)[i].p.y = 0.0;
    }

    // Print confirmation
    printf("Records allocated and initialized successfully.\n");

    return 0;
}

int read_and_filter_records(record** records, int* size) {
    FILE* file = fopen("input.txt", "r");
    if(file == NULL) {
        printf("File not found or unable to open.\n");
        return -1;
    }

    double threshold_value = 10.0;

    // Read and filter records
    for(int i=0; i<*size; i++) {
        fscanf(file, "%lf,%s,%lf,%lf\n", &((*records)[i].value), (*records)[i].str, &((*records)[i].p.x), &((*records)[i].p.y));
        if((*records)[i].value < threshold_value) {
            for(int j=i; j<*size-1; j++) {
                records[j] = records[j+1];
            }
            *size -= 1;
            i--;
        }
    }

    fclose(file);

    return 0;
}

void cleanup_resources(record** records, int* size) {
    // Free allocated memory
    for(int i=0; i<*size; i++) {
        free(((record*)records)[i].str);
    }
    free(*records);

    // Print confirmation
    printf("Resources cleaned up successfully.\n");
}

int main() {
    int array_size = 2048;
    int record_size = 1024;

    allocate_and_initialize_arrays(&array_size);
    record* records = NULL;
    if(allocate_and_initialize_records(&records, &record_size) == -1) {
        return -1;
    }

    read_and_filter_records(&records, &record_size);

    cleanup_resources(&records, &record_size);

    return 0;
}
