            if (desiredNode == null || root.SelectNodes("/root/element[@name='desired']").Count > 1)
            {
                Console.WriteLine("Error: Desired element not found or appears more than once.");
                return IntPtr.Zero;
            }
        }
        catch (Exception ex)
        {
