        byte[] desKey = new byte[keySize / 8];
        using (RNGCryptoServiceProvider crypto = new RNGCryptoServiceProvider())
        {
            crypto.GetBytes(desKey);
        }

        // Choose the desired cipher mode
        string cipherMode = "ECB"; // default mode

