        int[,] parent = new int[0, 2];
        int[,] rank = new int[0, 2];

        void union(int x, int y)
        {
            if (parent.GetLength(0) == 0)
            {
                parent = new int[1, 2] { { x, y } };
                rank = new int[1, 2];
            }
            else
            {
                for (int i = 0; i < parent.GetLength(0); i++)
                {
                    if (parent[i, 0] == x)
