typedef struct record {
    int key;
    long offset;
    time_t timestamp;
    char id[16];
} record;

record* processAndFindMax(int numRecords) {
    // Initialize random number generator with current time
    srand(time(NULL));

    // Allocate memory for arrays
    record* records = (record*)malloc(numRecords * sizeof(record));
    long* offsetValues = (long*)malloc(1024 * sizeof(long));
    int* keys = (int*)malloc(1024 * sizeof(int));

    if (!records || !offsetValues || !keys) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % 91 + 10;
        strcpy(records[i].id, "record-");
        sprintf("%s%d", records[i].id, i);
        records[i].timestamp = time(NULL);
    }

    // Sort records based on their 'int' key values
    qsort(records, numRecords, sizeof(record), compare);

    free(offsetValues);
    free(keys);
    return records;
}

int compare(const void* a, const void* b) {
    record* ra = (record*)a;
    record* rb = (record*)b;
    if (ra->key < rb->key)
        return -1;
    else if (ra->key > rb->key)
        return 1;
    return 0;
}
