const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Set up subscription limits
const maxSubscriptionsPerUser = 10;

// Set up subscription grouping categories
const categories = ['Sports', 'Arts', 'Music'];

// Handle subscription creation
app.post('/subscriptions', async (req, res) => {
    try {
        const { userId, categoryId, eventId } = req.body;
        if (!userId || !categoryId || !eventId) {
            return res.status(400).send({ error: 'Invalid request' });
        }
        // Check if user has exceeded subscription limits
        if (await Subscription.count({ where: { userId } }) >= maxSubscriptionsPerUser) {
            return res.status(402).send({ error: 'Subscription limit reached' });
        }
        // Create new subscription
        await Subscription.create({ userId, categoryId, eventId });
        return res.send({ message: 'Subscription created successfully' });
    } catch (err) {
        console.error(err);
        return res.status(500).send({ error: 'Internal server error' });
    }
});

// Handle subscription update
app.put('/subscriptions/:id', async (req, res) => {
    try {
        const { id } = req.params;
        const { categoryId, eventId } = req.body;
        // Check if subscription exists
        const subscription = await Subscription.findByPk(id);
        if (!subscription) {
            return res.status(404).send({ error: 'Subscription not found' });
        }
        // Update subscription category or event
        await subscription.update({ categoryId, eventId });
        return res.send({ message: 'Subscription updated successfully' });
    } catch (err) {
        console.error(err);
        return res.status(500).send({ error: 'Internal server error' });
    }
});

// Handle subscription removal
app.delete('/subscriptions/:id', async (req, res) => {
    try {
        const { id } = req.params;
        // Check if subscription exists
        const subscription = await Subscription.findByPk(id);
        if (!subscription) {
            return res.status(404).send({ error: 'Subscription not found' });
        }
        // Remove subscription
        await subscription.destroy();
        return res.send({ message: 'Subscription removed successfully' });
    } catch (err) {
        console.error(err);
        return res.status(500).send({ error: 'Internal server error' });
    }
});

// Handle listing subscriptions
app.get('/subscriptions', async (req, res) => {
    try {
        const { userId, categoryId, eventId } = req.query;
        // Filter subscriptions by user ID, category, or event
        const subscriptions = await Subscription.findAll({
            where: { [userId ? 'userId' : '']: userId, [categoryId ? 'categoryId' : '']: categoryId, [eventId ? 'eventId' : '']: eventId }
        });
        return res.send(subscriptions);
    } catch (err) {
        console.error(err);
        return res.status(500).send({ error: 'Internal server error' });
    }
});

// Handle subscription expiration
setInterval(() => {
    Subscription.destroy({
        where: {
            expiresAt: { [Op.lt]: new Date() }
        }
    }).then(() => {
        // Update notification queue with expired subscriptions
    });
}, 1000 * 60 * 60); // Check for expired subscriptions every hour

// Handle event notifications
app.post('/events', async (req, res) => {
    try {
        const { eventId, userId } = req.body;
        // Notify user of new event
        await notificationService.notify({ userId, eventId });
        return res.send({ message: 'Event notification sent successfully' });
    } catch (err) {
        console.error(err);
        return res.status(500).send({ error: 'Internal server error' });
    }
});

app.listen(3000, () => {
    console.log('Server started on port 3000');
});
