    if (!records) {
        printf("Error: Memory allocation failed.\n");
        exit(-1);
    }
}

// Set the value of each record's int field to a random value within a specified range
void set_record_values(record_t* records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].key = rand() % 100 + 10;
    }
}

// Sort the records based on their 'int' key values in ascending order
void sort_records(record_t* records, int size) {
    // Use quicksort algorithm for efficient sorting
    void swap(record_t* x, record_t* y) {
        record_t temp = *x;
        *x = *y;
        *y = temp;
    }

    void qsort(record_t* start, record_t* end) {
        if (start >= end)
            return;

        record_t pivot = *((end - 1));
        int i = (start);
        for (record_t* p = &(*start); p <= (&(pivot)); p++) {
        }
        swap(&(*p), &(pivot));
        p++;

        for (record_t* j = start; j < (p - 1); j++) {
            if ((*j).key <= pivot.key) {
                swap(&(*i), &(*j));
                i++;
            }
        }
        swap(&(*p-1), &(*i));
        qsort(start, p - 1);
        qsort(p, end);
    }

    qsort(records, records + size);
}

// Call the function from multiple threads
void* thread_func(void* arg) {
    // Create a copy of the record array for each thread
    int size = 512;
    record_t* records = init_records(size);

    // Set the value of each record's int field to a random value within a specified range
    set_record_values(records, size);

    // Sort the records based on their 'int' key values in ascending order
    sort_records(records, size);

    free(records);

    return NULL;
}

int main() {
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
