#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 512
#define RECORD_KEY_MIN 10
#define RECORD_KEY_MAX 100

typedef struct {
    int key;
} record_t;

record_t* allocate_records(int initial_size) {
    record_t* records = (record_t*)malloc(initial_size * sizeof(record_t));
    if (!records) {
        printf("Error: cannot allocate %d records\n", initial_size);
        return NULL;
    }
    for (int i = 0; i < initial_size; i++) {
        records[i].key = -1; // Initialize with invalid key
    }
    return records;
}

void validate_allocation(void* ptr) {
    if (!ptr) {
        printf("Error: allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

record_t** allocate_arrays(int offset_size, int key_size) {
    record_t** arrays = (record_t**)malloc(2 * sizeof(record_t*));
    validate_allocation(arrays);

    arrays[0] = (record_t*)malloc(offset_size * sizeof(record_t));
    validate_allocation(arrays[0]);

    arrays[1] = (record_t*)malloc(key_size * sizeof(record_t));
    validate_allocation(arrays[1]);

    return arrays;
}

void sort_records(record_t* records, int size) {
    record_t temp;
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            if (records[i].key > records[j].key) {
                temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
}

void set_record_values(record_t* records, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        while (1) {
            int key = rand() % (RECORD_KEY_MAX - RECORD_KEY_MIN + 1) + RECORD_KEY_MIN;
            record_t* existing_record = find_record(records, size, key);
            if (!existing_record) break; // Found a unique key
            printf("Collision detected. Regenerating key...\n");
        }
        records[i].key = key;
    }
}

record_t* find_record(record_t* records, int size, int key) {
    for (int i = 0; i < size; i++) {
        if (records[i].key == key) return &records[i];
    }
    return NULL;
}

void cleanup_allocation(void* ptr) {
    if (!ptr) return;
    free(ptr);
}

int main() {
    int offset_size = 1024, key_size = 1024;
    record_t** arrays = allocate_arrays(offset_size, key_size);

    int records_size = MAX_RECORDS;
    record_t* records = allocate_records(records_size);

    set_record_values(records, records_size);

    sort_records(records, records_size);

    // Cleanup resources
    cleanup_allocation(arrays[0]);
    cleanup_allocation(arrays[1]);
    free(records);
    return 0;
}
