#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <rand.h>

// Define the product structure
typedef struct {
    char* name;
    int quantity;
    float price;
    double weight;
} Product;

// Function to initialize a product with random values
Product* init_product(const char* name) {
    Product* product = (Product*)malloc(sizeof(Product));
    if (!product) return NULL; // Handle allocation error

    product->name = strdup(name);
    if (!product->name) return NULL; // Handle allocation error

    int quantity = rand() % 91 + 10;
    float price = (float)rand() / RAND_MAX * 45.0 + 5.0;

    product->quantity = quantity;
    product->price = price;
    product->weight = (double)rand() / RAND_MAX * 90.0 + 10.0;

    return product;
}

// Function to add a new product to the list
void add_product(Product** products, int* size, const char* name) {
    Product* new_product = init_product(name);
    if (!new_product) return; // Handle allocation error

    if (*size == 0 || *size % 10 == 0) { // Dynamically resize the array when necessary
        *products = (Product**)realloc(*products, (*size + 10) * sizeof(Product*));
        if (!(*products)) return; // Handle allocation error
        memset(&((*products)[*size]), 0, sizeof(Product)); // Initialize new slots to zero
    }

    (*products)[*size] = new_product;
    (*size)++;
}

// Function to calculate the total value of all products in the list
double calculate_total_value(Product** products, int size) {
    double total_value = 0.0;

    for (int i = 0; i < size; i++) {
        total_value += products[i]->quantity * products[i]->price;
    }

    return total_value;
}
