#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the data point structure
typedef struct {
    long offset;
    int key;
    float value;
    struct item* ptr;
} data_point;

// Define the processor structure
typedef struct {
    data_point** items;
    int size;
} processor;

// Custom memory pool structure
typedef struct {
    void** blocks;
    int size;
    pthread_mutex_t mutex;
} memory_pool;

// Initialize and return a new memory pool with the given size
memory_pool* create_memory_pool(int size) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    pool->blocks = (void**)malloc(size * sizeof(void*));
    pool->size = size;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Reclaim memory from the pool and free it
void destroy_memory_pool(memory_pool* pool) {
    for (int i = 0; i < pool->size; i++) {
        if (pool->blocks[i] != NULL) {
            free(pool->blocks[i]);
        }
    }
    free(pool->blocks);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

// Initialize and return a new processor with the given size
processor* create_processor(int size, memory_pool* pool) {
    processor* proc = (processor*)malloc(sizeof(processor));
    proc->items = (data_point**)malloc(size * sizeof(data_point*));
    proc->size = size;
    for (int i = 0; i < size; i++) {
        proc->items[i] = NULL;
    }
    return proc;
}

// Reclaim memory from the processor and free it
void destroy_processor(processor* proc) {
    for (int i = 0; i < proc->size; i++) {
        if (proc->items[i] != NULL) {
            free(proc->items[i]->ptr);
            free(proc->items[i]);
        }
    }
    free(proc->items);
    free(proc);
}

// Initialize and return a new data point with random values
data_point* create_data_point(memory_pool* pool) {
    data_point* dp = (data_point*)malloc(sizeof(data_point));
    dp->offset = rand();
    dp->key = rand() % 91 + 10;
    dp->value = ((double)rand()) / RAND_MAX * 100.0;
    dp->ptr = malloc(strlen("Random string") + 1);
    strcpy(dp->ptr, "Random string");
    return dp;
}

// Sort the data points by their integer key and then by their double value
void sort_data_points(data_point* points, int size) {
    qsort(points, size, sizeof(data_point), (int (*)(const void*, const void*))data_point_compare);
}

// Compare two data points for sorting
int data_point_compare(const void* a, const void* b) {
    data_point* pointA = *(data_point*)a;
    data_point* pointB = *(data_point*)b;
    if (pointA->key < pointB->key) return -1;
    else if (pointA->key > pointB->key) return 1;
    else if (pointA->value > pointB->value) return -1;
    else if (pointA->value < pointB->value) return 1;
    else return 0;
}

// Main function to manage the dataset
void* manage_dataset(void* arg) {
    memory_pool* pool = create_memory_pool(2048);
    processor* proc = create_processor(1024, pool);

    // Initialize and populate the data points
    data_point* points = (data_point*)malloc(sizeof(data_point) * 2048);
    for (int i = 0; i < 2048; i++) {
        points[i] = create_data_point(pool);
    }

    // Sort the data points
    sort_data_points(points, 2048);

    // Process the data points in the processor
    for (int i = 0; i < proc->size; i++) {
        proc->items[i] = &points[i];
    }

    // Clean up allocated memory
    destroy_processor(proc);
    destroy_memory_pool(pool);
    free(points);
}
