import os
import re
import concurrent.futures
from logging import Logger
from typing import List

class LogProcessor:
    def __init__(self, directory: str, keyword_patterns: List[str]):
        self.directory = directory
        self.keyword_patterns = keyword_patterns
        self.summary_report = {}
        self.logger = Logger(__name__)

    async def process_log_files(self) -> None:
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = [executor.submit(process_log_file, os.path.join(self.directory, file), self.keyword_patterns) for file in os.listdir(self.directory)]
            for future in concurrent.futures.as_completed(futures):
                try:
                    result = await future
                except Exception as e:
                    self.logger.error(f"Error processing log file: {e}")

        print(self.summary_report)

async def process_log_file(file_path: str, keyword_patterns: List[str]) -> int:
    with open(file_path, 'r') as file:
        contents = file.read()

    for pattern in keyword_patterns:
        if re.search(pattern, contents):
            self.summary_report[pattern] = self.summary_report.get(pattern, 0) + 1

    return len(contents)

if __name__ == "__main__":
    log_processor = LogProcessor('/path/to/logs', ['pattern1', 'pattern2'])
    await log_processor.process_log_files()
