import java.util.concurrent.ConcurrentHashMap;
import java.time.Instant;

public class DataManagementSystem {
    private final ConcurrentHashMap<Long, DataEntry> dataEntries;
    private final Instant retentionTime;

    public DataManagementSystem(long initialCapacity) {
        this.dataEntries = new ConcurrentHashMap<>(initialCapacity);
        this.retentionTime = Instant.now().minusSeconds(3600); // Initial retention time: 1 hour
    }

    public void addDataEntry(DataEntry entry) {
        dataEntries.put(entry.getId(), entry);
    }

    public DataEntry getDataEntry(long id) {
        return dataEntries.get(id);
    }

    public void updateTimestamp(long id, Instant timestamp) {
        DataEntry entry = dataEntries.get(id);
        if (entry != null) {
            entry.setTimestamp(timestamp);
        }
    }

    public void updateLastAccessTime(long id, Instant lastAccessTime) {
        DataEntry entry = dataEntries.get(id);
        if (entry != null) {
            entry.setLastAccessTime(lastAccessTime);
        }
    }

    public void purgeOutdatedEntries() {
        for (Map.Entry<Long, DataEntry> entry : new java.util.ArrayList<>(dataEntries.entrySet())) {
            if (Instant.now().toEpochMilli() - entry.getValue().getLastAccessTime().toEpochMilli() > retentionTime.toEpochMilli()) {
                dataEntries.remove(entry.getKey());
            }
        }
    }

    public static class DataEntry {
        private long id;
        private String value;
        private Instant timestamp;
        private Instant lastAccessTime;

        public DataEntry(long id, String value, Instant timestamp) {
            this.id = id;
            this.value = value;
            this.timestamp = timestamp;
            this.lastAccessTime = timestamp;
        }

        public long getId() {
            return id;
        }

        public void setId(long id) {
            this.id = id;
        }

        public String getValue() {
            return value;
        }

        public void setValue(String value) {
            this.value = value;
        }

        public Instant getTimestamp() {
            return timestamp;
        }

        public void setTimestamp(Instant timestamp) {
            this.timestamp = timestamp;
        }

        public Instant getLastAccessTime() {
            return lastAccessTime;
        }

        public void setLastAccessTime(Instant lastAccessTime) {
            this.lastAccessTime = lastAccessTime;
        }
    }
}
