void processAndManageRecords(int* records, int count) {
    // Initialize memory pool
    int pool_size = 1024;
    void** pool = malloc(pool_size * sizeof(void*));
    sem_t* semaphore = sem_open("/my_semaphore", O_CREAT, 0, pool_size);

    if (!semaphore) {
        printf("Error creating semaphore\n");
        exit(1);
    }

    // Initialize arrays
    long* offsets = (long*)malloc(1024 * sizeof(long));
    int* keys = (int*)malloc(1024 * sizeof(int));
    record** records_array = (record**)malloc(512 * sizeof(record));

    for (int i = 0; i < pool_size; i++) {
        sem_wait(semaphore);
        void* allocated_memory = malloc(sizeof(record));
        if (!allocated_memory) {
            printf("Error allocating memory\n");
            exit(1);
        }
        pool[i] = allocated_memory;
        sem_post(semaphore);
    }

    // Validate memory allocation
    for (int i = 0; i < pool_size; i++) {
        record* record_allocated = (record*)pool[i];
        if (!record_allocated) {
            printf("Error allocating record\n");
            exit(1);
        }
    }

    // Populate records with random values
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        record* current_record = pool[i % pool_size];
        current_record->key = rand() % (100 - 10 + 1) + 10;
    }

    // Sort records based on key values
    qsort(records_array, count, sizeof(record), compare);

    // Print sorted records
    for (int i = 0; i < count; i++) {
        record* current_record = records_array[i];
        printf("%d %ld %s\n", current_record->key, current_record->unique_id, ctime(&current_record->timestamp));
    }

    // Clean up
    sem_close(semaphore);
    for (int i = 0; i < pool_size; i++) {
        free(pool[i]);
    }
    free(pool);
}

int compare(const void* a, const void* b) {
    record* record_a = *(record**)a;
    record* record_b = *(record**)b;

    if (record_a->key < record_b->key)
        return -1;
    else if (record_a->key > record_b->key)
        return 1;
    else
        return 0;
}
