int main() {
    // Read binary file and initialize arrays
    uint16_t capacity = MAX_CAPACITY;
    uint32_t total_elements = 0;

    FILE *file = fopen("data.bin", "rb");
    if (file == NULL) {
        fprintf(stderr, "Error opening file.\n");
        exit(1);
    }

    struct {
        uint16_t capacity;
        uint32_t total_elements;
    } header;
    fread(&header, sizeof(header), 1, file);
    capacity = header.capacity;
    total_elements = header.total_elements;

    record **offsets = (record **)my_malloc(capacity * sizeof(record *));
    for (int i = 0; i < capacity; i++) {
        offsets[i] = my_calloc(1, sizeof(record));
        fread(&offsets[i]->key, sizeof(int32_t), 1, file);
        fread(&offsets[i]->offset, sizeof(int32_t), 1, file);
    }

    int *keys = (int *)my_malloc(capacity * sizeof(int));
    for (int i = 0; i < capacity; i++) {
        fread(&keys[i], sizeof(int), 1, file);
    }

    // Populate array of record structures
    record *records = my_calloc(512, sizeof(record));
    // Read data from database query
    int num_records = 0;
    while (num_records < MAX_SIZE) {
        if (fread(&records[num_records], sizeof(record), 1, file) != 1) break;
        num_records++;
    }

    // Validate memory allocations and initialization
    for (int i = 0; i < capacity; i++) {
        if (offsets[i] == NULL || keys[i] == -1) {
            fprintf(stderr, "Error in memory allocation.\n");
            exit(1);
        }
    }

    // Randomly populate int field of each record structure
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 90 + 10;
    }

    // Sort the records based on their key values
    pthread_t threads[MAX_SIZE / 2];
    int thread_num = 0;
    while (thread_num < MAX_SIZE) {
        pthread_create(&threads[thread_num], NULL, sort_records, &records[0]);
        thread_num++;
    }

    for (int i = 0; i < thread_num; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the file
    fclose(file);

    return 0;
}
