    if (!longOffset || !intKey || !shortIdentifier || !records) {
        fprintf(stderr, "Memory allocation failed. Exiting.\n");
        exit(1);
    }

    // Initialize arrays with random values
    pthread_srand(pthread_self());
    for (int i = 0; i < 1024; i++) {
        records[i].offset = lrand48();
        records[i].key = rand() % 91 + 10;
        records[i].identifier = rand() % 91 + 10;
