    // Sort records
    for (int i = 0; i < 1024 - 1; i++) {
        for (int j = 0; j < 1024 - i - 1; j++) {
            if (records[j].key > records[j + 1].key) {
                record_t temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }

    // Release memory
    free(longOffset);
    free(intKey);
    free(shortIdentifier);
    free(records);

    return NULL;
}

int main() {
    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        int* args = &i;
        if (pthread_create(&threads[i], NULL, processAndFindMax, args)) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
