        // Assign unique key to each record
        int key;
        do {
            key = rand() % 90 + 10; // Random integer within range [10, 100]
        } while (key % 2 == 0); // Backoff strategy to avoid key collisions

        records[i].key = key;
    }

    // Sort records based on their 'int' key values
    qsort(records, 512, sizeof(Record), compare);

    free(offsets);
    free(keys);

    return NULL; // Return value is not used
}

int compare(const void* a, const void* b) {
    Record* rec1 = (Record*)a;
    Record* rec2 = (Record*)b;

    if (rec1->key < rec2->key)
        return -1;
    else if (rec1->key > rec2->key)
        return 1;

    return 0; // Keys are equal
}
