void parseAndProcessTransactions(const char* inputFile) {
    // Initialize memory pool
    if (!memoryPool) {
        memoryPool = malloc(MEMORY_POOL_SIZE);
        memoryPoolSize = MEMORY_POOL_SIZE;
    }

    // Open file and acquire lock
    pthread_mutex_lock(&fileLock);
    fileHandle = fopen(inputFile, "r");
    if (!fileHandle) {
        perror("Error opening input file");
        return;
    }

    // Parse transactions
    Transaction* transactionBuffer = (Transaction*) memoryPool;
    size_t bufferIndex = 0;

    char line[1024];
    while (fgets(line, sizeof(line), fileHandle)) {
        // Parse transaction from line
        int64_t transactionId;
        char* dateEnd = strchr(line, '\t');
        if (!dateEnd) continue; // invalid line format

        *dateEnd++ = '\0'; // null-terminate the date field

        sscanf(dateEnd, "%ld %lf", &transactionId, &bufferIndex);
        Transaction transaction = (Transaction) {
            .transactionId = transactionId,
            .date = line,
            .amount = bufferIndex
        };

        if (!isValidTransaction(&transaction)) continue; // filter out invalid transactions

        // Store valid transaction in memory pool
        transactionBuffer[bufferIndex] = transaction;
        bufferIndex++;
    }

    fclose(fileHandle);
    pthread_mutex_unlock(&fileLock);

    // Normalize dates and store in final array
    Transaction* finalTransactions = (Transaction*) realloc(transactions, sizeof(Transaction) * transactionsSize + bufferIndex * sizeof(Transaction));
    memcpy(finalTransactions + transactionsSize, transactionBuffer, bufferIndex * sizeof(Transaction));
    transactionsSize += bufferIndex;

    free(transactionBuffer);
}

