typedef struct {
    char* str;
    unsigned short id;
    double value;
} Entry;

Entry** entries = NULL;
unsigned int capacity = 0;
unsigned int size = 0;
unsigned long seed = 0;

void allocateEntries(unsigned int newCapacity) {
    if (newCapacity > capacity) {
        Entry** temp = realloc(entries, newCapacity * sizeof(Entry*));
        if (temp == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }
        entries = temp;
        capacity = newCapacity;
        for (unsigned int i = size; i < capacity; i++) {
            entries[i] = NULL;
        }
    }
}

void insertEntry(const char* str, unsigned short id, double value) {
    if (size >= capacity) {
        allocateEntries(capacity * 2);
    }
    Entry** temp = realloc(entries, (size + 1) * sizeof(Entry*));
    if (temp == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    entries = temp;
    size++;
    Entry* entry = malloc(sizeof(Entry));
    if (entry == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    entry->str = strdup(str);
    if (entry->str == NULL) {
        printf("Memory allocation failed.\n");
        free(entry);
        return;
    }
    entry->id = id;
    entry->value = value;
    entries[size - 1] = entry;
}

void releaseEntries() {
    for (unsigned int i = 0; i < size; i++) {
        free(entries[i]->str);
        free(entries[i]);
    }
    free(entries);
    entries = NULL;
    capacity = 0;
    size = 0;
}
