```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <map>
#include <chrono>
#include <string>
#include <vector>
#include <queue>

class ServiceConfig {
public:
    std::string id;
    int startDelay;
    int stopDelay;

    ServiceConfig(std::string id, int startDelay, int stopDelay)
        : id(id), startDelay(startDelay), stopDelay(stopDelay) {}
};

class ServiceManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running(false);
    std::map<std::string, ServiceConfig> configs;
    std::queue<std::pair<ServiceConfig*, bool>> operationQueue;

public:
    void manageAndSendServiceNotifications() {
        while (running) {
            cv.wait(mtx, [this] { return !running; });
            if (!running)
                break;

            while (!operationQueue.empty()) {
                auto& op = operationQueue.front();
                op.first->start();
                if (op.second) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(op.first->config.startDelay));
                    op.first->stop();
                    std::this_thread::sleep_for(std::chrono::milliseconds(op.first->config.stopDelay));
                }
                operationQueue.pop();
            }

            // Send notifications for stopped services
            for (const auto& config : configs) {
                if (!config.second.stopCalled) {
                    sendNotification(config);
                }
            }
        }
    }

private:
    void sendNotification(const ServiceConfig& config) {
        // Logic to send notification to messaging system
    }
};

class Service {
public:
    std::string id;
    int startDelay;
    int stopDelay;
    bool stopped;

    Service(std::string id, int startDelay, int stopDelay)
        : id(id), startDelay(startDelay), stopDelay(stopDelay), stopped(false) {}

    void start() {
        // Logic to start service
    }

    void stop() {
        stopped = true;
        // Logic to stop service
    }
};

int main() {
    ServiceManager manager;

    // Initialize and manage configurations
    for (int i = 0; i < 10; i++) {
        ServiceConfig config("Service-" + std::to_string(i), 1000, 2000);
        configs[config.id] = config;
    }

    // Start services concurrently
    for (const auto& config : configs) {
        operationQueue.push({&config.second, false});
    }

    manager.running = true;

    // Wait for services to complete and send notifications
    while (!manager.operationQueue.empty()) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
