void* batchProcessImages(const char* directoryPath) {
    DIR* dir = opendir(directoryPath);
    if (!dir) {
        printf("Error opening directory: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize memory pool
    void* memoryPool = malloc(MEMORY_POOL_SIZE);
    if (!memoryPool) {
        printf("Error allocating memory pool: %s\n", strerror(errno));
        closedir(dir);
        return NULL;
    }

    // Initialize image metadata array
    ImageMetadata* images = (ImageMetadata*)malloc(sizeof(ImageMetadata)*MEMORY_POOL_SIZE);
    int imageCount = 0;

    struct dirent* entry;
    while ((entry = readdir(dir))) {
        char filePath[256];
        sprintf(filePath, "%s/%s", directoryPath, entry->d_name);

        // Check if file is an image
        FILE* file = fopen(filePath, "rb");
        if (!file) {
            printf("Error reading file: %s\n", strerror(errno));
            continue;
        }

        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        rewind(file);

        // Check if file is within size limit
        if (fileSize > MAX_IMAGE_SIZE) {
            printf("Skipping large image file: %s\n", filePath);
            fclose(file);
            continue;
        }

        ImageMetadata* image = &images[imageCount];
        fread(image, sizeof(ImageMetadata), 1, file);

        // Process image metadata
        // ...

        fclose(file);
        imageCount++;
    }
    closedir(dir);

    return images;
}

