int init_records(Record **records, int *offsets, int num_records) {
    // Initialize arrays
    *records = (Record *)malloc(num_records * sizeof(Record));
    *offsets = (int *)malloc(num_records * sizeof(int));

    if (*records == NULL || *offsets == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    // Populate records with random values
    int i;
    for (i = 0; i < num_records; i++) {
        (*records)[i].key = rand() % 100 + 10;
        (*records)[i].value = rand() % 90 + 11;
        (*offsets)[i] = i;
    }

    return 0;
}

// Function to sort records by key
void sort_records(Record *records, int num_records) {
    int i, j;
    for (i = 0; i < num_records - 1; i++) {
        for (j = i + 1; j < num_records; j++) {
            if ((*records)[i].key > (*records)[j].key) {
                Record temp = (*records)[i];
                (*records)[i] = (*records)[j];
                (*records)[j] = temp;
            }
        }
    }
}

// Function to process JSON configuration files
int process_json_config(const char *filename, int num_records) {
    json_object *config = json_object_from_file(filename);
    if (config == NULL) {
        fprintf(stderr, "Error reading JSON file.\n");
        return -1;
    }

    // Validate API version and settings
    const char *api_version = json_object_get_string(config, "version");
    int api_key = json_object_get_int(config, "key");

    if (json_object_get_type(config, "endpoints") != json_type_array) {
        fprintf(stderr, "Error: Endpoints field is missing or malformed.\n");
        return -1;
    }

    // Process API settings and data records
    int i;
    for (i = 0; i < num_records; i++) {
        (*records)[i].key = api_key + i;
        (*records)[i].value = json_object_get_int(config, "values")[i];
    }

    return 0;
}

// Function to cleanup allocated memory
void cleanup(Record *records, int *offsets) {
    if (records != NULL) free(records);
    if (offsets != NULL) free(offsets);
}
