        (*keys)[i] = i;
        (*offsets)[i] = (long)i;
        (*records)[i].key = i;
        (*records)[i].offset = (long)i;

        // Set random value within given range for record's int field
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, max_offset_value);
        (*records)[i].key = dis(gen);

        if ((*records)[i].key > threshold) {
            // Track number of records that exceed the threshold
            printf("Record %d exceeds the threshold value.\n", i);
        }
    }

    free(*keys);
    free(*offsets);
