#include <vector>
#include <algorithm>
#include <random>

class DataProcessor {
public:
    struct RowData {
        double data1, data2, data3, data4, data5, sum;
    };

    DataProcessor(const std::string& filename) : randomGen(std::mt19937(rowCount)), rowCount(0) {
        processFile(filename);
    }

    int factorial(int n) const {
        if (n < 0)
            throw std::invalid_argument("Factorial calculation requires a non-negative integer.");
        int result = 1;
        for (int i = 2; i <= n; ++i)
            result *= i;
        return result;
    }

private:
    void processFile(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open())
            throw std::runtime_error("Failed to open the file.");

        rowCount = 0;
        RowData rowData;

        while (file >> rowData.data1 >> rowData.data2 >> rowData.data3 >> rowData.data4 >> rowData.data5 >> std::skipws >> rowData.sum) {
            if (++rowCount > 10000)
                throw std::runtime_error("File contains more than 10,000 rows.");
        }

        file.close();
    }

    int getRowId(const RowData& row) const { return static_cast<int>(row.data1); }
    double getRandomNumber() { return randomGen(gen()); }
    std::mt19937 randomGen;
    int rowCount;
};

int main() {
    DataProcessor processor("input.csv");

    for (int i = 0; i < 10; ++i) {
        std::cout << "Factorial of " << i << ": " << processor.factorial(i) << std::endl;
    }

    return 0;
}
