#include <xml2Cfg.h>

#define MAX_CONNS 100
#define MEMORY_CAP (1024 * 1024)

int connect_to_server(int fd, int n) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < n; i++) {
        int conn_fd = accept(fd, NULL, NULL);

        if (conn_fd < 0) {
            perror("Connection failed");
            continue;
        }

        struct conn_data *conn_metadata = (struct conn_data *)malloc(sizeof(struct conn_data));
        conn_metadata->fd = conn_fd;
        conn_metadata->status = 1; // assume successful connection
        conn_metadata->last_comm_timestamp = time(NULL);

        if ((conn_metadata_array = realloc(conn_metadata_array, sizeof(*conn_metadata_array) * (n + 1))) == NULL) {
            perror("Memory allocation failed");
            free(conn_metadata);
            close(conn_fd);
            continue;
        }

        conn_metadata_array[n] = conn_metadata;
        n++;
    }

    pthread_mutex_unlock(&mutex);

    return n;
}

void close_connections() {
    for (int i = 0; i < n; i++) {
        close(conn_metadata_array[i]->fd);
        free(conn_metadata_array[i]);
    }

    free(conn_metadata_array);
}

int main() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    int n = connect_to_server(fd, 5); // assume port 80

    close_connections();

    return 0;
}
