#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Custom hash function with tunable parameters
unsigned long custom_hash(long offset) {
    return (offset * 1103515245 + 12345) % 0x7fffffff;
}

// Structure for record objects
typedef struct {
    int value;
    char* string;
    int active;
} Record;

// Thread-safe data structure for storing and managing records
typedef struct {
    int capacity;
    int size;
    Record** records;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} RecordSet;

// Function to initialize the record set with a given size
void init_record_set(RecordSet* rs, int size) {
    rs->capacity = size;
    rs->size = 0;
    rs->records = (Record**)malloc(size * sizeof(Record*));
    pthread_mutex_init(&rs->lock, NULL);
    pthread_cond_init(&rs->cond, NULL);
}

// Function to add a new record to the set
void add_record(RecordSet* rs, Record* record) {
    pthread_mutex_lock(&rs->lock);

    // Calculate the hash key for the record
    unsigned long key = custom_hash(record->value);
    int index = key % rs->capacity;

    // Check if the slot is empty or contains an inactive record
    if (rs->records[index] == NULL || !rs->records[index]->active) {
        rs->records[index] = record;
        rs->size++;
    } else {
        // Rehash until we find an empty slot or a suitable active record
        int i = 0;
        while (i < rs->capacity && rs->records[(key + i) % rs->capacity] != NULL && !rs->records[(key + i) % rs->capacity]->active)
            i++;

        // Insert the record at the found slot
        if (i < rs->capacity) {
            rs->records[(key + i) % rs->capacity] = record;
            rs->size++;
        }
    }

    pthread_mutex_unlock(&rs->lock);
}

// Function to retrieve all active records in a specified order
void get_active_records(RecordSet* rs, Record** out_records, int* out_size) {
    pthread_mutex_lock(&rs->lock);

    // Initialize the output arrays
    *out_size = 0;
    *out_records = (Record*)malloc(rs->size * sizeof(Record));

    // Iterate over the records and copy active ones to the output array
    for (int i = 0; i < rs->capacity; i++) {
        if (rs->records[i] != NULL && rs->records[i]->active) {
            Record* record = rs->records[i];
            memcpy(&(*out_records)[*out_size], record, sizeof(Record));
            (*out_size)++;
        }
    }

    pthread_mutex_unlock(&rs->lock);
}

// Function to update the string content of a record
void update_record_string(RecordSet* rs, int index, const char* new_string) {
    pthread_mutex_lock(&rs->lock);

    // Check if the slot contains an active record
    if (index < rs->size && rs->records[index] != NULL && rs->records[index]->active) {
        Record* record = rs->records[index];
        free(record->string);
        record->string = strdup(new_string);
    }

    pthread_mutex_unlock(&rs->lock);
}

// Function to periodically clean up inactive records
void cleanup_inactive_records(RecordSet* rs, int threshold) {
    pthread_mutex_lock(&rs->lock);

    // Iterate over the records and remove inactive ones if necessary
    for (int i = 0; i < rs->capacity; i++) {
        if (i >= rs->size || !rs->records[i]->active && rs->size > threshold) {
            free(rs->records[i]->string);
            free(rs->records[i]);
            rs->records[i] = NULL;
            rs->size--;
        }
    }

    pthread_mutex_unlock(&rs->lock);
}

// Function to set the maximum limit on active records
void set_max_active_records(RecordSet* rs, int threshold) {
    pthread_mutex_lock(&rs->lock);

    // Update the threshold for maintaining memory efficiency
    rs->threshold = threshold;

    pthread_mutex_unlock(&rs->lock);
}
