function renderScripts(scripts) {
  const cdnUrl = 'https://example-cdn.com/';
  const cache = {};

  async function renderScript(script) {
    if (!script.key || !script.innerHTML) return;

    const key = `${cdnUrl}${script.key}`;
    const cachedResult = cache[key];
    if (cachedResult) {
      const scriptTag = document.createElement('script');
      scriptTag.src = key;
      document.body.appendChild(scriptTag);
      return Promise.resolve();
    }

    try {
      const response = await fetch(key);
      const result = await response.text();

      cache[key] = result;

      const scriptTag = document.createElement('script');
      scriptTag.innerHTML = result;
      document.body.appendChild(scriptTag);

      return Promise.resolve();
    } catch (error) {
      console.error(`Error rendering script ${key}:`, error);
      return Promise.reject();
    }
  }

  async function renderScriptsBatch(scripts, batchStartIndex) {
    const batch = scripts.slice(batchStartIndex, Math.min(batchStartIndex + 10, scripts.length));
    await Promise.all(batch.map(renderScript));

    if (scripts.length > 10) console.warn('Rendering more than 10 scripts at once. This might impact performance.');
  }

  const startRenderTime = Date.now();
  await renderScriptsBatch(scripts.slice(0, Math.min(scripts.length, 10)), 0);
  const endRenderTime = Date.now();

  console.log(`Total rendering time: ${endRenderTime - startRenderTime}ms`);
}

// Example usage:
const scripts = [
  { key: 'script1', innerHTML: 'alert("Hello");' },
  { key: 'script2', innerHTML: 'console.log("World!");' },
  // ...
];

renderScripts(scripts);
