import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Future;

public class NIOConnectionManager {

    public static void connectToRemoteAddress(String address, int port) throws IOException {
        AsynchronousChannelGroup group = AsynchronousChannelGroup.withCapacity(1000);
        try (AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(group)) {
            InetSocketAddress inetSocketAddress = new InetSocketAddress(address, port);
            Future<AsynchronousSocketChannel> future = channel.connect(inetSocketAddress);
            AsynchronousSocketChannel connectedChannel = future.get();

            // Start reading from the channel
            byte[] buffer = new byte[1024];
            while (true) {
                int bytesRead = connectedChannel.read(buffer);
                if (bytesRead == -1) break;
                System.out.println("Received: " + new String(buffer, 0, bytesRead));
            }

        } catch (InterruptedException | ExecutionException e) {
            // Handle connection timeout and failure
            Thread.currentThread().interrupt();
            e.printStackTrace();
        }
    }
}
