            command.output().unwrap_or_default();
            let output = command.output().unwrap_or_default();
            let mut rss_after = get_resident_set_size();

            // Calculate memory usage change
            let delta_rss = rss_after - rss_before;
            if delta_rss > 10000000 {
                // Throttle compilation process if memory usage exceeds threshold
                std::thread::sleep(std::time::Duration::from_millis(500));
            }

            // Handle errors during compilation using ice hook and early error function
            if let Some(err) = output.stderr {
