#define MAX_PROFILE_COUNT 100000
#define MAX_USERNAME_LENGTH 256
#define MAX_EMAIL_LENGTH 256
#define UNIQUE_ID_SIZE 32
#define MEMORY_THRESHOLD 4 * 1024 * 1024

typedef struct {
    char* username;
    char* email;
    uint64_t unique_id;
} Profile;

// Custom hash function to generate unique keys for each profile
uint64_t custom_hash(const char* str) {
    uint64_t hash = 0;
    int i;
    for (i = 0; i < strlen(str); i++) {
        hash += str[i];
    }
    return hash;
}

// Allocate memory dynamically for usernames and email addresses, handling memory allocation failures
Profile* create_profile(const char* username, const char* email) {
    Profile* profile = malloc(sizeof(Profile));
    if (profile == NULL) {
        // Log error message and return special error status
        printf("Error: Out of memory\n");
        return NULL;
    }

    profile->username = strdup(username);
    profile->email = strdup(email);

    uint64_t timestamp = time(NULL);
    uint64_t email_hash = custom_hash(email);
    uint64_t unique_id = (timestamp ^ email_hash) % UINT_MAX;
    profile->unique_id = unique_id;

    return profile;
}

// Initialize usernames to unique random values within a specified range
void init_username(Profile* profile, int min_value, int max_value) {
    int value = rand() % (max_value - min_value + 1) + min_value;
    char username[MAX_USERNAME_LENGTH];
    sprintf(username, "user_%d", value);
    free(profile->username);
    profile->username = strdup(username);
}

// Update and delete user profiles efficiently, minimizing memory fragmentation
void update_profile(Profile* profile, const char* new_username, const char* new_email) {
    // Update username and email if necessary
    if (strcmp(new_username, profile->username) != 0 || strcmp(new_email, profile->email) != 0) {
        free(profile->username);
        free(profile->email);

        profile->username = strdup(new_username);
        profile->email = strdup(new_email);
    }
}

void delete_profile(Profile* profile) {
    // Free allocated memory and reset the profile
    free(profile->username);
    free(profile->email);
    free(profile);
}

// Log detailed information about the current state of the system
void log_system_state() {
    printf("System State: %d profiles, %lu bytes used\n", MAX_PROFILE_COUNT, MEMORY_THRESHOLD);
}
