        rec->str = (char*)calloc(65, sizeof(char));
        if (!rec->str) return NULL;

        for (int j = 0; j < 64; j++) {
            rec->str[j] = chars[rand() % 62];
        }
        rec->str[64] = '\0';
    }

    return records;
}

void freeRecords(record* records, int numRecords) {
    if (!records) return;

    for (int i = 0; i < numRecords; i++) {
        record* rec = &records[i];
        if (rec->str) free(rec->str);
    }

    free(records);
}
