#include <string.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_URL_LENGTH 1024
#define MAX_HEADERS 16

typedef struct {
    char* url;
    int headers_count;
    char** headers;
} httpRequest;

void httpRequestManager(httpRequest request) {
    // Validate URL structure and perform input sanitization
    if (strlen(request.url) > MAX_URL_LENGTH || !request.url[0]) {
        printf("Invalid URL: %s\n", request.url);
        return;
    }

    // Parse the URL and extract relevant information
    char* scheme = strtok(request.url, ":");
    char* host = strtok(NULL, "/??");
    int port = atoi(strtok(NULL, "://"));
    char* path = strtok(NULL, "?");
    char* query = strtok(NULL, "?");
    char* fragment = strtok(NULL, "#");

    // Create an HTTP request structure
    httpRequestRequest req;
    req.scheme = scheme;
    req.host = host;
    req.port = port;
    req.path = path;
    req.query = query;
    req.fragment = fragment;

    // Send the HTTP request with specified headers and body
    if (request.headers_count > 0) {
        for (int i = 0; i < request.headers_count; i++) {
            printf("Header %d: %s\n", i, request.headers[i]);
        }
    }

    // Handle network failures gracefully, retrying failed requests within a configurable backoff strategy
    if (req.scheme && req.host && req.port) {
        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        struct sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(req.port);
        inet_pton(AF_INET, req.host, &server_addr.sin_addr);

        if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            printf("Failed to connect to %s:%d\n", req.host, req.port);
            // Implement backoff strategy
            sleep(1);
            httpRequestManager(req);
        } else {
            // Send the request and handle response
            char* body = "Hello from C!";
            send(sockfd, body, strlen(body), 0);

            int bytes_received;
            recv(sockfd, &bytes_received, sizeof(int), 0);

            char* received_data = malloc(bytes_received + 1);
            if (received_data) {
                recv(sockfd, received_data, bytes_received, 0);
                received_data[bytes_received] = '\0';
                printf("Received: %s\n", received_data);
                free(received_data);
            }

            close(sockfd);
        }
    } else {
        printf("Invalid request structure\n");
    }
}

int main() {
    httpRequest req;
    req.url = "http://example.com/path?query=param";
    req.headers_count = 2;
    req.headers[0] = "Host: example.com";
    req.headers[1] = "User-Agent: C Client";

    httpRequestManager(req);

    return 0;
}
