#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int deviceId;
    float value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} SensorData;

SensorData* sensor_data_create(size_t initial_capacity) {
    SensorData* data = (SensorData*)malloc(sizeof(SensorData));
    data->records = (Record*)calloc(initial_capacity, sizeof(Record));
    data->capacity = initial_capacity;
    data->size = 0;
    pthread_mutex_init(&data->mutex, NULL);
    return data;
}

void sensor_data_free(SensorData* data) {
    if (!data) return;
    free(data->records);
    free(data);
}

int sensor_data_add(SensorData* data, long timestamp, int deviceId, float value) {
    pthread_mutex_lock(&data->mutex);

    // Adaptive resizing
    if (data->size >= data->capacity * 0.8) {
        size_t new_capacity = data->capacity * 2;
        Record* new_records = (Record*)realloc(data->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&data->mutex);
            return -1; // Allocation failed
        }
        data->records = new_records;
        data->capacity = new_capacity;
    }

    Record* record = &data->records[data->size++];
    record->timestamp = timestamp;
    record->deviceId = deviceId;
    record->value = value;

    pthread_mutex_unlock(&data->mutex);
    return 0; // Success
}

int sensor_data_update(SensorData* data, int index, long timestamp, float value) {
    if (index >= data->size) return -1; // Index out of bounds

    pthread_mutex_lock(&data->mutex);

    Record* record = &data->records[index];
    record->timestamp = timestamp;
    record->value = value;

    pthread_mutex_unlock(&data->mutex);
    return 0; // Success
}

int sensor_data_get(SensorData* data, int index, long* timestamp, int* deviceId, float* value) {
    if (index >= data->size) return -1; // Index out of bounds

    pthread_mutex_lock(&data->mutex);

    Record* record = &data->records[index];
    *timestamp = record->timestamp;
    *deviceId = record->deviceId;
    *value = record->value;

    pthread_mutex_unlock(&data->mutex);
    return 0; // Success
}

int sensor_data_prune(SensorData* data, long age_threshold) {
    pthread_mutex_lock(&data->mutex);

    size_t i = 0;
    while (i < data->size) {
        Record* record = &data->records[i];
        if (record->timestamp < age_threshold) {
            // Remove outdated record
            memmove(&data->records[i], &data->records[i+1], (data->size - i - 1) * sizeof(Record));
            data->size--;
            continue;
        }
        i++;
    }

    pthread_mutex_unlock(&data->mutex);
    return 0; // Success
}

void sensor_data_destroy(SensorData* data) {
    if (!data) return;
    free(data->records);
    free(data);
}
