int load_resource_bundle(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // Error opening file

    int num_records;
    fread(&num_records, sizeof(int), 1, file);

    record_t **bundle = (record_t **)malloc(num_records * sizeof(record_t *));
    for (int i = 0; i < num_records; i++) {
        bundle[i] = (record_t *)malloc(sizeof(record_t));
    }

    for (int i = 0; i < num_records; i++) {
        fread(&bundle[i]->offset, sizeof(long), 1, file);
        fread(&bundle[i]->key, sizeof(int), 1, file);
        fread(&bundle[i]->value, sizeof(float), 1, file);
    }

    fclose(file);

    return num_records;
}
