#include <string.h>

typedef struct {
    float value;
    int key;
    long offset;
} Record;

Record **createRecords(int capacity) {
    Record **records = (Record **)malloc(sizeof(Record *) * capacity);
    return records;
}

void addRecord(Record **records, int capacity, int key, float value, long offset) {
    for (int i = 0; i < capacity; i++) {
        if (records[i] == NULL || records[i]->key != key) {
            records[i] = malloc(sizeof(Record));
            records[i]->value = value;
            records[i]->key = key;
            records[i]->offset = offset;
            return;
        }
    }
}

void validateRecords(Record **records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (records[i] == NULL) continue;
        printf("Key: %d, Value: %.2f, Offset: %ld\n", records[i]->key, records[i]->value, records[i]->offset);
    }
}

void freeRecords(Record **records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (records[i] != NULL) free(records[i]);
    }
    free(records);
}

int main() {
    int capacity = 10;
    Record **records = createRecords(capacity);

    addRecord(records, capacity, 1, 3.14f, 1000L);
    addRecord(records, capacity, 2, 2.71f, 2000L);
    addRecord(records, capacity, 3, 4.22f, 3000L);
    addRecord(records, capacity, 1, 5.56f, 4000L); // duplicate key
    addRecord(records, capacity, 4, 6.78f, 5000L);

    validateRecords(records, capacity);

    freeRecords(records, capacity);

    return 0;
}

