import random
import ctypes

class record_t(ctypes.Structure):
    _fields_ = [("key", ctypes.c_int), ("offset", ctypes.c_long)]

def processLogAndAggregate():
    log_level = logging.INFO
    logger = logging.getLogger(__name__)
    logger.setLevel(log_level)
    file_handler = logging.FileHandler('performance.log')
    file_handler.setFormatter(logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s'))
    logger.addHandler(file_handler)

    memory_pool_size = 1024
    long_array = array(ctypes.c_long, [0] * memory_pool_size)
    int_array = array(ctypes.c_int, [0] * memory_pool_size)

    record_array = (record_t * 512)()
    for i in range(512):
        record_array[i].key = random.randint(10, 100)
        record_array[i].offset = long_array[random.randint(0, memory_pool_size-1)]

    int_keys = deque(int_array.tolist())
    long_offsets = deque(long_array.tolist())

    try:
        for i in range(memory_pool_size):
            if not all(isinstance(x, int) for x in [record_array[i].key]):
                logger.warning(f"Invalid record key: {record_array[i].key}")
            elif not all(isinstance(x, int) for x in [record_array[i].offset]):
                logger.warning(f"Invalid record offset: {record_array[i].offset}")
    except Exception as e:
        logger.error(f"Error processing log entries: {e}")

    try:
        sorted_record_array = sorted(record_array, key=lambda x: x.key)
    except Exception as e:
        logger.error(f"Error sorting records: {e}")

    valid_count = 0
    invalid_count = 0

    for record in sorted_record_array:
        if isinstance(record.key, int) and isinstance(record.offset, int):
            valid_count += 1
        else:
            invalid_count += 1

    logger.info(f"Valid entries: {valid_count}, Invalid entries: {invalid_count}")

    try:
        with open('log.txt', 'w') as f:
            for record in sorted_record_array:
                f.write(str(record.key) + " " + str(record.offset) + "\n")
    except Exception as e:
        logger.error(f"Error writing log file: {e}")
    finally:
        file_handler.close()

    try:
        os.remove('performance.log')
    except Exception as e:
        logger.warning(f"Failed to remove performance log file: {e}")

    return valid_count, invalid_count']

