    char** chars;
};

record_t* load_config(const char* file_path) {
    // Load configuration from file
    struct config* config = malloc(sizeof(struct config));
    if (config == NULL) return NULL;

    // Initialize random number generator
    srand(time(NULL));

    // Read and parse configuration data

    // Allocate memory for arrays based on config values
    long* offsets = malloc(config->max_records * sizeof(long));
    int* keys = malloc(config->max_records * sizeof(int));
    record_t** records = malloc(config->max_records * sizeof(record_t*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        // Clean up and return error
        free(config);
        for (int i = 0; i < config->max_records; i++) {
            free((void*)keys[i]);
            free((void*)records[i]->str);
        }
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays with random values
    for (int i = 0; i < config->max_records; i++) {
        offsets[i] = rand() % (config->max_offset - config->min_offset) + config->min_offset;
        keys[i] = i;

        // Allocate memory for record structure and string
        records[i] = malloc(sizeof(record_t));
        if (records[i] == NULL) {
            // Clean up and return error
            free(config);
            for (int j = 0; j < i; j++) {
                free((void*)keys[j]);
                free((void*)records[j]->str);
            }
            free(keys);
            free(records);
            return NULL;
        }

        // Initialize record structure
        records[i]->offset = offsets[i];
        records[i]->key = keys[i];

        // Allocate memory for string and fill with random characters
        int str_len = rand() % 64 + 1;
        records[i]->str = malloc(str_len);
        if (records[i]->str == NULL) {
            // Clean up and return error
            free(config);
            for (int j = 0; j < i; j++) {
                free((void*)keys[j]);
                free((void*)records[j]->str);
            }
            free(keys);
            free(records);
            return NULL;
        }

        // Fill string with random characters
