#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <chrono>
#include <thread>

class Drone {
public:
    int id;
    std::string area;
    bool busy = false;

    void assignTask(std::string area, bool& lastBusy) {
        this->area = area;
        lastBusy = true;
    }

    void performTask() {
        if (busy) return; // Avoid overheating
        busy = true;
        std::this_thread::sleep_for(std::chrono::seconds(5)); // Simulate task execution time
        busy = false;
    }
};

class TaskScheduler {
public:
    int numDrones;
    std::vector<Drone> drones;
    std::queue<std::string> areasToMonitor;

    void initialize(int numDrones, const std::vector<std::string>& areas) {
        this->numDrones = numDrones;
        for (int i = 0; i < numDrones; ++i) {
            Drone drone;
            drone.id = i;
            drones.push_back(drone);
        }
        for (const auto& area : areas) {
            areasToMonitor.push(area);
        }
    }

    void scheduleTasks() {
        while (!areasToMonitor.empty()) {
            std::string area = areasToMonitor.front();
            areasToMonitor.pop();

            // Assign task to available drone
            bool lastBusy = false;
            for (auto& drone : drones) {
                if (!drone.busy) {
                    drone.assignTask(area, lastBusy);
                    break;
                }
            }

            // Perform tasks
            for (auto& drone : drones) {
                if (!lastBusy || !drone.area.empty()) { // Ensure no consecutive task in same area
                    drone.performTask();
                } else {
                    std::this_thread::sleep_for(std::chrono::seconds(2)); // Simulate cooldown period
                    lastBusy = true;
                    break; // Move to next drone
                }
            }

            // Log and monitor system status
            for (auto& drone : drones) {
                if (!drone.area.empty()) {
                    std::cout << "Drone " << drone.id << " is performing task in area " << drone.area << ".\n";
                } else {
                    std::cout << "Drone " << drone.id << " is idle.\n";
                }
            }
        }
    }

    void addDrone() {
        if (drones.size() < numDrones) {
            Drone newDrone;
            newDrone.id = drones.size();
            drones.push_back(newDrone);
        } else {
            std::cout << "Maximum number of drones reached.\n";
        }
    }

    void removeDrone(int id) {
        for (auto it = drones.begin(); it != drones.end(); ++it) {
            if (it->id == id) {
                drones.erase(it);
                break;
            }
        }
    }
};

int main() {
    TaskScheduler scheduler;

    // Initialize the system
    int numDrones = 5;
    std::vector<std::string> areasToMonitor = {"Area 1", "Area 2", "Area 3"};
    scheduler.initialize(numDrones, areasToMonitor);

    // Perform tasks
    while (true) {
        scheduler.scheduleTasks();
        // Add or remove drones as needed
        // ...
    }

    return 0;
}
