#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum number of profiles and posts
#define MAX_PROFILES 10000
#define MAX_POSTS 1000

typedef struct {
    long timestamp;
    char message[280];
    int likeCount;
} Post;

typedef struct {
    int id;
    char username[32];
    List<Post> posts;
} Profile;

// Define the data structure for storing user profiles and their posts
typedef struct {
    Profile* profiles;
    int profileCount;
    List<Post*> postList;
    int postCount;
} UserProfileData;

UserProfileData userProfileData = {
    .profiles = (Profile*)malloc(MAX_PROFILES * sizeof(Profile)),
    .profileCount = 0,
    .postList = NULL,
    .postCount = 0
};

// Function to add a new user profile and their posts
void addUserProfile(int id, char* username, List<Post*> postList) {
    // Check if the maximum number of profiles is reached
    if (userProfileData.profileCount >= MAX_PROFILES) {
        printf("Maximum number of profiles reached. Cannot add more.\n");
        return;
    }

    // Create a new profile and add it to the list
    Profile* newProfile = &userProfileData.profiles[userProfileData.profileCount];
    newProfile->id = id;
    strcpy(newProfile->username, username);
    newProfile->posts = postList;

    // Update the profile count
    userProfileData.profileCount++;

    printf("User profile added successfully.\n");
}

// Function to remove a user profile and their posts
void removeUserProfile(int id) {
    // Find the profile to be removed
    for (int i = 0; i < userProfileData.profileCount; i++) {
        if (userProfileData.profiles[i].id == id) {
            break;
        }
    }

    // Remove the profile and update the count
    if (i < userProfileData.profileCount) {
        userProfileData.profiles[i] = userProfileData.profiles[userProfileData.profileCount - 1];
        userProfileData.profileCount--;
    } else {
        printf("User profile not found.\n");
    }
}

// Function to get a user profile and their posts
void getUserProfile(int id, Profile* profile) {
    // Find the profile
    for (int i = 0; i < userProfileData.profileCount; i++) {
        if (userProfileData.profiles[i].id == id) {
            *profile = userProfileData.profiles[i];
            break;
        }
    }

    if (i >= userProfileData.profileCount) {
        printf("User profile not found.\n");
    } else {
        printf("User profile retrieved successfully.\n");
    }
}

// Function to add a new post
void addPost(int id, long timestamp, char* message, int likeCount) {
    // Find the user profile and add the post to their list
    for (int i = 0; i < userProfileData.profileCount; i++) {
        if (userProfileData.profiles[i].id == id) {
            Post* newPost = &userProfileData.postList[userProfileData.postCount];
            newPost->timestamp = timestamp;
            strcpy(newPost->message, message);
            newPost->likeCount = likeCount;

            // Update the post count
            userProfileData.postCount++;

            printf("Post added successfully.\n");
            return;
        }
    }

    printf("User profile not found.\n");
}

// Function to remove a post
void removePost(int id, long timestamp) {
    // Find the user profile and their post to be removed
    for (int i = 0; i < userProfileData.profileCount; i++) {
        Profile* profile = &userProfileData.profiles[i];
        for (int j = 0; j < profile->posts.postCount; j++) {
            if (profile->posts.posts[j]->timestamp == timestamp) {
                // Remove the post and update the count
                memmove(&profile->posts.posts[j], &profile->posts.posts[j + 1], (profile->posts.postCount - j - 1) * sizeof(Post*));
                profile->posts.postCount--;
                printf("Post removed successfully.\n");
                return;
            }
        }
    }

    printf("Post not found.\n");
}

// Function to prune inactive user profiles and their posts
void pruneUserProfiles() {
    // Find all inactive profiles and remove them
    for (int i = 0; i < userProfileData.profileCount; i++) {
        Profile* profile = &userProfileData.profiles[i];
        if (profile->posts.postCount == 0) {
            // Remove the profile and update the count
            memmove(&userProfileData.profiles[i], &userProfileData.profiles[i + 1], (userProfileData.profileCount - i - 1) * sizeof(Profile));
            userProfileData.profileCount--;
        }
    }

    printf("Inactive user profiles pruned successfully.\n");
}

// Function to periodically clean up allocated resources
void cleanup() {
    // Free all allocated memory
    free(userProfileData.profiles);
    free(userProfileData.postList);

    printf("Memory cleaned up successfully.\n");
}
