typedef struct {
    int width;
    int height;
    char *data;
} Bitmap;

void process_line(char *line) {
    int fields[10], i = 0, j = 0, last_two_avg;
    char line_buf[MAX_LINE_LENGTH];
    strcpy(line_buf, line);
    char *token = strtok(line_buf, ",");

    while(token && i < 9) {
        fields[i++] = atoi(token);
        token = strtok(NULL, ",");
    }

    if(i >= 2)
        last_two_avg = (fields[i-1] + fields[i-2]) / 2;

    for(j = 0; j < i; j++)
        printf("%d", fields[j]);

    if(i > 1)
        printf(",%d", last_two_avg);

    printf("\n");
}

int main() {
    FILE *fp;
    char line[MAX_LINE_LENGTH];
    Bitmap *cache = NULL;
    int cache_size = 0, max_cache_size = MAX_CACHE_SIZE;

    // Set default theme directory if not set
    // ...

    // Initialize cache
    cache = (Bitmap *)malloc(sizeof(Bitmap));
    cache->width = -1; cache->height = -1; cache->data = NULL;

    while((fp = fopen(THEME_DIR"theme_0.png", "rb")) != NULL) {
        Bitmap *temp_bitmap = (Bitmap *)malloc(sizeof(Bitmap));
        temp_bitmap->width = -1; temp_bitmap->height = -1; temp_bitmap->data = NULL;

        // Read PNG file, handle errors
        // ...

        if(temp_bitmap->width > 0 && temp_bitmap->height > 0) {
            cache_size += temp_bitmap->width * temp_bitmap->height;
            if(cache_size > max_cache_size) {
                // Handle memory overflow
                // ...
            }
            else {
                // Add to cache
                temp_bitmap->data = (char *)malloc(temp_bitmap->width*temp_bitmap->height);
                // ...

                free(temp_bitmap->data);

                free(temp_bitmap);
                temp_bitmap = NULL;
            }
        }
        fclose(fp);
    }

    if(cache_size > max_cache_size) {
        // Handle memory overflow
        // ...
    }

    fp = fopen("input.txt", "r");
    while(fgets(line, MAX_LINE_LENGTH, fp)) {
        process_line(line);
    }
    fclose(fp);

    return 0;
}
