int max_id_length = MAX_ID_LENGTH;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* generate_unique_id(void) {
    static char buffer[16];
    // implement your unique ID generation logic here
    sprintf(buffer, "%x", (unsigned int)time(NULL));
    return strdup(buffer);
}

record* add_record(int value) {
    record* new_record;
    pthread_mutex_lock(&lock);

    if(record_count >= max_records) {
        printf("Record limit reached.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    new_record = (record*)malloc(sizeof(record));
    if(new_record == NULL) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char* id = generate_unique_id();
    if(id == NULL) {
        free(new_record);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    new_record->id = strlen(id);
    strncpy((char*)malloc(new_record->id), id, new_record->id);
    free(id);

    new_record->value = value;

    records = (record*)realloc(records, (record_count + 1) * sizeof(record));
    if(records == NULL) {
        printf("Memory allocation failed.\n");
        free(new_record);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    records[record_count] = *new_record;

    record_count++;
    pthread_mutex_unlock(&lock);

    return new_record;
}

void remove_records() {
    int i;
    for(i = 0; i < record_count; i++) {
        free((char*)malloc(records[i].id));
    }

    free(records);
}

int get_record_count() {
