// Function to traverse the DOM tree
record** traverseDOMTree(record* root, char* selector, int (*callback)(record*, void*), void* userData) {
    // Initialize the result array
    record** results = (record**)malloc(sizeof(record*) * 10);
    int numResults = 0;

    // Traverse the DOM tree
    traverseNode(root, selector, callback, userData, &results, &numResults);

    // Return the result array
    return results;
}

// Helper function to traverse the DOM tree
void traverseNode(record* node, char* selector, int (*callback)(record*, void*), void* userData, record*** results, int* numResults) {
    if (node == NULL) {
        return;
    }

    // Check if the current node matches the selector
    if (callback(node, userData)) {
        *results = realloc(*results, (*numResults + 1) * sizeof(record*));
        (*results)[*numResults] = node;
        (*numResults)++;
    }

    // Recursively traverse child nodes
    for (int i = 0; i < node->numChildren; i++) {
        record* child = node->children[i];
        traverseNode(child, selector, callback, userData, results, numResults);
    }
}

// Function to set the value of each record's int field to a random value within a given range
void initRecords(record** records, int numRecords, int minVal, int maxVal) {
