        if (WEXITSTATUS(status)) {
            return 0; // command execution failed
        }
    }

    int fd = open(cfg_file, O_RDONLY);
    if (fd < 0) {
        return 0; // file not found or I/O error
    }

    int num_records;
    fseek(fd, 0L, SEEK_END);
    num_records = ftell(fd) / sizeof(record_t); // assuming fixed record size

    record_t *records = malloc(num_records * sizeof(record_t));
    if (records == NULL) {
        close(fd);
        return 0; // memory allocation failed
    }

    fseek(fd, 0L, SEEK_SET);
    fread(records, sizeof(record_t), num_records, fd);

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand() % 10000;
        records[i].key = rand() % 100;
        records[i].value = (float)rand() / RAND_MAX;
    }

    close(fd);
    free(records);

    return num_records;
}
