typedef struct {
    long offset;
    int key;
    short identifier;
} Record;

// Function to process and find maximum values in arrays
void* processAndFindMax(void* arg) {
    // Get the configuration and input parameters from the global config structure
    int min = 10, max = 100;
    size_t offsetsSize = 2048, keysSize = 2048, identifiersSize = 1024;

    // Allocate memory for arrays and record structures
    long* offsets = (long*)malloc(offsetsSize * sizeof(long));
    int* keys = (int*)malloc(keysSize * sizeof(int));
    short* identifiers = (short*)malloc(identifiersSize * sizeof(short));
    Record* records = (Record*)malloc(1024 * sizeof(Record));

    // Initialize random values for record structures
    srand((unsigned)time(NULL));
    for (size_t i = 0; i < 1024; i++) {
        records[i].offset = (long)rand() % (max - min + 1) + min;
        records[i].key = rand() % (max - min + 1) + min;
        records[i].identifier = (short)rand() % (max - min + 1) + min;
    }

    // Sort the record structures based on their key values
    for (size_t i = 0; i < 1024; i++) {
        for (size_t j = i + 1; j < 1024; j++) {
            if (records[i].key > records[j].key) {
                Record temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }

    // Find the maximum value and corresponding record
    int maxKey = INT_MIN;
    Record* maxRecord = NULL;

    for (size_t i = 0; i < 1024; i++) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
            maxRecord = &records[i];
        }
    }

    // Print the maximum value and corresponding record
    printf("Maximum key: %d\n", maxKey);
    printf("Offset: %ld, Identifier: %hd\n", maxRecord->offset, maxRecord->identifier);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(identifiers);
    free(records);

    return NULL;
}

int main() {
    pthread_t threads[10];
    int threadCount = 0;

    while (1) {
        // Read integers from standard input
        int min, max;
        scanf("%d %d", &min, &max);

        if (min > max) {
            printf("Invalid input range. Please try again.\n");
            continue;
        }

        // Allocate and initialize thread-safe structures for each thread
        pthread_create(&threads[threadCount], NULL, processAndFindMax, NULL);
        threadCount++;

        // Wait for all threads to finish
        for (int i = 0; i < threadCount; i++) {
            pthread_join(threads[i], NULL);
        }

        printf("Press Enter to continue or 'q' to quit: ");
        char c;
        scanf(" %c", &c);

        if (c == 'q') {
            break;
        }
    }

    return 0;
}

