void batchInsert(std::forward_list<int>& list, int target, int count, const std::vector<std::pair<int, int>>& operations) {
    bool found = false;
    for (auto& op : operations) {
        if (op.first == target) {
            found = true;
            auto it = std::find(list.begin(), list.end(), op.second);
            if (it != list.end()) {
                list.insert_after(it, op.second);
            } else {
                list.push_back(op.second);
            }
        }
    }
    if (!found) {
        for (auto& op : operations) {
            auto it = std::find(list.begin(), list.end(), op.second);
            if (it == list.end()) {
                list.push_back(op.second);
            }
