        records[i].offset = rand() % 1000000;
        records[i].key = rand() % 90 + 10;
        records[i].identifier = rand() % 20 + 1;

        pthread_mutex_lock(&mutex);
        offsets[records[i].key]++;
        keys[records[i].key] = records[i].key;
        identifiers[records[i].identifier]++;
        pthread_mutex_unlock(&mutex);
    }

    for (int i = 0; i < RECORDS; i++) {
        // Sorting algorithm implementation
        pthread_mutex_lock(&mutex);
        int keyIndex = linearSearch(keys, records[i].key);
        pthread_mutex_unlock(&mutex);

        if (keyIndex != -1) {
            record_t temp = records[keyIndex];
            for (int j = keyIndex; j > 0; j--) {
                records[j] = records[j-1];
            }
            records[0] = temp;
        }
    }

    // Thread integration and synchronization
    pthread_t threads[numThreads];
    pthread_attr_t attr;

    for (int i = 0; i < numThreads; i++) {
        pthread_mutex_init(&mutex, NULL);
        pthread_create(&threads[i], &attr, threadFunction, NULL);
