typedef struct {
    int key;
    double value;
    char* message;
} data_point;

void* allocate_memory() {
    long* offset_values = (long*)malloc(sizeof(long) * MAX_ELEMENTS);
    int* keys = (int*)malloc(sizeof(int) * MAX_ELEMENTS);
    double* values = (double*)malloc(sizeof(double) * MAX_ELEMENTS);

    if (!offset_values || !keys || !values) {
        printf("Memory allocation failed. Exiting...\n");
        return NULL;
    }

    data_point* data_points = (data_point*)malloc(sizeof(data_point) * 1024);

    if (!data_points) {
        printf("Data points memory allocation failed. Exiting...\n");
        free(offset_values);
        free(keys);
        free(values);
        return NULL;
    }

    pthread_mutex_init(&lock, NULL); // Initialize the lock

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        offset_values[i] = rand() % KEY_RANGE;
        keys[i] = rand() % KEY_RANGE;
        values[i] = (double)rand() / RAND_MAX * VALUE_RANGE;

        if (i < 1024) {
            data_points[i].key = keys[i];
            data_points[i].value = values[i];
            data_points[i].message = generate_random_string();
        }
    }

    // Aggregate the double values grouped by the int key values
    pthread_t threads[MAX_ELEMENTS / 32];
    for (int i = 0; i < MAX_ELEMENTS / 32; i++) {
        pthread_create(&threads[i], NULL, aggregate_values, &data_points[i * 32]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_ELEMENTS / 32; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    free(offset_values);
    free(keys);
    free(values);
    free(data_points);

    return NULL;
}

void generate_random_string() {
    static const char* strings[] = {"Error: Invalid request", "Error: Server busy", "Error: Connection timed out", ...};

    // Randomly select a string from the array
    int index = rand() % (sizeof(strings) / sizeof(strings[0]));
    return strings[index];
}

void aggregate_values(data_point* data_points, pthread_exit(void)) {
    // Calculate the average of the double values grouped by the int key values
    for (int i = 0; i < MAX_ELEMENTS / 32; i++) {
        double sum = 0.0;
        int count = 0;

        for (int j = i * 32; j < (i + 1) * 32; j++) {
            if (data_points[j].key == data_points[i].key) {
                sum += data_points[j].value;
                count++;
            }
        }

        double average = sum / count;

        // Print the aggregated values
        printf("Average for key %d: %.2f\n", data_points[i].key, average);
    }

    pthread_exit(NULL);
}
