    Record** records = (Record**)arg;
    int num_records = *(long*)records;
    qsort(*records, num_records, sizeof(Record), my_compare);
    return NULL;
}

int my_compare(const void* a, const void* b) {
    Record* ra = (Record*)a;
    Record* rb = (Record*)b;
    if (ra->key < rb->key)
        return -1;
    else if (ra->key > rb->key)
        return 1;
    return 0;
}

