        if (strcmp(argv[i], "-n") == 0) {
            num_records = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-r") == 0) {
            key_range[0] = atoi(argv[++i]);
            key_range[1] = atoi(argv[++i]);
        }
