        exit(-1);
    }

    // Populate records with random values
    populate_records(&records, num_records);

    // Sort records using thread-safe qsort and custom comparator
    pthread_create(&tid, NULL, sort_thread, &records);
    pthread_join(tid, NULL);

    // Print sorted records
    for (long i = 0; i < num_records; i++) {
        printf("%ld %d\n", i, records[i]->key);
    }

    // Clean up allocated memory
    for (long i = 0; i < num_records; i++)
        my_free(records[i]);

