public class ServiceLifecycleManager {
    private static final Random RANDOM = new Random();
    private static final String RANDOM_ALPHANUMERIC_PATTERN = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private static final int MAX_RANDOM_LENGTH = 16;

    private final Logger logger = Logger.getLogger(ServiceLifecycleManager.class);
    private final AtomicLong startCount = new AtomicLong(0);
    private final AtomicLong stopCount = new AtomicLong(0);

    private volatile boolean isRunning = false;
    private Thread serviceThread;
    private int minStopDurationMs, maxStopDurationMs;

    public ServiceLifecycleManager() {
        loadConfigFromExternalSystem();
    }

    public void startService() {
        if (isRunning) return;
        try {
            isRunning = true;
            serviceThread = new Thread(() -> runService());
            serviceThread.start();
        } catch (Exception e) {
            logger.error("Error starting the service", e);
            stopService();
        }
    }

    public void stopService() {
        if (!isRunning) return;
        try {
            isRunning = false;
            long startTimestamp = LocalDateTime.now().toInstant().getEpochSecond();
            String uniqueId = generateUniqueId();
            logger.info("Stopping the service with ID {} and duration {}", uniqueId, getStopDuration());
            Thread.sleep(getRandomStopDuration());
            long stopTimestamp = LocalDateTime.now().toInstant().getEpochSecond();
            recordServiceEvent(uniqueId, startTimestamp, stopTimestamp);
        } catch (Exception e) {
            logger.error("Error stopping the service", e);
        }
    }

    private void runService() {
        try {
            while (isRunning) {
                startCount.incrementAndGet();
                Thread.sleep(getRandomStartInterval());
            }
        } catch (InterruptedException e) {
            logger.info("Service interrupted");
        } finally {
            stopService();
        }
    }

    private long getRandomStopDuration() {
        return RANDOM.nextInt((maxStopDurationMs - minStopDurationMs + 1)) + minStopDurationMs;
    }

    private long getRandomStartInterval() {
        // implement your start interval logic here
    }

    private void recordServiceEvent(String uniqueId, long startTimestamp, long stopTimestamp) {
        // implement your logging system integration here
    }

    private String generateUniqueId() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < MAX_RANDOM_LENGTH; i++) {
            sb.append(RANDOM_ALPHANUMERIC_PATTERN.charAt(RANDOM.nextInt(RANDOM_ALPHANUMERIC_PATTERN.length())));
        }
        return sb.toString();
    }

    private void loadConfigFromExternalSystem() {
        // implement your configuration loading logic here
    }

    public static void main(String[] args) {
        ServiceLifecycleManager service = new ServiceLifecycleManager();
        while (true) {
            System.out.println("Enter 1 to start the service, 2 to stop the service, or Q to quit:");
            String input = System.console().readLine();
            switch (input) {
                case "1":
                    service.startService();
                    break;
                case "2":
                    service.stopService();
                    break;
                case "Q":
                    System.exit(0);
                    break;
                default:
                    System.out.println("Invalid input. Try again.");
            }
        }
    }
}
