#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* _modify_filename_extension(char* filename) {
    int digits = 2;
    char fileType[] = ".txt";
    char originalExtension[256];
    char newExtension[256];

    // Get the original extension
    strcpy(originalExtension, strrchr(filename, '.'));

    // Generate a random number with specified digits
    sprintf(newExtension, "%0%d.%s", rand() % (int)pow(10, digits), fileType);

    // Replace the original extension with the new one
    char* modifiedFile = str_replace(originalExtension, newExtension, filename);
    return modifiedFile;
}

// Helper function to replace a substring in a string
char* str_replace(const char* haystack, const char* needle, const char* replacement) {
    int len = strlen(haystack);
    char* result = (char*)malloc((len - strlen(needle) + strlen(replacement)) * sizeof(char));
    sprintf(result, "%.*s%s%.*s", (int)(strlen(haystack) - strlen(needle)), haystack, replacement, (int)(strlen(haystack) - strlen(needle)));
    return result;
}
