    record_t** records = (record_t**)malloc(1000 * sizeof(record_t*));

    // Initialize arrays and structures
    for (int i = 0; i < 1000; i++) {
        offsets[i] = i;
        keys[i] = i;
        records[i] = (record_t*)malloc(sizeof(record_t));
        records[i]->key = i;
        records[i]->value = rand() % 100;

        // Create a hash table
        int* bucket_size = (int*)calloc(1000, sizeof(int));
        int** buckets = (int**)calloc(1000, sizeof(int*));

        for (int j = 0; j < 1000; j++) {
            unsigned long key_hash = hash_func(j);
            if (bucket_size[key_hash] == NULL) {
                bucket_size[key_hash] = (int*)malloc(sizeof(int));
                buckets[key_hash] = (int*)malloc(sizeof(int));
            }

            // Insert into the hash table
            int idx = *buckets[key_hash]++;
            records[idx]->value = j;

        }
    }

    // Free allocated memory when exiting
    for (int i = 0; i < 1000; i++) {
        free(records[i]);
    }
    free(records);

    free(keys);
    free(offsets);
    free(bucket_size);
    free(buckets);

    return 0;
}
