// Define the structure for product records
typedef struct Product {
    char* name;
    int quantity;
    float price;
} Product;

// Define the structure for hash table nodes (chaining)
typedef struct HashNode {
    int key;
    void* value;
    struct HashNode* next;
} HashNode;

// Define the record array with a simple hash function and collision resolution
void initRecordArray(int size) {
    srand(time(NULL));
    // Initialize an empty record array
}

int recordInsert(int key, int value) {
    // Hash function (simple implementation)
    unsigned int hash = key % 128;
    HashNode* node = malloc(sizeof(HashNode));
    node->key = key;
    node->value = &value;
    node->next = NULL;

    // Find the corresponding slot in the array
    HashNode** slots = (HashNode**)malloc((size_t)hash * sizeof(HashNode*));
    HashNode* prev = NULL, *curr = slots[hash % 128];
    while (curr != NULL) {
        if (curr->key == key) {
            // Collision resolution via chaining
            curr->next = node;
            free(node);
            return;
        }
        prev = curr;
        curr = curr->next;
    }

    // Insert the new node at the end of the chain
    prev ? (prev->next = node) : slots[hash % 128] = node;

    free(slots);
}

int recordLookup(int key) {
    // Hash function (simple implementation)
    unsigned int hash = key % 128;
    HashNode* curr = slots[hash % 128];
    while (curr != NULL) {
        if (curr->key == key) {
            return *(int*)curr->value;
        }
        curr = curr->next;
    }

    // If the key is not found, return a default value
    return -1;
}

// Define the product list with concurrent modification handling and total value calculation
void initProductList() {
    // Initialize an empty product list
    products = NULL;

    pthread_mutex_init(&mutex, NULL);
}

void addProduct(Product* product) {
    // Acquire a lock for thread safety
    pthread_mutex_lock(&mutex);

    Product* temp = products;
    while (temp != NULL && temp->name < product->name) {
        temp = temp->next;
    }

    if (temp == NULL || strcmp(temp->name, product->name) > 0) {
        // Insert the new product at the end of the list
        product->next = NULL;
        if (products == NULL) {
            products = product;
        } else {
            temp->next = product;
        }
    }

    pthread_mutex_unlock(&mutex);
}

float calculateTotalValue() {
    float totalValue = 0.0f;
    Product* curr = products;
    while (curr != NULL) {
        totalValue += curr->quantity * curr->price;
        curr = curr->next;
    }
    return totalValue;
}

// Define the mechanism to clear all data structures and free allocated memory
void cleanup() {
    // Release resources for record array and product list
    // Free any allocated memory
}
