#include <string.h>

// Define a structure for 'event' objects
typedef struct {
    long timestamp;
    char eventType[256];
    int userID;
} Event;

// Define a struct to hold the dynamic collection of events and some metadata
typedef struct {
    Event* events; // Dynamic array of event objects
    int size; // Current number of events in the collection
    int capacity; // Maximum allowed number of events
    int userIDFilter; // User ID to filter events by
} EventCollection;

// Function to initialize an EventCollection with a given initial capacity
EventCollection* initEventCollection(int initialCapacity) {
    EventCollection* ec = (EventCollection*)malloc(sizeof(EventCollection));
    ec->events = (Event*)malloc(initialCapacity * sizeof(Event));
    ec->size = 0;
    ec->capacity = initialCapacity;
    ec->userIDFilter = -1; // Initially, no filtering is done
    return ec;
}

// Function to insert an event into the collection
void insertEvent(EventCollection* ec, Event e) {
    if (ec->size == ec->capacity) { // If the array needs to grow
        int newCapacity = ec->capacity * 2; // Double the capacity
        Event* newArray = (Event*)realloc(ec->events, newCapacity * sizeof(Event));
        if (!newArray) {
            printf("Memory error: could not allocate memory\n");
            return;
        }
        ec->events = newArray;
        ec->capacity = newCapacity;
    }
    ec->events[ec->size++] = e; // Insert the event at the end
}

// Function to remove all events with a given user ID from the collection
void removeEventsByUserID(EventCollection* ec, int userID) {
    ec->userIDFilter = userID;
    for (int i = 0; i < ec->size; i++) {
        if (ec->events[i].userID == userID) { // Find events to remove
            memmove(&ec->events[i], &ec->events[i + 1], (ec->size - i - 1) * sizeof(Event));
            ec->size--;
        }
    }
}

// Function to clear the event collection and free all allocated memory
void freeEventCollection(EventCollection* ec) {
    if (!ec)
        return;
    if (ec->events) {
        free(ec->events);
        ec->events = NULL;
    }
    free(ec);
    ec = NULL; // Ensure it's not used again
}

// Example usage:
int main() {
    EventCollection* ec = initEventCollection(10); // Initialize with capacity 10

    // Insert some events
    Event e1 = {123456789, "event_type_1", 100};
    insertEvent(ec, e1);
    Event e2 = {987654321, "event_type_2", 101};
    insertEvent(ec, e2);
    Event e3 = {111111111, "event_type_3", 102};
    insertEvent(ec, e3);

    // Remove events with user ID 100
    removeEventsByUserID(ec, 100);

    // Clear the event collection when done
    freeEventCollection(ec);

    return 0;
}
