typedef struct {
    long* arr_long;
    int* arr_int;
    double* arr_double;
    size_t capacity, size;
    pthread_mutex_t mutex;
} MemPool;

MemPool* mem_pool_init(size_t capacity) {
    MemPool* pool = (MemPool*)malloc(sizeof(MemPool));
    pool->arr_long = (long*)malloc(capacity * sizeof(long));
    pool->arr_int = (int*)malloc(capacity * sizeof(int));
    pool->arr_double = (double*)malloc(capacity * sizeof(double));
    pool->capacity = capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void mem_pool_free(MemPool* pool) {
    free(pool->arr_long);
    free(pool->arr_int);
    free(pool->arr_double);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

// Custom Memory Pool
typedef struct {
    void** ptrs;
    size_t capacity, size;
    pthread_mutex_t mutex;
} MemPoolCustom;

MemPoolCustom* mem_pool_custom_init(size_t capacity) {
    MemPoolCustom* pool = (MemPoolCustom*)malloc(sizeof(MemPoolCustom));
    pool->ptrs = (void**)malloc(capacity * sizeof(void*));
    pool->capacity = capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void mem_pool_custom_free(MemPoolCustom* pool) {
    free(pool->ptrs);
    pthread_mutex_destroy(&pool->mutex);
