        Record* rec = record_init();
        // Initialize values...
        // Validate and log errors if necessary...
        records[i] = rec;
    }
    free(records);
}

// Sorting Algorithm Selection
void sort_records(Record** records, size_t num_records) {
    qsort(records, num_records, sizeof(Record*), compare_rec);
}

int compare_rec(const void* a, const void* b) {
    Record* ra = *(Record**)a;
    Record* rb = *(Record**)b;
    return (ra->key - rb->key);
}
