    for (int i = 0; i < size; i++) {
        if (dataArr[i].sensorReading > MAX_SENSOR_READING || dataArr[i].sensorReading < MIN_SENSOR_READING) {
            return -1; // remove this record
        }
    }
    return 0;
}

