using System.Threading.Tasks;

public class LineChecksumProcessor
{
    private const int CacheSizeLimit = 10000; // adjust this value based on your requirements
    private readonly ConcurrentDictionary<long, string> _checksumCache;
    private readonly object _lockObj = new object();
    private readonly ILogger _logger;

    public LineChecksumProcessor(ILogger logger)
    {
        _checksumCache = new ConcurrentDictionary<long, string>();
        _logger = logger;
    }

    public Dictionary<long, string> ProcessFile(string filePath)
    {
        var result = new Dictionary<long, string>();

        using (var fileStream = File.OpenRead(filePath))
        {
            long lineNumber = 0;

            var buffer = new byte[4096];
            int bytesRead;

            while ((bytesRead = fileStream.Read(buffer, 0, buffer.Length)) > 0)
            {
                for (int i = 0; i < bytesRead; i++)
                {
                    lineNumber++;
                    string line = Encoding.UTF8.GetString(buffer, i, bytesRead - i);
                    byte[] hashBytes;
                    using (var sha256 = SHA256.Create())
                    {
                        hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(line));
                    }
                    result[lineNumber] = Convert.ToBase64String(hashBytes);

                    if (_checksumCache.Count >= CacheSizeLimit)
                    {
                        _logger.LogError("Checksum cache exceeded size limit. Evicting less recently used items.");
                        var oldestItemsToRemove = _checksumCache
                            .OrderByDescending(x => x.Value.LastAccessTime)
                            .Take(_checksumCache.Count - CacheSizeLimit);

                        foreach (var item in oldestItemsToRemove)
                        {
                            _checksumCache.TryRemove(item.Key, out _);
                        }
                    }

                    // Update cache for the processed line
                    _checksumCache.AddOrUpdate(lineNumber, result[lineNumber], (key, old) => result[lineNumber]);
                }
            }
        }

        return result;
    }
}

public interface ILogger
{
    void LogError(string message);
}
