using System.Text.Json;
using System.Threading.Tasks;

namespace JsonDeserializer
{
    public class JsonSerializer
    {
        private readonly JsonSerializerOptions _options;
        private readonly object _lock = new object();

        public JsonSerializer(JsonSerializerOptions options = null)
        {
            _options = options ?? new JsonSerializerOptions();
        }

        public async Task<T> DeserializeJsonAsync<T>(string json, T @default) where T : class
        {
            try
            {
                return await Task.Run(() =>
                {
                    lock (_lock)
                    {
                        return JsonSerializer.Deserialize<T>(json, _options);
                    }
                });
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to deserialize JSON: {ex.Message}", ex);
            }
        }

        public T DeserializeJson<T>(string json) where T : class
        {
            try
            {
                return JsonSerializer.Deserialize<T>(json, _options);
            }
            catch (Exception ex)
            {
                throw new Exception($"Failed to deserialize JSON: {ex.Message}", ex);
            }
        }

        public void SetCustomOptions(JsonSerializerOptions options)
        {
            _options = options;
        }
    }
}
