    if (!records) {
        exit(EXIT_FAILURE);
    }

    int i, j;
    for (i = 0; i < MAX_KEY_T; i++) {
        records[i] = (record_t*)allocate_memory(sizeof(record_t));
        if (!records[i]) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        for (j = 0; j < MAX_OFFSET_T; j++) {
            records[i]->offset = i + j;
            records[i]->key = rand() % MAX_VALUE_RNG;
            records[i]->value = rand() % MAX_VALUE_RNG;
        }
    }

    // Handle concurrent access
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (i = 0; i < MAX_KEY_T; i++) {
        pthread_mutex_lock(&lock);
        // Access and process records concurrently
        pthread_mutex_unlock(&lock);
    }

    // Deallocate memory
    for (i = 0; i < MAX_KEY_T; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}

