import time
from typing import Dict, List
from functools import wraps
from redis import Redis
from rq.job import Job

def rate_limited(max_per_second: int):
    def decorator(func):
        last_call = [0]

        @wraps(func)
        def wrapper(*args, **kwargs):
            elapsed = time.time() - last_call[0]
            left_to_wait = 1 / max_per_second - elapsed
            if left_to_wait > 0:
                time.sleep(left_to_wait)
            ret = func(*args, **kwargs)
            last_call[0] = time.time()
            return ret

        return wrapper

    return decorator

def process_tokens(tokens: List[str], config: Dict) -> List[str]:
    redis_config = config['redis']
    redis_client = Redis(host=redis_config['host'], port=redis_config['port'], db=redis_config['db'])
    token_expirations_store = config['token_expirations_store']

    @rate_limited(max_per_second=10)
    def process_token(token: str) -> None:
        try:
            expiration_date = redis_client.get(token_expirations_store[0])
            if not expiration_date or int(expiration_date) < time.time():
                # Token is invalid, remove it from the list
                tokens.remove(token)
            else:
                # Token is valid, mark it as used and update the user's last seen timestamp
                redis_client.hincrby(token_expirations_store[1], token, 1)
        except Exception as e:
            print(f"Error processing token {token}: {str(e)}")

    [process_token(t) for t in tokens]
    return tokens

def cache_tokens(tokens: List[str], config: Dict) -> None:
    redis_config = config['redis']
    redis_client = Redis(host=redis_config['host'], port=redis_config['port'], db=redis_config['db'])
    token_expirations_store = config['token_expirations_store']

    @rate_limited(max_per_second=10)
    def cache_token(token: str) -> None:
        try:
            expiration_date = redis_client.get(token_expirations_store[0])
            if not expiration_date or int(expiration_date) < time.time():
                # Token is invalid, remove it from the list
                tokens.remove(token)
            else:
                # Cache token for future lookups
                redis_client.set(token, 'cached', ex=300)
        except Exception as e:
            print(f"Error caching token {token}: {str(e)}")

    [cache_token(t) for t in tokens]
