typedef struct record {
    int value;
    char* str;
} Record;

Record* init_records(int num_records, size_t max_str_len) {
    if (num_records <= 0 || max_str_len > INT_MAX - sizeof(Record)) {
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        records[i].str = malloc(max_str_len + 1);
        if (!records[i].str) {
            free(records);
            return NULL;
        }
    }

    return records;
}

void* alloc_with_grow(size_t* size, size_t grow_threshold) {
    void* ptr = malloc(*size);
    if (ptr && *size > grow_threshold) {
        size_t new_size = *size + *size / 2;
        free(ptr);
        ptr = realloc(NULL, new_size);
        *size = new_size;
    }
    return ptr;
}

void set_record_values(Record* records, int num_records, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void free_resources(Record* records, size_t max_str_len) {
    if (!records) {
        return;
    }

    for (int i = 0; i < records->num_records; i++) {
        free(records[i].str);
    }
    free(records);
}

