void insertStringAfterTarget(std::list<std::string>& strList, const std::string& target, const std::string& insertStr) {
    auto it = strList.begin();
    while (it != strList.end()) {
        if (*it == target) {
            strList.insert(++it, insertStr);
            return;
        }
        ++it;
    }
    strList.push_back(insertStr);
}

int main() {
    // Example usage
    std::vector<std::string> dialogFields = {"field1", "field2", "field3"};
    std::vector<std::string> fieldNamesToRefresh = {"field1", "field3"};

    refreshDialogFields(dialogFields, fieldNamesToRefresh);

    std::list<std::string> strList = {"hello", "world", "target", "this", "is", "a", "test"};
    const std::string targetStr = "target";
    const std::string insertStr = "inserted";

    insertStringAfterTarget(strList, targetStr, insertStr);

    // Print the modified list
    for (const auto& str : strList) {
        std::cout << str << std::endl;
    }

    return 0;
