// Define a structure for record data
typedef struct {
    char* key;
    double value;
} Record;

// Function to process data pipeline
void processDataPipeline() {
    // Allocate memory for arrays
    char** keys = (char**)malloc(4096 * sizeof(char*));
    double* values = (double*)malloc(4096 * sizeof(double));
    Record* records = (Record*)malloc(2048 * sizeof(Record));

    // Initialize arrays
    for(int i = 0; i < 4096; i++) {
        keys[i] = malloc(10);
        sprintf(keys[i], "key_%d", i);
        values[i] = (double)(rand() / (RAND_MAX / 100.0));
    }
    for(int i = 0; i < 2048; i++) {
        records[i].key = keys[rand() % 4096];
        records[i].value = values[rand() % 4096];
    }

    // Validate memory allocation
    if(!keys || !values || !records) {
        printf("Memory allocation failed\n");
        exit(1);
    }

    // Process data pipeline concurrently
    pthread_t threads[15];
    for(int i = 0; i < 15; i++) {
        pthread_create(&threads[i], NULL, processRecord, records + i * 128);
    }
    for(int i = 0; i < 15; i++) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup memory
    for(int i = 0; i < 4096; i++) {
        free(keys[i]);
    }
    free(keys);
    free(values);
    for(int i = 0; i < 2048; i++) {
        free(records[i].key);
    }
    free(records);
}

// Function to process a record concurrently
void* processRecord(void* arg) {
    Record* record = (Record*)arg;
    // Process the record based on specific criteria
    if(strlen(record->key) > 50) {
        printf("Filtered out string '%s'\n", record->key);
    } else {
        char* lowercaseKey = strdup(record->key);
        int i = 0;
        while(i < strlen(lowercaseKey)) {
            lowercaseKey[i] = tolower(lowercaseKey[i]);
            i++;
        }
        printf("Transformed string '%s' to '%s'\n", record->key, lowercaseKey);
        free(lowercaseKey);
    }
    return NULL;
}

int main() {
    processDataPipeline();
    return 0;
}
