        char* token = strtok(file, ";");
        if (token == NULL || strlen(token) > 20) {
            continue; // invalid entry
        }
        log_entry* log_entry = &log_entries[timestamp_idx];

        // Initialize log_entry fields
        sscanf(token, "%d", &log_entry->timestamp);
        token = strtok(NULL, ";");
        if (token == NULL || strlen(token) > 20) {
            continue; // invalid entry
        }
        strcpy(log_entry->log_level, token);

        token = strtok(NULL, ";");
        if (token == NULL || strlen(token) > 20) {
            continue; // invalid entry
        }
        strcpy(log_entry->source_ip, token);

        token = strtok(NULL, ";");
        if (token == NULL || strlen(token) > 20) {
            continue; // invalid entry
        }
        strcpy(log_entry->destination_ip, token);

        token = strtok(NULL, ";");
        if (token == NULL || strlen(token) > 10) {
            continue; // invalid entry
        }
        strcpy(log_entry->protocol, token);

        token = strtok(NULL, ";");
        if (token == NULL) {
            continue; // invalid entry
        }
        log_messages[message_idx] = strdup(token);
        message_idx++;

        timestamp_idx++;
    }

    fclose(file);
    return &log_entries;
