function traverseDOMTree(selector, callback) {
    const matches = document.querySelectorAll(selector);

    if (matches.length > 0) {
        const result = [];
        for (const match of matches) {
            callback(match);
            result.push(match);
        }
        return result;
    } else {
        return []; // return empty array
    }
}
