#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
} record;

typedef struct cache_entry {
    int key;
    record *record_ptr;
} cache_entry;

typedef struct {
    record **records;
    int capacity;
    int size;
    pthread_mutex_t mutex;
    cache_entry **cache;
    int cache_size;
    int cache_capacity;
} cache_manager;

void* init_cache_manager(int initial_capacity, int cache_capacity) {
    cache_manager *cm = (cache_manager*)malloc(sizeof(cache_manager));

    cm->records = (record**)calloc(initial_capacity, sizeof(record *));
    cm->capacity = initial_capacity;
    cm->size = 0;

    pthread_mutex_init(&cm->mutex, NULL);

    cm->cache = (cache_entry**)calloc(cache_capacity, sizeof(cache_entry *));
    cm->cache_size = 0;
    cm->cache_capacity = cache_capacity;

    return cm;
}

void add_record(cache_manager *cm, long offset, int key) {
    pthread_mutex_lock(&cm->mutex);

    if (cm->size >= cm->capacity) {
        // resize the records array
        record **new_records = (record**)realloc(cm->records, (cm->capacity *= 2) * sizeof(record *));

        for (int i = 0; i < cm->size; i++) {
            new_records[i] = cm->records[i];
        }
        free(cm->records);
        cm->records = new_records;
    }

    record *new_record = (record*)malloc(sizeof(record));
    new_record->offset = offset;
    new_record->key = key;

    cm->records[cm->size++] = new_record;

    pthread_mutex_unlock(&cm->mutex);
}

void update_record(cache_manager *cm, int key, long offset) {
    pthread_mutex_lock(&cm->mutex);

    for (int i = 0; i < cm->size; i++) {
        if (cm->records[i]->key == key) {
            cm->records[i]->offset = offset;
            break;
        }
    }

    pthread_mutex_unlock(&cm->mutex);
}

record* get_record(cache_manager *cm, int key) {
    pthread_mutex_lock(&cm->mutex);

    for (int i = 0; i < cm->cache_size; i++) {
        if (cm->cache[i]->key == key) {
            return cm->cache[i]->record_ptr;
        }
    }

    // cache miss, search in records array
    for (int i = 0; i < cm->size; i++) {
        if (cm->records[i]->key == key) {
            record *record_ptr = (record*)malloc(sizeof(record));
            *record_ptr = *(cm->records[i]);

            // add to cache
            cache_entry *new_cache_entry = (cache_entry*)malloc(sizeof(cache_entry));
            new_cache_entry->key = key;
            new_cache_entry->record_ptr = record_ptr;

            cm->cache[cm->cache_size++] = new_cache_entry;

            if (cm->cache_size >= cm->cache_capacity) {
                // resize the cache array
                cache_entry **new_cache = (cache_entry**)realloc(cm->cache, (cm->cache_capacity *= 2) * sizeof(cache_entry *));

                for (int j = 0; j < cm->cache_size; j++) {
                    new_cache[j] = cm->cache[j];
                }
                free(cm->cache);
                cm->cache = new_cache;
            }

            return record_ptr;
        }
    }

    pthread_mutex_unlock(&cm->mutex);

    // not found
    return NULL;
}

void monitor_performance(cache_manager *cm) {
    printf("Records: %d, Cache Size: %d, Cache Capacity: %d\n", cm->size, cm->cache_size, cm->cache_capacity);
}
