    int priority;
    time_t deadline;
    TaskStatus status;
    char* description;
} Task;

Task* tasks = NULL;
size_t task_count = 0;

void free_tasks() {
    for (size_t i = 0; i < task_count; i++) {
        free(tasks[i].description);
    }
    free(tasks);
}

int load_tasks_from_csv(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        return -1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        size_t i = 0;
        Task* task = NULL;
        for (char* p = strtok(line, ","); p; p = strtok(NULL, ",")) {
            if (!task) {
                task = realloc(task, sizeof(*task));
                task->priority = atoi(p);
                p = strtok(NULL, ",");
                task->deadline = atoi(p);
                p = strtok(NULL, ",");
                task->status = (p[0] == '1') ? TASK_NEW : (p[0] == '2') ? TASK_IN_PROGRESS : TASK_COMPLETED;
            } else {
                task->description = realloc(task->description, strlen(p) + 1);
                strcpy(task->description, p);
            }
        }

        if (task) {
            tasks = realloc(tasks, sizeof(*tasks) * ++task_count);
            memcpy(&tasks[task_count - 1], task, sizeof(*task));
            free(task);
        }
    }

    fclose(file);

    return 0;
}
