#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <zlib.h>

typedef enum {
    PENDING,
    RUNNING,
    FINISHED,
    FAILED
} TaskStatus;

typedef struct {
    int priority;
    time_t deadline;
    enum TaskStatus status;
    char* metadata;
} Task;

void init_task(Task* task) {
    task->priority = 0;
    task->deadline = 0;
    task->status = PENDING;
    task->metadata = NULL;
}

Task* create_task() {
    Task* task = (Task*)malloc(sizeof(Task));
    init_task(task);
    return task;
}

int parse_task(const char* line, Task* task) {
    char* token = strtok(line, ",");
    if (!token) return -1; // invalid format
    task->priority = atoi(token);

    token = strtok(NULL, ",");
    if (!token) return -2; // missing deadline
    task->deadline = strtotm(token);

    token = strtok(NULL, ",");
    if (!token) return -3; // missing status
    task->status = (TaskStatus)atoi(token);

    token = strtok(NULL, ",");
    if (!token) return -4; // missing metadata
    task->metadata = strdup(token);
    return 0;
}

int extract_tasks(const char* archive_path, Task** tasks) {
    FILE* file = fopen(archive_path, "r");
    if (!file) return -5; // cannot open file

    Task* current_task = NULL;
    int task_id = 0;

    while (1) {
        char line[1024];
        if (!fgets(line, sizeof(line), file)) break; // end of file
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0'; // remove trailing newline

        if (current_task) {
            int status = parse_task(line, current_task);
            if (status < 0) {
                free(current_task->metadata);
                free(current_task);
                current_task = NULL;
                task_id--;
            } else {
                task_id++;
            }
        } else {
            current_task = create_task();
            int status = parse_task(line, current_task);
            if (status < 0) return -6; // invalid format
        }

        if (!current_task) continue;

        tasks[task_id] = current_task;
    }

    fclose(file);
    return task_id + 1;
}

void free_tasks(Task** tasks, int count) {
    for (int i = 0; i < count; i++) {
        free(tasks[i]->metadata);
        free(tasks[i]);
    }
}

void log_operation(const char* message) {
    // implement logging mechanism here
}
