// Define transaction structure
typedef struct {
    int timestamp;
    char status;
    void* data;
    void* summary;
} Transaction;

// Allocate memory and initialize structures
void processTransactions() {
    // Initialize memory pool for dynamic memory allocation
    void* large_memory = NULL;
    void* medium_memory = NULL;
    void* small_memory = NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Create a lock

    if ((large_memory = malloc(4096 * sizeof(int))) == NULL) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    if ((medium_memory = malloc(2048 * sizeof(int))) == NULL) {
        free(large_memory);  // Free previously allocated memory
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    if ((small_memory = malloc(1024 * sizeof(int))) == NULL) {
        free(large_memory);  // Free previously allocated memory
        free(medium_memory);  // Free previously allocated medium memory
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    // Initialize array of 'transaction' objects, each containing a 'timestamp', 'status', 'data pointer', and 'summary pointer'
    Transaction* transactions = (Transaction*)malloc(1024 * sizeof(Transaction));

    // Validate successful memory allocation and initialization
    if (transactions == NULL) {
        free(large_memory);  // Free previously allocated large memory
        free(medium_memory);  // Free previously allocated medium memory
        free(small_memory);  // Free previously allocated small memory
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    // Populate each transaction's 'data pointer' and 'summary pointer' with dynamically allocated binary payloads
    for (int i = 0; i < 1024; i++) {
        transactions[i].timestamp = ...;  // Initialize timestamp
        transactions[i].status = ...;  // Initialize status

        // Allocate memory for data and summary using the previously initialized memory pool
        transactions[i].data = malloc(1024);  // Allocate memory for 'large' data block
