    for (int i = 0; i < arraySize - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < arraySize; j++) {
            if (keys[j] < keys[minIndex]) {
                minIndex = j;
            }
        }
        int temp = keys[i];
        keys[i] = keys[minIndex];
        keys[minIndex] = temp;

        // Swap corresponding offsets and timestamps
        long temp1 = offsets1[i];
        long temp2 = offsets2[i];
        offsets1[i] = offsets1[minIndex];
        offsets2[i] = offsets2[minIndex];
        offsets1[minIndex] = temp1;
        offsets2[minIndex] = temp2;
    }

    // Find and print the largest integer from the sorted array
    int maxKey = keys[0];
    for (int i = 1; i < arraySize; i++) {
        if (keys[i] > maxKey) {
            maxKey = keys[i];
        }
