// Define the maximum number of data points
#define MAX_DATA_POINTS 1000

// Define the maximum length of a string
#define MAX_STRING_LENGTH 256

// Define the range for random point coordinates
#define POINT_X_MIN 0.0
#define POINT_Y_MIN 0.0
#define POINT_X_MAX 10.0
#define POINT_Y_MAX 10.0

typedef struct {
    double value;
    char* name;
    struct point coordinates;
} data_point;

struct point {
    float x, y;
};

// Function to dynamically allocate and initialize an array of data_point structures
int create_data_points(int num_points) {
    int i;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Initialize a mutex for thread safety

    if (num_points > MAX_DATA_POINTS) {
        printf("Error: Too many points requested. Maximum is %d.\n", MAX_DATA_POINTS);
        return -1; // Return an error code
    }

    data_point* points = (data_point*)malloc(num_points * sizeof(data_point)); // Dynamically allocate memory for the array

    if (!points) {
        printf("Error: Memory allocation failed.\n");
        return -2; // Return an error code
    }

    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety

    for (i = 0; i < num_points; i++) {
        points[i].value = rand() / (RAND_MAX + 1.0); // Initialize a random value for each data point

        char* name = (char*)malloc(MAX_STRING_LENGTH * sizeof(char)); // Dynamically allocate memory for the string
        if (!name) {
            printf("Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            free(points);
            return -2; // Return an error code
        }

        name[0] = '\0'; // Initialize the string to zero-length

        pthread_mutex_lock(&lock); // Lock the mutex again for thread safety

        points[i].name = name;

        struct point* coordinates = (struct point*)malloc(sizeof(struct point)); // Dynamically allocate memory for the coordinates
        if (!coordinates) {
            printf("Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&lock);
            free(points[i].name);
            return -2; // Return an error code
        }

        do {
            coordinates->x = (float)(rand() / (RAND_MAX + 1.0)) * (POINT_X_MAX - POINT_X_MIN) + POINT_X_MIN;
            coordinates->y = (float)(rand() / (RAND_MAX + 1.0)) * (POINT_Y_MAX - POINT_Y_MIN) + POINT_Y_MIN;
        } while (coordinates->x == points[i].name ? 0 : i++); // Ensure no two points have the same x-coordinate

        points[i].coordinates = *coordinates;

        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_unlock(&lock);

    return num_points; // Return the number of successfully created data points
}

int main() {
    int num_points;
    printf("Enter the number of data points: ");
    scanf("%d", &num_points);

    int result = create_data_points(num_points);

    if (result < 0) {
        printf("Error occurred. Exiting.\n");
    } else {
        printf("Data point creation successful with %d points.\n", result);
    }

    return 0;
}
