task* create_task(const char* desc, int prio, const struct tm* due_date) {
    task* t = (task*)malloc(sizeof(task));
    if (!t) {
        return NULL;  // Memory allocation failed
    }

    t->description = (char*)malloc(strlen(desc) + 1);
    if (!t->description) {
        free(t);
        return NULL;  // Memory allocation failed
    }
    strcpy(t->description, desc);

    if (prio < 1 || prio > 5) {
        free(t->description);
        free(t);
        return NULL;  // Invalid priority level
    }

    t->priority = prio;

    if (due_date) {
        t->date.day = due_date->tm_mday;
        t->date.month = due_date->tm_mon + 1;
        t->date.year = due_date->tm_year + 1900;

        // Validate the date
        time_t now = time(NULL);
        struct tm* now_tm = localtime(&now);
        if (t->date.day > now_tm->tm_mday || 
            t->date.month > now_tm->tm_mon || 
            t->date.year > now_tm->tm_year + 1900) {
            free(t->description);
            free(t);
            return NULL;  // Invalid date
        }
    } else {
        // If no due_date is provided, consider it as the current date
        time_t now = time(NULL);
        struct tm* now_tm = localtime(&now);
        t->date.day = now_tm->tm_mday;
        t->date.month = now_tm->tm_mon + 1;
        t->date.year = now_tm->tm_year + 1900;
    }

    return t;
}

void destroy_task(task* t) {
    free(t->description);
    free(t);
}
