void processAndFindMax() {
    // Initialize arrays with optimized memory allocation
    int *long_offsets = (int *)malloc(4096 * sizeof(int));
    int *keys = (int *)malloc(4096 * sizeof(int));
    float *weights = (float *)malloc(4096 * sizeof(float));
    record *records = (record *)malloc(2048 * sizeof(record));

    // Initialize records with random values
    for (int i = 0; i < 2048; i++) {
        keys[i] = rand() % 90 + 10;
        weights[i] = (float)rand() / RAND_MAX;
        long_offsets[i] = hash(keys[i], weights[i]);
        records[i].key = keys[i];
        records[i].weight = weights[i];
        records[i].offset = long_offsets[i];
    }

    // Sort records based on their key values
    qsort(records, 2048, sizeof(record), compare);

    // Release allocated memory
    free(long_offsets);
    free(keys);
    free(weights);
    free(records);
}

int hash(int key, float weight) {
    return (key + (int)(weight * 1000)) % 4096;
}

int compare(const void *a, const void *b) {
    record *record1 = *(record *)a;
    record *record2 = *(record *)b;
    if (record1->key < record2->key)
        return -1;
    else if (record1->key > record2->key)
        return 1;
    else
        return 0;
}
