    int sumValues = 0;
    int maxValue = INT_MIN;
    int minValue = INT_MAX;
    int successfulFilters = 0;
    int failedFilters = 0;

    clock_t lastFilterTimestamp = 0;
    double rollingWeightedSum = 0.0;

    for (int i = 0; i < numRecords; i++) {
        // Generate record value from distribution function
        records[i].value = rand() % 100; // Replace with actual distribution function

        // Filter based on criteria: value, last 10ms records received, and rolling weighted sum
        if (records[i].value > max(0, 5 - (double)sumValues / totalProcessed)) {
            successfulFilters++;
        } else {
            failedFilters++;
        }

        sumValues += records[i].value;
        totalProcessed++;

        // Update metrics
        maxValue = records[i].value > maxValue ? records[i].value : maxValue;
        minValue = records[i].value < minValue ? records[i].value : minValue;

        // Calculate rolling weighted sum
        rollingWeightedSum *= 0.9; // Decay factor
        rollingWeightedSum += (double)records[i].value / totalProcessed;

        // Update last filter timestamp
        if ((clock() - lastFilterTimestamp) >= 10000) {
            lastFilterTimestamp = clock();
        }
    }

    free(offsets);
    free(keys);

    // Find maximum weighted sum and corresponding record ID
    int maxWeightedSumRecordID = 0;
    double maxWeightedSum = rollingWeightedSum;

    for (int i = 0; i < numRecords; i++) {
        if ((double)records[i].value / totalProcessed > maxWeightedSum) {
            maxWeightedSum = (double)records[i].value / totalProcessed;
            maxWeightedSumRecordID = i;
        }
    }

    // Free allocated memory
    free(records);

    return &records[maxWeightedSumRecordID];
}
