void* slab_alloc(size_t size);
void slab_free(void* ptr);

entry** array = NULL;
int capacity = 0;
int size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_entry(double value) {
    pthread_mutex_lock(&mutex);
    if (size >= capacity) {
        capacity *= 2;
        array = realloc(array, capacity * sizeof(entry*));
    }
    entry** new_array = malloc(capacity * sizeof(entry*));
    memcpy(new_array, array, size * sizeof(entry*));
    free(array);
    array = new_array;

    entry* new_entry = slab_alloc(sizeof(entry));
    new_entry->value = value;
    char buffer[64];
    sprintf(buffer, "%f", value);
    new_entry->id_str = strdup(buffer);
    array[size++] = new_entry;
    pthread_mutex_unlock(&mutex);
}

void print_entries() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < size; i++) {
        printf("Entry %d: value = %.2f, id = %s\n", i, array[i]->value, array[i]->id_str);
    }
    pthread_mutex_unlock(&mutex);
}

void* slab_alloc(size_t size) {
    static void* slab[SLAB_SIZE] = {NULL};
    int slot = (int)(size / sizeof(void*) + 1) % SLAB_SIZE;
    return slab[slot];
}

void slab_free(void* ptr) {
    // nothing to do here
}
