```c
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 50
#define TIMEOUT 10000 // in milliseconds

typedef struct {
    int sockfd;
    int timeout;
} connection_t;

connection_t* connections[MAX_CONNECTIONS];
int num_connections = 0;

void init_connection(int sockfd) {
    connection_t* new_conn = (connection_t*)malloc(sizeof(connection_t));
    new_conn->sockfd = sockfd;
    new_conn->timeout = TIMEOUT;
    connections[num_connections++] = new_conn;
}

void cleanup_connection(int index) {
    if(index < num_connections) {
        free(connections[index]);
        memmove(&connections[index], &connections[index + 1], (num_connections - index - 1) * sizeof(connection_t*));
        num_connections--;
    }
}

int get_available_connection() {
    for(int i = 0; i < num_connections; i++) {
        if(connections[i]->timeout > 0) {
            connections[i]->timeout -= TIMEOUT / 100;
            return i;
        }
    }
    return -1;
}

void update_timeout(int index) {
    if(index >= 0 && index < num_connections) {
        connections[index]->timeout = TIMEOUT;
    }
}

void check_connection_health() {
    for(int i = 0; i < num_connections; i++) {
        if(connections[i]->timeout <= 0) {
            cleanup_connection(i);
        } else {
            update_timeout(i);
        }
    }
}

// Function to handle connection pool
int manage_connection_pool(int sockfd, int new_conn_timeout) {
    if(num_connections >= MAX_CONNECTIONS) {
        return -1; // Connection pool is full
    }

    for(int i = 0; i < num_connections; i++) {
        if(connections[i]->sockfd == sockfd && connections[i]->timeout <= 0) {
            cleanup_connection(i);
            break;
        }
    }

    init_connection(sockfd);

    return get_available_connection();
}
