    pthread_t threads[num_threads];
    Record temp_record;

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, &sort_records_thread, NULL);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void* sort_records_thread(void* arg) {
    int start_idx = (MAX_RECORDS / num_threads) * i;
    int end_idx = (start_idx + MAX_RECORDS / num_threads - 1);

    for (int j = start_idx; j <= end_idx; j++) {
        for (int k = j + 1; k < MAX_RECORDS; k++) {
            if (record[j].key > record[k].key) {
                temp_record = record[j];
                record[j] = record[k];
                record[k] = temp_record;
            }
        }
    }

    return NULL;
}

void* log_performance(void* arg) {
    // Log performance metrics
    printf("Sorting took %f seconds\n", (double)clock() / CLOCKS_PER_SEC);
    return NULL;
}

int main(int argc, char** argv) {
    pthread_t thread;

    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    keys = (int*)malloc(MAX_RECORDS * sizeof(int));

    if (!records || !offsets || !keys) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].key = -1;
        records[i].offset = -1;
    }

    pthread_create(&thread, NULL, &populate_records, NULL);
    pthread_join(thread, NULL);

    // Sort and log performance
    sort_records(NULL);
    pthread_create(&thread, NULL, &log_performance, NULL);
    pthread_join(thread, NULL);

    for (int i = 0; i < MAX_RECORDS; i++) {
        printf("%d %ld\n", records[i].key, records[i].offset);
    }

    free(records);
    free(offsets);
    free(keys);

    return 0;
}

