// Data structure to manage multiple sensors
typedef struct {
    int count;
    sensorData **data;
} sensorLog;

// Function to initialize the memory management system
sensorLog* initSensorLog() {
    sensorLog* log = (sensorLog*)malloc(sizeof(sensorLog));
    log->count = 0;
    log->data = NULL;
    return log;
}

// Function to add a new sensor reading
void addSensorReading(sensorLog* log, long timestamp, float reading, char status) {
    // Dynamically allocate memory for the new sensor data
    sensorData* newData = (sensorData*)malloc(sizeof(sensorData));
    newData->timestamp = timestamp;
    newData->reading = reading;
    newData->status = status;

    // Reallocation if necessary
    int newSize = log->count + 1;
    sensorData** newDataArray = (sensorData**)realloc(log->data, newSize * sizeof(sensorData*));
    log->data = newDataArray;

    // Copy the new data to the end of the array
    log->data[log->count] = newData;
    log->count++;

    return;
}

// Function to remove a sensor reading
void removeSensorReading(sensorLog* log, long timestamp) {
    int i;
    for (i = 0; i < log->count; i++) {
        if (log->data[i]->timestamp == timestamp) {
            // Free the allocated memory
            free(log->data[i]);
            memmove(&log->data[i], &log->data[i+1], (log->count - i - 1) * sizeof(sensorData*));
            log->count--;
            break;
        }
    }

    return;
}

// Function to calculate average sensor reading within a time range
float calculateAverageReading(sensorLog* log, long startTimestamp, long endTimestamp) {
    int count = 0;
    float totalReading = 0.0;

    for (int i = 0; i < log->count; i++) {
        if (log->data[i]->timestamp >= startTimestamp && log->data[i]->timestamp <= endTimestamp) {
            totalReading += log->data[i]->reading;
            count++;
        }
    }

    // Check for potential data gaps
    if (count == 0) {
        return -1.0; // or handle the case as per your requirement
    } else {
        return totalReading / count;
    }
}

int main() {
    sensorLog* log = initSensorLog();

    addSensorReading(log, 1643723400, 3.5f, 'A');
    addSensorReading(log, 1643723410, 2.8f, 'B');
    addSensorReading(log, 1643723420, 4.2f, 'C');

    printf("Average reading within time range (1643723400-1643723420): %.2f\n", calculateAverageReading(log, 1643723400, 1643723420));

    removeSensorReading(log, 1643723410);

    return 0;
}

