int max_sensors = 10000;

void add_sensor(sensorData* new_sensor) {
    if (num_sensors >= max_sensors) {
        printf("Maximum number of sensors reached.\n");
        return;
    }

    sensorData** temp = realloc(sensor_array, (num_sensors + 1) * sizeof(sensorData*));
    if (!temp) {
        printf("Memory allocation failed.\n");
        return;
    }
    sensor_array = temp;

    sensor_array[num_sensors] = new_sensor;
    num_sensors++;

    return;
}

void remove_sensor(int index) {
    if (index < 0 || index >= num_sensors) {
        printf("Invalid sensor index.\n");
        return;
    }

    for (int i = index; i < num_sensors - 1; i++) {
        sensor_array[i] = sensor_array[i + 1];
    }
    num_sensors--;

    // Compact memory blocks
    int new_max_size = 0;
    sensorData** temp = NULL;
    for (int i = 0; i < num_sensors; i++) {
        if (new_max_size + sizeof(sensorData*) > new_max_size) {
            temp = realloc(temp, (new_max_size + 1) * sizeof(sensorData*));
            if (!temp) {
                printf("Memory allocation failed.\n");
                return;
            }
            sensor_array[i] = &sensor_array[i];
        } else {
            temp[new_max_size++] = &sensor_array[i];
        }
    }
    free(sensor_array);
    sensor_array = temp;

    return;
}

float calculate_average(float start_time, float end_time) {
    int count = 0;
    float sum = 0.0f;

    for (int i = 0; i < num_sensors; i++) {
        for (int j = 0; j < sensor_array[i]->timestamp; j++) {
            if (sensor_array[i]->timestamp > end_time) {
                break;
            }
            if (sensor_array[i]->timestamp >= start_time && sensor_array[i]->reading > 0.5f) {
                sum += sensor_array[i]->reading;
                count++;
            }
        }
    }

    return sum / count;
}

int validate_data(sensorData* data, int len) {
    for (int i = 0; i < len; i++) {
        if (data[i].timestamp <= 0 || data[i].reading < -100.0f || data[i].status != 'A' && data[i].status != 'E') {
            return 0;
        }
    }
    return 1;
}

int main() {
    // Initialize sensor array
    sensor_array = malloc(max_sensors * sizeof(sensorData));
    num_sensors = 0;

    // Add sensors dynamically
    add_sensor((sensorData*)malloc(sizeof(sensorData)));
    add_sensor((sensorData*)malloc(sizeof(sensorData)));

    // Remove sensors dynamically
    remove_sensor(0);

    float start_time = 100.0f;
    float end_time = 200.0f;
    printf("Average reading: %.2f\n", calculate_average(start_time, end_time));

    return 0;
}
