#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RECORDS_THRESHOLD 16
#define TABLE_SIZE 1024

typedef struct {
    int key;
    int value;
} record_t;

record_t** hash_table;
int active_records = 0;
int table_capacity = 0;

// Function to initialize the hash table and set its initial capacity
void init_hash_table() {
    hash_table = (record_t**)calloc(TABLE_SIZE, sizeof(record_t*));
    table_capacity = TABLE_SIZE;
}

// Function to insert a new record into the hash table
void insert_record(int key, int value) {
    // Calculate the index of the record in the hash table using a simple modulo operation
    int index = key % TABLE_SIZE;

    // Check if the current slot is empty
    if (!hash_table[index]) {
        // Allocate memory for the new record and initialize it with the given key and value
        hash_table[index] = (record_t*)malloc(sizeof(record_t));
        hash_table[index]->key = key;
        hash_table[index]->value = value;

        // Increment the active records counter
        active_records++;
    }
}

// Function to retrieve a record by its unique integer key
record_t* lookup_record(int key) {
    int index = key % TABLE_SIZE;

    // Check if the slot contains a record with the given key
    if (hash_table[index] && hash_table[index]->key == key) {
        return hash_table[index];
    }

    return NULL;
}

// Function to resize the hash table when its current capacity exceeds a specified threshold
void resize_hash_table() {
    // Check if the number of active records has exceeded the threshold
    if (active_records > RECORDS_THRESHOLD * 2) {
        // Calculate the new table size, doubling it for minimal fragmentation and maximizing cache locality
        int new_capacity = TABLE_SIZE * 2;

        // Allocate memory for the new hash table with its updated capacity
        record_t** new_table = (record_t**)calloc(new_capacity, sizeof(record_t*));

        // Rehash all existing records into the new table
        for (int i = 0; i < TABLE_SIZE; i++) {
            if (hash_table[i]) {
                int index = hash_table[i]->key % new_capacity;
                new_table[index] = hash_table[i];
            }
        }

        // Free memory allocated for the old hash table and update the current capacity
        free(hash_table);
        hash_table = new_table;
        TABLE_SIZE = new_capacity;
    }
}

// Function to iterate over all records in sorted order by key
void iterate_records() {
    record_t* current_record;

    // Iterate through each slot in the hash table
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (hash_table[i]) {
            // Iterate through each record in the current slot until a null pointer is encountered
            for (current_record = hash_table[i]; current_record; current_record = current_record->next) {
                printf("Key: %d, Value: %d\n", current_record->key, current_record->value);
            }
        }
    }
}

int main() {
    init_hash_table();

    // Example usage of the functions
    insert_record(1, 10);
    insert_record(2, 20);
    insert_record(3, 30);

    record_t* record = lookup_record(2);
    if (record) {
        printf("Found record: Key = %d, Value = %d\n", record->key, record->value);
    } else {
        printf("Record not found.\n");
    }

    resize_hash_table();

    iterate_records();

    return 0;
}
