typedef struct {
    long timestamp;
    float sensor_reading;
    char status;
} sensorData;

void processAndCalculateAverage() {
    int i, n;
    printf("Enter the number of records: ");
    scanf("%d", &n);
    if (n <= 0) {
        printf("Invalid input. Exiting.\n");
        return;
    }

    long *timestamps = NULL;
    float *sensor_readings = NULL;
    char *status_indicators = NULL;

    sensorData **sensor_data = NULL;

    srand(time(NULL)); // Initialize random number generator

    for (i = 0; i < n; i++) {
        timestamps = realloc(timestamps, sizeof(long) * (i + 1));
        sensor_readings = realloc(sensor_readings, sizeof(float) * (i + 1));
        status_indicators = realloc(status_indicators, sizeof(char) * (i + 1));

        timestamps[i] = rand() % 10000; // Random timestamp
        sensor_readings[i] = (float)rand() / RAND_MAX; // Random sensor reading
        status_indicators[i] = 'A'; // Initialize status indicator

        sensor_data = realloc(sensor_data, sizeof(sensorData *) * (i + 1));
        sensor_data[i] = malloc(sizeof(sensorData));
        sensor_data[i]->timestamp = timestamps[i];
        sensor_data[i]->sensor_reading = sensor_readings[i];
        sensor_data[i]->status = status_indicators[i];

        if (!timestamps || !sensor_readings || !status_indicators || !sensor_data) {
            printf("Memory allocation failed. Exiting.\n");
            for (int j = 0; j < i; j++) {
                free(sensor_data[j]);
            }
            free(sensor_data);
            return;
        }
    }

    // Sorting
    qsort(sensor_data, n, sizeof(sensorData *), compare);

    // Calculate average sensor reading
    float sum = 0.0f;
    for (i = 0; i < n; i++) {
        sum += sensor_data[i]->sensor_reading;
    }
    printf("Average sensor reading: %.2f\n", sum / n);

    // Free memory
    for (i = 0; i < n; i++) {
        free(sensor_data[i]);
    }
    free(sensor_data);
    free(timestamps);
    free(sensor_readings);
    free(status_indicators);
}

int compare(const void *a, const void *b) {
    sensorData *data_a = *(sensorData **)a;
    sensorData *data_b = *(sensorData **)b;

    return (data_a->timestamp - data_b->timestamp);
}
