    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0) {
        return NULL; // invalid input
    }

    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        return NULL; // memory allocation failure for offsets
    }

    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL; // memory allocation failure for keys
    }

    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL; // memory allocation failure for records
    }

    // initialize offsets and keys
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i % max_value + min_value;
    }

    // initialize records with default values
    for (int i = 0; i < num_records; i++) {
        records[i].value = i % max_value + min_value;
    }

    return records;
}
