    size_t index = key % table->size;
    if (table->buckets[index] != NULL && table->buckets[index]->key == key) {
        table->count--;
        table->buckets[index] = NULL;
    } else {
        // Handle missing or out-of-bounds error
    }
    return 0;
}

// Iterate over all records in the hash table and print their keys and values
void hash_table_iterate(HashTable *table, void (*callback)(Record *)) {
    for (size_t i = 0; i < table->size; i++) {
