#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORDS 1000
#define MAX_KEY 1024

typedef struct {
    int key;
    long offset;
} record;

record records[RECORDS];

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* load_data(void* ptr) {
    // Load data from external source here
    for (int i = 0; i < RECORDS; i++) {
        records[i].key = i + 1;
        records[i].offset = i * 1024;
    }
    return NULL;
}

void update_record(int key, long offset) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < RECORDS; i++) {
        if (records[i].key == key) {
            records[i].offset = offset;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < RECORDS; i++) {
        if (records[i].key == key) {
            records[i].key = -1;
            records[i].offset = -1;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void reset_collection() {
    // Reset the entire collection to default values here
    for (int i = 0; i < RECORDS; i++) {
        records[i].key = -1;
        records[i].offset = -1;
    }
}

// Web API endpoints

#include <http.h>

HTTP_GET("/records", handle_get);
HTTP_POST("/records", handle_post);
HTTP_PUT("/records/:id", handle_put);
HTTP_DELETE("/records/:id", handle_delete);

int main() {
    // Initialize the collection
    pthread_t load_thread;
    pthread_create(&load_thread, NULL, load_data, NULL);
    pthread_join(load_thread, NULL);

    // Start the web server
    HTTPServer* server = HTTPCreateServer(8080);
    HTTPSetHandler(server, "/records", handle_get);
    HTTPSetHandler(server, "/records", handle_post);
    HTTPSetHandler(server, "/records/:id", handle_put);
    HTTPSetHandler(server, "/records/:id", handle_delete);
    HTTPStartServer(server);

    return 0;
}

void handle_get(HTTPRequest* request) {
    // Send the entire collection
    HTTPResponse* response = HTTPCreateResponse();
    for (int i = 0; i < RECORDS; i++) {
        char buffer[1024];
        sprintf(buffer, "{\"key\": %d, \"offset\": %ld}", records[i].key, records[i].offset);
        HTTPWriteResponse(response, buffer);
    }
    HTTPSendResponse(request, response);
}

void handle_post(HTTPRequest* request) {
    // Update a record
    int key = atoi(request->query_string);
    long offset = atol(request->body);
    update_record(key, offset);
    HTTPResponse* response = HTTPCreateResponse();
    HTTPWriteResponse(response, "Record updated");
    HTTPSendResponse(request, response);
}

void handle_put(HTTPRequest* request) {
    // Delete a record
    int key = atoi(request->query_string);
    delete_record(key);
    HTTPResponse* response = HTTPCreateResponse();
    HTTPWriteResponse(response, "Record deleted");
    HTTPSendResponse(request, response);
}

void handle_delete(HTTPRequest* request) {
    // Reset the collection
    reset_collection();
    HTTPResponse* response = HTTPCreateResponse();
    HTTPWriteResponse(response, "Collection reset");
    HTTPSendResponse(request, response);
}
