#include <time.h>

typedef struct {
    long offset;
    int key;
    float value;
} record;

record* init_records(int num_records) {
    srand(time(NULL)); // seed pseudo-random number generator

    if (num_records <= 0x10000) { // stack allocation for smaller datasets
        record* records = alloca(num_records * sizeof(record));
        for (int i = 0; i < num_records; i++) {
            records[i].offset = i;
            records[i].key = rand() % 256; // random key between 0 and 255
            records[i].value = ((float) records[i].offset * records[i].key) / 1000.0 + (rand() % 101) / 100.0f;
        }
        return records;
    } else { // heap allocation for larger datasets
        record* records = malloc(num_records * sizeof(record));
        if (!records) {
            return NULL; // handle out-of-memory error
        }

        for (int i = 0; i < num_records; i++) {
            records[i].offset = i;
            records[i].key = rand() % 256; // random key between 0 and 255
            records[i].value = ((float) records[i].offset * records[i].key) / 1000.0 + (rand() % 101) / 100.0f;
        }

        return records;
    }
}

void free_records(record* records, int num_records) {
    if (num_records <= 0x10000) { // stack allocation for smaller datasets
        alloca(num_records * sizeof(record)); // no need to free stack memory
    } else { // heap allocation for larger datasets
        free(records); // properly free allocated memory
    }
}
