#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <time.h>

#define MAX_RECORDS 10000
#define OFFSET_RANGE_MIN 0
#define OFFSET_RANGE_MAX 1000000
#define STRING_LENGTH 64
#define ASCII_CHARACTERS "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

typedef struct {
    int value;
    long offset;
    int key;
    char* string;
} record;

record* initialize_records(const char* config_file_path) {
    json_object* config = NULL;
    int max_records, random_offset_min, random_offset_max;
    srand(time(NULL));

    // Load configuration from file
    config = json_load_file(config_file_path, JSONFILE_ERROR);
    if (config == NULL) {
        printf("Error: Failed to load configuration file.\n");
        return NULL;
    }

    // Parse configuration settings
    max_records = json_object_get_int_value(config, "max_records");
    random_offset_min = json_object_get_int_value(config, "random_offset_min");
    random_offset_max = json_object_get_int_value(config, "random_offset_max");

    if (json_object_object_size(config) != 3 || max_records < 1 || random_offset_min < OFFSET_RANGE_MIN || random_offset_max > OFFSET_RANGE_MAX) {
        printf("Error: Invalid configuration file format.\n");
        json_object_free(config);
        return NULL;
    }

    // Allocate memory for records
    record* records = (record*)malloc(max_records * sizeof(record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records.\n");
        json_object_free(config);
        return NULL;
    }

    // Initialize records
    for (int i = 0; i < max_records; i++) {
        record* current_record = &records[i];
        current_record->value = rand() % (max_records - 1) + 1;
        current_record->offset = (rand() % (random_offset_max - random_offset_min + 1)) + random_offset_min;
        current_record->key = i;

        // Allocate memory for string
        char* string = (char*)malloc((STRING_LENGTH + 1) * sizeof(char));
        if (string == NULL) {
            printf("Error: Failed to allocate memory for record string.\n");
            json_object_free(config);
            free(records);
            return NULL;
        }

        // Generate random string
        for (int j = 0; j < STRING_LENGTH; j++) {
            string[j] = ASCII_CHARACTERS[rand() % strlen(ASCII_CHARACTERS)];
        }
        string[STRING_LENGTH] = '\0';
        current_record->string = string;
    }

    json_object_free(config);
    return records;
}
