// Structure for record
typedef struct {
    long offset;
    int key;
    float value;
} record;

record* allocateRecords(int count) {
    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for records, offsets and keys
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;

    long* offsets = (long*)malloc(100 * sizeof(long));
    int* keys = (int*)malloc(500 * sizeof(int));
    float* values = (float*)malloc(count * sizeof(float));

    // Initialize offsets
    for (int i = 0; i < 100; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    // Shuffle and duplicate-free the offsets array
    for (int i = 0; i < count; i++) {
        int j = rand() % 100;
        while (i > 0 && offsets[j] == offsets[i-1]) {
            j = (j + 1) % 100;
        }
        records[i].offset = offsets[j];
    }

    // Initialize keys
    for (int i = 0; i < 500; i++) {
        keys[i] = i + 1;
    }

    // Assign unique keys to first 50 records
    for (int i = 0; i < 50; i++) {
        int j = rand() % 500;
        while (j >= 450) {
            j = (j + 1) % 500;
        }
        records[i].key = keys[j];
    }

    // Assign random values to first 50 records
    for (int i = 0; i < 50; i++) {
        values[i] = (float)rand() / RAND_MAX;
    }

    // Initialize the rest of the records with default value
    for (int i = 50; i < count; i++) {
        records[i].key = -1;
    }

    free(offsets);
    free(keys);

    return records;
}
