#include <string.h>
#include <time.h>

// Define the maximum number of records
#define MAX_RECORDS 1000

// Define the minimum and maximum random values
#define MIN_RANDOM 1
#define MAX_RANDOM 1000

// Define the record structure with an int value and a dynamically allocated string
typedef struct {
    int value;
    char* id;
} Record;

// Function to generate a random unique identifier for each record
char* generateId(int maxLength) {
    char* id = (char*)malloc((maxLength + 1)*sizeof(char));
    for(int i = 0; i < maxLength; i++) {
        id[i] = (char)(rand() % 26 + 'a');
    }
    id[maxLength] = '\0';
    return id;
}

// Function to dynamically manage memory for the three primary components
Record** manageMemory(int numRecords, int* offsets, int* keys) {
    // Initialize hash table with a size equal to the number of records
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    for(int i = 0; i < numRecords; i++) {
        // Initialize each record with a random value and unique identifier
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = rand() % (MAX_RANDOM - MIN_RANDOM + 1) + MIN_RANDOM;
        int maxLength = (int)(rand() % 10 + 5); // Random length for the ID
        record->id = generateId(maxLength);

        // Store the offset and key in the hash table
        *offsets++ = i;
        *keys++ = record->value;

        records[i] = record;
    }

    return records;
}

void freeMemory(Record** records, int numRecords) {
    for(int i = 0; i < numRecords; i++) {
        if(records[i]->id != NULL)
            free(records[i]->id);
        free(records[i]);
    }
    free(records);
}
