    if (!root || root->data.index == targetIndex) return root;
    if (targetIndex < root->data.index) return findNode(root->left, targetIndex);
    return findNode(root->right, targetIndex);
}

// Function to handle concurrent access and thread safety
void* nodeAccess(void* arg) {
