#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    TASK_STATUS_PENDING,
    TASK_STATUS_IN_PROGRESS,
    TASK_STATUS_COMPLETED
} TaskStatus;

typedef struct {
    int priority;
    time_t deadline;
    enum TaskStatus status;
    char* description;
    long offset;
    int key;
    float value;
} Task;

Task* task_collection = NULL;
int num_tasks = 0;

void load_tasks_from_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return; // handle error

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Task* task = (Task*)malloc(sizeof(Task));
        // parse line and populate task structure
        task->priority = atoi(strtok(line, ","));
        task->deadline = atol(strtok(NULL, ","));
        task->status = TASK_STATUS_PENDING;
        task->description = strdup(strtok(NULL, "\""));
        task->offset = atoll(strtok(NULL, ","));
        task->key = atoi(strtok(NULL, ","));
        task->value = (task->offset * task->key) / 1000.0 + (rand() % 100);
        task_collection = realloc(task_collection, sizeof(Task*) * ++num_tasks);
        task_collection[num_tasks - 1] = task;
    }
    fclose(file);
}

void unload_tasks_from_file(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) return; // handle error

    for (int i = 0; i < num_tasks; i++) {
        Task* task = task_collection[i];
        fprintf(file, "%d,%ld,\"%s\",%ld,%d\n", task->priority, task->deadline, task->description, task->offset, task->key);
    }
    fclose(file);
}

void query_tasks_by_priority(int min_priority) {
    for (int i = 0; i < num_tasks; i++) {
        Task* task = task_collection[i];
        if (task->priority >= min_priority) {
            printf("Priority: %d, Deadline: %ld, Status: %s, Description: %s\n", task->priority, task->deadline, get_task_status_name(task->status), task->description);
        }
    }
}

void query_tasks_by_deadline(time_t deadline) {
    for (int i = 0; i < num_tasks; i++) {
        Task* task = task_collection[i];
        if (task->deadline <= deadline) {
            printf("Priority: %d, Deadline: %ld, Status: %s, Description: %s\n", task->priority, task->deadline, get_task_status_name(task->status), task->description);
        }
    }
}

void add_new_task(int priority, time_t deadline, enum TaskStatus status, char* description) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    // populate new task structure
    new_task->priority = priority;
    new_task->deadline = deadline;
    new_task->status = status;
    new_task->description = strdup(description);
    new_task->offset = 0; // initialize offset
    new_task->key = 1; // initialize key
    new_task->value = (new_task->offset * new_task->key) / 1000.0 + rand() % 100;
    task_collection = realloc(task_collection, sizeof(Task*) * ++num_tasks);
    task_collection[num_tasks - 1] = new_task;
}

void free_task_collection() {
    for (int i = 0; i < num_tasks; i++) {
        Task* task = task_collection[i];
        free(task->description);
        free(task);
    }
    free(task_collection);
    task_collection = NULL;
    num_tasks = 0;
}
