['Here is the C code for the task management function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <yaml.h>

typedef struct {
    char* name;
    int priority;
    time_t start_time;
    struct timeval duration;
} Task;

Task* load_tasks_from_yaml(const char* config_file_path, int max_tasks) {
    yaml_parser_t* parser;
    yaml_event_t event;
    yaml_node_pair_t pair;
    yaml_node_t node;
    Task* tasks = NULL;
    Task* current_task = NULL;
    FILE* file = fopen(config_file_path, "r");
    if (!file) return NULL;

    // Initialize YAML parser
    parser = yaml_create_parser(YAML ParserConfiguration());
    yaml_parser_initialize(parser);

    while (yaml_parser_check_event(parser, &event)) {
        switch (event.type) {
            case YAML_NO_EVENT:
                break;
            case YAML_STREAM_START_EVENT:
                // Initialize task list and its first item
                tasks = malloc(sizeof(Task *) * max_tasks);
                current_task = &tasks[0];
                break;
            case YAML_MAPPING_START_EVENT: {
                yaml_sequence_start_event_t sequence_event = (yaml_sequence_start_event_t)event;
                for (int i = 0; i < sequence_event.count; i++) {
                    pair.key = yaml_get_string(parser, YAML_MAPPING_KEY);
                    pair.value = NULL;

                    // Load task name
                    if (!strcmp(pair.key, "name")) {
                        pair.value = malloc(129); // allocate extra byte for null-terminator
                        fread(pair.value, 1, 128, file);
                        *(pair.value + 128) = '\0';
                    } else {
                        pair.value = NULL;
                    }

                    // Load task priority and start time
                    if (!strcmp(pair.key, "priority")) {
                        fscanf(file, "%d", &current_task->priority);
                    } else if (!strcmp(pair.key, "start_time")) {
                        fscanf(file, "%ld", &current_task->start_time);
                    }

                    // Load task duration
                    if (!strcmp(pair.key, "duration")) {
                        fread(&current_task->duration.tv_sec, sizeof(int), 1, file);
                        fread(&current_task->duration.tv_usec, sizeof(int), 1, file);
                    }

                    free(pair.key);

                    if (pair.value) {
                        current_task = &tasks[i];
                        current_task->name = pair.value;
                    }
                }
                break;
            }
        }
    }

    yaml_parser_delete(parser);
    fclose(file);

    return tasks;
}

