typedef struct {
    double value;
    char* str;
} item;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int read_item_from_file(FILE* file, item** items, int* count) {
    char buffer[1024];
    while (fscanf(file, "%lf %s", &(*items)->value, (*items)->str = malloc_or_die(strlen(buffer))) == 2) {
        (*count)++;
        if (*count >= *sizeof(*items) / sizeof(**items)) {
            item* new_items = realloc_or_die(*items, *count * sizeof(**items));
            *items = new_items;
        }
    }
    return feof(file);
}

void free_item(item* item) {
    free(item->str);
    free(item);
}

void free_items(item** items, int count) {
    for (int i = 0; i < count; i++) {
        free_item(items[i]);
    }
    free(items);
}

item** read_file(const char* filename, int* count) {
    item* items = NULL;
    *count = 0;

    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file '%s'\n", filename);
        return NULL;
    }

    while (!read_item_from_file(file, &items, count));
    rewind(file);

    fclose(file);

    return items;
}

void free_all(item** items, int count) {
    free_items(items, count);
}
