#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1024
#define MIN_KEY -512
#define MAX_KEY 511
#define MIN_VALUE 0
#define MAX_VALUE 1023

typedef struct {
    int key;
    long value;
} Record;

Record* allocateRecords(int numRecords) {
    Record* records = (Record*)aligned_alloc(sizeof(Record), sizeof(long));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }
    return records;
}

void initRecords(Record* records, int numRecords) {
    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        records[i].value = (long)i * sizeof(Record);
    }
}

void validateAllocation(Record* records, int numRecords) {
    if (!records || numRecords < 0) {
        fprintf(stderr, "Error: invalid allocation or initialization.\n");
        exit(EXIT_FAILURE);
    }
}

int compareRecords(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    return recordA->key - recordB->key;
}

void* sortRecords(void* arg) {
    int numRecords = *(int*)arg;
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: failed to allocate memory for sorting.\n");
        exit(EXIT_FAILURE);
    }
    // Sort records in parallel using a custom sorting algorithm
    pthread_sort(records, numRecords);
    free(records);
    return NULL;
}

int main() {
    int numThreads = 4; // Adjust based on system resources and workload
    int numRecords = MAX_RECORDS;

    Record* records = allocateRecords(numRecords);
    initRecords(records, numRecords);

    pthread_t threads[numThreads];
    for (int i = 0; i < numThreads; i++) {
        int* arg = &numRecords;
        pthread_create(&threads[i], NULL, sortRecords, arg);
    }

    // Wait for all threads to complete
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Verify sorting and cleanup
    validateAllocation(records, numRecords);

    free(records);
    return 0;
}
