```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* tag;
    char* class_;
    char* id;
} Element;

void traverse_DOM(Element* node, void (*callback)(Element*)) {
    callback(node);
    if (node->tag && node->tag[0] != '\0') {
        for (int i = 0; i < strlen(node->tag); i++) {
            if (node->tag[i] == '>') {
                // Found end tag, recurse
                char* new_tag = strdup(node->tag + i + 1);
                traverse_DOM(new_tag, callback);
                free(new_tag);
                return;
            }
        }
    }

    for (int i = 0; i < strlen(node->class_); i++) {
        if (node->class_[i] == ' ') {
            // Found class attribute, recurse
            char* new_class = strdup(node->class_ + i + 1);
            traverse_DOM(new_class, callback);
            free(new_class);
            return;
        }
    }

    for (int i = 0; i < strlen(node->id); i++) {
        if (node->id[i] == ' ') {
            // Found ID attribute, recurse
            char* new_id = strdup(node->id + i + 1);
            traverse_DOM(new_id, callback);
            free(new_id);
            return;
        }
    }

    // Recurse on child nodes
    for (int i = 0; i < node->child_count; i++) {
        Element* child = &node->children[i];
        traverse_DOM(child, callback);
    }
}

int main() {
    // Initialize DOM tree
    Element* root = ...;
    traverse_DOM(root, (void (*)())...);

    return 0;
}
