// Define a structure for 'record' type
typedef struct {
    int key;
    time_t timestamp;
    char id[32];
} Record;

// Function to generate random number with thread-safe seeding
long long get_random_number() {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static long long seed = 0;
    pthread_mutex_lock(&mutex);
    seed = (seed * 1103515245 + 12345) % 2^32;
    pthread_mutex_unlock(&mutex);
    return (long long)seed;
}

// Function to sort 'record' array using quicksort
void quicksort(Record* arr, int left, int right) {
    if (left >= right)
        return;
    int i = left;
    int j = right;
    Record pivot = arr[(left + right) / 2];
    while (1) {
        while (i <= j && arr[i].key <= pivot.key)
            i++;
        while (i <= j && arr[j].key >= pivot.key)
            j--;
        if (i <= j)
            swap(&arr[i], &arr[j]);
        else
            break;
    }
    quicksort(arr, left, j);
    quicksort(arr, j + 1, right);
}

// Function to print error message and exit gracefully
void process_error(const char* msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

// Function to manage dynamically allocated array of integers within a multi-threaded data processing pipeline
int processAndFindMax() {
    // Allocate memory for arrays: 'long' offset values (1024), 'int' keys (1024), and 'record' structures (512)
    long* offsets = (long*)malloc(1024 * sizeof(long));
    int* keys = (int*)malloc(1024 * sizeof(int));
    Record* records = (Record*)malloc(512 * sizeof(Record));

    // Validate successful memory allocation and initialization of all arrays
    if (!offsets || !keys || !records) {
        process_error("Memory allocation failed");
        return -1;
    }

    // Initialize offset values and keys with random numbers using custom thread-safe random number generator
    for (int i = 0; i < 1024; i++) {
        offsets[i] = get_random_number();
    }
    for (int i = 0; i < 1024; i++) {
