#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

struct Record {
    double value;
};

struct OffsetArray {
    size_t *offsets;
    size_t length;
    pthread_mutex_t lock;
};

struct KeyArray {
    unsigned int *keys;
    size_t length;
    pthread_mutex_t lock;
};

struct RecordList {
    struct Record *records;
    size_t length;
    pthread_mutex_t lock;
};

int initializeDatastructures(struct OffsetArray *offsets, struct KeyArray *keys, struct RecordList *records, size_t size) {
    if (size == 0) return -1;

    offsets->length = size;
    keys->length = size;
    records->length = size;

    pthread_mutex_init(&offsets->lock, NULL);
    pthread_mutex_init(&keys->lock, NULL);
    pthread_mutex_init(&records->lock, NULL);

    offsets->offsets = malloc(size * sizeof(size_t));
    keys->keys = malloc(size * sizeof(unsigned int));
    records->records = malloc(size * sizeof(struct Record));

    if (!offsets->offsets || !keys->keys || !records->records) {
        // Handle memory allocation failure
        free(offsets->offsets);
        free(keys->keys);
        free(records->records);
        return -1;
    }

    for (size_t i = 0; i < size; ++i) {
        offsets->offsets[i] = rand() % (1000000 + 1); // Generate random offsets
        keys->keys[i] = rand() % (10000 + 1); // Generate random keys
        records->records[i].value = ((double)rand()) / RAND_MAX; // Generate random record values
    }

    return 0;
}
