    srand(time(NULL));

    // Validate the size of the key_t array
    if (num_keys > max_keys) {
        printf("Error: Key count exceeds limit.\n");
        return;
    }

    offset_t* offsets = (offset_t*)malloc(num_keys * sizeof(offset_t));
    key_t* keys = (key_t*)malloc(num_keys * sizeof(key_t));

    // Initialize the arrays with random values
    for (int i = 0; i < num_keys; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        keys[i] = i;
    }

    struct record_t* records = (struct record_t*)malloc(num_keys * sizeof(struct record_t));

    // Initialize the record array
    for (int i = 0; i < num_keys; i++) {
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Serialize the record array
    int* serialized_data = (int*)malloc((num_keys * sizeof(int)) + (sizeof(struct record_t)));
    int offset = 0;

    for (int i = 0; i < num_keys; i++) {
        *(serialized_data + offset) = records[i].value;
        offset += sizeof(int);
    }

    // Deserialize the record array
    struct record_t* deserialized_records = (struct record_t*)malloc(num_keys * sizeof(struct record_t));
    for (int i = 0; i < num_keys; i++) {
        deserialized_records[i].value = *(serialized_data + offset);
        offset += sizeof(int);
    }

    // Free the allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(serialized_data);
}
