// Custom memory pool allocator
typedef struct {
    void* addr;
    size_t size;
} mem_block;

mem_block* mem_pool = NULL;
size_t mem_pool_size = 0;
pthread_mutex_t mem_pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* malloc(size_t size) {
    pthread_mutex_lock(&mem_pool_lock);
    mem_block* new_block = (mem_block*)malloc(sizeof(mem_block));
    if (!new_block) return NULL;
    new_block->addr = malloc(size);
    if (!new_block->addr) {
        free(new_block);
        return NULL;
    }
    new_block->size = size;
    mem_pool_size += size;
    mem_pool = realloc(mem_pool, (mem_pool_size + sizeof(mem_block)) * sizeof(mem_block));
    mem_pool[mem_pool_size / sizeof(mem_block)] = *new_block;
    pthread_mutex_unlock(&mem_pool_lock);
    return new_block->addr;
}

void free(void* addr) {
    pthread_mutex_lock(&mem_pool_lock);
    for (int i = 0; i < mem_pool_size / sizeof(mem_block); i++) {
        if ((size_t)addr == (size_t)mem_pool[i].addr) {
            size_t offset = (size_t)addr - (size_t)mem_pool[i].addr;
            free((void*)((char*)mem_pool[i].addr + offset));
            mem_pool_size -= mem_pool[i].size;
            mem_pool[i] = mem_pool[--mem_pool_size];
            i--;
        }
    }
    pthread_mutex_unlock(&mem_pool_lock);
}

