typedef struct {
    int key;
    double value;
} record_t;

void* init_data_processing_pipeline() {
    // Initialize random number generator with current time as seed
    srand(time(NULL));

    // Allocate memory for arrays based on expected number of records
    long* cache_aligned_array = (long*) aligned_alloc(sizeof(long), 1024);
    int* keys = (int*) malloc(1024 * sizeof(int));
    double* values = (double*) malloc(1024 * sizeof(double));

    record_t** records = (record_t**) malloc(512 * sizeof(record_t*));
    for (int i = 0; i < 512; i++) {
        records[i] = (record_t*) malloc(sizeof(record_t));
        records[i]->key = rand() % 100 + 10;
        records[i]->value = (double) (rand() % 2001 - 1000);
    }

    // Initialize memory pool for optimal performance and minimal fragmentation
    pthread_mutex_t mem_pool_lock = PTHREAD_MUTEX_INITIALIZER;
    void* mem_pool = malloc(1024 * sizeof(long));

    // Thread-safe function to populate 'record' structures
    void* populate_records(void* arg) {
        int record_index = (int)arg;
        for (int i = 0; i < 512; i++) {
            if (i >= record_index) {
                records[i]->key = rand() % 100 + 10;
                records[i]->value = (double) (rand() % 2001 - 1000);
            }
        }
    }

    // Thread-safe function to sort 'record' structures
    void* sort_records(void* arg) {
        int record_index = (int)arg;
        for (int i = 0; i < 512; i++) {
            if (i >= record_index) {
                record_t temp = records[i];
                for (int j = i + 1; j < 512; j++) {
                    if (records[j]->key > temp.key) {
                        record_t swap = records[j];
                        records[j] = temp;
                        temp = swap;
                    }
                }
                records[i] = temp;
            }
        }
    }

    // Thread-safe function to sort 'record' structures using parallel sorting algorithm
    void* parallel_sort_records(void* arg) {
        int record_index = (int)arg;
        pthread_barrier_t barrier = PTHREAD_BARRIER_INITIALIZER;

        for (int i = 0; i < 512; i++) {
            if (i >= record_index) {
                record_t temp = records[i];
                for (int j = i + 1; j < 512; j++) {
                    if (records[j]->key > temp.key) {
                        record_t swap = records[j];
                        records[j] = temp;
                        temp = swap;
                    }
                }
                records[i] = temp;
            }
        }

        pthread_barrier_wait(&barrier);
    }

    return NULL;
}

int main() {
    // Initialize data processing pipeline
    void* result = init_data_processing_pipeline();

    // Test the function with different input ranges and threading scenarios
    for (int i = 0; i < 10; i++) {
        // Stress test under heavy loads
        pthread_t threads[8];
        for (int j = 0; j < 8; j++) {
            pthread_create(&threads[j], NULL, parallel_sort_records, (void*)i);
        }
        for (int j = 0; j < 8; j++) {
            pthread_join(threads[j], NULL);
        }

        // Evaluate performance under varying input sizes
        printf("Input size: %d\n", i);
        printf("Sorted records:\n");
        for (int k = 0; k < 512; k++) {
            printf("%d, ", records[k]->key);
        }
        printf("\n");
    }

    return 0;
}
