#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint8_t* pixels;
    int width, height;
    int id;
} ImageRecord;

void processImageStream(int numThreads, int imageWidth, int imageHeight) {
    // Initialize memory pool
    size_t poolSize = 1024 * 1024 * 16; // 16MB pool
    void* pool = malloc(poolSize);
    if (!pool) return;
    for (size_t i = 0; i < poolSize; i += sizeof(ImageRecord)) {
        ImageRecord* img = pool + i;
        img->pixels = (uint8_t*)malloc(imageWidth * imageHeight);
        if (!img->pixels) return;
        img->width = imageWidth;
        img->height = imageHeight;
        img->id = -1; // Initialize with invalid ID
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

    for (int i = 0; i < numThreads; i++) {
        pthread_t thread;
        pthread_create(&thread, &attr, processThread, NULL);
        pthread_join(thread, NULL);
    }

    // Release memory pool
    free(pool);
}

void* processThread(void*) {
    srand(time(NULL)); // Initialize random seed

    while (1) {
        ImageRecord* img = malloc(sizeof(ImageRecord));
        if (!img) break;

        // Read raw image data from standard input
        int bytesRead = fread(img->pixels, 1, img->width * img->height, stdin);
        if (bytesRead != img->width * img->height) break; // Invalid or corrupted image

        // Perform random transformation
        for (int y = 0; y < img->height; y++) {
            for (int x = 0; x < img->width; x++) {
                uint8_t value = rand() % 256;
                if (x == 0 || y == 0) { // Edge detection
                    value = (value * 2 + rand() % 128) / 3;
                } else if ((rand() % 2) && img->pixels[y * img->width + x] > 128) {
                    // Color adjustment
                    value = (value + img->pixels[y * img->width + x] - 128) / 2 + 128;
                }
                img->pixels[y * img->width + x] = value;
            }
        }

        // Print transformed image quality metrics
        int sum = 0;
        for (int y = 0; y < img->height; y++) {
            for (int x = 0; x < img->width; x++) {
                sum += img->pixels[y * img->width + x];
            }
        }
        printf("Mean pixel value: %d\n", sum / (img->width * img->height));

        free(img);
    }

    return NULL;
}

int main() {
    int numThreads = 4; // Number of concurrent threads
    int imageWidth = 1024, imageHeight = 768;

    processImageStream(numThreads, imageWidth, imageHeight);

    return 0;
}
