// Define structure for log entry
typedef struct {
    char timestamp[20];
    char log_level[10];
    char source_ip[16];
    char destination_ip[16];
    char protocol[8];
    char message[256];
    uint64_t log_hash;
} LogEntry;

void* processAndIntegrateLogs(void* arg) {
    // File pointer
    FILE* file = (FILE*)arg;

    // Allocate memory for and initialize arrays
    LogEntry** log_entries = NULL;
    size_t num_log_entries = 0;
    uint64_t* timestamps = NULL;
    char** messages = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        // Read a line from the file
        char buffer[1024];
        if (!fgets(buffer, sizeof(buffer), file)) {
            break;
        }

        // Parse log entry fields
        LogEntry* log_entry = malloc(sizeof(LogEntry));
        if (log_entry == NULL) {
            // Handle memory allocation failure
            fclose(file);
            printf("Memory allocation failed.\n");
            exit(-1);
        }

        pthread_mutex_lock(&mutex);

        // Initialize log entry fields
        strcpy(log_entry->timestamp, strtok(buffer, ";"));
        strcpy(log_entry->log_level, strtok(NULL, ";"));
        strcpy(log_entry->source_ip, strtok(NULL, ";"));
        strcpy(log_entry->destination_ip, strtok(NULL, ";"));
        strcpy(log_entry->protocol, strtok(NULL, ";"));
        strcpy(log_entry->message, strtok(NULL, ";"));

        // Increment log entry count and timestamp array
        if (num_log_entries >= sizeof(timestamps) / sizeof(*timestamps)) {
            timestamps = realloc(timestamps, 2 * sizeof(*timestamps));
            messages = realloc(messages, 2 * sizeof(*messages));

            // Resize log entries dynamically
            log_entries = realloc(log_entries, 2 * sizeof(*log_entries));
        }

        timestamps[num_log_entries] = (uint64_t)strtol(strtok(NULL, ";"), NULL, 10);
        messages[num_log_entries] = strdup(log_entry->message);

        free(log_entry);
        num_log_entries++;

        pthread_mutex_unlock(&mutex);
    }

    fclose(file);

    // Handle potential errors during file operations
    if (ferror(file)) {
        fprintf(stderr, "File operation failed.\n");
        exit(-1);
    }
}
