#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_FILE_SIZE (1024 * 1024 * 1000) // 1 GB in bytes
#define MAX_RECORDS 10000

typedef struct {
    int transaction_id;
    char date[20];
    float amount;
    char status[10];
    unsigned long long hash;
} transaction_record;

transaction_record* parseAndProcessRecords(const char* filename) {
    FILE* file = fopen(filename, "r");

    if (!file) {
        return NULL; // Handle error
    }

    fseek(file, 0L, SEEK_END);
    int fileSize = ftell(file);
    rewind(file);

    if (fileSize > MAX_FILE_SIZE) {
        fclose(file);
        return NULL; // Handle error
    }

    transaction_record* records = malloc(MAX_RECORDS * sizeof(transaction_record));
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int recordCount = 0;
    char line[1024];

    while (fgets(line, sizeof(line), file)) {
        // Parse the line
        char* fields = strtok(line, "\t");

        if (fields) {
            transaction_record* record = &records[recordCount++];

            if (strtok(NULL, "\t")) {
                record->transaction_id = atoi(fields);
                strcpy(record->date, strtok(NULL, "\t"));
                record->amount = atof(strtok(NULL, "\t"));
                strcpy(record->status, strtok(NULL, "\t"));
                record->hash = 0; // Initialize hash
            }
        }
    }

    fclose(file);

    pthread_mutex_destroy(&lock);

    return records;
}

