event_t* allocate_events(int num_events) {
    event_t* events = NULL;
    float* floats = NULL;
    double* timestamps = NULL;
    char** identifiers = NULL;

    try {
        events = (event_t*)malloc(num_events * sizeof(event_t));
        if (!events) {
            printf("Error: Memory allocation failed for 'events'.\n");
            return NULL;
        }

        floats = (float*)malloc(FLOAT_ARRAY_SIZE * sizeof(float));
        timestamps = (double*)malloc(FLOAT_ARRAY_SIZE * sizeof(double));
        identifiers = (char**)malloc(FLOAT_ARRAY_SIZE * sizeof(char*));

        // Initialize arrays
        for (int i = 0; i < FLOAT_ARRAY_SIZE; i++) {
            floats[i] = (float)(rand() / (RAND_MAX / 1.0f));
            timestamps[i] = (double)(rand() % TIMESTAMP_RANGE);
            identifiers[i] = (char*)malloc(IDENTIFIER_LENGTH + 1);
            sprintf(identifiers[i], "ID_%d", i);
        }

        // Initialize events
        for (int i = 0; i < num_events; i++) {
            events[i].value = floats[i % FLOAT_ARRAY_SIZE];
            events[i].timestamp = timestamps[i % FLOAT_ARRAY_SIZE];
            events[i].identifier = identifiers[i % FLOAT_ARRAY_SIZE];
        }
    } catch (std::exception& e) {
        free(floats);
        free(timestamps);
        for (int i = 0; i < FLOAT_ARRAY_SIZE; i++) {
            if (identifiers[i]) free(identifiers[i]);
        }
        free(identifiers);
        return NULL;
    }

    // Release allocated memory
    try {
        for (int i = 0; i < FLOAT_ARRAY_SIZE; i++) {
            if (floats) free(floats);
            if (timestamps) free(timestamps);
            for (int j = 0; j < FLOAT_ARRAY_SIZE; j++) {
                if (identifiers[j]) free(identifiers[j]);
            }
        }
    } catch (std::exception& e) {
        return NULL;
    }

    return events;
}

void release_events(event_t* events, int num_events) {
    // Release allocated memory
    for (int i = 0; i < num_events; i++) {
        free(events[i].identifier);
    }
    free(events);
}
