record* memory_manager(int num_keys, int num_records, int range_min, int range_max) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc((num_records + 1)*sizeof(long));
    int* keys = (int*)calloc(num_keys, sizeof(int));
    record* records = (record*)malloc((num_records)*sizeof(record));

    if (!offsets || !keys || !records) {
        // Error handling
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize keys array with sequential integers
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

    // Populate offsets array with unique random values within range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        long val;
        do {
            val = (long)rand() % (range_max - range_min + 1) + range_min;
        } while (val == 0); // Ensure non-zero values
        offsets[i] = val;
    }

    // Populate records array with random values and corresponding offset pointers
    for (int i = 0; i < num_records; i++) {
        record* rec = &records[i];
        rec->value = rand() % (range_max - range_min + 1) + range_min;
        rec->offset = &offsets[i];
    }

    // Log memory usage and allocation attempts
    printf("Memory allocated: offsets (%p), keys (%p), records (%p)\n", offsets, keys, records);

    return records;
}
