        return NULL;
    }

    json_object *root = json_parse_file(file);
    fclose(file);

    if (!root) {
        return NULL;
    }

    json_object *maxRecords = json_object_object_get(root, "max-records");
    int maxRecordCount = 0;

    if (json_object_type(maxRecords) == json_object_type_int) {
        maxRecordCount = json_object_get_int(maxRecords);
    } else {
        return NULL;
    }

    json_object *rangeStart = json_object_object_get(root, "offset-range-start");
    long rangeStartValue = 0;

    if (json_object_type(rangeStart) == json_object_type_int) {
        rangeStartValue = json_object_get_int(rangeStart);
    } else {
        return NULL;
    }

    json_object *rangeEnd = json_object_object_get(root, "offset-range-end");
    long rangeEndValue = 0;

    if (json_object_type(rangeEnd) == json_object_type_int) {
        rangeEndValue = json_object_get_int(rangeEnd);
    } else {
        return NULL;
    }

    json_object *asciiChars = json_object_object_get(root, "ascii-chars");
    char *chars = "";
    int i = 0;

    if (json_object_type(asciiChars) == json_object_type_string) {
        const char *asciiString = json_object_get_string(asciiChars);
        while (*asciiString != '\0') {
            chars += asciiString;
            asciiString++;
            i++;
        }
    }

    record *records = malloc(maxRecordCount * sizeof(record));
    long *offsets = malloc(maxRecordCount * sizeof(long));
    int *keys = malloc(maxRecordCount * sizeof(int));

    for (int j = 0; j < maxRecordCount; j++) {
        records[j].value = rand() % 100;
        offsets[j] = rangeStartValue + rand() % (rangeEndValue - rangeStartValue);
        keys[j] = rand() % 10;

        char *str = malloc((i + 1) * sizeof(char));
        int strIndex = 0;
        for (int k = 0; k < i; k++) {
            if (rand() % 2) {
                str[strIndex++] = chars[rand() % i];
            } else {
                str[strIndex++] = '\0';
            }
        }
        records[j].str = str;
    }

    *numRecords = maxRecordCount;

    return records;
}
