        data[index].timestamp = timestamp;
        data[index].temperature = temperature;
    } else {
        printf("Invalid index for updating sensor data\n");
    }
}

void log_sensor_data(const char* filename, int num_readings, const sensor_data* data) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Failed to open log file\n");
        return;
    }
    for (int i = 0; i < num_readings; i++) {
        fprintf(file, "%d %f\n", data[i].timestamp, data[i].temperature);
    }
    fclose(file);
}

int main() {
    int num_readings = 10;
    sensor_data* data = initialize_sensor_data(num_readings);

    // update and log sensor readings
    for (int i = 0; i < num_readings; i++) {
