record* manage_memory(int num_keys, int max_value_range, int unique_offsets) {
    record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    // Allocate memory for arrays
    if (!(records = (record*)malloc(num_keys * sizeof(record)))) {
        return NULL;
    }
    if (!(offsets = (long*)malloc(unique_offsets * sizeof(long)))) {
        free(records);
        return NULL;
    }
    if (!(keys = (int*)malloc(num_keys * sizeof(int)))) {
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize keys array with sequential integers
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

    // Populate offsets array with unique random values
    srand(time(NULL));
    for (int i = 0; i < unique_offsets; i++) {
        long value;
        do {
            value = rand() % max_value_range;
        } while (value >= unique_offsets);
        offsets[i] = value;
    }

    // Initialize records array with random values and corresponding offsets
    for (int i = 0; i < num_keys; i++) {
        record* record_ptr = &records[i];
        record_ptr->value = rand() % max_value_range;
        record_ptr->offset = &offsets[i % unique_offsets];
    }

    // Log memory allocation information (optional)
    // printf("Memory allocated: records - %p, offsets - %p, keys - %p\n", records, offsets, keys);

    return records;
}
