void* record_array = NULL;
size_t record_count = 0;
size_t allocated_size = 0;
size_t total_memory = 0;
int seed = time(NULL);

// Function to initialize the array of records
int init_record_array(size_t capacity) {
    size_t new_allocated_size = (capacity * sizeof(Record)) * 1.9; // 90% of system memory available

    if (new_allocated_size > total_memory || allocated_size == 0) {
        record_array = mmap(NULL, new_allocated_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
        if (record_array == MAP_FAILED) {
            printf("Memory allocation failed. Retrying in 5 seconds...\n");
            sleep(5);
            return init_record_array(capacity);
        }
    }

    allocated_size = new_allocated_size;
    total_memory += allocated_size;

    return 1;
}

// Function to serialize the array of records into a binary format
int serialize_records(const char* filepath) {
    FILE* file = fopen(filepath, "wb");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        return 0;
    }

    size_t serialized_size = record_count * sizeof(Record);
    fwrite(&record_array, 1, serialized_size, file);

    fclose(file);
    return 1;
}

// Function to generate a random number and initialize a record
int init_record(int key) {
    if (key < 0 || key > RAND_MAX) {
        key = 0; // Set default value for invalid range
    }

    Record* new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        printf("Memory allocation failed. Returning default values.\n");
        return 0;
    }

    srand(seed);
    new_record->offset = rand();
    new_record->key = key;

    // Callback function to notify external systems
    callback(new_record);

    record_array[record_count++] = *new_record;

    free(new_record);

    return 1;
}

// Function to log memory usage statistics periodically
void log_memory_stats() {
    printf("Total memory used: %lu bytes\n", total_memory);
    sleep(60); // Log every minute
}

int main(int argc, char* argv[]) {
    init_record_array(1000);

    for (size_t i = 0; i < 1000; i++) {
        if (!init_record(i)) {
            printf("Error initializing record.\n");
            break;
        }
    }

    serialize_records("records.bin");

    return 0;
}
