    // Sort metadata by creation timestamp in descending order
    for (int i = 0; i < numFiles - 1; i++) {
        for (int j = i + 1; j < numFiles; j++) {
            if (metadata[i].creationTimestamp < metadata[j].creationTimestamp) {
                fileMetadata temp = metadata[i];
                metadata[i] = metadata[j];
                metadata[j] = temp;
            }
        }
