void *process_records(void *arg) {
    int i = (int)arg;
    for(int j = 0; j < RECORD_SIZE; j++) {
        records[i * RECORD_SIZE + j].value = rand() % RANDOM_RANGE;
    }
    return NULL;
}

void allocate_and_init_memory(pthread_t *threads, int num_threads) {
    records = (record_t *)malloc(sizeof(record_t) * RECORD_SIZE);
    offsets[0] = 0;
    for(int i = 1; i < OFFSET_SIZE; i++) {
        offsets[i] = offsets[i-1] + sizeof(record_t);
    }
    keys[0] = rand() % RANDOM_RANGE;
    for(int i = 1; i < KEY_SIZE; i++) {
        keys[i] = (keys[i-1] + 1) % RANDOM_RANGE;
    }
}

void sort_records() {
    qsort(records, RECORD_SIZE, sizeof(record_t), compare_records);
}

int compare_records(const void *a, const void *b) {
    record_t *rec_a = (record_t *)a;
    record_t *rec_b = (record_t *)b;
    return rec_a->value - rec_b->value;
}

void free_memory() {
    free(records);
    for(int i = 0; i < OFFSET_SIZE; i++) {
        free((void*)offsets + i * sizeof(long long));
    }
    free(keys);
}

