    allocate_and_init_memory(threads, num_threads);

    for(int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, process_records, (void*)i);
    }

    for(int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

