// Define structure for record
typedef struct {
    int value;
} Record;

// Define custom memory allocator structure
typedef struct {
    void** chunks;
    size_t* sizes;
    size_t num_chunks;
} MemoryAllocator;

// Function to initialize memory allocator with initial capacity of 512 elements
MemoryAllocator* init_memory_allocator() {
    MemoryAllocator* allocator = malloc(sizeof(MemoryAllocator));
    allocator->chunks = malloc(512 * sizeof(void*));
    allocator->sizes = malloc(512 * sizeof(size_t));
    for (size_t i = 0; i < 512; ++i) {
        allocator->chunks[i] = NULL;
        allocator->sizes[i] = 0;
    }
    allocator->num_chunks = 0;
    return allocator;
}

// Function to allocate memory chunk
void* alloc_memory(MemoryAllocator* allocator, size_t size) {
    // Resize allocator if necessary
    if (allocator->num_chunks == 0 || size > allocator->chunks[0]->size - allocator->sizes[0]) {
        resize_allocator(allocator);
    }

    // Find first available chunk with sufficient space
    for (size_t i = 0; i < allocator->num_chunks; ++i) {
        if (allocator->sizes[i] >= size) {
            void* result = allocator->chunks[i];
            allocator->sizes[i] -= size;
            return result;
        }
    }

    // If no suitable chunk found, create a new one
    void* new_chunk = malloc(size + sizeof(void*));
    *(void**)new_chunk = NULL;
    if (allocator->num_chunks > 0) {
        for (size_t i = allocator->num_chunks; i > 0; --i) {
            allocator->chunks[i] = allocator->chunks[i - 1];
            allocator->sizes[i] = allocator->sizes[i - 1];
        }
    }
    allocator->chunks[0] = new_chunk;
    allocator->sizes[0] = size;
    allocator->num_chunks++;
    return new_chunk;
}

// Function to deallocate memory chunk
void free_memory(MemoryAllocator* allocator, void* ptr) {
    for (size_t i = 0; i < allocator->num_chunks; ++i) {
        if (allocator->chunks[i] == ptr) {
            allocator->sizes[i] += ((char*)ptr - (char*)allocator->chunks[0]);
            return;
        }
    }

    // If chunk not found, free it
    free(ptr);
}

// Function to resize memory allocator
void resize_allocator(MemoryAllocator* allocator) {
    size_t new_capacity = allocator->num_chunks * 2 + 1;
    MemoryAllocator* new_allocator = init_memory_allocator();
    for (size_t i = 0; i < allocator->num_chunks; ++i) {
        new_allocator->chunks[i] = allocator->chunks[i];
        new_allocator->sizes[i] = allocator->sizes[i];
    }
    // Free old allocator
    free(allocator);
    allocator = new_allocator;
}

// Function to process record insertion and memory allocation concurrently
void* process_records(void* ptr) {
    Record* records = (Record*)ptr;

    for (int i = 0; i < 10000; ++i) {
        Record new_record;
        // Allocate memory for the new record using custom allocator
        void* allocated_memory = alloc_memory(allocator, sizeof(Record));
        new_record.value = rand() % 90 + 10;

        // Insert new record into array
        *allocated_memory = new_record;

        // Free memory when no longer needed
        free_memory(allocator, allocated_memory);
    }

    return NULL;
}

int main() {
    MemoryAllocator* allocator = init_memory_allocator();
    pthread_t threads[10];

    for (int i = 0; i < 10; ++i) {
        Record records[i];
        pthread_create(&threads[i], NULL, process_records, &records);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up memory
    resize_allocator(allocator);

    return 0;
}

