    qsort(records, num_records, sizeof(record_t), (int (*)(const void*, const void*))record_cmp);
}

int record_cmp(const void* a, const void* b) {
    const record_t* ra = (const record_t*)a;
    const record_t* rb = (const record_t*)b;

    return ra->value - rb->value;
}

void partition_records(record_t** records, int start, int end) {
    int pivot = (records[start]->value + records[end]->value) / 2;
    int i = start - 1;
    int j = end + 1;

    while (1) {
        do {
            i++;
        } while (records[i]->value < pivot);

        do {
            j--;
        } while (records[j]->value > pivot);

        if (i >= j)
            return;

        record_t* temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }
}

void sort_and_partition_records(record_t** records, int num_records) {
    for (int i = 0; i < num_records; i += RECORD_SIZE) {
        partition_records(records + i, i, min(i + RECORD_SIZE - 1, num_records - 1));
    }

    qsort(records, num_records, sizeof(record_t), (int (*)(const void*, const void*))record_cmp);
