#define MAX_CONCURRENCY 10000
#define DATA_SIZE 1000000
#define INDEX_SIZE DATA_SIZE / 2
#define LOG_RECORDS 5000
#define TRANSFORM_THREADS 4

typedef struct {
    double value;
    struct data_record* next;
} data_record;

data_record* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int transform_count = 0;

void process_data_pipeline(double* data, int size) {
    // Create thread pool with max concurrency
    pthread_t threads[MAX_CONCURRENCY];
    for (int i = 0; i < MAX_CONCURRENCY; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, NULL) != 0) {
            printf("Error creating thread\n");
            return;
        }
    }

    // Initialize arrays
    double* data_array = (double*)malloc(DATA_SIZE * sizeof(double));
    int* index_array = (int*)malloc(INDEX_SIZE * sizeof(int));

    // Initialize linked list
    for (int i = 0; i < LOG_RECORDS; i++) {
        data_record* record = (data_record*)malloc(sizeof(data_record));
        record->value = 0.0;
        record->next = head;
        head = record;
    }

    // Transform linked list values
    pthread_mutex_lock(&lock);
    for (int i = 0; i < LOG_RECORDS; i++) {
        data_record* current = head;
        while (current != NULL) {
            double value = current->value + log(1.0);
            pthread_cond_signal(&cond);
            pthread_mutex_unlock(&lock);

            // Wait for transformation to complete
            pthread_cond_wait(&cond, &lock);
            pthread_mutex_lock(&lock);
            current = current->next;
        }
    }
    pthread_mutex_unlock(&lock);

    // Clean up
    free(data_array);
    free(index_array);
    for (int i = 0; i < LOG_RECORDS; i++) {
        data_record* record = head;
        while (record != NULL) {
            data_record* next = record->next;
            free(record);
            record = next;
        }
    }
}

void* worker_thread(void* arg) {
    // Worker function to transform linked list values
    pthread_mutex_lock(&lock);
    int count = 0;
    while (count < transform_count) {
        pthread_cond_wait(&cond, &lock);
        data_record* current = head;
        while (current != NULL) {
            double value = current->value + log(1.0);
            current = current->next;
        }
        pthread_mutex_unlock(&lock);

        // Decrement transformation count
        transform_count--;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    // Process data pipeline
    double* data = (double*)malloc(DATA_SIZE * sizeof(double));
    for (int i = 0; i < DATA_SIZE; i++) {
        data[i] = (double)rand() / RAND_MAX * 200.0 - 100.0;
    }

    process_data_pipeline(data, DATA_SIZE);

    // Free allocated memory
    free(data);
    return 0;
}
