typedef struct {
    int value;
    long offset;
    int key;
} Record;

Record* initialize_records(int max_size, int seed) {
    if (max_size <= 0) {
        return NULL; // handle error
    }

    srand(seed);

    Record* records = (Record*)malloc(max_size * sizeof(Record));
    if (!records) {
        return NULL; // handle error
    }

    long* offsets = (long*)calloc(max_size, sizeof(long));
    int* keys = (int*)calloc(max_size, sizeof(int));

    for (int i = 0; i < max_size; i++) {
        while (1) {
            Record* record = &records[i];
            record->value = rand() % 100;
            long offset = rand() % 1000000;
            int key = rand() % 100;

            // check for collision
            if (i > 0 && find_collision(key, keys, i)) {
                continue; // try again
            }

            record->offset = offset;
            record->key = key;

            break;
        }
    }

    free(offsets);
    free(keys);

    return records;
}

int find_collision(int key, int* keys, int max_size) {
    for (int i = 0; i < max_size; i++) {
        if (keys[i] == key) {
            return 1; // collision found
        }
    }

    return 0; // no collision found
}
