#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int value;
    double timestamp;
    char* buffer;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* create_node(Record record) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->record = record;
    node->next = NULL;
    return node;
}

void insert_record(Node** head, Record record) {
    Node* new_node = create_node(record);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void print_records(Node* head) {
    while (head != NULL) {
        printf("Value: %d, Timestamp: %f, Buffer: %s\n", head->record.value, head->record.timestamp, head->record.buffer);
        head = head->next;
    }
}

void free_memory(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    // Example usage
    Node* head = NULL;

    Record record1 = {1, 1643723400.0, (char*) "Hello"};
    Record record2 = {2, 1643723500.0, (char*) "World"};

    insert_record(&head, record1);
    insert_record(&head, record2);

    print_records(head);

    free_memory(&head);

    return 0;
}
