// Define a node structure for the linked list
typedef struct Node {
    struct Element* element;
    struct Node* next;
} Node;

// Define an element structure
typedef struct Element {
    int index;
    double value;
    char* name;
} Element;

// Function to create and manage the collection
int manageCollection(int size, Node** head) {
    // Initialize the head of the linked list
    *head = NULL;

    // Allocate memory for the element array
    Element** elements = (Element**)malloc(size * sizeof(Element*));

    // Check if allocation was successful
    if (!elements) return -1; // Memory allocation failed

    // Initialize the collection and its size
    int collectionSize = 0;

    // Function to add an element to the collection
    void addElement(int index, double value, char* name) {
        Element* newElement = (Element*)malloc(sizeof(Element));

        if (!newElement) return; // Memory allocation failed

        newElement->index = index;
        newElement->value = value;
        newElement->name = name;

        elements[collectionSize++] = newElement;
    }

    // Function to remove an element from the collection
    void removeElement(int index) {
        for (int i = 0; i < collectionSize; i++) {
            if (elements[i]->index == index) {
                free(elements[i]);
                memmove(&elements[i], &elements[i + 1], (collectionSize - i - 1) * sizeof(Element*));
                collectionSize--;
                return;
            }
        }
    }

    // Function to print the collection
    void printCollection() {
        for (int i = 0; i < collectionSize; i++) {
            printf("Index: %d, Value: %.2f, Name: %s\n", elements[i]->index, elements[i]->value, elements[i]->name);
        }
    }

    // Periodic cleanup of unused resources
    void periodicCleanup() {
        for (int i = 0; i < collectionSize; i++) {
            if (!elements[i]->name) free(elements[i]);
        }
    }

    return 0;
}

// Function to destroy the collection and its linked list
void destroyCollection(Node** head) {
    Node* current = *head;
    Node* next = NULL;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}

// Example usage:
int main() {
    int size = 5;
    Node* head = NULL;

    if (manageCollection(size, &head)) {
        printf("Error allocating memory.\n");
        return -1; // Memory allocation failed
    }

    addElement(0, 10.5, "John");
    addElement(1, 20.3, "Jane");
    addElement(2, 30.9, "Bob");

    printCollection();

    removeElement(1);

    printCollection();

    destroyCollection(&head);

    return 0;
}
