Session* create_session(int id, const char* ip, const char* user_agent) {
    Session* new_sess = (Session*)malloc(sizeof(Session));
    if (!new_sess) {
        return NULL;  // Handle memory allocation failure
    }

    new_sess->id = id;
    new_sess->ip = strdup(ip);
    new_sess->user_agent = strdup(user_agent);
    new_sess->next = NULL;

    return new_sess;
}

void free_session(Session* sess) {
    if (sess) {
        free(sess->ip);
        free(sess->user_agent);
        free(sess);
    }
}

Session* add_session(Session** head, int id, const char* ip, const char* user_agent) {
    Session* new_sess = create_session(id, ip, user_agent);
    if (!new_sess) {
        return NULL;  // Handle memory allocation failure
    }

    new_sess->next = *head;
    *head = new_sess;

    return *head;
}

Session* find_session(Session** head, int id) {
    Session* current = *head;
    while (current && current->id != id) {
        current = current->next;
    }

    return current;
}

void remove_session(Session** head, int id) {
    if (!*head || (*head)->id != id) {
        return;  // Not found
    }

    Session* old_sess = *head;
    *head = (*head)->next;
    free(old_sess->ip);
    free(old_sess->user_agent);
    free(old_sess);  // Free the session
}
