record_t *pool = NULL;
size_t pool_size = 0;
size_t pool_capacity = 1024;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int stream_counter = 0;
uint64_t random_seed = 0;

void* allocate_record(size_t size) {
    pthread_mutex_lock(&mutex);
    if (pool_size + size > pool_capacity) {
        // Expand the memory pool
        record_t *new_pool = realloc(pool, (pool_capacity += size) * RECORD_SIZE);
        if (!new_pool) {
            // Handle allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            pthread_exit(NULL);
        }
        pool = new_pool;
    }
    void* ptr = &pool[pool_size];
    pool_size += size;
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void free_records(size_t size) {
    pthread_mutex_lock(&mutex);
    pool_size -= size;
    pthread_mutex_unlock(&mutex);
}

int randomize_record(record_t *record, int stream_id) {
    srand((uint64_t)(random_seed + stream_id));
    record->offset = rand() % (100 - 10 + 1) + 10;
    record->key = rand() % (100 - 50 + 1) + 50;
    return 0;
}

int compare_records(const void* a, const void* b) {
    record_t *rec1 = (record_t*)a;
    record_t *rec2 = (record_t*)b;
    if (rec1->offset > rec2->offset) {
        return 1;
    } else if (rec1->offset < rec2->offset) {
        return -1;
    }
    return rec1->key - rec2->key;
}

void filter_records(record_t *records, size_t count, int threshold) {
    for (size_t i = 0; i < count; i++) {
        if (records[i].offset > threshold) {
            // Filtered record
            free(records + i);
            records[i] = *(record_t*)allocate_record(1);
            randomize_record(&records[i], stream_counter);
        }
    }
}

void serialize_records(record_t *records, size_t count) {
    FILE* file = fopen("output.json", "w");
    if (!file) {
        // Handle serialization failure
        return;
    }
    fwrite(records, sizeof(record_t), count, file);
    fclose(file);
}
