#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define INITIAL_CAPACITY 1024
#define THRESHOLD 0.5

typedef struct {
    long offset;
    int key;
    float value;
} record_t;

typedef struct {
    record_t* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dyn_array_t;

dyn_array_t* dyn_array_create() {
    dyn_array_t* arr = malloc(sizeof(dyn_array_t));
    arr->data = malloc(INITIAL_CAPACITY * sizeof(record_t));
    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

void dyn_array_destroy(dyn_array_t* arr) {
    free(arr->data);
    free(arr);
    pthread_mutex_destroy(&arr->mutex);
}

int dyn_array_append(dyn_array_t* arr, record_t* record) {
    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        void* temp = realloc(arr->data, new_capacity * sizeof(record_t));
        if (!temp) return -1;
        arr->data = temp;
        arr->capacity = new_capacity;
    }
    memcpy(&arr->data[arr->size], record, sizeof(record_t));
    arr->size++;
    return 0;
}

int dyn_array_filter(dyn_array_t* arr, float threshold) {
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->data[i].value < threshold) {
            record_t temp = arr->data[i];
            memmove(&arr->data[i], &arr->data[i + 1], (arr->size - i - 1) * sizeof(record_t));
            arr->size--;
            i--; // Re-check the new end
        }
    }
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

void* dyn_array_serialize(void* data, const char* format) {
    dyn_array_t* arr = (dyn_array_t*)data;
    pthread_mutex_lock(&arr->mutex);
    FILE* file = fopen("output.txt", "w");
