    int* keys = (int*)((char*)mp->mem + 512 * sizeof(long));
    for (int i = 0; i < 512; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (100 - 10) + 10;
    }

    // Populate 'record' structures
    int key_collision_count = 0;
    for (int i = 0; i < limit; i++) {
        record* r = create_record(offsets[i], keys[i], mp);
        // Handle key collisions using backoff strategy
        if (r->key >= 100) {
            usleep(10000); // Backoff for 10ms
            r = create_record(offsets[i], rand() % (100 - 10) + 10, mp);
        }
        records[i] = r;
    }

    // Validate memory allocation and initialization
    if (!mp || !records) {
        destroy_memory_pool(mp);
        free(records);
        return -1; // Allocation failure
    }

    // Sort records based on their 'int' key values
    pthread_mutex_lock(pthread_mutex_t);
    for (int i = 0; i < limit; i++) {
        for (int j = i + 1; j < limit; j++) {
            if (records[i]->key > records[j]->key) {
                record* temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
    pthread_mutex_unlock(pthread_mutex_t);

    // Validate total memory usage
    size_t total_memory_used = sizeof(long) * 512 + sizeof(int) * 512 + sizeof(record) * 512;
    if (total_memory_used > threshold) {
        destroy_memory_pool(mp);
        free(records);
        return -1; // Memory usage exceeds threshold
    }

    // Log successful memory allocation and initialization
    printf("Records created: %d, Total memory used: %zu bytes\n", limit, total_memory_used);

    // Free previously allocated memory
    for (int i = 0; i < limit; i++) {
        destroy_record(records[i]);
    }
    free(records);
    destroy_memory_pool(mp);
    return 0;
}
