        keys[i] = i;
    }

    // Allocate memory for records array
    if ((records = (record*)malloc(maxRecords * sizeof(record))) == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize and populate records array with random values
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < maxRecords; i++) {
