        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    // Task 4: Populate records' key values with random integers
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < 512; i++) {
        int random_key = rand() % (100 - 10 + 1) + 10;
        record_t* record = &records[i];
        pthread_mutex_lock(&lock);
        record->key = random_key;
        pthread_mutex_unlock(&lock);
    }

    // Task 5: Sort records based on their 'int' key values
    qsort(records, 512, sizeof(record_t), compare_records);

    // Task 6: Integrate the function into a larger application
    return records;
}

// Comparison function for sorting
int compare_records(const void* a, const void* b) {
    record_t* ra = (record_t*)a;
    record_t* rb = (record_t*)b;
    if (ra->key < rb->key)
        return -1;
    else if (ra->key > rb->key)
        return 1;
    return 0;
}

// Cleanup mechanism to release allocated memory
void cleanup(record_t* records) {
    free(records);
}
