#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <ini.h>

#define MAX_RECORDS 1000
#define JSON_KEY "records"
#define INI_KEY "Records"

typedef struct {
    char* name;
    void* value;
    int type;
} Setting;

Setting* setting_new(const char* name, void* value, int type) {
    Setting* setting = (Setting*)malloc(sizeof(Setting));
    setting->name = strdup(name);
    setting->value = value;
    setting->type = type;
    return setting;
}

void setting_free(Setting* setting) {
    free(setting->name);
    if(setting->value != NULL) {
        // Free the actual value (e.g. int, string, boolean)
    }
    free(setting);
}

int load_settings_from_file(const char* file_path, Setting** settings) {
    json_t* root = NULL;
    ini_t* inifile = NULL;

    if(strstr(file_path, ".json")) {
        FILE* f = fopen(file_path, "r");
        if(f == NULL) return -1;
        root = json_load_file(f, 0);
        fclose(f);

        if(root == NULL || !json_is_object(root)) return -1;
    } else if(strstr(file_path, ".ini")) {
        inifile = ini_open_file(file_path);
        if(inifile == NULL) return -1;

        *settings = (Setting*)malloc(sizeof(Setting));
        (*settings)->name = strdup(INI_KEY);
        (*settings)->value = inifile;
        (*settings)->type = 0; // INI type

        return 1;
    }

    if(root != NULL && json_object_get(root, JSON_KEY) == NULL) {
        // Handle malformed file
        return -2;
    }

    json_t* records = json_object_get(root, JSON_KEY);
    int count = 0;

    while(count < MAX_RECORDS && json_array_next(records)) {
        Setting* setting = setting_new(json_string_value(json_array_get(records, 0)), NULL, 1); // Integer type
        (*settings)[count] = setting;
        count++;
    }

    if(root != NULL) json_decref(root);
    return count;
}

void free_settings(Setting** settings, int size) {
    for(int i = 0; i < size; i++) {
        setting_free((*settings)[i]);
    }
    free(*settings);
}
