    int signal;
} Task;

Task **tasks = NULL;
int task_count = 0;

void sig_handler(int signum) {
    if (signum == SIGCHLD) {
        while (waitpid(-1, NULL, WNOHANG) > 0);
    }
}

void register_task(char *cmd, int timeout, int signal, char *task_id) {
    Task *new_task = malloc(sizeof(Task));
    new_task->pid = fork();
    if (new_task->pid == -1) {
        perror("fork");
        exit(1);
    } else if (new_task->pid > 0) {
        // Parent process
        return;
    }

    // Child process
    dup2(STDIN_FILENO, STDOUT_FILENO);
    execvp(cmd, NULL);
    perror("execvp");
    _exit(1);

    free(new_task);
}

void terminate_tasks() {
    for (int i = 0; i < task_count; i++) {
        kill(tasks[i]->pid, SIGTERM);
    }
    for (int i = 0; i < task_count; i++) {
        wait(NULL);
    }
}

