#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structure for record
typedef struct {
    int key;
} record_t;

// Custom thread-safe random number generator
int thread_rand(int min, int max) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static unsigned int seed = 0;

    pthread_mutex_lock(&mutex);
    seed = (seed * 1103515245 + 12345) % 2147483647;
    int result = (int)(seed % (max - min + 1)) + min;
    pthread_mutex_unlock(&mutex);

    return result;
}

// Custom merge sort algorithm
void merge_sort(record_t* records, int left, int right) {
    if (left >= right)
        return;

    int mid = (left + right) / 2;
    pthread_t t1, t2;

    // Create threads for sorting
    pthread_create(&t1, NULL, &merge_sort_thread, (void*)&records[left]);
    pthread_create(&t2, NULL, &merge_sort_thread, (void*)&records[mid+1]);

    // Wait for threads to finish
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    // Merge sorted halves
    int i = left;
    int j = mid + 1;
    record_t temp[4096];

    while (i <= mid && j <= right) {
        if (records[i].key < records[j].key) {
            temp[left++] = records[i++];
        } else {
            temp[left++] = records[j++];
        }
    }

    // Copy remaining elements
    while (i <= mid)
        temp[left++] = records[i++];
    while (j <= right)
        temp[left++] = records[j++];

    // Replace original array with merged result
    for (int k = 0; k < left; k++)
        records[k] = temp[k];
}

// Thread function for merge sort
void* merge_sort_thread(void* arg) {
    record_t* records = (record_t*)arg;
    int left = *(int*)records;
    int right = *(int*)(&records[1]);
    merge_sort(records, left, right);
    free((void*) &left);
    return NULL;
}

// Process and find maximum value
void processAndFindMax() {
    // Initialize arrays
    int* long_offsets = (int*)malloc(4096 * sizeof(int));
    int* keys = (int*)malloc(4096 * sizeof(int));
    record_t* records = (record_t*)malloc(1024 * sizeof(record_t));

    if (!long_offsets || !keys || !records) {
        printf("Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records
    for (int i = 0; i < 1024; i++) {
        int key = thread_rand(10, 100);
        records[i].key = key;
    }

    // Sort records
    merge_sort(records, 0, 1023);

    // Find maximum value
    int max_key = records[0].key;
    for (int i = 1; i < 1024; i++) {
        if (records[i].key > max_key)
            max_key = records[i].key;
    }

    printf("Maximum key: %d\n", max_key);

    // Free memory
    free(long_offsets);
    free(keys);
    free(records);
}

int main() {
    processAndFindMax();
    return 0;
}
