#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
} record_t;

void processAndFindMax() {
    int offset_size = 1024;
    int key_size = 1024;
    int record_size = 512;

    long* offsets = (long*) malloc(offset_size * sizeof(long));
    int* keys = (int*) malloc(key_size * sizeof(int));
    record_t* records = (record_t*) malloc(record_size * sizeof(record_t));

    srand(time(NULL)); // seed random number generator

    for (int i = 0; i < record_size; i++) {
        records[i].key = rand() % (100 - 10 + 1) + 10;
    }

    // sorting algorithm implementation
    void quicksort(int* arr, int low, int high) {
        if (low >= high)
            return;

        int pivot = partition(arr, low, high);

        quicksort(arr, low, pivot-1);
        quicksort(arr, pivot+1, high);
    }

    int partition(int* arr, int low, int high) {
        int pivot = arr[high];
        int i = (low - 1);

        for (int j = low; j <= high - 1; j++) {
            if (arr[j] < pivot) {
                i++;
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }

        int temp = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp;

        return (i + 1);
    }

    // sorting the keys array
    quicksort(keys, 0, key_size - 1);

    free(offsets);
    free(keys);
    free(records);
}
