void processAndAggregateMetrics(char* json_log_file_path, int time_window) {
    // Initialize error variables
    int file_open_error = 0;
    int file_read_error = 0;

    // Open the JSON log file and read its contents
    FILE* file = fopen(json_log_file_path, "r");
