        json_object* json_obj = json_load_file(file, JSON_LOOSE);
        if (!json_obj) {
            printf("Error parsing JSON file: %s\n", json_log_file_path);
            file_read_error = 1;
        }
    }

    // Close the file and handle any errors
    fclose(file);
    if (file_open_error || file_read_error) {
        exit(1);
    }

