    int num_server_metrics = 0;
    server_metric* server_metrics = NULL;

    // Allocate memory for server metrics array based on initial size
    int initial_size = 16;
    server_metrics = (server_metric*)malloc(initial_size * sizeof(server_metric));

    // Parse JSON log file and populate server metrics array
    json_object_object_iter* iter = json_object_object_iter_create(json_obj);
    while (json_object_object_iter_next(iter)) {
        char* server_id = strdup(json_object_get_string_value(iter->key));
        long timestamp = json_object_get_int_value(iter->value);
        int metric_type = json_object_get_int_value(iter->value);
        double value = json_object_get_double_value(iter->value);

