            for (int i = 0; i < num_server_metrics; i++) {
                temp[i] = server_metrics[i];
            }
            free(server_metrics);
            server_metrics = temp;
            initial_size = new_size;
        }

        // Normalize timestamp field
        struct tm* tm = localtime(&timestamp);
        char* iso_timestamp = malloc(20);
        strftime(iso_timestamp, 20, "%Y-%m-%dT%H:%M:%S.%z", tm);

        // Populate server metric structure
