        new_server_metric.server_id = server_id;
        new_server_metric.timestamp = timestamp;
        new_server_metric.metric_type = metric_type;
        new_server_metric.value = value;

        // Store the parsed server metrics in the array
        server_metrics[num_server_metrics].server_id = server_id;
        server_metrics[num_server_metrics].timestamp = timestamp;
        server_metrics[num_server_metrics].metric_type = metric_type;
        server_metrics[num_server_metrics].value = value;
        num_server_metrics++;

