void add_record(int key, const char* log_message, int value) {
    if (record_count >= MAX_RECORDS) {
        // out of memory
        return;
    }

    Record* new_record = &records[record_count];
    new_record->key = key;
    strcpy(new_record->log_message, log_message);
    new_record->value = value;

    record_count++;

    // append log message to file
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", log_message);
    }
}

void update_record(int key, const char* log_message, int value) {
    for (int i = 0; i < record_count; i++) {
        Record* current_record = &records[i];
        if (current_record->key == key) {
            strcpy(current_record->log_message, log_message);
            current_record->value = value;
            return;
        }
    }
}

