void sort_records(int start, int end) {
    record_t temp;
    for (int i = start; i < end - 1; i++) {
        for (int j = i + 1; j < end; j++) {
            if (records[i].value > records[j].value) {
                temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
}

