// Structure to represent a record
typedef struct {
    int key;
    long offset;
} Record;

// Custom memory pool structure
typedef struct {
    void** chunks;
    size_t chunk_size;
    size_t used;
    pthread_mutex_t mutex;
} MemoryPool;

// Function to allocate memory from the custom pool
void* mempool_alloc(MemoryPool* mp, size_t size) {
    if (mp->used + size > mp->chunk_size * sizeof(void*)) {
        // Reallocate chunks when needed
        mp->chunks = realloc(mp->chunks, (mp->used / mp->chunk_size + 1) * sizeof(void*));
        mp->chunk_size *= 2;
    }
    void* ptr = mp->chunks[mp->used / mp->chunk_size];
    mp->used += size;
    return ptr;
}

// Function to deallocate memory from the custom pool
void mempool_free(MemoryPool* mp, void* ptr) {
    size_t chunk = mp->used - ((char*)ptr - (char*)mp->chunks[0]);
    mp->used -= chunk;
    if (chunk / mp->chunk_size > 0 && mp->used <= mp->chunk_size * sizeof(void*)) {
        // Shrink chunks when possible
        mp->chunks = realloc(mp->chunks, (mp->used / mp->chunk_size + 1) * sizeof(void*));
        mp->chunk_size /= 2;
    }
}

// Function to validate memory allocation and initialization
void validate(MemoryPool* mp, Record* records) {
    for (size_t i = 0; i < 512; i++) {
        if (!mp->chunks[i % (mp->used / sizeof(void*))]) {
            fprintf(stderr, "Memory allocation failed!\n");
            exit(1);
        }
    }
}

// Function to set record values
void set_values(MemoryPool* mp, Record* records) {
    for (size_t i = 0; i < 512; i++) {
        records[i].key = rand() % 90 + 10;
        records[i].offset = (long)i * sizeof(Record);
    }
}

// Function to merge sorted segments
void merge_segments(Record* records, size_t left, size_t mid, size_t right) {
    Record* temp = malloc((right - left + 1) * sizeof(Record));
    size_t i = left, j = mid;
    for (size_t k = 0; k <= right - left; k++) {
        if (i > mid) {
            temp[k] = records[j++];
        } else if (j > right) {
            temp[k] = records[i++];
        } else {
            if (records[i].key <= records[j].key) {
                temp[k] = records[i++];
            } else {
                temp[k] = records[j++];
            }
        }
    }
    for (size_t k = 0; k <= right - left; k++) {
        records[left + k] = temp[k];
    }
    free(temp);
}

// Main function
int main() {
    // Initialize memory pool and arrays
    MemoryPool mp;
    mp.chunks = malloc(1024 * sizeof(void*));
    mp.chunk_size = 4096;
    mp.used = 0;
    pthread_mutex_init(&mp.mutex, NULL);

    Record* records = (Record*)mempool_alloc(&mp, 512 * sizeof(Record));
    long* offsets = (long*)mempool_alloc(&mp, 1024 * sizeof(long));

    // Initialize arrays
    for (size_t i = 0; i < 1024; i++) {
        offsets[i] = (long)i;
    }
    for (size_t i = 0; i < 512; i++) {
        records[i].key = -1;
        records[i].offset = -1;
    }

    // Validate memory allocation and initialization
    validate(&mp, records);

    // Set record values
    set_values(&mp, records);

    // Sort records
    pthread_t threads[4];
    for (size_t i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, &merge_segments, records);
    }
    for (size_t i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    // Print record values
    for (size_t i = 0; i < 512; i++) {
        printf("%d %ld\n", records[i].key, records[i].offset);
    }

    return 0;
}
