#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Custom memory pool structure
typedef struct {
    void **memory;
    size_t capacity;
    size_t used;
} MemoryPool;

// Initialize a new memory pool with the specified initial capacity
MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    pool->memory = (void**) malloc(capacity * sizeof(void*));
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

// Allocate memory from the given pool
void* alloc_memory(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        // If we've reached capacity, double it and resize
        pool->memory = (void**) realloc(pool->memory, 2 * pool->capacity * sizeof(void*));
        pool->capacity *= 2;
    }
    void* ptr = &pool->memory[pool->used];
    pool->used += size;
    return ptr;
}

// Free memory from the given pool
void free_memory(MemoryPool* pool, void* ptr) {
    size_t index = (size_t) (ptr - pool->memory);
    // Mark the block as free and update usage
    pool->memory[index] = NULL;
    pool->used -= 1;
}

// Record structure
typedef struct {
    double value;
    int key;
    char field;
} record;

record* records;
int num_records;

// Custom lock for thread safety
pthread_mutex_t lock;

void* worker(void* arg) {
    int segment = *(int*) arg;
    size_t start = 1024 * segment;
    size_t end = start + 1024;
    // Process the record segment concurrently
    for (size_t i = start; i < end; ++i) {
        record* rec = &records[i];
        // Set random values for 'int' and 'char' fields
        rec->key = rand() % 90 + 10;
        rec->field = (char)(rand() % 94 + 33);
    }
    return NULL;
}

void main() {
    // Initialize memory pool
    MemoryPool* pool = init_memory_pool(2048);

    // Allocate memory for arrays and records
    offset_values = alloc_memory(pool, sizeof(long) * 2048);
    keys = alloc_memory(pool, sizeof(int) * 2048);
    values = alloc_memory(pool, sizeof(double) * 2048);
    records = (record*) alloc_memory(pool, sizeof(record) * 1024);

    // Initialize random number generator
    srand(time(NULL));

    // Create and start threads for concurrent processing
    pthread_t threads[4];
    int thread_args[] = {0, 1, 2, 3};
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, worker, &thread_args[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    free_memory(pool, offset_values);
    free_memory(pool, keys);
    free_memory(pool, values);
    free(records);

    // Sort the records based on 'int' key and 'char' field
    qsort(records, 1024, sizeof(record), compare_records);

    // Print sorted records
    for (size_t i = 0; i < 1024; ++i) {
        record* rec = &records[i];
        printf("(%d, %f, %c)\n", rec->key, rec->value, rec->field);
    }
}

int compare_records(const void* a, const void* b) {
    record* rec1 = (record*) a;
    record* rec2 = (record*) b;
    if (rec1->key < rec2->key) return -1;
    else if (rec1->key > rec2->key) return 1;
    else if (rec1->field < rec2->field) return -1;
    else if (rec1->field > rec2->field) return 1;
    return 0;
}
