void init_pipeline(int size) {
    // Allocate and initialize memory for arrays
    float *values = (float *)malloc(sizeof(float) * size);
    char *statuses = (char *)malloc(sizeof(char) * size);
    item_t *items = (item_t *)malloc(sizeof(item_t) * size);

    if (!values || !statuses || !items) {
        printf("Memory allocation failed!\n");
        return;
    }

    // Populate each item
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        items[i].value = (float)(rand() % 101);
        if (items[i].value > 50.0f) {
            items[i].status = 'H';
        } else {
            items[i].status = 'L';
        }
    }

    // Sort the item array
    qsort(items, size, sizeof(item_t), (int (*)(const void *, const void *))compare_items);

    free(values);
    free(statuses);
    free(items);
}

int compare_items(const void *a, const void *b) {
