// Function to generate random Gaussian value
double gaussianRand(double mean, double std_dev) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    double rand_val = (rand() / (double)RAND_MAX) * 2 - 1;
    double scaled_rand = rand_val * std_dev + mean;
    pthread_mutex_unlock(&lock);
    return scaled_rand;
}

// Function to calculate moving average
double movingAverage(sensorData* data, int window_size, int start_index) {
    double sum = 0.0;
    for (int i = start_index; i < start_index + window_size; i++) {
        sum += data[i].temperature;
    }
    return sum / window_size;
}

// Function to filter and interpolate data
void filterData(sensorData* data, int* data_len) {
    int filtered_len = 0;
    for (int i = 0; i < *data_len; i++) {
        if (data[i].temperature >= 20.0 && data[i].temperature <= 30.0) {
            sensorData new_data;
            // Interpolate temperature reading here
            // For simplicity, assume it's the same as the previous or next valid reading
            if (i > 0) {
                new_data.temperature = data[i - 1].temperature;
            } else if (i < *data_len - 1) {
                new_data.temperature = data[i + 1].temperature;
            } else {
                // Handle edge case where there's only one valid reading
                new_data.temperature = data[i].temperature;
            }
            // Copy timestamp and sensor_id to the new_data structure
            new_data.timestamp = data[i].timestamp;
            new_data.sensor_id = data[i].sensor_id;
            data[filtered_len++] = new_data;
        }
    }
    *data_len = filtered_len;
}

// Main function
