        temperatures[i] = gaussianRand(25, 5);
    }

    int data_len = 2048;
    filterData(data, &data_len);

    // Calculate moving average
    double avg = movingAverage(data, 100, 0);

    // Clean up allocated memory
    free(timestamps);
    free(temperatures);
    free(sensor_ids);
