// Structure to represent a record
typedef struct {
    int id;
    int field1;
} record;

// Function to manage memory for three arrays
record** process_data(char* file_name) {
    // Initialize pointers to arrays
    long* large_offsets = NULL;
    int* unique_keys = NULL;
    record** records = NULL;

    FILE* file = fopen(file_name, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_name);
        return NULL;
    }

    // Parse CSV file and initialize large offsets array
    long max_offset = 0;
    size_t num_offsets = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int len = strlen(line) - 1;
        if (len < 5 || memcmp(line, "offset,", 7) != 0)
            continue;

        long offset = 0;
        if (sscanf(line + 7, "%llx", &offset) == 1 && offset > max_offset) {
            max_offset = offset;
            num_offsets++;
        }
    }

    large_offsets = (long*)malloc((num_offsets + 1) * sizeof(long));
    fseek(file, 0, SEEK_SET);
    for (size_t i = 0; i < num_offsets; i++) {
        if (fscanf(file, "offset:%llx\n", &large_offsets[i]) != 1)
            break;
    }

    // Parse CSV file and initialize unique keys array
    int max_key = 0;
    size_t num_keys = 0;
    while (fgets(line, sizeof(line), file)) {
        int len = strlen(line) - 1;
        if (len < 6 || memcmp(line, "key,", 4) != 0)
            continue;

        int key = 0;
        if (sscanf(line + 4, "%d", &key) == 1 && key > max_key)
            max_key = key;
    }

    unique_keys = (int*)malloc((max_key + 1) * sizeof(int));
    fseek(file, 0, SEEK_SET);
    for (size_t i = 0; i < num_offsets; i++) {
        if (fscanf(file, "offset:%d\n", &unique_keys[i]) != 1)
            break;
    }

    // Initialize records array
    size_t record_count = 0;
    while (fgets(line, sizeof(line), file)) {
        int len = strlen(line) - 1;
        if (len < 7 || memcmp(line, "record,", 7) != 0)
            continue;

        record* record_ptr = (record*)malloc(sizeof(record));
        if (fscanf(line + 7, "%d %d", &record_ptr->id, &record_ptr->field1) == 2) {
            records = (record**)realloc(records, ++record_count * sizeof(record*));
            records[record_count - 1] = record_ptr;
        } else
            break;
    }

    fclose(file);

    return records;
}
