// Function to manage memory for three distinct arrays
void manage_memory(char* file_path, uint32_t** offsets_array, int** keys_array, record** records_array) {
    // Initialize arrays
    *offsets_array = (uint32_t*)malloc(sizeof(uint32_t));
    *keys_array = (int*)malloc(sizeof(int));
    *records_array = (record*)malloc(sizeof(record));

    FILE* file = fopen(file_path, "r");
    if (!file) {
        log_message("Failed to open file.");
        return;
    }

    // Parse CSV file and skip duplicates and invalid values
    uint32_t offset_count = 0;
    int key_count = 0;
    record* records = *records_array;

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    char buffer[1024];
    for (size_t i = 0; i < file_size; i += 1024) {
        size_t read_size = fread(buffer, 1, 1024, file);
        if (read_size == 0) break;

        // Process offsets
        uint32_t offset;
        char* token = strtok(buffer, ",");
        while (token && sscanf(token, "%x", &offset) == 1) {
            if (!isValidOffset(offset)) continue; // Skip duplicates and invalid values

            *((*offsets_array) + offset_count++) = offset;
        }

        // Process keys
        int key;
        token = strtok(NULL, ",");
        while (token && sscanf(token, "%d", &key) == 1) {
            if (key < 0) continue; // Skip non-negative values

            *((*keys_array) + key_count++) = key;
        }

        // Process records
        for (int j = 0; j < read_size / sizeof(record); j++) {
            record* record_ptr = &records[j];
            srand(time(NULL)); // Randomly initialize record values
            record_ptr->value = rand() % 100 + 1; // Initialize with a random value within the specified range

            // Verify integrity of generated random values periodically
            if (j % 1000 == 0) {
                for (int k = 0; k < j; k++) {
                    if (records[k].value > 100 || records[k].value < 1) {
                        log_message("Anomaly detected in record generation!");
                    }
                }
            }
        }
    }

    fclose(file);

    // Dynamically allocate memory and handle errors gracefully
    uint32_t total_offsets = offset_count;
    int total_keys = key_count;

    *offsets_array = (uint32_t*)realloc(*offsets_array, (total_offsets + 1) * sizeof(uint32_t));
    *keys_array = (int*)realloc(*keys_array, (total_keys + 1) * sizeof(int));

