#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initializeDataArrays(int numOffsets, int maxKey, int recordsPerOffset) {
    if (numOffsets <= 0 || maxKey <= 0 || recordsPerOffset <= 0) {
        return NULL; // invalid input
    }

    srand(time(NULL)); // seed random number generator

    long* offsets = malloc(numOffsets * sizeof(long));
    if (!offsets) {
        free(offsets);
        return NULL;
    }

    int* keys = malloc(maxKey * sizeof(int));
    if (!keys) {
        free(keys);
        free(offsets);
        return NULL;
    }

    record** records = (record**)malloc(numOffsets * sizeof(record*));
    for (int i = 0; i < numOffsets; i++) {
        records[i] = malloc(recordsPerOffset * sizeof(record));
        if (!records[i]) {
            free(keys);
            free(offsets);
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            return NULL;
        }
    }

    int keyCount = 0;
    int uniqueKeyCount = 0;
    int* keysUnique = malloc(maxKey * sizeof(int));
    int recordsCount = 0;

    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i * recordsPerOffset;
        for (int j = 0; j < recordsPerOffset; j++) {
            record* rec = &records[i][j];
            int randomKey = rand() % maxKey;
            while (findInArray(keys, keysCount, randomKey)) {
                randomKey = (rand() % maxKey) + 1;
            }
            rec->value = randomKey;
            keys[uniqueKeyCount] = randomKey;
            uniqueKeyCount++;
            recordsCount++;
        }
    }

    if (uniqueKeyCount != keyCount) { // duplicate found
        int* tempKeys = realloc(keys, (uniqueKeyCount + 1) * sizeof(int));
        if (!tempKeys) {
            free(keys);
            for (int i = 0; i < numOffsets; i++) {
                free(records[i]);
            }
            free(offsets);
            return NULL;
        }
        keys = tempKeys;

        int* tempRecords = malloc(numOffsets * sizeof(record*));
        if (!tempRecords) {
            free(tempKeys);
            for (int i = 0; i < numOffsets; i++) {
                free(records[i]);
            }
            free(offsets);
            return NULL;
        }
        records = tempRecords;

        int recIndex = 0;
        for (int i = 0; i < numOffsets; i++) {
            record* rec = &records[i][recIndex];
            for (int j = recIndex; j < recordsPerOffset; j++) {
                if (j >= uniqueKeyCount) break;
                rec->value = keys[j];
                recIndex++;
            }
        }

        free(tempKeys);
    }

    // clean up
    free(keysUnique);
    free(keys);

    for (int i = 0; i < numOffsets; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);

    return NULL;
}

int findInArray(int* array, int count, int target) {
    for (int i = 0; i < count; i++) {
        if (array[i] == target) return 1;
    }
    return 0;
}
