        records[i].key = rand() % 90 + 10;
    }

    // Sort the records based on their 'int' key values in ascending order
    pthread_mutex_lock();
    qsort(records, 512, sizeof(record), (int(*)(const void*, const void*))compare);
    pthread_mutex_unlock();

    return NULL;
}

int compare(const void* a, const void* b) {
    record* ra = (record*)a;
    record* rb = (record*)b;

    if (ra->key < rb->key)
        return -1;
    else if (ra->key > rb->key)
        return 1;
    else
        return 0;
}
