// Define an enum type for record priority levels
enum {
    LOW,
    MEDIUM,
    HIGH
};

// Structure representing a record
typedef struct {
    int value;
    double timestamp;
    char* string_id;
    short status;
    enum{LOW, MEDIUM, HIGH} priority;
} Record;

// Function to initialize arrays and records
int init_records(int num_records, long max_offset, int threshold) {
    // Initialize arrays
    long* offset_array = (long*)malloc(num_records * sizeof(long));
    int* key_array = (int*)malloc(num_records * sizeof(int));
    Record* record_array = (Record*)malloc(num_records * sizeof(Record));
    char** string_id_array = (char**)malloc(num_records * sizeof(char*));
    short* status_array = (short*)malloc(num_records * sizeof(short));

    // Initialize random number generator
    srand(time(NULL));

    // Initialize records and arrays
    int i;
    for(i = 0; i < num_records; i++) {
        Record record;

        // Randomly initialize record values
        record.value = rand() % (max_offset + 1);
        record.timestamp = time(NULL);
        record.string_id = (char*)malloc(10 * sizeof(char));
        sprintf(record.string_id, "Record_%d", i);

        // Randomly set status flag and priority level
        record.status = rand() % 2;
        record.priority = LOW + rand() % 3;

        // Add record to array
        record_array[i] = record;

        // Update arrays
        offset_array[i] = record.value;
        key_array[i] = i;
        strcpy(string_id_array[i], record.string_id);
        status_array[i] = record.status;
    }

    // Free memory and return results
    free(offset_array);
    free(key_array);
    free(record_array);
    for(i = 0; i < num_records; i++) {
        free(string_id_array[i]);
    }
    free(string_id_array);
    free(status_array);

    // Report memory usage and fragmentation levels
    printf("Memory Usage: %d bytes\n", num_records * sizeof(Record) + 10 * num_records);
    printf("Fragmentation Level: %f %%\n", (1.0 - (double)num_records / (threshold * sizeof(Record))) * 100);

    return num_records;
}

int main() {
    int num_records = 5;
    long max_offset = 1000000;
    int threshold = 1024 * 1024; // 1 MB

    int result = init_records(num_records, max_offset, threshold);

    printf("Total Number of Successfully Initialized Records: %d\n", result);
    return 0;
}
