#define MEMORY_POOL_SIZE 1000000
#define RECORD_MAX 10
#define BUFFER_LENGTH 16

typedef struct {
    int value;
    char* buffer;
} Record;

Record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
size_t numRecords = 0, offsetSize = 0, keySize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(size_t size) {
    void* ptr = NULL;
    pthread_mutex_lock(&mutex);
    if (size <= MEMORY_POOL_SIZE - size) {
        ptr = malloc(size);
        if (ptr == NULL)
            printf("Memory allocation failed\n");
    }
    pthread_mutex_unlock(&mutex);
    return ptr;
}

void deallocateMemory(void* ptr, size_t size) {
    pthread_mutex_lock(&mutex);
    free(ptr);
    pthread_mutex_unlock(&mutex);
}

void initArrays(size_t numRecords, size_t offsetSize, size_t keySize) {
    this->numRecords = numRecords;
    this->offsetSize = offsetSize;
    this->keySize = keySize;

    offsets = (long*)allocateMemory(numRecords * sizeof(long));
    keys = (int*)allocateMemory(numRecords * sizeof(int));

    for (size_t i = 0; i < numRecords; i++) {
        Record* record = (Record*)allocateMemory(sizeof(Record));
        char buffer[BUFFER_LENGTH];
        sprintf(buffer, "%d", i);
        record->value = rand() % RECORD_MAX;
        record->buffer = (char*)allocateMemory(BUFFER_LENGTH + 1);
        strcpy(record->buffer, buffer);
        records[i] = record;
    }
}

void freeArrays() {
    for (size_t i = 0; i < numRecords; i++) {
        deallocateMemory(records[i]->buffer, BUFFER_LENGTH + 1);
        deallocateMemory((void*)records[i], sizeof(Record));
    }
    deallocateMemory(keys, offsetSize * sizeof(int));
    deallocateMemory(offsets, numRecords * sizeof(long));

    records = NULL;
    keys = NULL;
    offsets = NULL;
}

