// Function to initialize and manage dynamic memory allocation
void* sensor_system(int num_sensors) {
    // Allocate memory for the array of sensors
    Sensor** sensors = (Sensor**)malloc(num_sensors * sizeof(Sensor*));

    if (!sensors) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize each sensor with default values
    for (int i = 0; i < num_sensors; i++) {
        sensors[i] = (Sensor*)malloc(sizeof(Sensor));
        if (!sensors[i]) {
            printf("Error: cannot allocate memory for sensor %d!\n", i);
            // Handle error and free already allocated memory
            for (int j = 0; j < i; j++)
                free(sensors[j]);
            free(sensors);
            return NULL;
        }
        sensors[i]->identifier = '\0';
        sensors[i]->status_flag = -1; // Default status flag value
    }

    // Return the array of sensors
    return (void*)sensors;
}

// Function to dynamically resize the array of sensor objects
Sensor** realloc_sensors(Sensor** sensors, int new_size) {
    // Allocate memory for the resized array
    Sensor** new_sensors = (Sensor**)realloc(sensors, new_size * sizeof(Sensor*));

    if (!new_sensors) {
        printf("Error: cannot allocate memory for resized sensor array!\n");
        return NULL;
    }

    // Initialize each sensor with default values in the resized array
    for (int i = new_size - 1; i >= num_sensors; i--) {
        new_sensors[i] = sensors[num_sensors - 1];
        num_sensors++;
    }

    // Free memory allocated earlier and update the original pointer
    free(sensors);
    return new_sensors;
}

// Function to log errors and warnings for debugging purposes
void log_error(int level, char* message) {
    printf("Error (Level %d): %s\n", level, message);
}
