    int *keys = (int *)malloc(RECORDS * sizeof(int));

    pthread_t threads[numThreads];
    pthread_attr_t attr;
    pthread_attr_init(&attr);

    // Initialize arrays
    for (int i = 0; i < RECORDS; i++) {
        keys[i] = rand() % KEY_RANGE;
        offsets[i] = i * 100; // dummy value, actual data source integration needed
    }

