    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], &attr, threadFunc, keys + i * RECORDS / numThreads);
    }

    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(keys);
    free(offsets);

    return NULL;
}

void* processThread(void* args) {
    int start = *(int*)args;
    int end = RECORDS / ((int*)args)[1];
    float* results = (float*)malloc((end - start + 1) * sizeof(float));

    for (int i = start; i < end; i++) {
        long offset = offsets[i];
        int key = keys[i];
        float result = sqrt((float)offset) + (float)key / TRANSFORMATION;
        results[i - start] = result;
