int (*transform_func)(long);

// Custom thread function
void* processRecord(void* arg) {
    long offset = *(long*)arg;
    float result = TRANSFORM_FUNC(offset);
    printf("Processed record: %ld -> %.2f\n", offset, result);
    return NULL;
}

int processRecords() {
    // Initialize arrays
    long* offsets = (long*)malloc(RECORDS * sizeof(long));
    int* keys = (int*)malloc(RECORDS * sizeof(int));

    // Randomize key values
    for (int i = 0; i < RECORDS; i++) {
        keys[i] = rand() % KEY_RANGE;
    }

    // Initialize transformation function
    switch ((int)transform_func) {
        case LOG:
            printf("Using logarithmic transformation\n");
            break;
        case SQRT:
            printf("Using square root transformation\n");
            break;
        default:
            printf("Invalid transformation function\n");
            return -1;
    }

    // Create and join threads
    pthread_t* threads = (pthread_t*)malloc(RECORDS * sizeof(pthread_t));
    for (int i = 0; i < RECORDS; i++) {
        long* offset_ptr = &offsets[i];
        pthread_create(&threads[i], NULL, processRecord, offset_ptr);
    }

    for (int i = 0; i < RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free memory
    free(offsets);
    free(keys);
    free(threads);

    return 0;
}

int LOG(long x) {
    return (int)log2(x);
}

int SQRT(long x) {
    return (int)sqrt((double)x);
