#define LOG_ENTRY_SIZE sizeof(struct log_entry)
#define TIMESTAMP_ARRAY_SIZE 10000000
#define MESSAGE_ARRAY_SIZE 5000000
#define HASH_ARRAY_SIZE 5000000

typedef struct {
    char timestamp[64];
    int log_level;
    char source_ip[16];
    char dest_ip[16];
    char protocol[10];
    char message[1024];
    char hash[40];
    unsigned long id;
} log_entry;

void processAndIntegrateLogs(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    log_entry* entries = (log_entry*)malloc(TIMESTAMP_ARRAY_SIZE * LOG_ENTRY_SIZE);
    unsigned long* timestamps = (unsigned long*)malloc(TIMESTAMP_ARRAY_SIZE * sizeof(unsigned long));
    char** messages = (char**)calloc(MESSAGE_ARRAY_SIZE, sizeof(char*));
    char** hashes = (char**)calloc(HASH_ARRAY_SIZE, sizeof(char*));

    for (int i = 0; i < TIMESTAMP_ARRAY_SIZE; i++) {
        entries[i].id = i;
    }

    unsigned long timestamp_count = 0;
    unsigned long message_count = 0;
    unsigned long hash_count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Parse log entry
        char* fields = strtok(line, ";");
        if (fields == NULL) continue; // Skip empty lines

        entries[timestamp_count].log_level = atoi(fields);
        strcpy(entries[timestamp_count].source_ip, strtok(NULL, ";"));
        strcpy(entries[timestamp_count].dest_ip, strtok(NULL, ";"));
        strcpy(entries[timestamp_count].protocol, strtok(NULL, ";"));
        strcpy(entries[timestamp_count].message, strtok(NULL, ";"));

        // Normalize timestamp
        time_t t = mktime(strtoll(fields, NULL, 0));
        strftime(entries[timestamp_count].timestamp, sizeof(entries[timestamp_count].timestamp), "%FT%T%z", localtime(&t));

        // Allocate memory for message and hash
        messages[message_count] = (char*)malloc(1024);
        strcpy(messages[message_count], entries[timestamp_count].message);

        hashes[hash_count] = (char*)malloc(40);
        sprintf(hashes[hash_count], "%016llx", strtoull(entries[timestamp_count].source_ip, NULL, 0));

        timestamp_count++;
    }

    fclose(file);
}
