void batchProcessImages(const char* dir_path) {
    // Initialize memory pool allocator
    void* mem_pool = malloc(1 << 30); // 500 GB
    size_t block_size = (size_t)(1 << 20); // 1 MB
    void* block = mem_pool;
    int num_blocks = (int)((mem_pool + 500 * 1024 * 1024 - block) / block_size);

    // Initialize image path, metadata, and feature arrays
    char** image_paths = calloc(10000000, sizeof(char*));
    struct {
        uint32_t width;
        uint32_t height;
        char format[16];
        json_object* exif_data;
    }** image_metadata = calloc(5000000, sizeof(struct{}));
    double*** color_histograms = malloc(10000000 * sizeof(double*));
    int** edge_maps = calloc(10000000, sizeof(int));

    // Process images
    DIR* dir = opendir(dir_path);
    if (!dir) {
        perror("Error opening directory");
        return;
    }

    int i = 0;
    struct dirent* ent;
    while ((ent = readdir(dir))) {
        char path[256];
        sprintf(path, "%s/%s", dir_path, ent->d_name);

        // Read image and metadata
        FILE* img_file = fopen(path, "rb");
        if (!img_file) {
            perror("Error opening image file");
            continue;
        }

        json_object* img_metadata = json_object_from_file(path);
        if (!img_metadata) {
            fprintf(stderr, "Error reading JSON metadata for %s\n", path);
            fclose(img_file);
            continue;
        }
        json_object* exif_data = json_object_object_get(img_metadata, "EXIF");
        int width = (int)json_object_get_int(json_object_object_get(img_metadata, "width"));
        int height = (int)json_object_get_int(json_object_object_get(img_metadata, "height"));

        // Process image
        double* color_histogram = malloc(1024 * sizeof(double));
        int edge_map[256];
        // ...

        // Store metadata and features
        image_paths[i] = strdup(path);
        image_metadata[i]->width = width;
        image_metadata[i]->height = height;
        json_object_put(img_metadata, NULL); // Release JSON object
        color_histograms[i] = &color_histogram;
        edge_maps[i] = edge_map;

        i++;
    }

    // Close directory and clean up
    closedir(dir);
    free(mem_pool);
    for (int j = 0; j < i; j++) {
        free(image_paths[j]);
        json_object_put(image_metadata[j]->exif_data, NULL); // Release JSON object
        free(color_histograms[j]);
        free(edge_maps[j]);
    }
    free(image_paths);
    free(image_metadata);
    free(color_histograms);
    free(edge_maps);
}
