// Define a struct to represent a dataset record
typedef struct {
    int key;
    long offset;
} Record;

// Initialize the random number generator with a consistent seed
srand(RANDOM_SEED);

// Function prototypes for thread-safe memory management
void* malloc_thread_safe(size_t size);
void free_thread_safe(void* ptr);

// Initialize and manage the dynamic dataset of records
Record** create_dataset(int capacity) {
    Record** dataset = (Record**)malloc_thread_safe(capacity * sizeof(Record*));
    int num_records = 0;
    pthread_mutex_init(&dataset_lock, NULL);

    return dataset;
}

void add_record(Record** dataset, int key, long offset) {
    // Validate the record's uniqueness
    Record* existing_record = find_record(dataset, key);
    if (existing_record != NULL) {
        // Handle duplicate key by ignoring and logging the operation
        printf("Duplicate key detected: %d. Operation ignored.\n");
        return;
    }

    // Initialize a new record with random values within specified range
    Record* new_record = (Record*)malloc_thread_safe(RECORD_LENGTH);
    new_record->key = rand() % 100; // Generate random key in range [0, 99]
    new_record->offset = rand() % 10000000; // Generate random offset in range [0, 9,999,999]

    // Add the new record to the dataset and update the number of records
    pthread_mutex_lock(&dataset_lock);
    if (num_records < capacity) {
        dataset[num_records] = new_record;
        num_records++;
    } else {
        // Handle memory exhaustion by logging and returning an error
        printf("Memory threshold exceeded. Operation failed.\n");
        free_thread_safe(new_record);
        return;
    }

    pthread_mutex_unlock(&dataset_lock);
}

// Function to find a record in the dataset by its key
Record* find_record(Record** dataset, int key) {
    for (int i = 0; i < num_records; i++) {
        if (dataset[i]->key == key) {
            return dataset[i];
        }
    }

    // Handle not-found condition by returning a null pointer
    return NULL;
}

// Function to free all records in the dataset and release memory
void destroy_dataset(Record** dataset) {
    for (int i = 0; i < num_records; i++) {
        free_thread_safe(dataset[i]);
    }

    free_thread_safe(dataset);
    pthread_mutex_destroy(&dataset_lock);
}
