#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record_t;

void* processAndAggregateRecords(void* arg) {
    // Dynamically allocate arrays for 'long' offset values, 'int' keys, and 'record' structures
    long* offsets = (long*)malloc(sizeof(long));
    int* keys = (int*)malloc(sizeof(int));
    record_t* records = (record_t*)malloc(sizeof(record_t));

    // Initialize arrays with SIMD instructions
    for (int i = 0; i < 1024; i++) {
        *(offsets + i) = i * sizeof(int);
        *(keys + i) = i;
        records[i].value = rand() % 100;
    }

    // Validate memory allocation and initialization
    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Calculate cumulative sum and average for each pair of records
    int cumulative_sum = 0;
    float cumulative_average = 0.0f;

    for (int i = 0; i < 1024; i++) {
        cumulative_sum += records[i].value;
        cumulative_average += records[i].value / (float)(i + 1);
    }

    // Print results
    printf("Cumulative sum: %d\n", cumulative_sum);
    printf("Cumulative average: %.2f\n", cumulative_average);

    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;

    pthread_create(&thread, NULL, processAndAggregateRecords, NULL);
    pthread_join(thread, NULL);

    return 0;
}
