typedef struct {
    double value;
    char *str;
} data_point;

void validate_allocation(void *ptr) {
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
}

data_point *init_data_points(int count) {
    data_point *points = (data_point *)malloc(count * sizeof(data_point));
    if (!points) {
        validate_allocation(points);
    }
    return points;
}

void populate_data_points(data_point *points, int count) {
    for (int i = 0; i < count; i++) {
        double value = (double)rand() / RAND_MAX;
        char buffer[64];
        for (int j = 0; j < 63; j++) {
            buffer[j] = (char)(rand() % 26 + 'a');
        }
        buffer[63] = '\0';
        points[i].value = value;
        points[i].str = malloc(strlen(buffer) + 1);
        strcpy(points[i].str, buffer);
    }
}

int filter_data_points(data_point *points, int count, double threshold) {
    int filtered_count = 0;
    for (int i = 0; i < count; i++) {
        if (points[i].value >= threshold) {
            filtered_count++;
        } else {
            free(points[i].str);
        }
    }
    return filtered_count;
}

void sort_data_points(data_point *points, int count) {
    qsort(points, count, sizeof(data_point), (int(*)(const void*, const void*))compare_double_values);
}

int compare_double_values(const void *a, const void *b) {
    data_point *point_a = *(data_point **)a;
    data_point *point_b = *(data_point **)b;
    if (point_a->value > point_b->value) {
        return -1;
    } else if (point_a->value < point_b->value) {
        return 1;
    }
    return 0;
}

int main() {
    // Initialize arrays
    double *doubles = malloc(1024 * sizeof(double));
    char **strings = malloc(1024 * sizeof(char *));
    for (int i = 0; i < 1024; i++) {
        doubles[i] = (double)rand() / RAND_MAX;
        strings[i] = malloc(64);
        for (int j = 0; j < 63; j++) {
            ((char *)strings[i])[j] = (char)(rand() % 26 + 'a');
        }
        ((char *)strings[i])[63] = '\0';
    }

    // Initialize data points
    int count = 512;
    data_point *points = init_data_points(count);
    for (int i = 0; i < count; i++) {
        points[i].value = doubles[rand() % 1024];
        points[i].str = strings[rand() % 1024];
    }

    // Filter and sort
    double threshold = 0.5;
    int filtered_count = filter_data_points(points, count, threshold);
    qsort(&points[0], filtered_count, sizeof(data_point), (int(*)(const void*, const void*))compare_double_values);

    return 0;
}

