#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 1024
#define DATA_POINT_ARRAY_SIZE 512
#define THRESHOLD 0.5

typedef struct {
    double value;
    char* string;
} data_point;

data_point data_points[DATA_POINT_ARRAY_SIZE];

void* generate_random_data(void* arg) {
    int i = *(int*)arg;
    for (int j = 0; j < MAX_ELEMENTS; j++) {
        data_points[i].value = (double)rand() / RAND_MAX;
        data_points[i].string = (char*)malloc(strlen("abcdefghijklmnopqrstuvwxyz") * sizeof(char));
        strcpy(data_points[i].string, "abcdefghijklmnopqrstuvwxyz");
        i++;
    }
    free((void*)arg);
    return NULL;
}

int filter_and_sort_data() {
    int filtered_count = 0;
    for (int i = 0; i < DATA_POINT_ARRAY_SIZE; i++) {
        if (data_points[i].value >= THRESHOLD) {
            filtered_count++;
        }
    }

    data_point* sorted_data = (data_point*)malloc(filtered_count * sizeof(data_point));
    int sorted_index = 0;
    for (int i = 0; i < DATA_POINT_ARRAY_SIZE; i++) {
        if (data_points[i].value >= THRESHOLD) {
            sorted_data[sorted_index] = data_points[i];
            sorted_index++;
        }
    }

    qsort(sorted_data, filtered_count, sizeof(data_point), compare_function);

    for (int i = 0; i < filtered_count; i++) {
        printf("%f %s\n", sorted_data[i].value, sorted_data[i].string);
    }

    free(sorted_data);
    return 0;
}

int compare_function(const void* a, const void* b) {
    data_point* da = (data_point*)a;
    data_point* db = (data_point*)b;

    if (da->value > db->value) {
        return -1;
    } else if (da->value < db->value) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
    pthread_t threads[MAX_ELEMENTS / DATA_POINT_ARRAY_SIZE];

    for (int i = 0; i < MAX_ELEMENTS / DATA_POINT_ARRAY_SIZE; i++) {
        int* arg = malloc(sizeof(int));
        *arg = i;
        pthread_create(&threads[i], NULL, generate_random_data, (void*)arg);
    }

    for (int i = 0; i < MAX_ELEMENTS / DATA_POINT_ARRAY_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }

    filter_and_sort_data();

    return 0;
}
