// Define the structure for 'entry' type
typedef struct {
    char* key;
    int value;
    long* offset;
} entry;

// Function to generate unique keys and random values within a specified range
void generateEntry(entry* e, int seed) {
    srand(seed);
    e->key = (char*)malloc(16 * sizeof(char));
    sprintf(e->key, "Key_%d", rand());
    e->value = rand() % 100;
}

// Function to add new entries with unique keys and random values
void addEntry(entry** arr, int* size, entry* new_entry) {
    if (*size >= (int)(sizeof(entry*) * 16)) {
        // Dynamically allocate memory for the array
        *arr = (entry**)realloc(*arr, sizeof(entry*) * (*size + 16));
    }
    (*arr)[*size] = *new_entry;
    (*size)++;
}

// Function to update existing entries by their key
void updateEntry(entry** arr, int size, char* key, int value) {
    for (int i = 0; i < size; i++) {
        if (!strcmp(arr[i]->key, key)) {
            arr[i]->value = value;
            return;
        }
    }
}

// Function to retrieve specific entries by their key
entry* getEntry(entry** arr, int size, char* key) {
    for (int i = 0; i < size; i++) {
        if (!strcmp(arr[i]->key, key)) {
            return arr[i];
        }
    }
    return NULL;
}

// Function to clean up all allocated memory
void cleanup(entry** arr, int size) {
    for (int i = 0; i < size; i++) {
        free(arr[i]->key);
        free(arr[i]->offset);
        free(arr[i]);
    }
    free(arr);
}

// Example usage
int main() {
    entry* entries = NULL;
    int entry_count = 0;

    // Generate and add initial entries
    for (int i = 0; i < 5; i++) {
        entry new_entry;
        generateEntry(&new_entry, 42);
        addEntry(&entries, &entry_count, &new_entry);
    }

    // Update an existing entry
    updateEntry(&entries, entry_count, "Key_3", 75);

    // Retrieve and print a specific entry
    entry* retrieved = getEntry(&entries, entry_count, "Key_2");
    if (retrieved != NULL) {
        printf("Retrieved entry: key=%s, value=%d\n", retrieved->key, retrieved->value);
        free(retrieved->key);
        free(retrieved->offset);
        free(retrieved);
    }

    // Clean up all allocated memory
    cleanup(&entries, entry_count);

    return 0;
}
