typedef struct {
    long *offsets;
    int *keys;
    struct Record **records;
} MemoryManager;

typedef struct {
    long *ptr;
    int key;
} Record;

MemoryManager* memoryManagerInit(int max_offset_count, int max_key_count) {
    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->offsets = malloc(max_offset_count * sizeof(long));
    manager->keys = malloc(max_key_count * sizeof(int));
    manager->records = calloc(max_key_count, sizeof(struct Record*));

    // Initialize random seed
    srand(time(NULL));

    return manager;
}

void memoryManagerFree(MemoryManager *manager) {
    free(manager->offsets);
    free(manager->keys);
    for (int i = 0; i < max_key_count; i++) {
        if (manager->records[i] != NULL)
            free(manager->records[i]);
    }
    free(manager->records);
    free(manager);
}

void memoryManagerResize(MemoryManager *manager, int new_max_offset_count) {
    long *new_offsets = realloc(manager->offsets, new_max_offset_count * sizeof(long));
    if (new_offsets == NULL)
        printf("Error: unable to reallocate offsets.\n");
    manager->offsets = new_offsets;

    // Update max_offset_count and records
    for (int i = 0; i < new_max_offset_count; i++) {
        manager->records[i]->ptr = &manager->offsets[i];
    }
}

void memoryManagerAddRecord(MemoryManager *manager, int key) {
    Record *new_record = malloc(sizeof(Record));
    // Assign a random offset
    new_record->key = key;
    new_record->ptr = &manager->offsets[rand() % max_offset_count];

    // Reassign keys if duplicate found
    for (int i = 0; i < max_key_count; i++) {
        if (manager->keys[i] == key) {
            manager->keys[i] = i;
            break;
        }
    }

    // Update records array
    for (int i = 0; i < max_key_count; i++) {
        if (manager->records[i] != NULL)
            free(manager->records[i]);
    }
    manager->records[max_key_count - 1] = new_record;

    // Free old record
    if (max_key_count > 1) {
        for (int i = max_key_count - 2; i >= 0; i--) {
            manager->keys[i]++;
            manager->records[i]->key++;
        }
        free(manager->records[0]);
    }

    // Update records array
    for (int i = 0; i < max_key_count; i++) {
        if (manager->records[i] != NULL)
            free(manager->records[i]);
    }
    for (int i = 0; i < max_key_count - 1; i++) {
        manager->records[i] = malloc(sizeof(struct Record));
        // Assign a random offset
        manager->records[i]->key = rand() % max_offset_count;
        manager->records[i]->ptr = &manager->offsets[rand() % max_offset_count];
    }
}

int main() {
    MemoryManager *manager = memoryManagerInit(100, 50);
    // Test adding records
    for (int i = 0; i < 20; i++) {
        memoryManagerAddRecord(manager, rand() % 50);
    }

    // Free memory when done
    memoryManagerFree(manager);

    return 0;
}
