    float reading;
    struct sensorData* next;
} sensorData;

// Function to generate unique timestamps with real-time clock offset
long generateTimestamp(int seed, int offset) {
    srand(seed);
    return (long)time(NULL) + offset + rand() % 1000; // Assuming a maximum timestamp value of 1000 seconds
}

// Function to validate and sanitize inputs
int validateInputs(int seed, int offset, int sensorCount, float minReading, float maxReading) {
    if (seed < 0 || offset < 0 || sensorCount <= 0 || minReading > maxReading) {
        return -1; // Invalid input parameters
    }
    return 0; // Valid inputs
}

// Function to initialize data structures
int initDataStructures(int seed, int offset, int sensorCount, float minReading, float maxReading, sensorData** headRef) {
    *headRef = NULL;
    for (int i = 0; i < sensorCount; i++) {
        // Initialize sensorData node
        sensorData* newNode = (sensorData*)malloc(sizeof(sensorData));
        if (!newNode) return -1; // Memory allocation failed

        // Generate unique timestamp with real-time clock offset
        long timestamp = generateTimestamp(seed, offset);

        // Convert timestamp to string and store in the sensorData node
        char buffer[20];
        sprintf(buffer, "%ld", timestamp);
        newNode->timestamp = (char*)malloc(strlen(buffer) + 1);
        strcpy(newNode->timestamp, buffer);
        if (!newNode->timestamp) return -1; // Memory allocation failed

        // Generate random reading value within the specified range
        float reading = minReading + ((float)rand() / RAND_MAX) * (maxReading - minReading);

        newNode->reading = reading;
        newNode->next = NULL;

        // Insert new sensorData node at the end of the linked list
        if (!*headRef) {
            *headRef = newNode;
        } else {
            sensorData* current = *headRef;
            while (current->next) current = current->next;
            current->next = newNode;
        }
    }
    return 0; // Initialization successful
}

// Function to free allocated memory
int freeMemory(sensorData* head) {
    while (head) {
        sensorData* next = head->next;
        free(head->timestamp);
        free(head);
        head = next;
    }
    return 0; // Memory freed successfully
}

