// Custom memory pool allocator
typedef struct {
    void* base;
    size_t capacity;
    size_t used;
} MemoryPool;

MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->base = aligned_alloc(64, capacity);
    pool->capacity = capacity;
    pool->used = 0;
    return pool;
}

void* allocaligned(MemoryPool* pool, size_t size) {
    void* ptr = NULL;
    if (pool->used + size <= pool->capacity) {
        ptr = (void*)((size_t)pool->base + pool->used);
        pool->used += size;
    } else {
        // Reallocate the memory pool when it's full
        MemoryPool* new_pool = init_memory_pool(pool->capacity * 2);
        if (!new_pool) {
            return NULL;
        }
        void* new_base = aligned_alloc(64, new_pool->capacity);
        if (new_base) {
            // Copy data from old pool to new pool
            memcpy(new_base, pool->base, pool->used);
            free(pool->base);
            pool->base = new_base;
            pool->capacity *= 2;
        } else {
            return NULL;
        }
    }
    return ptr;
}

void deallocaligned(MemoryPool* pool, void* ptr) {
    if (ptr >= (void*)pool->base && ptr < ((void*)pool->base + pool->used)) {
        pool->used = (size_t)(ptr - (void*)pool->base);
    }
}

