#include <string.h>
#include <time.h>

// Define constants for dataset size and record structure
#define MAX_DATASETS 5
#define RECORDS_PER_DATASET 1000
#define STRING_LENGTH 16

typedef struct {
    int value;
    char string[STRING_LENGTH + 1]; // +1 for null termination
} Record;

typedef struct {
    int id;
    Record* records;
    size_t numRecords;
} Dataset;

// Function to manage datasets dynamically
void manageDatasets() {
    // Initialize random seed and dataset array
    srand(time(NULL));
    Dataset datasets[MAX_DATASETS];
    int activeDatasetCount = 0;

    // Add a new dataset (initialize with random values)
    void addDataset() {
        if (activeDatasetCount >= MAX_DATASETS) {
            printf("Maximum number of datasets reached.\n");
            return;
        }

        Dataset* newDataset = &datasets[activeDatasetCount++];
        newDataset->numRecords = RECORDS_PER_DATASET;
        newDataset->records = (Record*)malloc(newDataset->numRecords * sizeof(Record));

        // Initialize records with random values and null-terminate strings
        for (size_t i = 0; i < newDataset->numRecords; i++) {
            Record* record = &newDataset->records[i];
            record->value = rand() % 100;
            sprintf(record->string, "%02d", record->value);
            record->string[STRING_LENGTH] = '\0';
        }
    }

    // Remove a dataset (release memory)
    void removeDataset(int id) {
        for (int i = 0; i < activeDatasetCount; i++) {
            if (datasets[i].id == id) {
                free(datasets[i].records);
                datasets[i] = datasets[--activeDatasetCount];
                return;
            }
        }
    }

    // Main loop
    while (1) {
        int choice;
        printf("1. Add dataset\n2. Remove dataset\n3. Exit\n");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addDataset();
                break;
            case 2: {
                int id;
                printf("Enter dataset ID to remove: ");
                scanf("%d", &id);
                removeDataset(id);
                break;
            }
            case 3:
                exit(0);
            default:
                printf("Invalid choice.\n");
        }
    }
}
