#define MAX_PRODUCTS 10000
#define PRODUCT_SIZE sizeof(struct Product)

typedef struct {
    char* name;
    int value;
    float price;
} Product;

Product* products = NULL;
int product_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
FILE* cache_file = NULL;

void add_product(Product* new_product) {
    pthread_mutex_lock(&mutex);
    if (product_count >= MAX_PRODUCTS) {
        printf("List is full. Cannot add more products.\n");
        exit(1);
    }
    for (int i = 0; i < product_count; i++) {
        if (strcmp(products[i].name, new_product->name) == 0) {
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    products = realloc(products, (product_count + 1) * PRODUCT_SIZE);
    products[product_count] = *new_product;
    product_count++;
    pthread_mutex_unlock(&mutex);
}

Product* find_product_by_name(const char* name) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (strcmp(products[i].name, name) == 0) {
            pthread_mutex_unlock(&mutex);
            return &products[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void remove_product_by_name(const char* name) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (strcmp(products[i].name, name) == 0) {
            memmove(&products[i], &products[i + 1], (product_count - i - 1) * PRODUCT_SIZE);
            product_count--;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    pthread_mutex_unlock(&mutex);
}

Product* find_product_by_value(int value) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (products[i].value == value) {
            pthread_mutex_unlock(&mutex);
            return &products[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

Product* find_product_by_price(float price) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < product_count; i++) {
        if (products[i].price == price) {
            pthread_mutex_unlock(&mutex);
            return &products[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void serialize_to_file(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file for writing.\n");
        return;
    }
    fwrite(&product_count, sizeof(int), 1, file);
    for (int i = 0; i < product_count; i++) {
        fwrite(&products[i], PRODUCT_SIZE, 1, file);
    }
    fclose(file);
}

void deserialize_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file for reading.\n");
        return;
    }
    int temp_count;
    fread(&temp_count, sizeof(int), 1, file);
    products = malloc(temp_count * PRODUCT_SIZE);
    product_count = temp_count;
    for (int i = 0; i < product_count; i++) {
        fread(&products[i], PRODUCT_SIZE, 1, file);
    }
    fclose(file);
}

void cache_products() {
    if (!cache_file) {
        cache_file = fopen("product_cache.bin", "wb");
        if (!cache_file) {
            printf("Error opening cache file for writing.\n");
            return;
        }
    }
    fwrite(&products, PRODUCT_SIZE * product_count, 1, cache_file);
    fclose(cache_file);
}

void load_cache_products() {
    cache_file = fopen("product_cache.bin", "rb");
    if (!cache_file) {
        printf("Error opening cache file for reading.\n");
        return;
    }
    fread(&products, PRODUCT_SIZE * product_count, 1, cache_file);
    fclose(cache_file);
}

void free_resources() {
    free(products);
    products = NULL;
    product_count = 0;
    pthread_mutex_unlock(&mutex);
}
