#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define FIXED_LENGTH 16

typedef struct {
    long offset;
    int key;
    char string[FIXED_LENGTH + 1]; // null-terminated
} Record;

void init_dataset(int records, Record** dataset) {
    *dataset = (Record*)malloc(records * sizeof(Record));
    if (*dataset == NULL) {
        printf("Memory allocation failed!\n");
        return;
    }

    int i;
    for (i = 0; i < records; i++) {
        Record* record = &(*dataset)[i];
        record->offset = rand();
        record->key = rand() % 100;
        sprintf(record->string, "Random string %d", i);
    }
}

int process_dataset(int records, const Record* dataset) {
    int sum = 0;
    int count = 0;

    for (int i = 0; i < records; i++) {
        sum += dataset[i].offset;
        count++;
    }

    double average = (double)sum / count;

    if (average > 5000) {
        return rand() % 750 + 500; // next dataset size
    } else {
        return MAX_RECORDS;
    }
}

void free_datasets(Record** datasets, int numDatasets) {
    for (int i = 0; i < numDatasets; i++) {
        if (datasets[i] != NULL) {
            free(datasets[i]);
        }
    }
}

void log_stats(int totalRecords) {
    printf("Total records processed: %d\n", totalRecords);
}

int main() {
    srand(time(NULL));

    Record** datasets = NULL;
    int numDatasets = 0;

    while (1) {
        // Initialize next dataset
        int records = MAX_RECORDS;
        if (numDatasets > 0) {
            records = process_dataset(MAX_RECORDS, datasets[numDatasets - 1]);
        }
        Record* dataset = NULL;
        init_dataset(records, &dataset);

        // Process the current dataset
        printf("Processing dataset %d...\n", numDatasets + 1);
        // ... process the dataset ...

        if (numDatasets > 0) {
            free_datasets(datasets, numDatasets - 1);
        }

        datasets = realloc(datasets, sizeof(Record*) * (numDatasets + 1));
        datasets[numDatasets] = dataset;
        numDatasets++;

        // Log statistics
        log_stats(records);

        if (records < MAX_RECORDS) {
            break; // Early termination due to insufficient memory
        }
    }

    free_datasets(datasets, numDatasets);
    return 0;
}
