void init_profiles(Profile** profiles, size_t totalProfiles) {
    // Initialize random seed for each profile
    srand(time(NULL));

    // Allocate memory for each profile and its settings
    *profiles = (Profile*)malloc(totalProfiles * sizeof(Profile));
    for (size_t i = 0; i < totalProfiles; i++) {
        (*profiles)[i].numSettings = rand() % 1000;
        (*profiles)[i].keys = (char**)malloc((*profiles)[i].numSettings * sizeof(char*));
        (*profiles)[i].values = (int*)malloc((*profiles)[i].numSettings * sizeof(int));

        for (size_t j = 0; j < (*profiles)[i].numSettings; j++) {
            // Generate random key and value
            char key[65];
            sprintf(key, "setting_%zu_%zu", i, j);
            int val = rand();

            // Allocate memory for the setting's data
            MemoryBlock* setting_data = (MemoryBlock*)malloc(sizeof(MemoryBlock));
            setting_data->ptr = malloc(strlen(key) + 1);
            strcpy((char*)setting_data->ptr, key);
            setting_data->size = strlen(key) + 1;

            (*profiles)[i].keys[j] = (char*)setting_data->ptr;
            (*profiles)[i].values[j] = val;

            // Store the setting's data
            (*profiles)[i].data = setting_data;
        }
    }
}

// Free allocated memory for a profile and its settings
void free_profile(Profile* profile) {
    if (profile != NULL) {
        for (size_t i = 0; i < profile->numSettings; i++) {
            free(profile->keys[i]);
            free(profile->values);
        }

        // Release the setting's data memory
        MemoryBlock* setting_data = profile->data;
        while (setting_data != NULL) {
            void* ptr = setting_data->ptr;
            size_t size = setting_data->size;

            // Free the memory block and update the pointer
            free(ptr);
            setting_data = ((MemoryBlock*)realloc(setting_data, sizeof(MemoryBlock)));
        }

        free(profile->keys);
        free(profile->values);
        free(profile);
    }
}

