typedef struct {
    char* name;
    int price;
    struct node* next;
} product;

typedef struct node {
    product* data;
    struct node* next;
} node;

// Create a new product structure
product* create_product(char* name, int price) {
    product* p = (product*)malloc(sizeof(product));
    p->name = (char*)malloc(strlen(name)+1);
    strcpy(p->name, name);
    p->price = price;
    p->next = NULL;
    return p;
}

// Create a new node
node* create_node(product* data) {
    node* n = (node*)malloc(sizeof(node));
    n->data = data;
    n->next = NULL;
    return n;
}

// Add a product to the end of the list
void add_product(product** head, char* name, int price) {
    product* p = create_product(name, price);
    if (*head == NULL) {
        *head = p;
    } else {
        node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = p;
    }
}

// Remove a product from the list by name
void remove_product(product** head, char* name) {
    if (*head == NULL) return;

    node* current = *head;
    node* previous = NULL;

    while (current != NULL && strcmp(current->data->name, name) != 0) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) {
        if (previous == NULL) {
            *head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current->data->name);
        free(current->data);
        free(current);
    }
}

// Update the price of a product by name
void update_price(product** head, char* name, int new_price) {
    if (*head == NULL) return;

    node* current = *head;
    while (current != NULL && strcmp(current->data->name, name) != 0) {
        current = current->next;
    }

    if (current != NULL) {
        current->data->price = new_price;
    }
}

// Find a product by price
product* find_product(product* head, int target_price) {
    node* current = head;
    while (current != NULL) {
        if (current->data->price == target_price) return current->data;
        current = current->next;
    }
    return NULL;
}

// Merge two lists into one
product* merge_lists(product* list1, product* list2) {
    product* head = NULL;

    // Add products from list1 to the new list
    while (list1 != NULL) {
        node* current = head;
        while (current != NULL && current->next != NULL) {
            current = current->next;
        }
        if (current == NULL) {
            head = create_node(list1);
        } else {
            current->next = create_node(list1);
        }
        list1 = list1->next;
    }

    // Add products from list2 to the new list
    while (list2 != NULL) {
        node* current = head;
        while (current != NULL && current->next != NULL) {
            current = current->next;
        }
        if (current == NULL) {
            head = create_node(list2);
        } else {
            current->next = create_node(list2);
        }
        list2 = list2->next;
    }

    return head;
}

// Serialize the list to a file
void serialize_list(product* head, const char* filename) {
    FILE* f = fopen(filename, "wb");
    if (f == NULL) return;

    // Write the number of products
    fwrite(&head->next, sizeof(node*), 1, f);

    // Write each product's data and link
    node* current = head;
    while (current != NULL) {
        fwrite(current->data->name, strlen(current->data->name)+1, 1, f);
        fwrite(&current->data->price, sizeof(int), 1, f);
        fwrite(&current, sizeof(node*), 1, f);
        current = current->next;
    }

    fclose(f);
}

// Deserialize the list from a file
product* deserialize_list(const char* filename) {
    product* head = NULL;
    FILE* f = fopen(filename, "rb");
    if (f == NULL) return NULL;

    // Read the number of products
    node* next = (node*)malloc(sizeof(node));
    fread(&next, sizeof(node*), 1, f);
    while (next != NULL) {
        product* p = create_product((char*)malloc(strlen(next->data->name)+1), next->data->price);
        strcpy(p->name, (char*)malloc(strlen(next->data->name)+1));
        fread(p->name, strlen(next->data->name)+1, 1, f);
        fread(&p->price, sizeof(int), 1, f);
        p->next = next->next;
        if (head == NULL) {
            head = p;
        } else {
            node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = p;
        }
        free(next->data->name);
        free(next->data);
        next = next->next;
    }

    fclose(f);
    return head;
}

int main() {
    // Example usage:
    product* list1 = NULL;
    add_product(&list1, "Product 1", 10);
    add_product(&list1, "Product 2", 20);
    add_product(&list1, "Product 3", 30);

    product* list2 = NULL;
    add_product(&list2, "Product 4", 40);
    add_product(&list2, "Product 5", 50);

    product* merged_list = merge_lists(list1, list2);

    // Serialize the merged list to a file
    serialize_list(merged_list, "products.bin");

    // Deserialize the list from the file
    product* deserialized_list = deserialize_list("products.bin");

    return 0;
}
