    newProduct->value = value;
    newProduct->price = price;

    // Add the new product to the list and increment the count
    (*products) = (Product*)realloc(*products, (*count + 1) * sizeof(Product));
    if (!(*products)) {
        printf("Error: Out of memory.\n");
        free(newProduct);
        return;
    }
    (*products)[*count] = *newProduct;
    (*count)++;
}

// Define a function to remove a product from the list by name
void removeProduct(Product** products, int* count, const char* name) {
