    int i;
    for (i = 0; i < *count; i++) {
        if (strcmp(products[i]->name, name) == 0) {
            break;
        }
    }

    // If the product is found, remove it from the list and decrement the count
    if (i < *count) {
        free(products[i]->name);
        memmove(&products[i], &products[i + 1], (*count - i - 1) * sizeof(Product));
        (*count]--;
    }
}

// Define a function to find products by their value or price
void findProducts(Product* products, int count, int targetValue, float targetPrice, int maxResults) {
    // Initialize the result array and the number of results found
    Product* results = NULL;
    int resultCount = 0;

    // Iterate over the products to find matches
    for (int i = 0; i < count; i++) {
        if ((products[i]->value == targetValue) || (fabs(products[i]->price - targetPrice) < 1e-6)) {
            // If the maximum number of results has been reached, exit early
            if (resultCount >= maxResults) {
                break;
            }

            // Add the matching product to the result array and increment the count
            Product* newResult = (Product*)malloc(sizeof(Product));
            *newResult = products[i];
            results = (Product*)realloc(results, ++resultCount * sizeof(Product));
            if (!results) {
                printf("Error: Out of memory.\n");
                return;
            }
        }
    }

    // Print the matching products
    for (int i = 0; i < resultCount; i++) {
        printf("%s - Value: %d, Price: %.2f\n", results[i]->name, results[i]->value, results[i]->price);
    }

    // Free the result array and its contents
    for (int i = 0; i < resultCount; i++) {
        free(results[i]->name);
        free(results[i]);
    }
    free(results);
}

// Define a function to serialize the product list to a file
void serializeProducts(Product* products, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Unable to open file.\n");
        return;
    }

    // Write the number of products and each product's properties to the file
    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(&products[i]->name, sizeof(char*), 1, file);
        fwrite(&products[i]->value, sizeof(int), 1, file);
        fwrite(&products[i]->price, sizeof(float), 1, file);
    }

    // Close the file
    fclose(file);
}

// Define a function to deserialize the product list from a file
void deserializeProducts(Product** products, int* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Unable to open file.\n");
        return;
    }

    // Read the number of products and each product's properties from the file
    fread(count, sizeof(int), 1, file);
    *products = (Product*)malloc(*count * sizeof(Product));
    if (!*products) {
        printf("Error: Out of memory.\n");
        fclose(file);
        return;
    }
    for (int i = 0; i < *count; i++) {
        fread(&((*products)[i]->name), sizeof(char*), 1, file);
        fread(&((*products)[i]->value), sizeof(int), 1, file);
        fread(&((*products)[i]->price), sizeof(float), 1, file);
    }

    // Close the file
    fclose(file);
}

// Define a function to print the product list
void printProducts(Product* products, int count) {
    for (int i = 0; i < count; i++) {
        printf("%s - Value: %d, Price: %.2f\n", products[i]->name, products[i]->value, products[i]->price);
    }
}

int main() {
    Product* products = NULL;
    int count = 0;

    // Add products to the list
    addProduct(&products, &count, "Product A", 10, 9.99f);
    addProduct(&products, &count, "Product B", 20, 14.95f);
    addProduct(&products, &count, "Product C", 30, 24.99f);

    // Print the product list
    printProducts(products, count);

    // Find products by their value or price
    findProducts(products, count, 15, 12.99f, 3);

    // Serialize the product list to a file
    serializeProducts(products, count, "products.bin");

    // Deserialize the product list from the file
