    int deserializedCount = 0;
    deserializeProducts(&deserializedProducts, &deserializedCount, "products.bin");

    // Print the deserialized product list
    printProducts(deserializedProducts, deserializedCount);

    // Free the memory for the products and their names
    for (int i = 0; i < count; i++) {
        free(products[i]->name);
        free(products[i]);
    }
    free(products);
    for (int i = 0; i < deserializedCount; i++) {
        free(deserializedProducts[i]->name);
        free(deserializedProducts[i]);
    }
    free(deserializedProducts);

    return 0;
}
