#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
} record_t;

void* processAndFindMax(void* arg) {
    int i, max = 0;
    record_t records[512];
    int long_offsets[10000];
    int keys[10000];

    // Initialize arrays
    for (i = 0; i < 10000; i++) {
        long_offsets[i] = -1;
        keys[i] = -1;
    }

    // Read integers from standard input and store them in the array
    int current_key = rand() % 90 + 10;
    for (i = 0; i < 512; i++) {
        records[i].key = current_key++;
    }

    // Sort the records based on their 'int' key values
    pthread_mutex_lock(pthread_mutex_t) {
        for (i = 1; i < 512; i++) {
            record_t temp = records[i];
            int j;
            for (j = i - 1; j >= 0 && temp.key > records[j].key; j--) {
                records[j + 1] = records[j];
            }
            records[j + 1] = temp;
        }
    }

    // Find the largest integer stored in the array
    for (i = 0; i < 512; i++) {
        if (records[i].key > max) {
            max = records[i].key;
        }
    }

    printf("Largest integer: %d\n", max);

    // Clean up
    free(records);
    free(long_offsets);
    free(keys);

    return NULL;
}

int main() {
    pthread_t thread[100];
    for (int i = 0; i < 100; i++) {
        pthread_create(&thread[i], NULL, processAndFindMax, NULL);
        pthread_join(thread[i]);
    }

    return 0;
}
