#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DOUBLE_ARRAY_SIZE 2048
#define MAX_CHAR_ARRAY_SIZE 2048
#define MAX_ITEM_ARRAY_SIZE 1024
#define MIN_DOUBLE_VALUE 0.5
#define MAX_DOUBLE_VALUE 5.0

typedef struct {
    char* str;
    double value;
} item_t;

void init_arrays(item_t** items, double** doubles, char** chars) {
    // Initialize arrays with random values
    for (int i = 0; i < MAX_ITEM_ARRAY_SIZE; i++) {
        item_t* item = (item_t*)malloc(sizeof(item_t));
        if (!item) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        item->str = (char*)malloc(MAX_DOUBLE_VALUE * sizeof(char));
        if (!item->str) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        sprintf(item->str, "Random sentence %d", i);
        item->value = (double)(rand() % 1000 / 100.0); // Random double value
        *items++ = item;
    }

    for (int i = 0; i < MAX_DOUBLE_ARRAY_SIZE; i++) {
        double* d = (double*)malloc(sizeof(double));
        if (!d) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        *doubles++ = *d;
    }

    for (int i = 0; i < MAX_CHAR_ARRAY_SIZE; i++) {
        char* c = (char*)malloc(MAX_DOUBLE_VALUE * sizeof(char));
        if (!c) {
            printf("Memory allocation failed.\n");
            exit(1);
        }
        *chars++ = *c;
    }

}

void filter_items(item_t** items, double threshold) {
    // Filter out items where the 'double' value is below or equal to the threshold
    for (int i = 0; i < MAX_ITEM_ARRAY_SIZE; i++) {
        if ((*items)[i]->value <= threshold) {
            free((*items)[i]->str);
            free(*items[i]);
            *items++ = NULL;
        }
    }

}

void sort_items(item_t** items, int size) {
    // Sort the filtered 'struct item' array based on the length of the 'char' string in descending order
    qsort(items, size, sizeof(item_t*), compare_items);

}

int compare_items(const void* a, const void* b) {
    // Compare function to sort 'struct item' array by the length of the 'char' string in descending order
    item_t* item1 = *(item_t**)a;
    item_t* item2 = *(item_t**)b;
    return strlen(item1->str) - strlen(item2->str);
}

void clean_up(item_t** items, double** doubles, char** chars) {
    // Clean up allocated memory
    for (int i = 0; i < MAX_ITEM_ARRAY_SIZE; i++) {
        if (*items) {
            free((*items)->str);
            free(*items);
            *items = NULL;
        }
    }

    for (int i = 0; i < MAX_DOUBLE_ARRAY_SIZE; i++) {
        if (*doubles) {
            free(*doubles);
            *doubles = NULL;
        }
    }

    for (int i = 0; i < MAX_CHAR_ARRAY_SIZE; i++) {
        if (*chars) {
            free(*chars);
            *chars = NULL;
        }
    }

}

int main() {
    srand(time(NULL)); // Seed random number generator

    item_t* items[MAX_ITEM_ARRAY_SIZE];
    double* doubles[MAX_DOUBLE_ARRAY_SIZE];
    char* chars[MAX_CHAR_ARRAY_SIZE];

    init_arrays(items, doubles, chars);

