// Structure to represent a record
typedef struct {
    int key;
    long offset;
    time_t timestamp;
    uint32_t id;
} Record;

// Function to process and find maximum value in the array
void* processAndFindMax(void* arg) {
    // Allocate memory for arrays
    Record* records = (Record*)malloc(512 * sizeof(Record));
    int* longOffsets = (int*)malloc(1024 * sizeof(int));
    int* keys = (int*)malloc(1024 * sizeof(int));

    if (!records || !longOffsets || !keys) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < 512; i++) {
        records[i].key = rand() % 90 + 10;
        records[i].offset = i;
        records[i].timestamp = time(NULL);
        records[i].id = i;
    }
    for (int j = 0; j < 1024; j++) {
        longOffsets[j] = j;
        keys[j] = rand() % 90 + 10;
    }

    // Sort the records
    qsort(records, 512, sizeof(Record), (int(*)(const void*, const void*))compare);

    // Find maximum key value
    int maxKey = records[0].key;

    // Print the result
    printf("Maximum key value: %d\n", maxKey);

    // Free allocated memory
    free(records);
    free(longOffsets);
    free(keys);

    return NULL;
}

// Comparison function for sorting records
int compare(const void* a, const void* b) {
    Record* record1 = (Record*)a;
    Record* record2 = (Record*)b;

    if (record1->key < record2->key)
        return -1;
    else if (record1->key > record2->key)
        return 1;
    else
        return 0;
}

int main() {
    // Create a thread pool to manage concurrent processing
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, processAndFindMax, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
