    int key;
} record_t;

void* createDirAndSetEnv(void* arg) {
    // Dynamically allocate memory for arrays
    long* offsets = (long*) malloc(OFFSETS * sizeof(long));
    int* keys = (int*) malloc(KEYS * sizeof(int));
    record_t* records = (record_t*) malloc(RECORDS * sizeof(record_t));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }

    // Initialize arrays
    for (int i = 0; i < OFFSETS; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < KEYS; i++) {
        keys[i] = rand() % 90 + 10; // Random int within range [10, 100]
    }
    for (int i = 0; i < RECORDS; i++) {
        records[i].key = keys[rand() % KEYS];
    }

    // Sort records
    qsort(records, RECORDS, sizeof(record_t), (int (*)(const void*, const void*)) strcmp);

    // Create directory and set environment variable
    char dirName[] = "my_directory";
    DIR* dir;
    struct dirent* ent;

    if ((dir = opendir(dirName)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            free(ent->d_name);
        }
        closedir(dir);
    } else {
        mkdir(dirName, 0700);
    }

    setenv("MY_DIR", dirName, 1);

    // Clean up
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
