        for (int j = i + 1; j < size; j++) {
            // Calculate Euclidean distance
            double dist = sqrt(pow(data_points[i].value - data_points[j].value, 2));
            distances[i][j] = dist;
            distances[j][i] = dist;
        }
    }
}

