// Define structure for record
typedef struct {
    int value;
    long* offset;
} Record;

// Function to manage memory for three dynamically sized arrays
int manageMemory(int initialSize, int offsetMaxValue) {
    // Initialize arrays with specified sizes
    long* offsets = (long*)malloc(initialSize * sizeof(long));
    int* keys = (int*)malloc(initialSize * sizeof(int));
    Record* records = (Record*)malloc(initialSize * sizeof(Record));

    // Track memory usage for each array separately
    size_t offsetsMemoryUsage = initialSize * sizeof(long);
    size_t keysMemoryUsage = initialSize * sizeof(int);
    size_t recordsMemoryUsage = initialSize * sizeof(Record);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    // Initialize arrays
    for (int i = 0; i < initialSize; i++) {
        offsets[i] = i * offsetMaxValue;
        keys[i] = rand() % 100; // Random value within range [0, 99]
        records[i].value = keys[i];
        records[i].offset = &offsets[i];
    }

    // Function to handle dynamic resizing of arrays
    int resizeFactor = 2;

    void* reallocFunc(void* ptr, size_t newSize) {
        return realloc(ptr, newSize);
    }

    int resizeArrays(size_t currentSize) {
        size_t newSize = currentSize * resizeFactor;
        long* newOffsets = (long*)reallocFunc(offsets, newSize * sizeof(long));
        int* newKeys = (int*)reallocFunc(keys, newSize * sizeof(int));
        Record* newRecords = (Record*)reallocFunc(records, newSize * sizeof(Record));

        if (!newOffsets || !newKeys || !newRecords) {
            free(newOffsets);
            free(newKeys);
            free(newRecords);
            return -1;
        }

        // Update memory usage for each array
        offsetsMemoryUsage = newSize * sizeof(long);
        keysMemoryUsage = newSize * sizeof(int);
        recordsMemoryUsage = newSize * sizeof(Record);

        // Copy existing data to new arrays
        for (int i = 0; i < currentSize; i++) {
            newOffsets[i] = offsets[i];
            newKeys[i] = keys[i];
            newRecords[i].value = records[i].value;
            newRecords[i].offset = &newOffsets[i];
        }

        // Free original arrays
        free(offsets);
        free(keys);
        free(records);

        return 0;
    }

    // Resize arrays if initial allocation size is exceeded
    if (initialSize < 10) {
        for (int i = 0; i < initialSize; i++) {
            printf("Key: %d, Offset: %ld\n", keys[i], *records[i].offset);
        }
    } else {
        int newSize = initialSize;
        while (1) {
            int result = resizeArrays(newSize);
            if (result == 0) break;

            // Handle memory allocation failure
            printf("Memory allocation failed. Trying to resize arrays again...\n");
            newSize *= 2; // Double the array size and try again
        }

        // Print records in resized arrays
        for (int i = 0; i < newSize; i++) {
            printf("Key: %d, Offset: %ld\n", keys[i], *records[i].offset);
        }
    }

    // Free allocated memory upon function completion
    free(offsets);
    free(keys);
    free(records);

    return 0;
}

int main() {
    srand(time(NULL));
    manageMemory(10, 100);
    return 0;
}
