#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

typedef struct {
    int process_id;
    double cpu_usage;
    char name[255];
    pid_t parent_pid;
} process_status;

process_status **process_list = NULL;
int process_list_size = 0;
int max_process_list_size = 500;

void *malloc_or_die(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_process_record(process_status *record) {
    if (record != NULL) {
        free(record->name);
        free(record);
    }
}

process_status *add_process(int process_id, double cpu_usage, const char *name, pid_t parent_pid) {
    process_status *new_process = malloc_or_die(sizeof(process_status));
    new_process->process_id = process_id;
    new_process->cpu_usage = cpu_usage;
    strncpy(new_process->name, name, 254);
    new_process->name[254] = '\0';
    new_process->parent_pid = parent_pid;

    if (process_list_size == max_process_list_size) {
        printf("Process list is full. Cannot add more processes.\n");
        return NULL;
    }

    process_list[process_list_size++] = new_process;

    return new_process;
}

void update_process(int process_id, double cpu_usage, const char *name, pid_t parent_pid) {
    for (int i = 0; i < process_list_size; i++) {
        if (process_list[i]->process_id == process_id) {
            process_list[i]->cpu_usage = cpu_usage;
            strncpy(process_list[i]->name, name, 254);
            process_list[i]->name[254] = '\0';
            process_list[i]->parent_pid = parent_pid;
            return;
        }
    }

    printf("Process not found. Cannot update.\n");
}

void remove_process(int process_id) {
    for (int i = 0; i < process_list_size; i++) {
        if (process_list[i]->process_id == process_id) {
            free_process_record(process_list[i]);
            memmove(&process_list[i], &process_list[i + 1], sizeof(process_status *) * (process_list_size - i));
            process_list_size--;
            return;
        }
    }

    printf("Process not found. Cannot remove.\n");
}

void print_processes() {
    for (int i = 0; i < process_list_size; i++) {
        printf("ID: %d, CPU Usage: %.2lf, Name: %s, Parent PID: %ld\n",
               process_list[i]->process_id, process_list[i]->cpu_usage, process_list[i]->name,
               (long)process_list[i]->parent_pid);
    }
}

int main() {
    // Initialize the process list
    process_list = (process_status **)malloc_or_die(max_process_list_size * sizeof(process_status *));
    for (int i = 0; i < max_process_list_size; i++) {
        process_list[i] = NULL;
    }

    // Use the functions to add, update, and remove processes
    add_process(1, 0.5, "ProcessA", 1234);
    add_process(2, 0.3, "ProcessB", 5678);
    update_process(1, 0.7, "ProcessAUpdated", 9012);
    remove_process(2);

    // Print the process list
    print_processes();

    // Free the memory when you're done
    for (int i = 0; i < process_list_size; i++) {
        free_process_record(process_list[i]);
    }
    free(process_list);

    return 0;
}
