void* processAndFindMax(void* arg) {
    // Initialize random seed with current time
    srand((unsigned)time(NULL));

    // Declare and initialize arrays
    record_t* records = (record_t*)malloc(512 * sizeof(record_t));
    int* keys = (int*)malloc(1024 * sizeof(int));
    long* offsets = (long*)malloc(1024 * sizeof(long));

    // Check for memory allocation errors
    if (!records || !keys || !offsets) {
        printf("Memory allocation failed. Exiting.\n");
        exit(1);
    }

    // Populate records and keys arrays
    for (int i = 0; i < 512; i++) {
        records[i].key = rand() % 90 + 10;
        records[i].offset = rand();
        records[i].timestamp = time(NULL);
        records[i].id = i;
    }

    // Sort records based on keys
    qsort(records, 512, sizeof(record_t), compare);

    // Free memory
    free(records);
    free(keys);
    free(offsets);

    return NULL;
}

int compare(const void* a, const void* b) {
    record_t* rec1 = (record_t*)a;
    record_t* rec2 = (record_t*)b;

    if (rec1->key < rec2->key) {
        return -1;
    } else if (rec1->key > rec2->key) {
        return 1;
    } else {
        return 0;
    }
}
