#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define LOG_FILE_SIZE 1073741824 // 10 GB in bytes
#define CHUNK_SIZE 1048576 // 1 MB in bytes
#define MAX_LOG_ENTRIES 1000

typedef struct {
    char timestamp[64];
    char log_level;
    char source_ip[16];
    char message[256];
} LogEntry;

void *parseAndProcessLogs(void *args) {
    FILE *file = fopen("logs.log", "r");
    if (!file) {
        printf("Error opening file.\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int chunk_count = LOG_FILE_SIZE / CHUNK_SIZE + 1;

    for (int i = 0; i < chunk_count; i++) {
        char buffer[CHUNK_SIZE];
        if (!fread(buffer, 1, CHUNK_SIZE, file)) {
            printf("Error reading file.\n");
            break;
        }

        LogEntry *log_entries = malloc(sizeof(LogEntry) * MAX_LOG_ENTRIES);
        int log_entry_count = 0;

        pthread_mutex_lock(&lock);

        char *line = buffer;
        while (line < buffer + CHUNK_SIZE && log_entry_count < MAX_LOG_ENTRIES) {
            line += strlen(line) + 1; // skip to next line
            if (*line != '\n') continue;
            *line = '\0'; // null-terminate the line

            sscanf(line, "%63s,%c%s,%15s", log_entries[log_entry_count].timestamp,
                   &log_entries[log_entry_count].log_level, log_entries[log_entry_count].source_ip,
                   log_entries[log_entry_count].message);

            log_entry_count++;
        }

        pthread_mutex_unlock(&lock);

        // process log entries
        for (int j = 0; j < log_entry_count; j++) {
            printf("Timestamp: %s, Log Level: %c, Source IP: %s, Message: %s\n",
                   log_entries[j].timestamp, log_entries[j].log_level,
                   log_entries[j].source_ip, log_entries[j].message);
        }

        free(log_entries);

        pthread_cond_signal(NULL); // signal the logging thread
    }

    fclose(file);
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, parseAndProcessLogs, NULL);

    pthread_join(thread, NULL);

    return 0;
}
