    int i, j;
    pthread_t thread_id = pthread_self();
    DataPoint* data_points;
    double* accumulators;
    float* thresholds;

    // Initialize memory management structures
    data_points = (DataPoint*)malloc(128 * sizeof(DataPoint));
    if (!data_points) {
        printf("Memory allocation failed: exiting gracefully.\n");
        return NULL;
    }

    accumulators = (double*)malloc(256 * sizeof(double));
    thresholds = (float*)malloc(256 * sizeof(float));
    if (!(accumulators && thresholds)) {
        printf("Memory allocation failed: exiting gracefully.\n");
        free(data_points);
        return NULL;
    }

    // Initialize arrays
    for (i = 0; i < 128; i++) {
        data_points[i].value = (float)rand() / RAND_MAX * 200.0 - 100.0;
        data_points[i].status = false;
    }
    for (j = 0; j < 256; j++) {
        accumulators[j] = 0.0;
        thresholds[j] = (float)(-1.0 + rand() / RAND_MAX * 2.0);
    }

    // Perform aggregation and transformation
    for (i = 0; i < 128; i++) {
        for (j = 0; j < 256; j++) {
            if (data_points[i].value > thresholds[j]) {
                accumulators[j]++;
                break;
            }
        }
    }

    // Release allocated memory
    free(data_points);
    free(accumulators);
    free(thresholds);

    return NULL;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, processAndAggregateData, NULL);
    pthread_join(thread, NULL);

    return 0;
