using System;
using System.IO;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;

public class ConnectionProcessor
{
    public enum ErrorCodes { InvalidPassword, InvalidConnectionMetadata, DecryptionFailed }

    public void ProcessConnection(Connection connection, AsyncCallback callback)
    {
        if (string.IsNullOrEmpty(connection.EncryptedPassword))
            return; // No password to process

        try
        {
            string decodedPassword = DecodeBase64EncodedPassword(connection.EncryptedPassword);
            if (decodedPassword == null || decodedPassword.Length == 0)
                throw new Exception("Invalid or empty password");

            ConnectionMetadata metadata = connection.Metadata;
            if (!ValidateConnectionMetadata(metadata))
                return; // Invalid connection metadata

            try
            {
                byte[] decryptedBytes = DecryptPassword(decodedPassword, connection.Key, connection.IV);
                callback(new AsyncCallbackEventArgs { Password = decryptedBytes });
            }
            catch (Exception ex)
            {
                callback(new AsyncCallbackEventArgs { ErrorMessage = "Decryption failed: " + ex.Message });
            }
        }
        catch (Exception ex)
        {
            callback(new AsyncCallbackEventArgs { ErrorMessage = "Error processing connection: " + ex.Message });
        }
    }

    private string DecodeBase64EncodedPassword(string encryptedPassword)
    {
        byte[] decodedBytes;
        try
        {
            decodedBytes = Convert.FromBase64String(encryptedPassword);
        }
        catch (FormatException)
        {
            throw new Exception("Invalid Base64 encoding");
        }
        return Encoding.UTF8.GetString(decodedBytes);
    }

    private bool ValidateConnectionMetadata(ConnectionMetadata metadata)
    {
        if (!string.IsNullOrEmpty(metadata.Title) && metadata.Title.Length > 255)
            return false;

        DateTime lastActivity = DateTime.FromFileTime(metadata.LastActivityTimestamp);
        return (DateTime.Now - lastActivity).Hours <= 24 &&
               metadata.Active &&
               !metadata.IsMarkedForDeletion;
    }

    private byte[] DecryptPassword(string password, byte[] key, byte[] iv)
    {
        using (TripleDESCryptoServiceProvider crypto = new TripleDESCryptoServiceProvider())
        {
            crypto.Key = key;
            crypto.IV = iv;
            using (MemoryStream ms = new MemoryStream(Encoding.UTF8.GetBytes(password)))
            {
                using (CryptoStream cs = new CryptoStream(ms, crypto.CreateDecryptor()))
                {
                    byte[] decryptedBytes = new byte[cs.Length];
                    cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
    }

    public IDataReader ExecuteParameterizedQuery(SqlConnection connection, string query, params object[] parameters)
    {
        using (SqlCommand command = new SqlCommand(query, connection))
        {
            foreach (object param in parameters)
            {
                command.Parameters.AddWithValue(param.ToString(), param);
            }
            return command.ExecuteReader();
        }
    }
}

public class Connection
{
    public string EncryptedPassword { get; set; }
    public ConnectionMetadata Metadata { get; set; }
    public byte[] Key { get; set; }
    public byte[] IV { get; set; }
}

public class ConnectionMetadata
{
    public string Title { get; set; }
    public long LastActivityTimestamp { get; set; }
    public bool Active { get; set; }
    public bool IsMarkedForDeletion { get; set; }
}

public class AsyncCallbackEventArgs
{
    public byte[] Password { get; set; }
    public string ErrorMessage { get; set; }
}
