#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <json-c/json.h>

typedef struct log_entry {
    char timestamp[50];
    int log_level;
    char source_ip[20];
    char destination_ip[20];
    char protocol[10];
    char message[1000];
    uint64_t log_hash;
} log_entry;

log_entry* processAndIntegrateConfiguredLogs(const char* file_path, json_object* config) {
    // 1. Parse a large text file containing log entries
    FILE *file = fopen(file_path, "r");
    if (!file) {
        printf("Error opening file: %s\n", file_path);
        return NULL;
    }

    // Initialize memory-mapped file
    int file_size = lseek(file, 0, SEEK_END);
    struct stat file_stat;
    fstat(file->fd, &file_stat);
    char* mmapped_file = mmap(NULL, file_size, PROT_READ | PROT_WRITE, MAP_SHARED, file->fd, 0);
    if (mmapped_file == MAP_FAILED) {
        printf("Error mapping file: %s\n", file_path);
        fclose(file);
        return NULL;
    }

    // Initialize data structures
    log_entry* log_entries = malloc(5 * 1000000 * sizeof(log_entry));
    uint64_t* timestamps = malloc(10 * 1000000 * sizeof(uint64_t));
    char** messages = malloc(5 * 1000000 * sizeof(char*));

    // Parse and process log entries
    int line_num = 0;
    for (char* line = mmapped_file; fgets(line, file_size, file);) {
        // Skip empty lines
        if (!strchr(line, ';')) continue;

        // Parse fields
        char* field = strtok(line, ";");
        log_entry* entry = &log_entries[line_num++];

        // Set timestamp and normalize it to ISO 8601 format
        entry->timestamp[0] = '\0';
        strftime(entry->timestamp, sizeof(entry->timestamp), "%Y-%m-%dT%H:%M:%S%z", strptime(field++, "%F %T%z", &entry->timestamp));
        if (!strptime(entry->timestamp, "%Y-%m-%dT%H:%M:%S%z", entry->timestamp)) {
            printf("Error parsing timestamp: %s\n", file_path);
            fclose(file);
            munmap(mmapped_file, file_size);
            free(log_entries);
            free(timestamps);
            free(messages);
            return NULL;
        }

        // Parse and validate log level
        field = strtok(NULL, ";");
        entry->log_level = atoi(field);

        // Parse and validate source IP
        field = strtok(NULL, ";");
        strncpy(entry->source_ip, field, sizeof(entry->source_ip));
        entry->source_ip[sizeof(entry->source_ip) - 1] = '\0';

        // Parse and validate destination IP
        field = strtok(NULL, ";");
        strncpy(entry->destination_ip, field, sizeof(entry->destination_ip));
        entry->destination_ip[sizeof(entry->destination_ip) - 1] = '\0';

        // Parse protocol
        field = strtok(NULL, ";");
        strcpy(entry->protocol, field);

        // Parse and validate message
        int message_len;
        field = strtok(NULL, ";");
        message_len = strlen(field);
        messages[line_num++ - 1] = strndup(field, message_len);

        // Validate log entry
        if (!entry->timestamp[0] || !entry->protocol[0] || message_len > sizeof(entry->message)) {
            printf("Error validating log entry: %s\n", file_path);
            fclose(file);
            munmap(mmapped_file, file_size);
            free(log_entries);
            free(timestamps);
            free(messages);
            return NULL;
        }
    }

    // Filter out invalid log entries
    for (int i = 0; i < line_num; i++) {
        if (!strcmp(entry->protocol, "invalid")) {
            printf("Invalid protocol: %s\n", file_path);
            continue;
        }

        if (!strchr(entry->source_ip, '.') || !strchr(entry->destination_ip, '.')) {
            printf("Invalid IP address: %s\n", file_path);
            continue;
        }
    }

    // Close file and unmap memory
    fclose(file);
    munmap(mmapped_file, file_size);

    return log_entries;
}
