        measurementsArray[i] = malloc(sizeof(measurement_t));
        doubleOffsetValues[i] = rand() / (double)RAND_MAX;
        floatPrecisionValues[i] = (float)(rand() / (double)RAND_MAX);
    }

    // Aggregate measurements
    for (int i = 0; i < measurementsCount; i++) {
        measurement_t* measurement = &measurementsArray[i];
        double sum = 0.0;
        int count = 128;
        for (int j = 0; j < count; j++) {
            sum += measurement->value;
        }
        measurement->value = sum / count;

        // Compute variance and standard deviation
        sum = 0.0;
        for (int j = 0; j < count; j++) {
            double diff = measurement->value - (measurement->value);
            sum += diff * diff;
        }
        measurement->variance = sum / count;
        measurement->standardDeviation = sqrt(measurement->variance);
    }

    // Sort aggregated results
    qsort(measurementsArray, 2048, sizeof(measurement_t*), compareMeasurements);

    return measurementsArray;
}

int compareMeasurements(const void* a, const void* b) {
    measurement_t* meas1 = *(measurement_t**)a;
    measurement_t* meas2 = *(measurement_t**)b;

    if (meas1->value < meas2->value) {
        return -1;
    } else if (meas1->value > meas2->value) {
        return 1;
    } else {
        return 0;
    }
}
