using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace SubscriptionManagementAPI.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class SubscriptionsController : ControllerBase
    {
        private readonly ILogger _logger;
        private readonly Dictionary<string, List<Subscription>> _subscriptions = new();
        private readonly int _subscriptionLimit;
        private readonly TimeSpan _subscriptionExpirationGracePeriod;

        public SubscriptionsController(ILogger<SubscriptionsController> logger, int subscriptionLimit, TimeSpan subscriptionExpirationGracePeriod)
        {
            _logger = logger;
            _subscriptionLimit = subscriptionLimit;
            _subscriptionExpirationGracePeriod = subscriptionExpirationGracePeriod;
        }

        [HttpPost]
        public IActionResult Subscribe([FromBody]SubscribeRequest request)
        {
            // Check if the user has reached the subscription limit
            if (_subscriptions.TryGetValue(request.UserId, out var existingSubscriptions) && existingSubscriptions.Count >= _subscriptionLimit)
            {
                return BadRequest("User has reached the subscription limit.");
            }

            // Check if the requested subscription is already active
            if (existingSubscriptions.Any(s => s.EventId == request.EventId))
            {
                return Conflict("Subscription already exists for this event.");
            }

            // Create a new subscription
            var subscription = new Subscription(request.UserId, request.EventId);
            _subscriptions.AddOrModify(request.UserId, existingSubscriptions, subscription);

            // Schedule the subscription expiration if necessary
            _logger.LogInformation($"Scheduled subscription expiration for {request.UserId} in {_subscriptionExpirationGracePeriod}");
            // todo: implement a mechanism to automatically expire subscriptions inactive beyond a specified grace period

            return CreatedAtAction(nameof(ListSubscriptions), new { userId = request.UserId }, "Subscription created successfully");
        }

        [HttpDelete]
        public IActionResult Unsubscribe([FromQuery]UnsubscribeRequest request)
        {
            if (!_subscriptions.TryGetValue(request.UserId, out var existingSubscriptions))
            {
                return NotFound("User not found or has no subscriptions.");
            }

            // Find the subscription to be unsubscribed
            var subscriptionToRemove = existingSubscriptions.Find(s => s.EventId == request.EventId);
            if (subscriptionToRemove == null)
            {
                return NotFound("Subscription not found for this event.");
            }

            // Remove the subscription
            _subscriptions.AddOrModify(request.UserId, existingSubscriptions.Where(s => s.EventId != request.EventId).ToList());
            _logger.LogInformation($"Unsubscribed {request.UserId} from {request.EventId}");

            if (_subscriptionExpirationGracePeriod > TimeSpan.Zero)
            {
                _logger.LogInformation($"Scheduled subscription expiration for {request.UserId}");
                // todo: implement a mechanism to automatically expire subscriptions inactive beyond a specified grace period
            }

            return Ok("Subscription removed successfully");
        }

        [HttpGet]
        public IActionResult ListSubscriptions([FromQuery]ListSubscriptionsRequest request)
        {
            if (!_subscriptions.TryGetValue(request.UserId, out var existingSubscriptions))
            {
                return NotFound("User not found or has no subscriptions.");
            }

            // Filter the subscriptions based on the category
            var filteredSubscriptions = existingSubscriptions.Where(s => s.Category == request.Category);

            // Paginate the results
            int pageIndex = 0;
            int pageSize = 10;

            if (request.PageIndex > 0)
                pageIndex = request.PageIndex;
            else if (request.PageSize > 0)
                pageSize = request.PageSize;

            var paginatedSubscriptions = filteredSubscriptions.Skip(pageIndex * pageSize).Take(pageSize);

            // Cache the pagination result for better performance
            _logger.LogInformation($"Caching paginated subscriptions for {request.UserId} and category {request.Category}");
            // todo: implement caching mechanisms

            return Ok(paginatedSubscriptions.ToList());
        }

        [HttpGet]
        public IActionResult ListAllSubscriptions()
        {
            // Return a list of all active subscriptions
            var allSubscriptions = _subscriptions.Values.SelectMany(s => s).Where(s => s.IsActive);

            return Ok(allSubscriptions.ToList());
        }
    }

    public class SubscribeRequest
    {
        public string UserId { get; set; }
        public string EventId { get; set; }
    }

    public class UnsubscribeRequest
    {
        public string UserId { get; set; }
        public string EventId { get; set; }
    }

    public class ListSubscriptionsRequest
    {
        public string UserId { get; set; }
        public string Category { get; set; }
        public int PageIndex { get; set; }
        public int PageSize { get; set; }
    }
}
