// Strategy pattern to generate random values
class RandomValueGenerator {
public:
    virtual int generate(int min, int max) = 0;
};

// Uniform distribution strategy
class UniformRandomValueGenerator : public RandomValueGenerator {
public:
    int generate(int min, int max) override {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dis(min, max);
        return dis(gen);
    }
};

// Normal distribution strategy
class NormalRandomValueGenerator : public RandomValueGenerator {
public:
    int generate(int min, int max) override {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::normal_distribution<double> nd(min, (max - min) / 2);
        return static_cast<int>(nd(gen));
    }
};

// Exponential distribution strategy
class ExponentialRandomValueGenerator : public RandomValueGenerator {
public:
    int generate(int min, int max) override {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::exponential_distribution<double> ed(min, (max - min));
        return static_cast<int>(ed(gen));
    }
};

// Main application class
class Application {
public:
    Application(int numRecords, int minValue, int maxValue, RandomValueGenerator* generator)
        : numRecords_(numRecords), minValue_(minValue), maxValue_(maxValue), generator_(generator) {}

    void run() {
        // Initialize memory for arrays
        long* offsets = new long[numRecords_];
        int* keys = new int[numRecords_];
        Record* records = new Record[numRecords_];

        // Generate random values and populate the record array
        for (int i = 0; i < numRecords_; i++) {
            records[i].key = generator_->generate(minValue_, maxValue_);
            records[i].value = generator_->generate(minValue_, maxValue_);
        }

        // Perform API operations using Boost Asio
        boost::asio::io_context ioContext;
        boost::asio::ip::tcp::resolver resolver(ioContext);
        boost::asio::ip::tcp::socket socket(ioContext);

        // Simulate API request and response handling
        InterfaceTableMock table;
        for (int i = 0; i < numRecords_; i++) {
            std::string metadataIp = "metadata_ip_" + std::to_string(i);
            std::string vmUuid = table.FindVmUuidFromMetadataIp(metadataIp);

            // Perform API request and handle response
            boost::asio::ip::tcp::endpoint endpoint = *resolver.resolve(vmUuid, "api.com", boost::asio::ip::tcp::v4());
            socket.connect(endpoint);

            // Simulate API request failure handling
            try {
                // Send API request and receive response
                boost::asio::write(socket, boost::asio::buffer("API Request"));
                boost::asio::read_until(socket, boost::asio::dynamic_buffer(1024), "OK");

                // Log API operation execution time
                double elapsed = (boost::chrono::high_resolution_clock::now() - start_).count();
                std::cout << "API Operation " << i + 1 << ": Executed in " << elapsed << " seconds" << std::endl;
            } catch (const boost::system::system_error& e) {
                // Handle API request failure
                std::cerr << "Error: " << e.what() << std::endl;
            }

            // Release socket resources
            socket.close();
        }

        // Clean up memory and exit
        delete[] offsets;
        delete[] keys;
        delete[] records;
    }

private:
    int numRecords_;
    int minValue_;
    int maxValue_;
    RandomValueGenerator* generator_;
    boost::chrono::high_resolution_clock::time_point start_ = boost::chrono::high_resolution_clock::now();
};

int main(int argc, char** argv) {
    // Parse command-line arguments
    int numRecords = 100;
    int minValue = 1;
    int maxValue = 1000;

    // Set the random value generation strategy based on command-line options
    RandomValueGenerator* generator = nullptr;
    if (argc > 1 && std::string(argv[1]) == "uniform") {
        generator = new UniformRandomValueGenerator();
    } else if (argc > 1 && std::string(argv[1]) == "normal") {
        generator = new NormalRandomValueGenerator();
    } else if (argc > 1 && std::string(argv[1]) == "exponential") {
        generator = new ExponentialRandomValueGenerator();
    }

    // Run the application with the specified parameters
    Application app(numRecords, minValue, maxValue, generator);
    app.run();

    // Clean up resources
    delete generator;
    return 0;
}

