// Define record structure and its size
typedef struct {
    int key;
    float value;
    time_t timestamp;
} Record;

Record* initDataProcessingPipeline(const char* directoryName) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for offset values array
    long* offsets = (long*)malloc(2048 * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Memory allocation failed for offset values.\n");
        return NULL;
    }

    // Initialize offset values array with random numbers
    for (int i = 0; i < 2048; i++) {
        offsets[i] = rand() % 10000000 + 10;
    }

    // Allocate memory for keys array
    int* keys = (int*)malloc(2048 * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Memory allocation failed for keys.\n");
        free(offsets);
        return NULL;
    }

    // Initialize keys array with random numbers
    for (int i = 0; i < 2048; i++) {
        keys[i] = rand() % 100 + 10;
    }

    // Allocate memory for float values array
    float* floats = (float*)malloc(1024 * sizeof(float));
    if (!floats) {
        fprintf(stderr, "Error: Memory allocation failed for float values.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize float values array with random numbers
    for (int i = 0; i < 1024; i++) {
        floats[i] = (float)rand() / (RAND_MAX + 1.0f);
    }

    // Allocate memory for record structures
    Record* records = (Record*)malloc(1024 * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        free(floats);
        return NULL;
    }

    // Populate record structures with random data
    for (int i = 0; i < 1024; i++) {
        records[i].key = keys[rand() % 2048];
        records[i].value = floats[rand() % 1024];
        records[i].timestamp = time(NULL);
    }

    // Sort records by key in descending order using mergesort
    int (*sort)(Record*, int, int) = mergesort;
    sort(records, 0, 1023);

    // Create directory and set environment variable
    char* dirPath = (char*)malloc(strlen(directoryName) + 1);
    strcpy(dirPath, directoryName);
    if (mkdir(dirPath, 0755) != 0) {
        fprintf(stderr, "Error: Directory creation failed.\n");
        free(dirPath);
        return NULL;
    }

    // Set environment variable
    setenv("DATA_PIPELINE_DIR", dirPath, 1);

    // Cleanup memory allocation and environment variables
    free(offsets);
    free(keys);
    free(floats);
    free(records);
    free(dirPath);

    return records;
}

// Quick sort implementation (not used in this function)
int (*quicksort)(Record*, int, int) = NULL;

// Mergesort implementation for sorting records by key
void mergesort(Record* arr, int low, int high) {
    if (low < high) {
        int mid = (low + high) / 2;
        mergesort(arr, low, mid);
        mergesort(arr, mid + 1, high);
        merge(arr, low, mid, high);
    }
}

void merge(Record* arr, int low, int mid, int high) {
    Record* left = (Record*)malloc((mid - low + 1) * sizeof(Record));
    Record* right = (Record*)malloc((high - mid) * sizeof(Record));

    for (int i = 0; i < mid - low + 1; i++) {
        left[i] = arr[low + i];
    }
    for (int i = 0; i < high - mid; i++) {
        right[i] = arr[mid + 1 + i];
    }

    int i = 0, j = 0, k = low;
    while (i < mid - low + 1 && j < high - mid) {
        if (left[i].key > right[j].key) {
            arr[k++] = left[i++];
        } else {
            arr[k++] = right[j++];
        }
    }

    while (i < mid - low + 1) {
        arr[k++] = left[i++];
    }
    while (j < high - mid) {
        arr[k++] = right[j++];
    }
}
