void processAndIndexDocuments(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        fprintf(stderr, "Error opening directory: %s\n", strerror(errno));
        return;
    }

    // Initialize data structures
    document_entry** documents = calloc(1000000, sizeof(document_entry*)); // 1 million elements
    char** titles = calloc(1000000, sizeof(char*)); // 1 billion elements
    char** authors = calloc(500000, sizeof(char*)); // 500 million elements

    // Process each file in the directory
    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        char file_path[1024];
        sprintf(file_path, "%s/%s", dir_path, ent->d_name);

        FILE* file = fopen(file_path, "r");
        if (file == NULL) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
            continue;
