typedef struct {
    int key;
    int value;
    time_t timestamp;
} Record;

void* processAndFindMax(void* arg) {
    Record** records = (Record**)malloc(512 * sizeof(Record*));
    for(int i = 0; i < 512; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->key = rand() % 90 + 10;
        records[i]->value = 0;
        time(&records[i]->timestamp);
    }

    Record* keys[1024];
    for(int i = 0; i < 1024; i++) {
        keys[i] = (Record*)malloc(sizeof(Record));
        keys[i]->key = rand() % 90 + 10;
        keys[i]->value = 0;
        time(&keys[i]->timestamp);
    }

    int* offsets[1024];
    for(int i = 0; i < 1024; i++) {
        offsets[i] = (int*)malloc(sizeof(int));
        *offsets[i] = rand() % 10000;
    }

    // Sort records based on their 'int' key values
    pthread_sort(records, 512);

    // Release memory and exit gracefully if any allocation fails
    for(int i = 0; i < 512; i++) free(records[i]);
    for(int i = 0; i < 1024; i++) free(keys[i]);
    for(int i = 0; i < 1024; i++) free(offsets[i]);
    free(records);
    return NULL;
}

void pthread_sort(void** arr, int n) {
    // Mergesort implementation
    if(n > 1) {
        int mid = n / 2;
        void** left = (void**)malloc(mid * sizeof(void*));
        void** right = (void**)malloc((n - mid) * sizeof(void*));

        for(int i = 0; i < mid; i++) left[i] = arr[i];
        for(int i = mid; i < n; i++) right[i - mid] = arr[i];

        pthread_sort(left, mid);
        pthread_sort(right, n - mid);

        int k = 0;
        int j = 0;
        int i = 0;

        while(k < mid && j < (n - mid)) {
            if(((Record*)left[k])->key <= ((Record*)right[j])->key) {
                arr[i++] = left[k++];
            } else {
                arr[i++] = right[j++];
            }
        }

        while(k < mid) {
            arr[i++] = left[k++];
        }

        while(j < (n - mid)) {
            arr[i++] = right[j++];
        }
    }
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, processAndFindMax, NULL);
    pthread_join(thread, NULL);
    return 0;
}
