#include <arpa/inet.h>
#include <pthread.h>

#define BUFFER_SIZE 1048576 // 10 MB
#define TRANSFORM_BUFFER_SIZE 5242880 // 5 MB

typedef struct {
    void* raw_data;
    char metadata[256];
    unsigned long hash;
    int processing_status;
} data_chunk;

void* streamAndTransformData(void*) {
    int sockfd, conn_retry_count = 0;
    struct sockaddr_in server_addr;
    pthread_t thread_id;
    data_chunk* chunk_array = (data_chunk*)malloc(BUFFER_SIZE);
    void* temp_buffer = malloc(BUFFER_SIZE);
    void* transform_buffer = malloc(TRANSFORM_BUFFER_SIZE);

    // Establish connection and process data
    while (1) {
        if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
            printf("Socket creation failed\n");
            exit(-1);
        }

        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(8080);

        inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

        if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
            printf("Connection failed\n");
            // Retry connection
            if (++conn_retry_count > 3) {
                printf("Maximum retries exceeded\n");
                break;
            }
            sleep(2); // Wait for some time before retrying
        } else {
            printf("Connected to the server\n");
            break;
        }
    }

    // Process data chunks
    while (1) {
        int bytes_read = read(sockfd, temp_buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            printf("Error reading from socket\n");
            break;
        } else if (bytes_read == 0) {
            break; // Connection closed by server
        }

        // Allocate memory for a new chunk
        data_chunk* chunk = (data_chunk*)malloc(sizeof(data_chunk));
        chunk->raw_data = temp_buffer;

        // Process the chunk and transform its contents
        pthread_create(&thread_id, NULL, processChunk, chunk);
    }

    free(temp_buffer);
    free(transform_buffer);

    close(sockfd);
    return NULL;
}

void* processChunk(void* arg) {
    data_chunk* chunk = (data_chunk*)arg;

    // Normalize the raw data fields using a thread-safe data transformation library
    transformRawData(chunk->raw_data);

    // Filter out any invalid data chunks based on predefined criteria
    if (!isValidChunk(chunk)) {
        free(chunk);
        return NULL;
    }

    // Store only valid data in the allocated buffers
    storeValidChunk(chunk);

    return NULL;
}

int main() {
    streamAndTransformData(NULL);
    return 0;
}
