} transaction_record;

// Function to parse and process records
void* parseAndProcessRecords(void* arg) {
    FILE* file = (FILE*)arg;

    // Initialize arrays and structures
    int array1_size = 1000000;
    int array2_size = 500000;
    int array3_size = 250000;
    transaction_record** records = malloc(sizeof(transaction_record*) * (array1_size + array2_size + array3_size));

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Process file
    fseek(file, 0, SEEK_SET);
    while (!feof(file)) {
        char line[1024];
        fgets(line, sizeof(line), file);

        transaction_record* record = malloc(sizeof(transaction_record));
        sscanf(line, "%d\t%s\t%f\t%s\t%s\t%s", &record->id, record->date, &record->amount, record->status, record->hash, record->metadata);

        pthread_mutex_lock(&lock);
        // Insert record into one of the arrays based on its size
        if (array1_size > 0) {
            records[array1_size - 1] = record;
            array1_size--;
        } else if (array2_size > 0) {
            records[array2_size - 1] = record;
            array2_size--;
        } else {
            records[array3_size - 1] = record;
            array3_size--;
        }
        pthread_mutex_unlock(&lock);
    }

    // Close file
    fclose(file);

    return NULL;
}

