#define MAX_FILES 1024
#define MAX_METADATA_SIZE (sizeof(struct FileMetadata) * MAX_FILES)

struct FileMetadata {
    time_t lastModified;
    off_t fileSize;
};

// Memory-efficient data structure for storing file metadata
typedef struct {
    struct FileMetadata metadata[MAX_FILES];
    int fileCount;
} FileMetadataArray;

// Function to read metadata from a directory and populate the data structure
void readMetadataFromDirectory(const char *directory, FileMetadataArray *metadataArray) {
    DIR *dir = opendir(directory);
    if (!dir) {
        // Handle error condition
        return;
    }

    struct dirent *ent;
    int i = 0;

    while ((ent = readdir(dir)) && i < MAX_FILES) {
        const char *path = malloc(strlen(directory) + strlen(ent->d_name) + 2);
        sprintf(path, "%s/%s", directory, ent->d_name);

        struct stat statbuf;
        if (stat(path, &statbuf) == -1) {
            free(path);
            continue;
        }

        metadataArray->metadata[i].lastModified = statbuf.st_mtime;
        metadataArray->metadata[i].fileSize = statbuf.st_size;

        free(path);
        i++;
    }

    metadataArray->fileCount = i;
    closedir(dir);
}

// Function to sort file metadata in ascending order based on last modification timestamp
void sortMetadata(FileMetadataArray *metadataArray) {
    qsort(metadataArray->metadata, metadataArray->fileCount, sizeof(struct FileMetadata), compareMetadata);
}

int compareMetadata(const void *a, const void *b) {
    struct FileMetadata *fileA = (struct FileMetadata *)a;
    struct FileMetadata *fileB = (struct FileMetadata *)b;

    if (fileA->lastModified < fileB->lastModified)
        return -1;
    else if (fileA->lastModified > fileB->lastModified)
        return 1;
    else
        return 0;
}

// Function to integrate the function into a larger file management system that supports concurrent operations
void manageFiles(FileMetadataArray *metadataArray) {
    // Implement concurrency control mechanisms, such as locks or condition variables, to manage access to shared resources.
}

int main() {
