    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->mem = malloc(capacity);
    mp->capacity = capacity;
    mp->free_blocks = 0;
    return mp;
}

// Allocate memory from the custom memory pool allocator
void *image_processor_memory_allocator(void *data, size_t size) {
    MemoryPool *mp = (MemoryPool *)data;
    void *ptr = NULL;

    if (mp->free_blocks > 0) {
        ptr = mp->mem + (size_t)(size * mp->free_blocks);
        mp->free_blocks--;
    } else {
        ptr = mp->mem;
    }

    return ptr;
}

// Function to process an image
