// Define the structure for records
typedef struct {
    int key;
} record;

// Function to process and find max
void* processAndFindMax(void* arg) {
    // Initialize arrays
    int* offsets = (int*)malloc(1024 * sizeof(int));
    int* keys = (int*)malloc(1024 * sizeof(int));
    record* records = (record*)malloc(512 * sizeof(record));

    // Validate memory allocation and initialization
    if (!offsets || !keys || !records) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }

    // Initialize random number generator
    srand(time(NULL));

    // Populate records with random keys
    for (int i = 0; i < 512; i++) {
        int key = rand() % 90 + 10;
        records[i].key = key;
    }

    // Sort records by their keys in ascending order
    qsort(records, 512, sizeof(record), compare);

    // Find the largest integer stored in the array of integers read from standard input
    int max_key = 0;
    for (int i = 0; i < 1024; i++) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }

    // Print the largest integer
    printf("Largest key: %d\n", max_key);

    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

// Compare function for qsort()
int compare(const void* a, const void* b) {
    record* ra = (record*)a;
    record* rb = (record*)b;
    if (ra->key < rb->key) {
        return -1;
    } else if (ra->key > rb->key) {
        return 1;
    }
    return 0;
}

int main() {
    // Create a background worker thread
    pthread_t thread;
    pthread_create(&thread, NULL, processAndFindMax, NULL);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}
