        record->value = rand() % (max_value - min_value + 1) + min_value;
        int buffer_size = snprintf(NULL, 0, "%d", record->value) + 1;
        record->buffer = malloc(buffer_size);
        if (!record->buffer) return NULL; // Handle memory allocation failure
        sprintf(record->buffer, "%d", record->value);
        record->key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    }
    return records;
}

void free_records(record_t* records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].buffer) free(records[i].buffer);
    }
    free(records);
