    int* keys;
    size_t record_size;
    Record* records;
} Context;

Context* create_context(size_t offset_size, size_t key_size, size_t record_size) {
    Context* ctx = (Context*)malloc(sizeof(Context));
    ctx->offset_size = offset_size;
    ctx->offsets = (long*)calloc(offset_size, sizeof(long));
    ctx->key_size = key_size;
    ctx->keys = (int*)calloc(key_size, sizeof(int));
    ctx->record_size = record_size;
    ctx->records = (Record*)calloc(record_size, sizeof(Record));
    return ctx;
}

void free_context(Context* ctx) {
    if(ctx != NULL) {
        free(ctx->offsets);
        free(ctx->keys);
        free(ctx->records);
        free(ctx);
    }
}

int generate_random_value(int min, int max) {
    // Use a suitable random number generation algorithm
    static time_t last_time = 0;
    time_t current_time = time(NULL);
    if(current_time > last_time) {
        srand(current_time);
        last_time = current_time;
    }
    return rand() % (max - min + 1) + min;
}

int process_data(Context* ctx, int offset_start, int key_start, int record_start, int range_min, int range_max) {
    for(int i = 0; i < ctx->record_size; i++) {
        // Set the value of each record's int field to a random value within the given range
        Record* record = &ctx->records[i];
        record->value = generate_random_value(range_min, range_max);
    }
    return 0;
}

