    int* offsets = (int*)malloc((*offsetSize) * sizeof(int));
    for (int i = 0; i < *offsetSize; i++) {
        offsets[i] = rand() % 100;
    }

    int* keys = (int*)malloc((*keySize) * sizeof(int));
    for (int i = 0; i < *keySize; i++) {
