    }

    Record** records = (Record**)malloc((*offsetSize) * sizeof(Record*));
    for (int i = 0; i < *offsetSize; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = rand() % 200;
        records[i] = record;
    }

    return records;
}

void sortArrays(Record** records, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (records[j]->value > records[j + 1]->value) {
                Record* temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void deallocateArrays(Record** records, int offsetSize) {
    for (int i = 0; i < offsetSize; i++) {
        free(records[i]);
    }
    free(records);
}

