#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    int key;
    long offset;
} record_t;

// Define the memory pool structure
typedef struct {
    void** mem_blocks;
    size_t num_blocks;
    pthread_mutex_t lock;
} memory_pool_t;

// Function to allocate memory from the pool
void* malloc_from_pool(memory_pool_t* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (pool->mem_blocks[i] != NULL && size <= sizeof(void*)) {
            void* ptr = pool->mem_blocks[i];
            pool->mem_blocks[i] = NULL;
            pthread_mutex_unlock(&pool->lock);
            return ptr;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

// Function to initialize the memory pool
memory_pool_t* init_memory_pool(size_t num_blocks, size_t block_size) {
    memory_pool_t* pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    pool->mem_blocks = (void**)malloc(num_blocks * sizeof(void*));
    pool->num_blocks = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Function to free the memory pool
void free_memory_pool(memory_pool_t* pool) {
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (pool->mem_blocks[i] != NULL) {
            free(pool->mem_blocks[i]);
        }
    }
    free(pool->mem_blocks);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Function to populate the records with random integer values
void populate_records(record_t* records, size_t num_records, int min, int max) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand() % (max - min + 1) + min;
    }
}

// Function to sort the records based on their 'int' key values
void sort_records(record_t* records, size_t num_records) {
    qsort(records, num_records, sizeof(record_t), NULL);
}

// Main function
int main() {
    // Initialize the memory pool
    memory_pool_t* pool = init_memory_pool(1024, sizeof(void*));

    // Allocate and initialize the arrays
    record_t* records = (record_t*)malloc_from_pool(pool, 512 * sizeof(record_t));
    int* keys = (int*)malloc_from_pool(pool, 1024 * sizeof(int));
    long* offsets = (long*)malloc_from_pool(pool, 1024 * sizeof(long));

    // Populate the records with random integer values
    populate_records(records, 512, 10, 100);

    // Sort the records based on their 'int' key values
    sort_records(records, 512);

    // Free the allocated memory
    free_memory_pool(pool);
    free(keys);
    free(offsets);
    return 0;
}
