#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>

// Custom memory pool allocator
class MemoryPool {
public:
    MemoryPool(size_t numTiers) : tiers_(numTiers), currentTier_(0), totalMemory_(1024*1024*128) {}

    void* allocate(size_t size) {
        // Allocate from current tier or move to next tier if needed
        if (currentTier_ < tiers_) {
            auto& currentTier = tiers_[currentTier_++];
            if (!currentTier.full()) {
                return currentTier.allocate(size);
            }
        }
        return nullptr;
    }

    void deallocate(void* ptr) {
        // Deallocate in the tier where it was allocated
        for (int i = 0; i < currentTier_; ++i) {
            auto& tier = tiers_[i];
            if (tier.deallocate(ptr)) {
                return;
            }
        }
    }

private:
    struct Tier {
        std::vector<char> memory_;
        size_t used_ = 0;

        void* allocate(size_t size) {
            // Allocate within the current tier
            if (used_ + size <= memory_.size()) {
                used_ += size;
                return &memory_[used_ - size];
            }
            return nullptr;
        }

        bool full() const { return used_ == memory_.size(); }

        void deallocate(void* ptr) {
            // Deallocate within the current tier
            if (ptr >= &memory_[0] && ptr < &memory_[0] + memory_.size()) {
                used_ -= static_cast<size_t>(ptr - &memory_[0]);
                return;
            }
        }
    };

    std::vector<Tier> tiers_;
    size_t currentTier_;
    size_t totalMemory_;
};

// Record structure
struct Record {
    int value_;
};

// Array of records
std::vector<Record> records_(512000);

// Sorting algorithm (parallel merge sort)
void parallelMergeSort(Record* arr, size_t n) {
    // Sort small chunks in parallel using OpenMP
    size_t chunkSize = 16;
    std::vector<std::thread> threads;
    for (size_t i = 0; i < n; i += chunkSize) {
        threads.emplace_back(
            [&arr, &n, i, chunkSize]() {
                Record* chunk = &arr[i];
                size_t end = std::min(i + chunkSize, n);
                for (size_t j = i; j < end; ++j) {
                    for (size_t k = j + 1; k < end; ++k) {
                        if (chunk[j].value_ > chunk[k].value_) {
                            std::swap(chunk[j], chunk[k]);
                        }
                    }
                }
            }
        );
    }
    for (auto& thread : threads) {
        thread.join();
    }

    // Merge sorted chunks
    size_t left = 0, right = n;
    while (right > left + chunkSize - 1) {
        size_t midLeft = left + (right - left) / 2;
        size_t midRight = left + (right - left + chunkSize - 1) / 2;
        merge(&arr[left], &arr[midLeft], &arr[midRight], right);
        left = midRight;
    }

    // Final sort
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            if (arr[i].value_ > arr[j].value_) {
                std::swap(arr[i], arr[j]);
            }
        }
    }
}

// Memory leak detection mechanism
class MemoryLeakDetector {
public:
    void* trackAllocation(void* ptr, size_t size) {
        // Track allocation in the shadow memory pool
        return &shadowMemory_[size];
    }

    void detectLeaks() {
        // Iterate over the shadow memory pool and check for unallocated blocks
        for (auto& block : shadowMemory_) {
            if (!block.allocated) {
                std::cout << "Memory leak detected at address " << block.ptr << "\n";
            }
        }
    }

private:
    struct AllocationBlock {
        void* ptr;
        size_t size;
        bool allocated = true;
    };

    std::vector<AllocationBlock> shadowMemory_;
};

// Main program
int main() {
    // Initialize the memory pool and record array
