#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define WORD_LIST_SIZE 100
#define ITEM_STRUCT_LENGTH 136 // sizeof(int) + 128

// Define a struct to hold item data
typedef struct {
    int value;
    char word[128];
} item_t;

// Define a memory pool with slab allocator
typedef struct {
    void** blocks;
    int block_size;
    int free_blocks;
} memory_pool_t;

void* alloc_memory(memory_pool_t* pool, int size) {
    if (pool->free_blocks > 0) {
        void* ptr = pool->blocks[pool->block_size * --pool->free_blocks];
        memset(ptr, 0, size);
        return ptr;
    }
    return NULL;
}

void free_memory(memory_pool_t* pool, void* ptr) {
    int index = (int)ptr - pool->blocks[0];
    pool->blocks[index] = alloc_memory(pool, ITEM_STRUCT_LENGTH); // Update the block to free
    pool->free_blocks++;
}

// Initialize the word list with random words from a predefined list of 100 common English words
void init_word_list(char* (*word_list)[128]) {
    char** words = (char**)malloc(WORD_LIST_SIZE * sizeof(char*));
    for (int i = 0; i < WORD_LIST_SIZE; i++) {
        words[i] = malloc(129); // 1 byte for null-terminator
        strcpy(words[i], ...common English words...);
    }
    *word_list = words;
}

// Generate random integer values for keys and struct item values
void generate_random_data(int* keys, item_t* items) {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        keys[i] = rand() % 90 + 10; // Random key between 10 and 100
        items[i].value = rand() % 999 + 1; // Random item value between 1 and 1000
        for (int j = 0; j < 128; j++) {
            items[i].word[j] = word_list[rand() % WORD_LIST_SIZE][j]; // Randomly select a word from the list
        }
    }
}

// Sort function to handle both stable and unstable sorting based on different criteria
void sort_records(int* keys, item_t* items) {
    if (/* smaller dataset */) {
        // Prioritize stability for consistent ordering among records with the same integer key
        qsort(keys, MAX_RECORDS, sizeof(int), /* comparator */);
        qsort(items, MAX_RECORDS, sizeof(item_t), /* comparator */);
    } else {
        // Switch to a faster but less stable sort for larger datasets
        qsort_key_value_sort(keys, items, /* comparator */);
    }
}

// Main function to demonstrate the data processing pipeline
int main() {
    int* keys = malloc(MAX_RECORDS * sizeof(int));
    item_t* items = malloc(MAX_RECORDS * sizeof(item_t));

    // Initialize and populate data structures
    memory_pool_t pool;
    char* word_list[WORD_LIST_SIZE];
    init_word_list(word_list);
    generate_random_data(keys, items);

    // Sort the records
    sort_records(keys, items);

    free_memory(&pool, NULL); // Free all allocated memory
    free(keys);
    free(items);
    for (int i = 0; i < WORD_LIST_SIZE; i++) {
        free(word_list[i]);
    }
    return 0;
}
