dataRecord* processAndManageDataStream() {
    // Initialize fixed-size arrays
    long* timestampOffsets = (long*)malloc(1024 * sizeof(long));
    int* keyValues = (int*)malloc(1024 * sizeof(int));

    if (!timestampOffsets || !keyValues) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize dynamic array
    dataRecord** records = (dataRecord**)malloc(2048 * sizeof(dataRecord*));
    int numRecords = 0;

    srand(time(NULL)); // Initialize thread-safe random number generator

    while (1) {
        int recordKey = rand() % 91 + 10; // Generate random integer between 10 and 100
        float recordValue = (float)rand() / RAND_MAX;
        long recordTimestamp = time(NULL);

        dataRecord* record = (dataRecord*)malloc(sizeof(dataRecord));
        if (!record) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        record->key = recordKey;
        record->value = recordValue;
        record->timestamp = recordTimestamp;

        records[numRecords] = record;
        numRecords++;

        if (numRecords >= 2048) {
            break;
        }
    }

    // Sort records based on their key values
    pthread_mutex_lock();
    qsort(records, numRecords, sizeof(dataRecord*), compareDataRecords);
    pthread_mutex_unlock();

    return records;
}

int compareDataRecords(const void* a, const void* b) {
    dataRecord* recordA = *(dataRecord**)a;
    dataRecord* recordB = *(dataRecord**)b;

    if (recordA->key < recordB->key) {
        return -1;
    } else if (recordA->key > recordB->key) {
        return 1;
    }

    return 0;
}
