typedef struct {
    int key;
    long offset;
} record;

record* allocateArrays(int size, size_t alignment) {
    record *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;

    // Allocate memory for arrays
    if ((offsets = (long*)aligned_alloc(alignment, sizeof(long) * size)) == NULL || 
        (keys = (int*)aligned_alloc(alignment, sizeof(int) * size)) == NULL || 
        (records = (record*)malloc(sizeof(record) * size)) == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 90 + 10; // Random key between 10 and 100
        offsets[i] = (long)rand(); // Random offset value
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    return records;
}

void validateAllocation(record* records, int size) {
    if (records == NULL || size <= 0) {
        printf("Invalid allocation.\n");
        exit(1);
    }
}

record* sortRecords(record *records, int size) {
    // Sort records using insertion sort
    for (int i = 1; i < size; i++) {
        record temp = records[i];
        int j = i - 1;
        while (j >= 0 && temp.key < records[j].key) {
            records[j + 1] = records[j];
            j--;
        }
        records[j + 1] = temp;
    }

    return records;
}

void freeMemory(record* records, int size) {
    if (records != NULL) {
        free(records);
    }
}
