#define MIN_ARRAY_SIZE 2048
#define MAX_RECORDS 1000000

typedef struct record {
    int value;
} Record;

void* malloc_or_die(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int main() {
    pthread_t threads[4];

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, process_pipeline, NULL);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void* process_pipeline(void* arg) {
    // Initialize arrays
    long* offsets = malloc_or_die(MIN_ARRAY_SIZE * sizeof(long));
    int* keys = malloc_or_die(MIN_ARRAY_SIZE * sizeof(int));
    Record* records = malloc_or_die(MAX_RECORDS * sizeof(Record));

    // Initialize random seed for record values
    srand((unsigned)time(NULL));

    // Perform aggregation operation
    double sum = 0;
    long offset_count[MIN_ARRAY_SIZE] = {0};
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % MIN_ARRAY_SIZE;
        records[i].value = rand() % 100;
        offsets[key]++;
        sum += records[i].value;
    }

    // Calculate average per offset
    double total_records = (double)MAX_RECORDS;
    for (int i = 0; i < MIN_ARRAY_SIZE; i++) {
        if (offsets[i] > 0) {
            double avg = (sum / offsets[i]) * (total_records / offsets[i]);
            printf("Offset %ld: Average value is %.2f\n", i, avg);
        }
    }

    // Clean up
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
