    // Allocate memory for long offset values (1024 elements)
    *offsetValues = (int*) aligned_alloc(64, 1024 * sizeof(int));

    // Allocate memory for int keys (1024 elements)
    *keys = (int**) malloc(sizeof(int*) * 1024);
    for (int i = 0; i < 1024; i++) {
        (*keys)[i] = (int*) aligned_alloc(64, sizeof(int));
    }

    // Allocate memory for record structures (512 elements)
    *records = (Record*) malloc(sizeof(Record) * 512);

    return NULL;
}

