void validateArrays(int* offsetValues, int** keys, Record* records) {
    // Check for memory alignment
    if (!is_aligned((uintptr_t) offsetValues, 64)) {
        printf("Error: Offset values not aligned\n");
        exit(1);
    }

    for (int i = 0; i < 1024; i++) {
        if (!is_aligned((uintptr_t) (*keys)[i], 64)) {
            printf("Error: Key values not aligned\n");
            exit(1);
        }
    }

    // Check for out-of-range elements in int array
    for (int i = 0; i < 1024; i++) {
        if ((*keys)[i] < 10 || (*keys)[i] > 100) {
            printf("Error: Key value out of range\n");
            exit(1);
        }
    }

    // Check for valid record values
    for (int i = 0; i < 512; i++) {
        if (records[i].value < 10 || records[i].value > 100) {
            printf("Error: Record value out of range\n");
            exit(1);
        }
    }
}

// Function to set record values to random numbers
