        records[i].value = rand() % 91 + 10;
    }
}

// Function to sort record values based on their keys
void sortRecords(Record* records, int numRecords) {
    // Use a sorting algorithm of your choice (e.g., quicksort)
    quicksort(records, 0, numRecords - 1);
}

int main() {
    // Initialize arrays and validate memory allocation
    int* offsetValues;
    int** keys;
    Record* records;
    initArrays(&offsetValues, &keys, &records);
    validateArrays(offsetValues, keys, records);

    // Populate record values with random numbers
    populateRecords(offsetValues, keys, records);

    // Sort record values based on their keys
    sortRecords(records, 512);

    return 0;
}

// Custom function to check memory alignment
int is_aligned(uintptr_t ptr, size_t alignment) {
    return (ptr & (alignment - 1)) == 0;
