// Define structure for 'entry' containing string key and size
typedef struct {
    char* string;
    size_t size;
} entry;

// Define hash table node
typedef struct _node {
    entry* data;
    struct _node* next;
} node;

// Define hash table
typedef struct {
    int capacity;
    int size;
    node** buckets;
} hash_table;

// Initialize hash table with given capacity
hash_table* init_hash_table(int capacity) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = (node**)calloc(capacity, sizeof(node*));
    return ht;
}

// Calculate the index for a given string in the hash table
int hash_function(const char* str, int capacity) {
    // Implement your own hash function here
    // For demonstration purposes, use a simple modulo operation
    return strlen(str) % capacity;
}

// Insert an entry into the hash table
void insert_entry(hash_table* ht, const char* str, size_t size) {
    int index = hash_function(str, ht->capacity);
    node* bucket = ht->buckets[index];
    if (!bucket) {
        bucket = (node*)malloc(sizeof(node));
        bucket->data = (entry*)malloc(sizeof(entry));
        bucket->next = NULL;
        ht->buckets[index] = bucket;
    }
    bucket->data->string = str;
    bucket->data->size = size;
}

// Calculate the total size of all strings stored in the hash table
size_t total_string_size(hash_table* ht) {
    size_t total_size = 0;
    for (int i = 0; i < ht->capacity; i++) {
        node* bucket = ht->buckets[i];
        while (bucket) {
            total_size += bucket->data->size;
            bucket = bucket->next;
        }
    }
    return total_size;
}

// Process and find unique strings
void processAndFindUnique() {
    // Initialize hash table with capacity 4096
    hash_table* ht = init_hash_table(4096);

    // Read list of strings from standard input
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        // Remove trailing newline character and allocate memory for the string
        size_t size = strlen(buffer) + 1;
        char* str = (char*)malloc(size);
        strcpy(str, buffer);

        // Initialize array of 'entry' structures with a total of 2048 elements
        entry entries[2048];
        int count = 0;

        // Validate successful memory allocation and initialization of all data structures
        if (!ht || !entries) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            exit(1);
        }

        // Populate each 'entry' with unique strings read from standard input
        for (int i = 0; i < size; i++) {
            entries[count].string = str;
            entries[count].size = size;
            count++;
        }

        // Insert entries into the hash table using thread-safe insertion method
        for (int i = 0; i < count; i++) {
            insert_entry(ht, entries[i].string, entries[i].size);
        }
    }

    // Calculate total size of all strings stored in the hash table
    size_t total_size = total_string_size(ht);

    printf("Total string size: %zu\n", total_size);
}

int main() {
    processAndFindUnique();
    return 0;
}
