int comp_func(const void* a, const void* b) {
    record_t* rec_a = (record_t*)a;
    record_t* rec_b = (record_t*)b;
    if (rec_a->key < rec_b->key)
        return -1;
    else if (rec_a->key > rec_b->key)
        return 1;
    return 0;
}

void free_records(record_t* records, int size) {
    free(records);
}

int main() {
    record_t* records = init_records(512);
    sort_records(records, 512);
    free_records(records, 512);
    return 0;
}
