        return -1; // Handle memory allocation failure
    }

    for (int i = 0; i < num_records; i++) {
        records[i] = new_record(1, 100); // Initialize record with random value
        offsets[i] = rand();
    }

    // Free any previously allocated memory on error or exit
    free(records);
    free(offsets);

    return 0;
}

