    void* offsets = malloc(size * sizeof(long));
    if (!offsets) return NULL;

    void* keys = malloc(size * sizeof(int));
    if (!keys || !offsets) return NULL;

    return offsets;
}

void freeArrays(void** arrays) {
    free((void*)arrays[0]);
    free((void*)arrays[1]);
    arrays[0] = NULL;
    arrays[1] = NULL;
}

record* allocateRecords(int size) {
    if (size <= 0) return NULL;

    record* records = malloc(size * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < size; ++i) {
        records[i].offset = i + 1;
        records[i].key = rand() % 100;
        // Initialize value
    }

    return records;
}

record* getRecord(record* records, int index) {
    if (!records || index < 0 || index >= (int)sizeof(records) / sizeof(record)) {
        printf("Out of bounds access!\n");
        return NULL;
    }

    return &records[index];
}

void cleanup(void** arrays, record* records) {
    freeArrays(arrays);
    freeRecords(records);
}

int main() {
    int size = 0;
    scanf("%d", &size);

    void** arrays = allocateArrays(size);

    if (!arrays) {
        printf("Memory allocation failed!\n");
        return 1;
    }

    record* records = allocateRecords(size);

    // Example usage
    for (int i = 0; i < size; ++i) {
        record* r = getRecord(records, i);
        if (r) printf("Index: %d, Key: %d, Value: %d\n", i, r->key, r->value);
    }

    cleanup(arrays, records);

    return 0;
}
