#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Node structure representing a linked list node
typedef struct {
    long value;
    struct node* next;
    int referenceCount;
} node;

// Memory manager data structures
node* head = NULL;
node* tail = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int allocatedNodes = 0;

// Function to create a new node with the given value
node* newNode(long val) {
    node* new_node = (node*)malloc(sizeof(node));
    if(new_node == NULL) {
        printf("Memory allocation failed.\n");
        exit(-1);
    }
    new_node->value = val;
    new_node->next = NULL;
    new_node->referenceCount = 0;
    return new_node;
}

// Function to increment the reference count of a node
void refNode(node* node) {
    pthread_mutex_lock(&mutex);
    node->referenceCount++;
    pthread_mutex_unlock(&mutex);
}

// Function to decrement the reference count of a node
void derefNode(node* node) {
    pthread_mutex_lock(&mutex);
    node->referenceCount--;
    if(node->referenceCount == 0) {
        free(node);
        allocatedNodes--;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to add a new node at the end of the linked list
void insertNode(long val) {
    node* newNode = newNode(val);
    pthread_mutex_lock(&mutex);
    if(head == NULL) {
        head = newNode;
        tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }
    allocatedNodes++;
    pthread_mutex_unlock(&mutex);
}

// Function to remove the node at the front of the linked list
node* removeNode() {
    node* oldHead = head;
    if(oldHead != NULL) {
        head = oldHead->next;
        if(head == NULL) {
            tail = NULL;
        }
        allocatedNodes--;
        return oldHead;
    } else {
        return NULL;
    }
}

// Function to serialize the linked list into a binary file
void serializeList(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if(file == NULL) {
        printf("Failed to open file for writing.\n");
        return;
    }
    pthread_mutex_lock(&mutex);
    node* current = head;
    while(current != NULL) {
        fwrite(&current->value, sizeof(long), 1, file);
        fwrite(&current->next, sizeof(void*), 1, file);
        fwrite(&current->referenceCount, sizeof(int), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
    fclose(file);
}

// Function to deserialize the linked list from a binary file
void deserializeList(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if(file == NULL) {
        printf("Failed to open file for reading.\n");
        return;
    }
    pthread_mutex_lock(&mutex);
    head = NULL;
    tail = NULL;
    allocatedNodes = 0;
    node* current = NULL;
    while(fread(&current->value, sizeof(long), 1, file) == 1) {
        current->next = (node*)malloc(sizeof(node));
        if(current->next == NULL) {
            printf("Memory allocation failed.\n");
            exit(-1);
        }
        current->next->value = *(long*)file;
        fread(&current->next->next, sizeof(void*), 1, file);
        fread(&current->next->referenceCount, sizeof(int), 1, file);
        if(head == NULL) {
            head = current->next;
            tail = current->next;
        } else {
            tail->next = current->next;
            tail = current->next;
        }
    }
    pthread_mutex_unlock(&mutex);
    fclose(file);
}
