typedef struct {
    int size; // Size of the hash table
    int threshold; // Threshold for resizing the hash table
    long** keys; // Array of linked lists for each key
    record** records; // Array of records
} hashtable;

// Function to create a new record
record* create_record(int value) {
    record* rec = (record*)malloc(sizeof(record));
    rec->value = value;
    return rec;
}

// Function to free the memory allocated for a record
void free_record(record* rec) {
    if(rec != NULL)
        free(rec);
}

// Function to create a new hash table
hashtable* create_hashtable(int size, int threshold) {
    hashtable* ht = (hashtable*)malloc(sizeof(hashtable));
    ht->size = size;
    ht->threshold = threshold;
    ht->keys = (long**)calloc(size, sizeof(long*));
    ht->records = (record**)calloc(size, sizeof(record*));
    for(int i=0; i<size; i++) {
        ht->keys[i] = NULL;
        ht->records[i] = NULL;
    }
    return ht;
}

// Function to free the memory allocated for a hash table
void free_hashtable(hashtable* ht) {
    if(ht != NULL) {
        for(int i=0; i<ht->size; i++) {
            free_record(ht->records[i]);
            free(ht->keys[i]);
        }
        free(ht->records);
        free(ht->keys);
        free(ht);
    }
}

// Function to insert a key-value pair into the hash table
void insert(hashtable* ht, long offset, int key, record* rec) {
    int index = offset % ht->size;
    if(ht->keys[index] == NULL)
        ht->keys[index] = (long*)malloc(sizeof(long));
    *(ht->keys[index]) = key;
    ht->records[index] = rec;
}

// Function to retrieve a record from the hash table
record* get(hashtable* ht, long offset, int key) {
    int index = offset % ht->size;
    if(ht->keys[index] != NULL && *(ht->keys[index]) == key)
        return ht->records[index];
    else
        return NULL;
}

// Function to resize the hash table
void resize(hashtable* ht) {
    int new_size = ht->size * 2;
    hashtable* new_ht = create_hashtable(new_size, ht->threshold);
    for(int i=0; i<ht->size; i++) {
        long key = *(ht->keys[i]);
        record* rec = ht->records[i];
        int index = key % new_size;
        if(rec != NULL)
            insert(new_ht, offset, key, rec);
    }
    free_hashtable(ht);
    ht = new_ht;
}

// Function to print the contents of the hash table
void print_hashtable(hashtable* ht) {
    for(int i=0; i<ht->size; i++) {
        if(ht->keys[i] != NULL) {
            long key = *(ht->keys[i]);
            record* rec = ht->records[i];
            printf("Key: %d, Value: %d\n", key, rec->value);
        }
    }
}

int main() {
    // Create a new hash table with initial size 16 and threshold 8
    hashtable* ht = create_hashtable(16, 8);

    // Insert some records into the hash table
    record* rec1 = create_record(10);
    insert(ht, 0, 5, rec1);
    record* rec2 = create_record(20);
    insert(ht, 0, 3, rec2);
    record* rec3 = create_record(30);
    insert(ht, 0, 7, rec3);

    // Print the contents of the hash table
    print_hashtable(ht);

    // Resize the hash table when it reaches the threshold
    if(ht->size >= ht->threshold) {
        resize(ht);
    }

    // Free the memory allocated for the hash table and records
    free_hashtable(ht);

    return 0;
}
