#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <math.h>

#define RECORD_MAX 1000 // maximum capacity of the record collection
#define LOGLEVEL_DEFAULT 1 // log level for diagnostics (0:off, 1:on)
#define THREAD_SAFE 1 // flag for thread safety

typedef struct {
    long timestamp;
    double value;
} Record;

typedef struct {
    Record* records;
    int size;
    int capacity;
} Collection;

Collection* collection_create(int max_capacity) {
    if (!max_capacity || max_capacity > RECORD_MAX)
        return NULL;

    Collection* col = (Collection*)malloc(sizeof(Collection));
    col->records = (Record*)calloc(max_capacity, sizeof(Record));
    col->size = 0;
    col->capacity = max_capacity;
    return col;
}

void collection_insert(Collection* col, long timestamp, double value) {
    if (!col || col->size >= col->capacity)
        return;

    Record* record = (Record*)malloc(sizeof(Record));
    record->timestamp = timestamp;
    record->value = value;

    col->records[col->size++] = *record;
}

void collection_populate(Collection* col, int start_timestamp, double mean, double std_dev) {
    srand(time(NULL)); // seed for randomness

    for (int i = 0; i < RECORD_MAX; i++) {
        long timestamp = rand() % (start_timestamp + RECORD_MAX - start_timestamp);
        double value = normdev(mean, std_dev);

        collection_insert(col, timestamp, value);
    }
}

double normdev(double mean, double stddev) {
    static double r;
    static int sgn;

    if (!stddev)
        return 0.0;

    if (!(r = (rand() * 1.0 / RAND_MAX))) {
        sgn = -1; // ensure non-zero result
        r += 0.5;
    }

    double u = (r - 0.5) * 2.0;
    double v = sqrt(-2.0 * log(r)) * cos(2.0 * M_PI * u);

    return mean + stddev * v;
}

int collection_get_size(Collection* col) {
    if (!col)
        return 0;

    return col->size;
}

