#include <pthread.h>

// Define a custom memory manager structure
typedef struct {
    void **cache;
    int size;
    pthread_mutex_t mutex;
} MemoryManager;

// Initialize the custom memory manager
void init_memory_manager(MemoryManager *mm, int size) {
    mm->cache = (void **)malloc(size * sizeof(void *));
    mm->size = size;
    pthread_mutex_init(&mm->mutex, NULL);
}

// Free memory managed by the custom memory manager
void free_memory_manager(MemoryManager *mm) {
    for (int i = 0; i < mm->size; i++) {
        if (mm->cache[i] != NULL) {
            free(mm->cache[i]);
        }
    }
    free(mm->cache);
    pthread_mutex_destroy(&mm->mutex);
}

// Custom memory allocation function using the cache
void *my_malloc(int size, MemoryManager *mm) {
    void *ptr = NULL;
    pthread_mutex_lock(&mm->mutex);
    for (int i = 0; i < mm->size; i++) {
        if (mm->cache[i] == NULL) {
            ptr = malloc(size);
            mm->cache[i] = ptr;
            break;
        }
    }
    pthread_mutex_unlock(&mm->mutex);
    return ptr;
}

// Custom memory deallocation function using the cache
void my_free(void *ptr, MemoryManager *mm) {
    pthread_mutex_lock(&mm->mutex);
    for (int i = 0; i < mm->size; i++) {
        if (mm->cache[i] == ptr) {
            free(ptr);
            mm->cache[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&mm->mutex);
}

// Define a record structure
typedef struct {
    int key;
} Record;

// Define the custom data processing pipeline function
void *data_processing_pipeline(void *arg) {
    // Initialize memory manager and cache arrays
    MemoryManager mm;
    init_memory_manager(&mm, 1024);

    // Allocate and initialize offset and key arrays
    long *offsets = my_malloc(sizeof(long), &mm);
    int *keys = my_malloc(sizeof(int), &mm);

    // Allocate memory for the record array
    Record **records = (Record **)malloc(512 * sizeof(Record *));
    for (int i = 0; i < 512; i++) {
        records[i] = malloc(sizeof(Record));
        records[i]->key = rand() % 90 + 10;
    }

    // Implement thread-safe sorting of the record array
    pthread_mutex_lock(&mm->mutex);
    qsort(records, 512, sizeof(Record), (int (*)(const void *, const void *))compare_records);
    pthread_mutex_unlock(&mm->mutex);

    // Free memory and cache arrays
    for (int i = 0; i < 512; i++) {
        free(records[i]);
    }
    free(records);
    my_free(offsets, &mm);
    my_free(keys, &mm);
    free_memory_manager(&mm);

    return NULL;
}

// Compare function for qsort to sort records by key
int compare_records(const void *a, const void *b) {
    Record *record1 = *(Record *)a;
    Record *record2 = *(Record *)b;
    if (record1->key < record2->key) {
        return -1;
    } else if (record1->key > record2->key) {
        return 1;
    } else {
        return 0;
    }
}
