#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int id;
} Event;

typedef struct {
    Event* events;
    size_t capacity, count;
} Log;

Log* log_create(size_t initial_capacity) {
    Log* log = (Log*)malloc(sizeof(Log));
    log->capacity = initial_capacity;
    log->count = 0;
    log->events = (Event*)calloc(log->capacity, sizeof(Event));
    return log;
}

void log_add_event(Log* log, int id) {
    if (log->count >= log->capacity) {
        // Double the capacity
        log->capacity *= 2;
        log->events = (Event*)realloc(log->events, log->capacity * sizeof(Event));
    }
    log->events[log->count].id = id;
    log->events[log->count].timestamp = time(NULL);
    log->count++;
}

Event* log_get_event(Log* log, int id) {
    for (size_t i = 0; i < log->count; ++i) {
        if (log->events[i].id == id) {
            return &log->events[i];
        }
    }
    return NULL;
}

