#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int key;
    long offset;
} Record;

Record* create_record(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    return record;
}

typedef struct {
    int* keys;
    long* offsets;
    Record** records;
    int capacity;
    int size;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->keys = (int*)calloc(initial_capacity, sizeof(int));
    table->offsets = (long*)calloc(initial_capacity, sizeof(long));
    table->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    return table;
}

void resize_hash_table(HashTable* table) {
    if (table->size >= 0.7 * table->capacity) {
        int new_capacity = table->capacity * 2;
        HashTable* new_table = create_hash_table(new_capacity);

        for (int i = 0; i < table->capacity; i++) {
            if (table->keys[i] != 0 && table->offsets[i] != 0) {
                int key = table->keys[i];
                long offset = table->offsets[i];
                Record* record = create_record(key, offset);
                hash_insert(new_table, record->key, record);
            }
        }

        for (int i = 0; i < table->capacity; i++) {
            free(table->keys[i]);
            free(table->offsets[i]);
            free(table->records[i]);
        }

        free(table->keys);
        free(table->offsets);
        free(table->records);
        *table = *new_table;
    }
}

int hash(HashTable* table, int key) {
    return key % table->capacity;
}

void insert_record(HashTable* table, Record* record) {
    int index = hash(table, record->key);
    while (table->keys[index] != 0 && table->offsets[index] == 0) {
        index = (index + 1) % table->capacity;
    }

    if (table->size >= table->capacity) {
        resize_hash_table(table);
        index = hash(table, record->key);
    }

    table->keys[index] = record->key;
    table->offsets[index] = record->offset;
    table->records[index] = record;
    table->size++;
}

Record* retrieve_record(HashTable* table, int key) {
    int index = hash(table, key);
    while (table->keys[index] != key && table->offsets[index] == 0) {
        index = (index + 1) % table->capacity;
    }

    if (table->keys[index] == key) {
        return table->records[index];
    } else {
        return NULL;
    }
}

void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->keys[i] != 0 && table->offsets[i] != 0) {
            Record* record = retrieve_record(table, table->keys[i]);
            free(record);
        }
    }

    free(table->keys);
    free(table->offsets);
    free(table->records);
    free(table);
}
