typedef struct {
    int key;
} record_t;

void processAndFindMax() {
    // Initialize arrays for 'long' offset values and 'int' keys
    long *offsets = (long *) malloc(1024 * sizeof(long));
    int *keys = (int *) malloc(1024 * sizeof(int));

    // Initialize array of records with 512 elements
    record_t *records = (record_t *) malloc(512 * sizeof(record_t));

    // Partition records into multiple segments and manage each segment by a separate thread
    pthread_t threads[4];
    int numSegments = 128;
    int segmentSize = 4;

    for (int i = 0; i < numSegments; i++) {
        record_t *segmentRecords = &records[i * segmentSize];
        pthread_create(&threads[i], NULL, processSegment, &segmentRecords);
    }

    // Wait for all threads to finish
    for (int i = 0; i < numSegments; i++) {
        pthread_join(threads[i], NULL);
    }

    // Sort and merge segments
    record_t *sortedRecords = sortAndMergeSegements(records);

    // Print the maximum key value from the sorted records
    int maxKey = findMaxKey(sortedRecords, 512);
    printf("Maximum key value: %d\n", maxKey);
}

void *processSegment(void *arg) {
    // Process and manipulate the segment of records
    record_t *segmentRecords = (record_t *) arg;
    for (int i = 0; i < segmentSize; i++) {
        // Validate successful memory allocation and initialization of all arrays
        if (!offsets || !keys || !records) {
            printf("Error: Memory allocation failed\n");
            exit(1);
        }

        // Populate each record's 'int' key value with a random integer within a specified range
        int randomKey = rand() % 90 + 10;
        segmentRecords[i].key = randomKey;

        // Synchronize random number generation across threads to ensure consistent results
        pthread_mutex_lock(NULL);
        printf("Thread %lu: Random key value is %d\n", (unsigned long)pthread_self(), randomKey);
        pthread_mutex_unlock(NULL);
    }

    return NULL;
}

record_t *sortAndMergeSegements(record_t *records) {
    // Sort each segment independently using a thread-safe sorting algorithm
    for (int i = 0; i < numSegments; i++) {
        record_t *segmentRecords = &records[i * segmentSize];
        qsort(segmentRecords, segmentSize, sizeof(record_t), compare);

        // Merge sorted segments using a multi-threaded merge sort algorithm
        record_t *mergedRecords = (record_t *) malloc(512 * sizeof(record_t));
        for (int i = 0; i < numSegments; i++) {
            record_t *segmentRecords = &records[i * segmentSize];
            for (int j = 0; j < segmentSize; j++) {
                mergedRecords[i * segmentSize + j] = segmentRecords[j];
            }
        }

        return mergedRecords;
    }

    // Find the maximum key value from the sorted records
    int maxKey = findMaxKey(sortedRecords, 512);
    return sortedRecords;
}

int compare(const void *a, const void *b) {
    record_t *recordA = (record_t *) a;
    record_t *recordB = (record_t *) b;

    if (recordA->key < recordB->key) {
        return -1;
    } else if (recordA->key > recordB->key) {
        return 1;
    }

    return 0;
}

int findMaxKey(record_t *records, int size) {
    int maxKey = records[0].key;

    for (int i = 1; i < size; i++) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
        }
    }

    return maxKey;
}
