void addProduct(int productId, const char* productName, double productPrice) {
    Product* newNode = (Product*)malloc(sizeof(Product));
    strcpy(newNode->name, productName);
    newNode->id = productId;
    newNode->price = productPrice;

    if (productList == NULL || productListSize == 0) {
        newNode->next = NULL;
        productList = newNode;
    } else {
        Product* lastNode = productList;
        while (lastNode->next != NULL)
            lastNode = lastNode->next;
        lastNode->next = newNode;
    }
    productListSize++;
}

void updateProduct(int productId, const char* productName) {
    Product* current = productList;
    while (current != NULL) {
        if (current->id == productId) {
            strcpy(current->name, productName);
            return;
        }
        current = current->next;
    }
}

void removeProduct(int productId) {
    Product* current = productList;
    Product* previous = NULL;

    while (current != NULL) {
        if (current->id == productId) {
            if (previous == NULL)
                productList = current->next;
            else
                previous->next = current->next;

            free(current);
            return;
        }

        previous = current;
        current = current->next;
    }
}

