#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the product struct
typedef struct {
    char name[64];
    int id;
    double price;
    size_t quantity;
} Product;

// Define the inventory struct, using a linked list for efficient insertions and deletions
typedef struct InventoryNode {
    Product product;
    struct InventoryNode* next;
} InventoryNode;

// Define the inventory struct itself, with a head pointer to the first node in the list
typedef struct {
    InventoryNode* head;
    pthread_mutex_t lock;
} Inventory;

// Function to create and initialize an empty inventory
Inventory* create_inventory() {
    Inventory* inv = (Inventory*)malloc(sizeof(Inventory));
    inv->head = NULL;
    pthread_mutex_init(&inv->lock, NULL);
    return inv;
}

// Function to add a product to the inventory, updating stock quantity if it already exists
void add_product(Inventory* inv, Product new_product) {
    InventoryNode* node = (InventoryNode*)malloc(sizeof(InventoryNode));
    node->product = new_product;
    node->next = inv->head;
    inv->head = node;
    pthread_mutex_unlock(&inv->lock);
}

// Function to update the stock quantity of a product in the inventory
void update_product(Inventory* inv, int id, size_t new_quantity) {
    InventoryNode* current = inv->head;
    while (current != NULL) {
        if (current->product.id == id) {
            current->product.quantity = new_quantity;
            pthread_mutex_unlock(&inv->lock);
            return;
        }
        current = current->next;
    }
}

// Function to remove a product from the inventory
void remove_product(Inventory* inv, int id) {
    InventoryNode* prev = NULL;
    InventoryNode* current = inv->head;
    while (current != NULL) {
        if (current->product.id == id) {
            if (prev != NULL)
                prev->next = current->next;
            else
                inv->head = current->next;
            free(current);
            pthread_mutex_unlock(&inv->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Function to reorder products by stock quantity in descending order and calculate the total value of all products in the inventory
void reorder_inventory(Inventory* inv) {
    InventoryNode* sorted_list = NULL;
    double total_value = 0.0;

    // Sort the products by stock quantity in descending order, keeping track of the total value
    for (InventoryNode* current = inv->head; current != NULL; current = current->next) {
        if (sorted_list == NULL || current->product.quantity >= sorted_list->product.quantity) {
            InventoryNode* new_node = (InventoryNode*)malloc(sizeof(InventoryNode));
            new_node->product = current->product;
            new_node->next = sorted_list;
            sorted_list = new_node;
            total_value += current->product.price * current->product.quantity;
        } else {
            for (InventoryNode* prev = sorted_list; prev->next != NULL; prev = prev->next) {
                if (prev->next->product.quantity < current->product.quantity) {
                    InventoryNode* new_node = (InventoryNode*)malloc(sizeof(InventoryNode));
                    new_node->product = current->product;
                    new_node->next = prev->next;
                    prev->next = new_node;
                    total_value += current->product.price * current->product.quantity;
                    break;
                }
            }
        }
    }

    // Update the inventory head with the sorted list
    inv->head = sorted_list;

    printf("Total value of products: $%.2f\n", total_value);
}

// Function to serialize and deserialize the inventory structure for backup and recovery processes
void serialize_inventory(Inventory* inv, FILE* file) {
    InventoryNode* current = inv->head;
    fwrite(&inv->head, sizeof(InventoryNode*), 1, file);
    while (current != NULL) {
        fwrite(&current->product.name, sizeof(char), strlen(current->product.name) + 1, file);
        fwrite(&current->product.id, sizeof(int), 1, file);
        fwrite(&current->product.price, sizeof(double), 1, file);
        fwrite(&current->product.quantity, sizeof(size_t), 1, file);
        current = current->next;
    }
}

void deserialize_inventory(Inventory* inv, FILE* file) {
    InventoryNode** head_ptr = (InventoryNode**)malloc(sizeof(InventoryNode*));
    fread(head_ptr, sizeof(InventoryNode*), 1, file);
    inv->head = *head_ptr;
    free(head_ptr);

    Product product;
    while (fread(&product.name, sizeof(char), strlen(product.name) + 1, file) > 0) {
        fread(&product.id, sizeof(int), 1, file);
        fread(&product.price, sizeof(double), 1, file);
        fread(&product.quantity, sizeof(size_t), 1, file);
        add_product(inv, product);
    }
}

int main() {
    // Create an empty inventory
    Inventory* inv = create_inventory();

    // Add some products to the inventory
    Product new_product1 = {"Product A", 1, 10.99, 100};
    Product new_product2 = {"Product B", 2, 9.99, 200};
    add_product(inv, new_product1);
    add_product(inv, new_product2);

    // Update the stock quantity of a product
    update_product(inv, 1, 150);

    // Remove a product from the inventory
    remove_product(inv, 2);

    // Reorder products by stock quantity and calculate total value
    reorder_inventory(inv);

    // Serialize and deserialize the inventory for backup and recovery processes
    FILE* file = fopen("inventory.dat", "wb");
    serialize_inventory(inv, file);
    fclose(file);

    inv = create_inventory();
    file = fopen("inventory.dat", "rb");
    deserialize_inventory(inv, file);
    fclose(file);

    return 0;
}
