int allocate_memory(int max_records, int* status) {
    int num_records = 0;
    void** memory_blocks = NULL;
    int chunk_size = 1024; // adjust this value for optimal performance and memory usage

    while (num_records < max_records) {
        void* block = malloc(chunk_size);
        if (!block) {
            *status = -1; // allocation failed
            free_memory(memory_blocks, &num_records);
            return *status;
        }
        memory_blocks = realloc(memory_blocks, (num_records + 1) * sizeof(void*));
        memory_blocks[num_records++] = block;

        // validate key size and initialize record structure
        for (int i = 0; i < num_records; i++) {
            Record* record = (Record*) memory_blocks[i];
            record->offset = i;
            sprintf(record->key, "Key-%d", i);
            strcpy(record->record, "Initial Record");
        }
    }

    return 0; // successful allocation
}

void free_memory(void** memory_blocks, int* num_records) {
    for (int i = 0; i < *num_records; i++) {
        free(memory_blocks[i]);
    }
    free(memory_blocks);
}

int main() {
    int status;
    allocate_memory(100, &status);

    if (status == -1) {
        // handle allocation failure
        printf("Memory allocation failed.\n");
    } else {
        printf("Memory allocated successfully.\n");

        // use the allocated memory here...

        free_memory((void**)memory_blocks, &num_records);
    }

    return 0;
}
