#include <map>
#include <vector>
#include <string>
#include <mutex>

class CustomerManager {
private:
    std::multimap<int, std::pair<std::string, std::vector<double>>> customers;
    std::mutex mtx;

public:
    void addCustomer(int id, const std::string& name, const std::vector<double>& transactions) {
        std::lock_guard<std::mutex> lock(mtx);
        customers.insert({id, {name, transactions}});
    }

    void updateTransactions(int id, const std::vector<double>& transactions) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& customer : customers.equal_range(id).first) {
            if (customer.first == id) {
                customer.second.second = transactions;
                break;
            }
        }
    }

    void removeCustomer(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        customers.erase(customers.find(id));
    }

    void generateReports(std::ostream& os) const {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& customer : customers) {
            os << "Customer ID: " << customer.first << "\n";
            os << "Name: " << customer.second.first << "\n";
            os << "Transactions:\n";
            for (const auto& transaction : customer.second.second) {
                os << transaction << "\n";
            }
            os << "\n";
        }
    }
};
