typedef struct {
    long* offsets;
    int* keys;
    record_t* records;
    int active_records_count;
} data_structure_t;

data_structure_t* create_data_structure(int initial_size) {
    data_structure_t* ds = (data_structure_t*)malloc(sizeof(data_structure_t));
    if (!ds) return NULL; // Handle out-of-memory condition

    ds->offsets = (long*)malloc(initial_size * sizeof(long));
    if (!ds->offsets) {
        free(ds);
        return NULL;
    }

    ds->keys = (int*)malloc(initial_size * sizeof(int));
    if (!ds->keys) {
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->records = (record_t*)malloc(initial_size * sizeof(record_t));
    if (!ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds);
        return NULL;
    }

    ds->active_records_count = 0;

    return ds;
}

void destroy_data_structure(data_structure_t* ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
    }
}

int serialize_data_structure_to_binary_file(const data_structure_t* ds, char* filename) {
    // Binary serialization implementation
    FILE* file = fopen(filename, "wb");
    if (!file) return -1; // Handle file open error

    int written_bytes = fwrite(&ds->active_records_count, sizeof(int), 1, file);
    if (written_bytes != 1) return -1; // Handle write error
    written_bytes += fwrite(ds->offsets, sizeof(long), ds->active_records_count, file);
    if (written_bytes != ds->active_records_count) return -1; // Handle write error
    written_bytes += fwrite(ds->keys, sizeof(int), ds->active_records_count, file);
    if (written_bytes != ds->active_records_count) return -1; // Handle write error
    written_bytes += fwrite(&ds->records[0], sizeof(record_t), ds->active_records_count, file);
    if (written_bytes != ds->active_records_count) return -1; // Handle write error

    fclose(file);

    return 0;
}

int serialize_data_structure_to_text_file(const data_structure_t* ds, char* filename) {
    // Text serialization implementation
    FILE* file = fopen(filename, "w");
    if (!file) return -1; // Handle file open error

    fprintf(file, "%d\n", ds->active_records_count);
    for (int i = 0; i < ds->active_records_count; i++) {
        fprintf(file, "%ld %d %.2f\n", ds->offsets[i], ds->keys[i], ds->records[i].value);
    }

    fclose(file);

    return 0;
}

data_structure_t* deserialize_data_structure_from_binary_file(const char* filename) {
    // Binary deserialization implementation
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL; // Handle file open error

    data_structure_t* ds = create_data_structure(MAX_RECORDS);
    if (!ds) return NULL;

    int active_records_count;
    fread(&active_records_count, sizeof(int), 1, file);

    for (int i = 0; i < active_records_count; i++) {
        fread(&ds->offsets[i], sizeof(long), 1, file);
        fread(&ds->keys[i], sizeof(int), 1, file);
        fread(&ds->records[i], sizeof(record_t), 1, file);
    }

    fclose(file);

    return ds;
}

data_structure_t* deserialize_data_structure_from_text_file(const char* filename) {
    // Text deserialization implementation
    FILE* file = fopen(filename, "r");
    if (!file) return NULL; // Handle file open error

    data_structure_t* ds = create_data_structure(MAX_RECORDS);
    if (!ds) return NULL;

