        double value;
        fscanf(file, "%ld %d %.2f\n", &offset, &key, &value);
        // Assign values to ds->offsets[i], ds->keys[i], and ds->records[i].value
    }

    fclose(file);

    return ds;
}

int main() {
    // Example usage
    data_structure_t* ds = create_data_structure(MAX_RECORDS);
    // ...

    char* filename = "data.bin";
    int result = serialize_data_structure_to_binary_file(ds, filename);
