int loadOrdersFromFile(char* filename, Order*** orders, int* orderCount, FILE* file) {
    int count = 0;
    *orderCount = 0;

    if (file == NULL || fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return -1;
    }

    size_t fileSize = ftell(file);
    rewind(file);

    char* buffer = allocateMemory(fileSize + 1);
    fread(buffer, 1, fileSize, file);
    buffer[fileSize] = '\0';

    char* p = buffer;
    while (p < buffer + fileSize) {
        if (sscanf(p, "{\"price\": %f, \"item\": {\"name\": \"%s\", \"value\": %d}}\n", &(*orders)[count].price, (*orders)[count].item->name, &((*orders)[count].item)->value) == 3) {
            ++*orderCount;
            p += strlen(p);
        } else {
            free(buffer);
            fclose(file);
            return -1;
        }
    }

    free(buffer);
    return 0;
}

int saveOrdersToFile(char* filename, Order* orders, int orderCount, FILE* file) {
    if (file == NULL) {
        return -1;
    }

    for (int i = 0; i < orderCount; ++i) {
        fprintf(file, "{\"price\": %f, \"item\": {\"name\": \"%s\", \"value\": %d}}\n", orders[i].price, orders[i].item->name, orders[i].item->value);
    }

    return 0;
}

int main() {
    // Initialize and manipulate data structures
    Order* orders = NULL;
    int orderCount = 0;

    FILE* file = fopen("orders.bin", "wb");
    if (file == NULL) {
        file = fopen("orders.txt", "w+");
        if (file == NULL) {
            return -1;
        }
    }

    // Load data from file
    loadOrdersFromFile(file ? "orders.bin" : "orders.txt", &orders, &orderCount, file);

    // Manipulate data structures here...

    // Save data to file
    int newOrderCount = orderCount + 1;
    Order* newOrders = allocateMemory(newOrderCount * sizeof(Order));
    for (int i = 0; i < newOrderCount; ++i) {
        newOrders[i] = orders[i];
    }

    free(orders);
    orders = newOrders;

    fclose(file);

    return 0;
}
