record* manage_memory(long size, long offset_range_min, long offset_range_max, 
                         int key_range_min, int key_range_max, int record_int_min, int record_int_max) {
    record* records = NULL;

    // Allocate memory for arrays
    if ((records = (record*)malloc(size * sizeof(record))) == NULL) {
        return NULL;
    }

    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));

    // Initialize offset array with sequential values
    for (long i = 0; i < size; i++) {
        offsets[i] = i;
    }

    // Initialize key array with random integer values
    srand(time(NULL));
    for (long i = 0; i < size; i++) {
        keys[i] = rand() % ((key_range_max - key_range_min) + 1) + key_range_min;
    }

    // Initialize record structures with randomly assigned 'int' field values
    for (long i = 0; i < size; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];

        // Assign random value to 'int' field within specified range
        records[i].key = rand() % ((record_int_max - record_int_min) + 1) + record_int_min;
    }

    // Release allocated memory
    free(offsets);
    free(keys);

    return records;
