        free(data->names);
        free(data->ages);
        free(data->scores);
        free(data->records);
        free(data);
        return NULL;
    }
    data->activeStudents = 0;
    return data;
}

void deserializeStudentData(FILE* file, StudentData* data) {
    int capacity = (int)fseek(file, SEEK_END, SEEK_END) / sizeof(student_record);
    data->records = realloc(data->records, capacity * sizeof(student_record));
    for (int i = 0; i < capacity; i++) {
        fread(&data->records[i], sizeof(student_record), 1, file);
    }
}

void serializeStudentData(FILE* file, StudentData* data) {
    fwrite(&data->activeStudents, sizeof(int), 1, file);
    for (int i = 0; i < data->activeStudents; i++) {
        student_record record;
        strcpy(record.address, data->names[i]);
        record.gradeLevel = data->ages[i];
        record.GPA = data->scores[i].GPA;
        fwrite(&record, sizeof(student_record), 1, file);
    }
}

