#include <time.h>
#include <curl/curl.h>

typedef struct {
    char location[20];
    time_t timestamp;
} sensor_metadata;

void filter_sensors(sensor_metadata* sensors, int num_sensors, const char* area, time_t start_time, time_t end_time) {
    for (int i = 0; i < num_sensors; i++) {
        if (strcmp(sensors[i].location, area) == 0 && sensors[i].timestamp >= start_time && sensors[i].timestamp <= end_time) {
            printf("Filtered sensor: %s\n", sensors[i].location);
        }
    }
}

int send_notifications(sensor_metadata* filtered_sensors, int num_filtered_sensors, CURL* curl) {
    for (int i = 0; i < num_filtered_sensors; i++) {
        CURLcode res;
        char buffer[256];
        sprintf(buffer, "Sensor %s detected at timestamp %ld", filtered_sensors[i].location, filtered_sensors[i].timestamp);
        res = CURLeasy_send(curl, "http://example.com/notifications", buffer);
        if (res != CURLE_OK) {
            printf("Failed to send notification: %s\n", curl_easy_strerror(res));
            return 1;
        }
    }
    return 0;
}

void process_data(sensor_metadata* sensors, int num_sensors, CURL* curl) {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_sensors; i++) {
        sensor_metadata& metadata = sensors[i];
        metadata.timestamp += rand() % 60;
    }

    // Filter sensors
    const char* area = "New York";
    time_t start_time = current_time - 3600;
    time_t end_time = current_time + 1800;
    int num_filtered_sensors = filter_sensors(sensors, num_sensors, area, start_time, end_time);

    // Send notifications
    CURLcode res = CURLE_OK;
    CURL* easy = curl_easy_init();
    if (easy) {
        curl_easy_setopt(easy, CURLOPT_URL, "http://example.com/notifications");
        send_notifications(sensors, num_filtered_sensors, easy);
        curl_easy_cleanup(easy);
    } else {
        printf("Failed to initialize CURL\n");
    }
}

int main() {
    int num_sensors = 10;
    sensor_metadata* sensors = (sensor_metadata*)malloc(num_sensors * sizeof(sensor_metadata));
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].location[20] = '\0';
        sensors[i].timestamp = time(NULL);
    }

    CURL* curl;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        process_data(sensors, num_sensors, curl);
        curl_easy_cleanup(curl);
    } else {
        printf("Failed to initialize CURL\n");
    }
    free(sensors);
    return 0;
}
