int get_weather_data(double*** temperatures, time_t** timestamps, int* record_count, MYSQL* conn) {
    if (!conn) {
        return -1; // Connection failure
    }

    MYSQL_RES* result = mysql_query(conn, "SELECT temperature, timestamp FROM WeatherData");
    if (mysql_errno(conn)) {
        log_message(LOG_LEVEL_ERROR, "Error executing query: ");
        return -2; // Query execution failure
    }

    int num_rows = mysql_num_rows(result);
    *record_count = num_rows;

    *temperatures = (double**)malloc(num_rows * sizeof(double*));
    *timestamps = (time_t*)malloc(num_rows * sizeof(time_t));

    for (int i = 0; i < num_rows; i++) {
        MYSQL_ROW row = mysql_fetch_row(result);
        if (!row) break;
        *temperatures[i] = (double*)malloc(sizeof(double));
        **temperatures[i] = atof(row[0]);
        *timestamps[i] = atoi(row[1]) * 60 * 60; // Convert timestamp to seconds since epoch
    }

    mysql_free_result(result);
    return 0;
}

int main() {
    MYSQL* conn = mysql_init(NULL);
    if (!conn) {
        return -1; // Initialization failure
    }

    // Establish database connection and set timeout (e.g., 30 seconds)
    conn->timeout = 30000;

    int record_count;
    double** temperatures;
    time_t* timestamps;

    int status = get_weather_data(&temperatures, &timestamps, &record_count, conn);

    if (status) {
        log_message(LOG_LEVEL_ERROR, "Failed to retrieve weather data: ");
        // Handle error and cleanup
    } else {
        for (int i = 0; i < record_count; i++) {
            printf("Temperature: %f, Timestamp: %ld\n", **temperatures[i], *timestamps[i]);
        }
    }

    // Clean up allocated memory
    for (int i = 0; i < record_count; i++) {
        free(*temperatures[i]);
    }
    free(*temperatures);
    free(timestamps);

    mysql_close(conn);
    return 0;
}
