#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    long offset;
    int key;
} record;

typedef enum {
    RESIZE_LINEAR,
    RESIZE_EXPONENTIAL
} resize_strategy;

typedef struct {
    record* records;
    size_t capacity;
    size_t size;
    resize_strategy strategy;
    int error;
} record_storage;

record_storage* create_record_storage(size_t initial_capacity, resize_strategy strategy) {
    record_storage* storage = (record_storage*)malloc(sizeof(record_storage));
    if (!storage) {
        return NULL;
    }
    storage->records = (record*)malloc(initial_capacity * sizeof(record));
    storage->capacity = initial_capacity;
    storage->size = 0;
    storage->strategy = strategy;
    storage->error = 0;
    return storage;
}

void destroy_record_storage(record_storage* storage) {
    if (!storage) {
        return;
    }
    free(storage->records);
    free(storage);
}

int add_record(record_storage* storage, int value, long offset, int key) {
    if (storage->size == storage->capacity) {
        resize_records(storage);
    }
    record new_record = {value, offset, key};
    storage->records[storage->size] = new_record;
    storage->size++;
    return 0;
}

int update_record(record_storage* storage, int old_key, int value, long offset) {
    for (size_t i = 0; i < storage->size; i++) {
        if (storage->records[i].key == old_key) {
            storage->records[i].value = value;
            storage->records[i].offset = offset;
            return 0;
        }
    }
    return -1; // Record not found
}

int iterate_records(record_storage* storage, void (*callback)(record)) {
    for (size_t i = 0; i < storage->size; i++) {
        callback(storage->records[i]);
    }
    return 0;
}

void resize_records(record_storage* storage) {
    size_t new_capacity = get_new_capacity(storage->capacity, storage->strategy);
    record* new_records = (record*)malloc(new_capacity * sizeof(record));
    if (!new_records) {
        storage->error = 1; // Allocation failure
        return;
    }
    for (size_t i = 0; i < storage->size; i++) {
        new_records[i] = storage->records[i];
    }
    free(storage->records);
    storage->records = new_records;
    storage->capacity = new_capacity;
}

size_t get_new_capacity(size_t old_capacity, resize_strategy strategy) {
    if (strategy == RESIZE_LINEAR) {
        return old_capacity + 1;
    } else if (strategy == RESIZE_EXPONENTIAL) {
        return old_capacity * 2; // Simple exponential growth
    }
    return 0; // Unknown strategy
}

void reset_record_storage(record_storage* storage) {
    free(storage->records);
    storage->size = 0;
    storage->capacity = 0;
    storage->error = 0;
}
