#include <time.h>

typedef struct {
    int id;
    int priority;
    char* description;
} Task;

Task* task_list = NULL;
int num_tasks = 0;

void add_task(int id, int length, const char* desc) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (new_task == NULL) {
        printf("Error: Out of memory.\n");
        return;
    }

    new_task->id = id;
    new_task->priority = rand() % 100; // Random priority within range [0, 99]
    new_task->description = (char*)malloc((length + 1) * sizeof(char));
    if (new_task->description == NULL) {
        printf("Error: Out of memory.\n");
        free(new_task);
        return;
    }

    strcpy(new_task->description, desc);
    new_task->description[length] = '\0'; // Null-terminate the string

    if (task_list != NULL) {
        task_list = (Task*)realloc(task_list, (num_tasks + 1) * sizeof(Task));
        if (task_list == NULL) {
            printf("Error: Out of memory.\n");
            free(new_task->description);
            free(new_task);
            return;
        }
    } else {
        task_list = new_task;
    }

    num_tasks++;
}

void remove_task(int id) {
    for (int i = 0; i < num_tasks; i++) {
        if (task_list[i].id == id) {
            free(task_list[i].description);
            Task* temp = task_list;
            task_list = &task_list[i + 1];
            num_tasks--;
            free(temp);
            return;
        }
    }
}

