        records[i] = (record_t *)malloc(sizeof(record_t));
        records[i]->key = rand() % 100 + 10;
        records[i]->offset = (long)i;
    }

    timestamps = (time_t *)malloc(sizeof(time_t) * num_records);
}

void sort_records(int num_records) {
    int i, j;
    record_t *tmp;

    for (i = 0; i < num_records - 1; i++) {
        for (j = i + 1; j < num_records; j++) {
            if (records[i]->key > records[j]->key) {
                tmp = records[i];
                records[i] = records[j];
                records[j] = tmp;
            }
        }
    }
}

void clean_up(int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);
    free(timestamps);
}
