    MemoryBlock* allocator = NULL;
    Record** records = NULL;

    // Allocate the custom memory allocator
    allocator = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    if (!allocator) return NULL;

    // Initialize the memory block size and alignment
    allocator->start = aligned_malloc(1024, sizeof(void*));  // Assuming 8-byte alignment for most architectures
    allocator->end = allocator->start + 1024;
    allocator->start -= 8;  // Ensure proper padding

    // Allocate space for the records themselves
    records = (Record**)malloc(numRecords * sizeof(Record*));
    if (!records) {
        free(allocator);
        return NULL;
    }

    // Initialize each record
    for (int i = 0; i < numRecords; i++) {
        Record* record = (Record*)aligned_malloc(sizeof(Record), sizeof(void*));  // Assuming 8-byte alignment for most architectures
        if (!record) {
            // Reallocate the memory blocks and records
            freeMemoryBlocks(allocator, records);
            return NULL;
        }

        // Initialize the record fields
        record->offset = i;
        record->key = rand() % (maxValue - minValue + 1) + minValue;
        record->value = (int)(rand() / (double)RAND_MAX * (maxValue - minValue + 1)) + minValue;
        record->status = 'A';  // Assuming the status indicator should always be 'A' for simplicity
        record->timestamp = time(NULL);

