}

// Function to deallocate and reset the custom memory allocator
void freeMemoryBlocks(MemoryBlock* allocator, Record** records) {
    if (!allocator || !records) return;

    for (int i = 0; i < 1024 / sizeof(void*); i++) {
        void* address = allocator->start + i * sizeof(void*);
