// Configuration structure for custom memory allocator
typedef struct {
    size_t block_size;
    size_t alignment_mask;
} Config;

// Record structure with int value and padding for alignment
typedef struct {
    int value;
    char pad[3]; // 12 bytes of padding for alignment to 16-byte boundary
} Record;

void* my_malloc(size_t size, void* config) {
    // Get the block size and alignment mask from the configuration
    Config* conf = (Config*)config;
    size_t block_size = conf->block_size;
    size_t alignment_mask = conf->alignment_mask;

    // Calculate the total memory required including padding
    size += sizeof(Record); // Add size of Record struct

    // Round up to nearest block size for efficient allocation
    size = (size + block_size - 1) & ~(block_size - 1);

    // Allocate memory from pool
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Align the allocated memory to the specified boundary
    ptr = (void*)((size_t)ptr + alignment_mask - ((size_t)ptr & alignment_mask));

    return ptr;
}

int main() {
