        free(imageFrames[i]->pixelBuffer);
        free(imageFrames[i]->compressedImageData);
        free(imageFrames[i]);
    }
    free(imageFrames);
    free(pixelBuffers);
    free(compressedImageDataArrays);
    free(transformationMatrices);

    // Exit gracefully
    printf("Image processing complete.\n");
}

int frameSortCompare(const void* a, const void* b) {
    imageFrame* frameA = *(imageFrame**)a;
    imageFrame* frameB = *(imageFrame**)b;
    return (frameA->frameIndex - frameB->frameIndex);
}
