#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
    double value;
} record_t;

// Custom hash function to group records by 'int' key values
unsigned long custom_hash(record_t *record) {
    return (unsigned long)record->key;
}

// Thread-safe sorting algorithm for records within each group
void thread_safe_sort(record_t **group, int size) {
    pthread_mutex_lock(NULL);
    qsort(group, size, sizeof(record_t *), compare_records);
    pthread_mutex_unlock(NULL);
}

int compare_records(const void *a, const void *b) {
    record_t *record1 = *(record_t **)a;
    record_t *record2 = *(record_t **)b;

    if (record1->offset > record2->offset)
        return -1;
    else if (record1->offset < record2->offset)
        return 1;

    return 0;
}

// Batch processing function
void batchProcessRecords(int num_records) {
    // Allocate memory for and initialize arrays
    long *offsets = (long *)malloc(2048 * sizeof(long));
    int *keys = (int *)malloc(2048 * sizeof(int));
    double *values = (double *)malloc(2048 * sizeof(double));

    if (!offsets || !keys || !values) {
        printf("Error: Memory allocation failed.\n");
        exit(-1);
    }

    // Initialize arrays with default values
    for (int i = 0; i < 2048; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        values[i] = 0.0;
    }

    // Populate records with random values
    srand(time(NULL));
    record_t *records = (record_t *)malloc(num_records * sizeof(record_t));

    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 2048;
        records[i].offset = (long)rand();
        records[i].value = (double)rand();

        // Group records by 'int' key values
        unsigned long hash_value = custom_hash(&records[i]);
    }

    // Sort each group of records within the hash table
    record_t **hash_table = (record_t **)malloc(2048 * sizeof(record_t *));
    for (int i = 0; i < 2048; i++) {
        hash_table[i] = (record_t *)malloc(num_records / 2048 * sizeof(record_t));
        pthread_mutex_lock(NULL);
        qsort(hash_table[i], num_records / 2048, sizeof(record_t *), compare_records);
        pthread_mutex_unlock(NULL);
    }

    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(values);
    free(records);

    for (int i = 0; i < 2048; i++) {
        free(hash_table[i]);
    }
    free(hash_table);
}
