// Define a record structure
typedef struct {
    int key;
} Record;

// Function to initialize and load data from file
void* load_data(void* ptr) {
    // Initialize variables
    FILE* file = (FILE*)ptr;
    long offset_values[1024];
    int keys[1024];
    size_t bytesRead = fread(offset_values, sizeof(long), 1024, file);
    size_t bytesRead2 = fread(keys, sizeof(int), 1024, file);

    // Validate data
    if (bytesRead != 1024 || bytesRead2 != 1024) {
        fprintf(stderr, "Error loading data\n");
        exit(EXIT_FAILURE);
    }

    return NULL;
}

// Function to validate memory allocation and initialization
void validate_memory_allocation() {
    int* allocated_array = malloc(sizeof(int));
    if (allocated_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    free(allocated_array);
}

// Function to sort records based on 'int' key values in ascending order
void compare_records(const void* a, const void* b) {
    Record* rec1 = (Record*)a;
    Record* rec2 = (Record*)b;

    // Sort based on int key values and then long offset values for ties
    if (rec1->key < rec2->key)
        return -1;
    else if (rec1->key > rec2->key)
        return 1;
    else {
        if (rec1->key == rec2->key) { // Handle tie based on long offset values
            long offset1 = * ((long*)a);
            long offset2 = * ((long*)b);

            if (offset1 < offset2)
                return -1;
            else if (offset1 > offset2)
                return 1;
        }
    }

    return 0;
}

// Function to generate random values for each record
void* generate_random_values(void* ptr) {
    // Initialize variables
    pthread_t thread_id = pthread_self();
    Record* records = (Record*)ptr;

    // Generate random values within a specified range (min = 10, max = 100)
    for (int i = 0; i < 512; i++) {
        int value = (rand() % ((max - min) + 1)) + min;
        records[i].key = value;
    }

    return NULL;
}

// Main function
int main(int argc, char* argv[]) {
    // Initialize variables
    FILE* file1 = fopen("file1.txt", "rb");
    FILE* file2 = fopen("file2.txt", "rb");

    if (file1 == NULL || file2 == NULL) {
        fprintf(stderr, "Error opening files\n");
        exit(EXIT_FAILURE);
    }

    // Load data from files
    pthread_t threads[2];
    void* thread_result;

    pthread_create(&threads[0], NULL, load_data, file1);
    pthread_create(&threads[1], NULL, load_data, file2);

    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], &thread_result);
    }

    // Validate memory allocation and initialization
    validate_memory_allocation();

    // Initialize record array
    Record records[512];
    void* thread_results[2];

    pthread_create(&threads[0], NULL, generate_random_values, &records);
    pthread_create(&threads[1], NULL, generate_random_values, &records);

    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], &thread_results[i]);
    }

    // Sort records based on 'int' key values in ascending order
    qsort(records, 512, sizeof(Record), compare_records);

    return 0;
}

