void* read_data_from_file(void* file_path) {
    FILE* f = (FILE*)file_path;
    if (!f) return NULL;

    // Read data for long offset values
    long* offsets = malloc(1024 * sizeof(long));
    char* buffer = malloc(1024);
    int i, j = 0;
    while (1) {
        fread(buffer, 1, 1024, f);
        if (feof(f)) break;

        for (i = 0; i < 1024; i++) {
            offsets[j] = ((long*)buffer)[i];
            j++;
        }
    }

    // Read data for int keys
    int* keys = malloc(1024 * sizeof(int));
    while (1) {
        fread(buffer, 1, 1024, f);
        if (feof(f)) break;

        for (i = 0; i < 1024; i++) {
            keys[i] = ((int*)buffer)[i];
        }
    }

    // Read data for record structures
    record_t* records = malloc(512 * sizeof(record_t));
    int record_index = 0;
    while (1) {
        fread(buffer, 1, 1024, f);
        if (feof(f)) break;

        for (i = 0; i < 1024; i++) {
            records[record_index].value = ((int*)buffer)[i];
            record_index++;
        }
    }

    free(buffer);

    return malloc(sizeof(char*) + strlen((char*)file_path) + 1);
}

