void* processDataPipeline(void* arg) {
    // Set up variables for allocation limits
    int minSize = 10, maxSize = 1000;

    // Allocate and initialize arrays with dynamic sizes
    int offsetNum = rand() % (maxSize - minSize + 1) + minSize;
    int keyNum = offsetNum;
    float weightNum = offsetNum / 2.5f;

    record_t* records = (record_t*)malloc(offsetNum * sizeof(record_t));
    long* offsets = (long*)malloc(offsetNum * sizeof(long));
    int* keys = (int*)malloc(keyNum * sizeof(int));
    float* weights = (float*)malloc(weightNum * sizeof(float));

    // Initialize arrays with random values
    for (int i = 0; i < offsetNum; i++) {
        records[i].key = rand();
        records[i].weight = (float)rand() / RAND_MAX;
        offsets[i] = (long)i;
    }
    for (int i = 0; i < keyNum; i++) {
        keys[i] = rand();
    }
    for (int i = 0; i < weightNum; i++) {
        weights[i] = (float)rand() / RAND_MAX;
    }

    // Sort records using quicksort
    qsort(records, offsetNum, sizeof(record_t), compareRecords);

    // Free allocated memory
    free(records);
    free(offsets);
    free(keys);
    free(weights);

    return NULL;
}

// Compare function for qsort
int compareRecords(const void* a, const void* b) {
    record_t* rec1 = (record_t*)a;
    record_t* rec2 = (record_t*)b;
    if (rec1->key < rec2->key)
        return -1;
    else if (rec1->key > rec2->key)
        return 1;
    else
        return 0;
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, processDataPipeline, NULL);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}
