#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
} Record;

// Define the memory management strategy structure
typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    size_t chunkSize;
    void **chunks;
    size_t numChunks;
    pthread_mutex_t mutex;
} MemoryManager;

// Function to initialize memory manager and allocate arrays
MemoryManager* initMemoryManager() {
    MemoryManager *manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    manager->capacity = 1024;
    manager->size = 0;
    manager->chunkSize = 512;
    manager->numChunks = (manager->capacity + manager->chunkSize - 1) / manager->chunkSize;
    manager->chunks = (void **)malloc(sizeof(void *) * manager->numChunks);
    manager->records = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Function to allocate a new chunk of memory
void* allocChunk(MemoryManager *manager) {
    void *chunk = malloc(manager->chunkSize);
    if (!chunk) {
        printf("Error: Failed to allocate chunk.\n");
        exit(1);
    }
    return chunk;
}

// Function to free a chunk of memory
void freeChunk(MemoryManager *manager, void *chunk) {
    free(chunk);
}

// Function to add a record to the array
int addRecord(MemoryManager *manager, int key) {
    if (manager->size >= manager->capacity) {
        printf("Error: Memory full.\n");
        exit(1);
    }
    Record *record = (Record*)malloc(sizeof(Record));
    record->key = key;
    void *chunk = NULL;
    size_t index = 0;
    for (int i = 0; i < manager->numChunks; i++) {
        if ((manager->chunks[i]) && (index + manager->chunkSize <= manager->size)) {
            chunk = manager->chunks[i];
            break;
        }
        index += manager->chunkSize;
    }
    size_t recordIndex = manager->size % manager->chunkSize;
    memcpy((char*)chunk + recordIndex * sizeof(Record), &record, sizeof(Record));
    free(record);
    return 0;
}

// Function to validate memory allocation and initialization
void validateMemory(MemoryManager *manager) {
    for (int i = 0; i < manager->size; i++) {
        Record *record = (char*)manager->chunks[i / manager->chunkSize] + (i % manager->chunkSize) * sizeof(Record);
        if (!record) {
            printf("Error: Invalid record at index %d.\n", i);
            exit(1);
        }
    }
}

// Function to populate records with random integer values
void populateRecords(MemoryManager *manager, int seed) {
