void manageRecords(int min_size, int max_size, int threshold) {
    // Allocate and initialize arrays
    record_t **records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    float *weights = NULL;

    while (1) {
        int size = rand() % (max_size - min_size + 1) + min_size;
        if ((records = malloc(size * sizeof(record_t))) == NULL ||
            (offsets = malloc(size * sizeof(long))) == NULL ||
            (keys = malloc(size * sizeof(int))) == NULL ||
            (weights = malloc(size * sizeof(float))) == NULL) {
            fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Initialize arrays
        for (int i = 0; i < size; i++) {
            records[i]->key = rand() % (100 - 10 + 1) + 10;
            keys[i] = records[i]->key;
            weights[i] = (float)(rand() % 2);
        }

        // Sort arrays
        pthread_mutex_lock();
        qsort(records, size, sizeof(record_t), compareRecords);
        pthread_mutex_unlock();

        // Monitor memory usage
        int total_bytes = sizeof(record_t) * size + sizeof(long) * size + sizeof(int) * size + sizeof(float) * size;
        if (total_bytes > threshold) {
            fprintf(stderr, "Memory usage exceeded threshold: %d bytes\n", total_bytes);
            break;
        }

        free(records);
        free(offsets);
        free(keys);
        free(weights);

        // Clean up allocated memory
        records = NULL;
    }

    void compareRecords(const void *a, const void *b) {
        record_t *record1 = *(record_t **)a;
        record_t *record2 = *(record_t **)b;

        return (record1->key - record2->key);
    }
}
