void generate_random_values(Record* records, int num_records) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 90 + 10;
    }
}

// Parallel sorting algorithm using insertion sort
void parallel_insertion_sort(Record** records, int* keys, int left, int right) {
    if (left >= right)
        return;

    int mid = (left + right) / 2;

    pthread_t thread;
    pthread_create(&thread, NULL, &parallel_insertion_sort, (void*) (records, keys, left, mid));
    pthread_join(thread);

    parallel_insertion_sort(records, keys, mid + 1, right);
}

// Main function to manage the data processing pipeline
void* process_pipeline(void* args) {
    int offset_values[1024];
    int key_values[1024];

    // Initialize offsets starting from 0 and incrementing by 1
    for (int i = 0; i < 1024; i++) {
        offset_values[i] = i;
    }

    // Fill keys with prime numbers within the range of 1 to 1024
    for (int i = 2; i * i <= 1024; i++) {
        if (offset_values[i]) {
            key_values[i - 1] = i;
        }
    }

    // Populate timestamps with the current time at initialization
    time_t timestamp = time(NULL);
    Record records[1024];

    for (int i = 0; i < 1024; i++) {
        records[i].value = 0;
        records[i].timestamp = timestamp;
    }

    // Generate random values for record int fields
    generate_random_values(records, 1024);

    // Sort records based on their 'int' key values in ascending order
    parallel_insertion_sort(&records, key_values, 0, 1023);

    free(offset_values);
    free(key_values);

    return NULL;
}

// Main program entry point
int main() {
    pthread_t thread;

    pthread_create(&thread, NULL, &process_pipeline, NULL);
    pthread_join(thread);

    return 0;
}
