    // Allocate memory for the records array
    *records = (struct record*)malloc(capacity * sizeof(struct record));

    if (*records == NULL) {
        return -1;  // Allocation failed
    }

    return 0;
}

// Custom pseudo-random number generator
int get_random(int min, int max) {
    static int seed = 42;  // Initial seed value
    return (seed += rand()) % ((max + 1) - min);  
}

// Sort function using multi-threaded merge sort
void* sort_records(void* arg) {
    struct record* start = *((struct record**)arg);
    struct record* end;
    int mid, i, j;

    // Find the middle of the segment
    if (start != end) {
        mid = (end - start + 1) / 2;

        // Split the segment into two halves and sort each half
        pthread_t thread;
        pthread_create(&thread, NULL, sort_records, &start);
        pthread_join(thread, NULL);
        pthread_create(&thread, NULL, sort_records, &mid);
        pthread_join(thread, NULL);

        // Merge the sorted halves
        for (i = mid; i < end + 1; ++i) {
            for (j = i; j > mid && start[j - 1].key > start[i - 1].key; --j) {
                struct record temp = start[j];
                start[j] = start[j - 1];
                start[j - 1] = temp;
            }
        }
    }

    return NULL;
}

// Main function
