void init_sensors(int num_points, SensorData** sensors) {
    if (!sensors || !num_points)
        return; // Check for null or zero input

    int i;
    SensorData* sensor;

    // Verify sufficient heap memory
    unsigned long mem_left = sysconf(_SC_PAGESIZE);
    for (i = 0; i < num_points; i++) {
        sensor = malloc(sizeof(SensorData));
        if (!sensor) {
            printf("Insufficient memory\n");
            return; // Exit if no more memory is available
        }
        mem_left -= sizeof(SensorData);

        DataPoint* point;
        point = malloc(sizeof(DataPoint));
        if (!point) {
            printf("Insufficient memory\n");
            free(sensor);
            return; // Exit if no more memory is available
        }
        mem_left -= sizeof(DataPoint);

        time_t now = time(NULL);
        srand(now); // Initialize random number generator with current time

        point->value = (double)rand() / RAND_MAX;
        point->id = rand();
        char ch = (char)(rand() % 26 + 'a');
        point->tag = ch;

        sensor->value = (double)rand() / RAND_MAX;
        sensor->type = ch;
        sensor->point = point;

        *sensors = sensor;

        if (!mem_left)
            break; // Exit if no more memory is available
    }
}

void free_sensors(int num_points, SensorData** sensors) {
    int i;
    for (i = 0; i < num_points; i++) {
        SensorData* sensor = sensors[i];
        DataPoint* point = sensor->point;

        free(point);
        free(sensor);
    }
}
