    int value;
    long offset;
} entry_t;

// Initialize the mutex and condition variable
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Function to initialize and manage arrays for 'long' offset values, 'int' keys, and 'record' or 'entry' structures
void* manage_memory(void* args) {
    int num_entries = 10; // initial number of entries
    entry_t** entries = (entry_t**)malloc(num_entries * sizeof(entry_t*));
    long* offsets = (long*)malloc(num_entries * sizeof(long));
    int* keys = (int*)malloc(num_entries * sizeof(int));

    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_entries; i++) {
        entries[i] = (entry_t*)malloc(sizeof(entry_t));
        // Initialize the entry
        strcpy(entries[i]->key, "init_key");
        entries[i]->value = 0;
        offsets[i] = i;
        keys[i] = i;
    }

    pthread_mutex_unlock(&lock);

    // Manage memory allocation and deallocation
    while (1) {
        int action = (int)pthread_cond_wait(&cond_var, &lock); // wait for condition variable

        if (action == 1) { // add entry
            int new_key = (int)args;
            pthread_mutex_lock(&lock);
            entries[new_key] = (entry_t*)malloc(sizeof(entry_t));
            strcpy(entries[new_key]->key, "new_key");
            entries[new_key]->value = 0;
            offsets[new_key] = new_key;
            keys[new_key] = new_key;
            pthread_mutex_unlock(&lock);
        } else if (action == 2) { // update entry
            int key = (int)args;
            pthread_mutex_lock(&lock);
            entries[key]->value = 1; // update the value
            pthread_mutex_unlock(&lock);
        } else if (action == 3) { // retrieve entry
            int key = (int)args;
            pthread_mutex_lock(&lock);
            printf("Key: %d, Value: %d, Offset: %ld\n", key, entries[key]->value, offsets[key]);
            pthread_mutex_unlock(&lock);
        } else if (action == 4) { // release partial memory
            int num_to_release = (int)args;
            pthread_mutex_lock(&lock);
            for (int i = 0; i < num_to_release; i++) {
                free(entries[i]);
