// Define the memory pool structure
typedef struct {
    record_t* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} memory_pool_t;

// Initialize the memory pool with an initial capacity of 512 records
memory_pool_t* memory_pool_init() {
    memory_pool_t* pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    pool->records = (record_t*)calloc(512, sizeof(record_t));
    pool->capacity = 512;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Resize the memory pool when it reaches its capacity
void memory_pool_resize(memory_pool_t* pool) {
    size_t new_capacity = pool->capacity * 2;
    record_t* new_records = (record_t*)calloc(new_capacity, sizeof(record_t));
    memcpy(new_records, pool->records, pool->size * sizeof(record_t));
    free(pool->records);
    pool->records = new_records;
    pool->capacity = new_capacity;
}

// Add a record to the memory pool
void memory_pool_add(memory_pool_t* pool, int value) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size >= pool->capacity) {
        memory_pool_resize(pool);
    }
    record_t* record = &pool->records[pool->size++];
    record->value = value;
    pthread_mutex_unlock(&pool->mutex);
}

