#include <pthread.h>

typedef struct {
    char* string;
    int value;
    char* ptr;
} item;

typedef struct processor {
    item** items;
    int num_items;
} processor;

processor* create_processor() {
    processor* proc = (processor*)malloc(sizeof(processor));
    proc->items = NULL;
    proc->num_items = 0;
    return proc;
}

void add_item(processor* proc, item* item) {
    if(proc->items == NULL) {
        proc->items = (item**)malloc(1 * sizeof(item*));
        proc->num_items = 1;
    } else {
        proc->items = (item**)realloc(proc->items, (proc->num_items + 1) * sizeof(item*));
        proc->num_items++;
    }
    proc->items[proc->num_items - 1] = item;
}

void free_processor(processor* proc) {
    for(int i = 0; i < proc->num_items; i++) {
        free(proc->items[i]->string);
        free(proc->items[i]->ptr);
        free(proc->items[i]);
    }
    free(proc->items);
    free(proc);
}

item* create_item(char* str, int val, char* ptr) {
    item* it = (item*)malloc(sizeof(item));
    it->string = (char*)malloc(strlen(str) + 1);
    strcpy(it->string, str);
    it->value = val;
    it->ptr = (char*)malloc(strlen(ptr) + 1);
    strcpy(it->ptr, ptr);
    return it;
}

void free_item(item* item) {
    free(item->string);
    free(item->ptr);
    free(item);
}

int main() {
    processor* proc = create_processor();

    for(int i = 0; i < 100; i++) {
        char str[16];
        sprintf(str, "item %d", i);
        item* it = create_item(str, i + 10, "ptr");
        add_item(proc, it);
    }

    printf("Processor items: %d\n", proc->num_items);

    for(int i = 0; i < proc->num_items; i++) {
        printf("%s, value: %d, ptr: %s\n", proc->items[i]->string, proc->items[i]->value, proc->items[i]->ptr);
    }

    free_processor(proc);

    return 0;
}
