void *custom_allocator(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && (size <= CHUNK_SIZE)) {
        // Allocate in chunks
        ptr = realloc(records, sizeof(file_data*) * (record_count + size / CHUNK_SIZE));
        record_count += size / CHUNK_SIZE;
        records = ptr;
    }
    return ptr;
}

int custom_deallocator(void *ptr) {
    free(ptr);
    return 0;
}

void generate_random_records(int count) {
    file_data **new_records = NULL;
    int new_record_count = 0;

    pthread_mutex_lock(&lock);
    while (record_count < count) {
        if (!records || record_count + CHUNK_SIZE <= RECORD_CAPACITY) {
            new_records = custom_allocator(sizeof(file_data*) * CHUNK_SIZE);
            for (int i = 0; i < CHUNK_SIZE && record_count < count; i++) {
                file_data *rec = custom_allocator(sizeof(file_data));
                rec->value = drand48() * RAND_MAX;
                rec->path = strdup("path"); // Placeholder
                rec->timestamp = time(NULL);
                rec->permissions = rand() % MAX_PERMISSIONS;
                new_records[i] = rec;
                record_count++;
            }
        } else {
            pthread_cond_wait(&cond, &lock);
        }
    }

    if (new_records) {
        records = new_records;
        new_record_count = record_count - (RECORD_CAPACITY - CHUNK_SIZE);
        for (int i = 0; i < new_record_count; i++) {
            custom_deallocator(new_records[i]);
        }
        custom_allocator(0); // Zero-fill memory
    }

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    file_data **ptr = records;
    while (*ptr) {
        file_data *rec = *ptr;
        free(rec->path);
        custom_deallocator(rec);
        ptr++;
    }
    custom_allocator(0); // Zero-fill memory
}

int main() {
    srand(time(NULL));
    generate_random_records(RECORD_CAPACITY);

    // Data processing pipeline implementation...
