// Function to initialize and manage memory for three data structures
measurement_t** allocate_memory(int num_measurements, int max_timestamps, int max_temps) {
    // Allocate memory for timestamps
    long* timestamps = (long*)malloc(max_timestamps * sizeof(long));
    if (!timestamps) {
        printf("Error allocating timestamp memory.\n");
        return NULL;
    }

    // Initialize timestamps to current time minus a specified number of days
    time_t now = time(NULL);
    for (int i = 0; i < max_timestamps; i++) {
        timestamps[i] = now - i * 24 * 60 * 60; // adjust this value as needed
    }

    // Allocate memory for temperatures and measurements
    float* temps = (float*)malloc(max_temps * sizeof(float));
    measurement_t** measurements = (measurement_t**)malloc(num_measurements * sizeof(measurement_t*));
    if (!temps || !measurements) {
        printf("Error allocating temperature or measurement memory.\n");
        free(timestamps);
        return NULL;
    }

    // Initialize temperatures to zero
    for (int i = 0; i < max_temps; i++) {
        temps[i] = 0.0f;
    }

    // Create and populate measurements array
    for (int i = 0; i < num_measurements; i++) {
        measurements[i] = (measurement_t*)malloc(sizeof(measurement_t));
        if (!measurements[i]) {
            printf("Error allocating measurement memory.\n");
            free(timestamps);
            free(temps);
            return NULL;
        }

        // Associate timestamp and temperature with each measurement
        measurements[i]->timestamp = timestamps[i % max_timestamps];
        measurements[i]->temperature = temps[i % max_temps];
    }

    // Return the allocated memory structures
    return measurements;
}
