    if(offsetSize < 1 || offsetSize > 1000 || 
       keySize < 1 || keySize > 1000 || 
       recordSize < 1 || recordSize > 1000) {
        printf("Invalid size. Sizes must be between 1 and 1000.\n");
        return NULL;
    }

    int* offsets = (int*)malloc(offsetSize * sizeof(int));
    int* keys = (int*)malloc(keySize * sizeof(int));
    Record* records = (Record*)malloc(recordSize * sizeof(Record));

    for(int i = 0; i < offsetSize; i++) {
        offsets[i] = i;
    }

    for(int i = 0; i < keySize; i++) {
        keys[i] = i;
    }

    for(int i = 0; i < recordSize; i++) {
        records[i].value = i;
    }

    return records;
}

void sortRecords(Record* records, int size, int order) {
    if(order == 1) { // ascending
        qsort(records, size, sizeof(Record), compare);
    } else if(order == -1) { // descending
        qsort(records, size, sizeof(Record), compareReverse);
    }
}

int compare(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;

    return recordA->value - recordB->value;
}

int compareReverse(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;

    return recordB->value - recordA->value;
}
