void processAndFindMax(int numRecords, Record** records) {
    // Initialize the offsets and keys arrays with variable sizes
    long* offsets = (long*)malloc(sizeof(long) * numRecords);
    int* keys = (int*)malloc(sizeof(int) * numRecords);

    // Allocate memory for record structures dynamically
    Record** recArr = (Record**)malloc(sizeof(Record*) * numRecords);

    // Initialize the custom random number generator
    srand(time(NULL));

    // Fill records with pseudo-random integers within a specified range
    for (int i = 0; i < numRecords; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->key = rand() % 91 + 10;
        record->value = rand() % 1001;
        record->timestamp = time(NULL);
        recArr[i] = record;
    }

    // Sort the records based on their key values
    for (int i = 0; i < numRecords - 1; i++) {
        for (int j = i + 1; j > 0; j--) {
            if (recArr[j]->key < recArr[j-1]->key) {
                Record* temp = recArr[j];
                recArr[j] = recArr[j-1];
                recArr[j-1] = temp;
            }
        }
    }

    // Process and find the maximum value
    int maxVal = recArr[0]->value;
    for (int i = 1; i < numRecords; i++) {
        if (recArr[i]->value > maxVal) {
            maxVal = recArr[i]->value;
        }
    }

    // Clean up memory and exit
    for (int i = 0; i < numRecords; i++) {
        free(recArr[i]);
    }
    free(recArr);
    free(keys);
    free(offsets);

    printf("Maximum value: %d\n", maxVal);
}
