#include <stdlib.h>
#include <stdio.h>

typedef struct Record {
    int value;
} Record;

typedef struct HashEntry {
    int key;
    Record record;
    struct HashEntry* next;
} HashEntry;

HashEntry** hashTable;
size_t hashTableSize = 0;
size_t hashTableCapacity = 16;
size_t* offsets;
int* keys;
Record** records;

void initArrays(size_t size) {
    offsets = (size_t*)malloc(sizeof(size_t) * size);
    keys = (int*)malloc(sizeof(int) * size);
    records = (Record**)malloc(sizeof(Record*) * size);

    for (size_t i = 0; i < size; i++) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i] = NULL;
    }
}

void resizeArrays(size_t newSize) {
    if (newSize > hashTableCapacity) {
        hashTableCapacity *= 2;
    }

    size_t* newOffsets = (size_t*)malloc(sizeof(size_t) * newSize);
    int* newKeys = (int*)malloc(sizeof(int) * newSize);
    Record** newRecords = (Record**)malloc(sizeof(Record*) * newSize);

    for (size_t i = 0; i < newSize; i++) {
        newOffsets[i] = -1;
        newKeys[i] = -1;
        newRecords[i] = NULL;
    }

    // Copy existing data to new arrays
    for (size_t i = 0; i < hashTableSize; i++) {
        offsets[i] = newOffsets[i];
        keys[i] = newKeys[i];
        records[i] = newRecords[i];
    }

    // Free old arrays
    free(offsets);
    free(keys);
    free(records);

    offsets = newOffsets;
    keys = newKeys;
    records = newRecords;

    hashTableSize = newSize;
}

void* hashInsert(int key, int value) {
    size_t index = key % hashTableCapacity;
    HashEntry** bucket = &hashTable[index];

    while (*bucket != NULL) {
        if ((*bucket)->key == key) {
            // Update existing record
            Record* record = (*bucket)->record;
            record->value = value;
            return (void*)record;
        }
        bucket = &((*bucket)->next);
    }

    HashEntry* newEntry = (HashEntry*)malloc(sizeof(HashEntry));
    newEntry->key = key;
    newEntry->record = (Record*)malloc(sizeof(Record));
    newEntry->record->value = value;

    if (*bucket == NULL) {
        *bucket = newEntry;
    } else {
        HashEntry* prev = *bucket;
        while (prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = newEntry;
    }

    return (void*)newEntry->record;
}

int hashLookup(int key) {
    size_t index = key % hashTableCapacity;
    HashEntry** bucket = &hashTable[index];

    while (*bucket != NULL) {
        if ((*bucket)->key == key) {
            Record* record = (*bucket)->record;
            return record->value;
        }
        bucket = &((*bucket)->next);
    }

    return -1; // Key not found
}

void hashDelete(int key) {
    size_t index = key % hashTableCapacity;
    HashEntry** bucket = &hashTable[index];

    while (*bucket != NULL) {
        if ((*bucket)->key == key) {
            // Free record and entry
            Record* record = (*bucket)->record;
            free(record);
            HashEntry* entry = *bucket;
            *bucket = (*bucket)->next;
            free(entry);

            return;
        }
        bucket = &((*bucket)->next);
    }
}

void freeArrays() {
    for (size_t i = 0; i < hashTableSize; i++) {
        // Free record and next pointers
        Record* record = records[i];
        while (record != NULL) {
            Record* temp = record;
            record = record->next;
            free(temp);
        }

        // Free hash entry
        HashEntry* entry = hashTable[i];
        while (entry != NULL) {
            HashEntry* temp = entry;
            entry = entry->next;
            free(temp);
        }
    }

    free(offsets);
    free(keys);
    free(records);
}

void freeHashTable() {
    for (size_t i = 0; i < hashTableCapacity; i++) {
        // Free bucket
        HashEntry** bucket = &hashTable[i];
        while (*bucket != NULL) {
            HashEntry* entry = *bucket;
            *bucket = (*bucket)->next;
            free(entry);
        }
    }

    free(hashTable);
}

void destroy() {
    freeArrays();
    freeHashTable();
}
