mem_pool_t* create_mem_pool(int capacity) {
    mem_pool_t* pool = (mem_pool_t*)malloc(sizeof(mem_pool_t));
    pool->capacity = capacity;
    pool->ptrs = (void**)malloc(capacity * sizeof(void*));
    pool->sizes = (size_t*)malloc(capacity * sizeof(size_t));
    return pool;
}

void* alloc_mem(mem_pool_t* pool, mem_type_e type) {
    void* ptr;
    size_t size;

    switch(type) {
        case FLOAT:
            size = sizeof(float);
            break;
        case CHAR_IDENTIFIER:
            size = sizeof(char);
            break;
        case TRANSACTION:
            size = sizeof(transaction_t);
            break;
    }

    for(int i=0; i<pool->capacity; i++) {
        if(pool->sizes[i] == 0) {
            ptr = pool->ptrs[i];
            pool->sizes[i] = size;
            return ptr;
        }
    }

    // Allocate new memory block
    size_t block_size = sizeof(float) * 128; // aligned allocation for SIMD
    void* block = malloc(block_size);
    pool->ptrs[pool->capacity++] = block;

    return block;
}

void free_mem(mem_pool_t* pool, void* ptr, mem_type_e type) {
    size_t size;

    switch(type) {
        case FLOAT:
