void initRecords(Record **records, int *size) {
    *size = 512; // Initial size of the array
    *records = (Record *)malloc(*size * sizeof(Record));

    if (*records == NULL) {
        printf("Memory allocation failed.\n");
        exit(-1);
    }

    for (int i = 0; i < *size; i++) {
        (*records)[i].offset = rand() % 1000;
        (*records)[i].key = rand() % 91 + 10; // Random int key within range [10, 100]
        (*records)[i].flag = true;
        (*records)[i].timestamp = (double)clock() / CLOCKS_PER_SEC * 1e9; // Get current time in nanoseconds
    }
}

// Function to sort the records based on their 'int' key values in ascending order
void sortRecords(Record **records, int *size) {
    qsort(*records, *size, sizeof(Record), (int (*)(const void *, const void *))cmpRecords);
}

// Comparison function for sorting records
int cmpRecords(const void *a, const void *b) {
    Record *recA = (Record *)a;
    Record *recB = (Record *)b;

    if (recA->key < recB->key)
        return -1;
    else if (recA->key > recB->key)
        return 1;
    else
        return 0;
}

// Function to dynamically resize the record array when it reaches its capacity
void resizeRecords(Record **records, int *size) {
    Record *newRecords = (Record *)realloc(*records, (*size + MAX_SIZE / 2) * sizeof(Record));

    if (newRecords == NULL) {
        printf("Memory reallocation failed.\n");
        exit(-1);
    }

    *records = newRecords;
    *size += MAX_SIZE / 2;
}

// Function to clean up memory
void cleanup(Record **records, int *size) {
    free(*records);
    *size = 0;
}
