#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEASUREMENTS 1024
#define THRESHOLD 50.0
#define MIN_VALUE -100.0
#define MAX_VALUE 100.0

typedef struct {
    int key;
    double value;
} measurement_t;

measurement_t *measurements = NULL;
size_t measurements_size = 0;
pthread_mutex_t measurements_lock = PTHREAD_MUTEX_INITIALIZER;

void* my_malloc(size_t size) {
    return malloc(size);
}

void* my_realloc(void* ptr, size_t size) {
    return realloc(ptr, size);
}

void my_free(void* ptr) {
    free(ptr);
}

measurement_t* create_measurement(int key, double value) {
    measurement_t* meas = (measurement_t*)my_malloc(sizeof(measurement_t));
    if (!meas) return NULL;
    meas->key = key;
    meas->value = value;
    return meas;
}

void add_measurement(int key, double value) {
    measurement_t* new_meas = create_measurement(key, value);
    if (!new_meas) return;

    pthread_mutex_lock(&measurements_lock);

    measurements_size++;
    if (measurements_size >= MAX_MEASUREMENTS) {
        measurements = (measurement_t*)my_realloc(measurements, sizeof(measurement_t) * measurements_size * 2);
    }

    measurement_t* old_measurements = measurements;
    measurements = new_meas;

    pthread_mutex_unlock(&measurements_lock);

    free(old_measurements);
}

void filter_measurements(double threshold) {
    for (int i = 0; i < measurements_size; i++) {
        if (measurements[i].value <= threshold) continue;
        measurement_t* meas = measurements + i;
        // shift all measurements with key >= meas->key
        int j = i - 1;
        while (j >= 0 && measurements[j].key >= meas->key) {
            measurements[j + 1] = measurements[j];
            j--;
        }
        memmove(meas, meas + 1, sizeof(measurement_t) * (measurements_size - i));
        measurements_size--;
    }
}

void sort_measurements() {
    qsort(measurements, measurements_size, sizeof(measurement_t), &measurement_cmp);
}

int measurement_cmp(const void* a, const void* b) {
    measurement_t* m1 = *(measurement_t*)a;
    measurement_t* m2 = *(measurement_t*)b;
    return (m1->key - m2->key);
}

void* thread_func(void* arg) {
    // simulate real-time data processing pipeline
    for (int i = 0; i < 100000; i++) {
        int key = rand() % 1000;
        double value = (double)rand() / RAND_MAX * (MAX_VALUE - MIN_VALUE) + MIN_VALUE;
        add_measurement(key, value);
    }
}

void main_thread_func(void* arg) {
    // perform data processing pipeline
    filter_measurements(THRESHOLD);
    sort_measurements();

