        long* temp_offset_values = (long*)malloc((offset / sizeof(long)) * sizeof(long));
        int* temp_keys = (int*)malloc((offset / sizeof(int)) * sizeof(int));
        double* temp_precision_values = (double*)malloc((offset / sizeof(double)) * sizeof(double));

        lseek(fd, 0, SEEK_SET);
        read(fd, temp_offset_values, offset);
        read(fd, temp_keys, offset);
        read(fd, temp_precision_values, offset);

        for(int j = 0; j < (int)offset / sizeof(long); j++) {
