            data_points[i * 100 + j].label = (char*)malloc((temp_keys[j] + 1) * sizeof(char));
            strcpy(data_points[i * 100 + j].label, "Label");
            data_points[i * 100 + j].length = temp_keys[j];
        }

        free(temp_offset_values);
        free(temp_keys);
