static unsigned long long random_state = 0;
unsigned int rand(int max) {
    unsigned long long *state = &random_state;
    *state = (*state * 1103515245 + 12345);
    return (unsigned int)(*state % max);
}

int main() {
    // Memory pool for efficient allocation and deallocation
    void* memory_pool = malloc(1024 * 1024); // Allocate 1MB for memory pool
    size_t pool_size = 1024 * 1024;

    // Initialize arrays and structures
    long offset[1024];
    int key[1024];
    Record record[512];

    // Validate memory allocation and initialization
    if (!memory_pool) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < 1024; i++) {
        offset[i] = (long)i;
        key[i] = rand(10000);
    }

    // Populate record structures with random values
    for (int i = 0; i < 512; i++) {
        record[i].value = rand(90) + 10; // Random value between 10 and 100
        record[i].priority = rand(5) + 1; // Random priority level (1-5)
    }

    // Sort records by key values in ascending order, with priority levels influencing position
    for (int i = 0; i < 512; i++) {
        for (int j = i + 1; j < 512; j++) {
            if (key[i] > key[j]) {
                int temp_key = key[i];
                long temp_offset = offset[i];
                Record temp_record = record[i];

                key[i] = key[j];
                offset[i] = offset[j];
                record[i] = record[j];

                key[j] = temp_key;
                offset[j] = temp_offset;
                record[j] = temp_record;

                if (record[i].priority > record[j].priority) {
                    int temp_priority = record[i].priority;
                    Record temp_record2 = record[i];

                    record[i] = record[j];
                    record[j] = temp_record2;
                    record[i].priority = temp_priority;
                }
            }
        }
    }

    // Logging mechanism to track critical events
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) {
        printf("Error: Unable to open log file.\n");
        return -1;
    }

    for (int i = 0; i < 512; i++) {
        fprintf(log_file, "%d %d\n", key[i], record[i].value);
    }
    fclose(log_file);

    // Resource cleanup
    for (int i = 0; i < 1024; i++) {
        free((void*)offset + i * sizeof(long));
        free((void*)key + i * sizeof(int));
        free((void*)record + i * sizeof(Record));
    }
    free(memory_pool);

    return 0;
}
