#include <json-c/json.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_METRIC_WINDOW 300 // configurable time window in seconds (5 minutes)

typedef struct {
    int server_id;
    long timestamp;
    char metric_type[64];
    double value;
    uint32_t hash;
    double sum;
    int count;
    double avg;
    double max;
} ServerMetric;

ServerMetric *processServerMetrics(json_object *json_data, pthread_mutex_t *mutex) {
    json_object *metrics_json = json_object_object_get(json_data, "metrics");
    if (!metrics_json) return NULL; // handle empty or invalid input

    ServerMetric *server_metrics = malloc(sizeof(ServerMetric));
    server_metrics->count = 0;
    server_metrics->sum = 0.0;
    server_metrics->avg = 0.0;
    server_metrics->max = 0.0;

    pthread_mutex_lock(mutex);

    while (json_object_object_iter(metrics_json, NULL)) {
        json_object *metric_json = json_object_object_get(metrics_json, "metric");
        if (!metric_json) break; // handle missing or malformed metric

        int server_id = json_object_get_int_val(metric_json, "server_id");
        long timestamp = json_object_get_long_val(metric_json, "timestamp");
        char metric_type[64];
        strcpy(metric_type, json_object_get_string_val(metric_json, "metric_type"));
        double value = json_object_get_double_val(metric_json, "value");

        // normalize timestamp
        time_t t = (time_t) timestamp;
        struct tm *ts = localtime(&t);
        char normalized_timestamp[32];
        strftime(normalized_timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", ts);

        ServerMetric new_metric = {
            .server_id = server_id,
            .timestamp = timestamp,
            .metric_type = metric_type,
            .value = value,
            // ...
        };

        // update rolling average and maximum
        if (new_metric.value > server_metrics->max) server_metrics->max = new_metric.value;
        server_metrics->sum += new_metric.value;
        server_metrics->count++;

        if (server_metrics->count >= MAX_METRIC_WINDOW) {
            // calculate cumulative sum, count, rolling average, and maximum
            double cum_sum = 0.0;
            int cum_count = 0;
            for (int i = 0; i < server_metrics->count; i++) {
                cum_sum += server_metrics->sum - (i * new_metric.value);
                cum_count++;
            }
            server_metrics->avg = cum_sum / cum_count;

            // reset window
            server_metrics->sum -= (server_metrics->count * new_metric.value);
            server_metrics->count--;
        }

        pthread_mutex_unlock(mutex);

        free(server_metrics);
        return &new_metric;
    }

    pthread_mutex_unlock(mutex);
    return NULL;
}
