#define TREE_NODE struct TreeNode

TREE_NODE* initTree(int value);

void insertNode(TREE_NODE** root, int value);

void inOrderTraversal(TREE_NODE* root);

int verifyKeyUniqueness(int key, TREE_NODE** cache);

void printTree(TREE_NODE* root);

typedef struct TreeNode {
    int value;
    TREE_NODE* left;
    TREE_NODE* right;
} TreeNode;

TREE_NODE* initTree(int value) {
    TREE_NODE* node = (TREE_NODE*) malloc(sizeof(TreeNode));
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

void insertNode(TREE_NODE** root, int value) {
    if (*root == NULL) {
        *root = initTree(value);
        return;
    }

    TREE_NODE* current = *root;
    TREE_NODE* previous = NULL;

    while (current != NULL) {
        previous = current;
        if (value < current->value) {
            current = current->left;
        } else if (value > current->value) {
            current = current->right;
        } else {
            // Duplicate key found
            printf("Duplicate key detected\n");
            return;
        }
    }

    if (value < previous->value) {
        previous->left = initTree(value);
    } else {
        previous->right = initTree(value);
    }
}

void inOrderTraversal(TREE_NODE* root) {
    if (root == NULL) {
        return;
    }

    inOrderTraversal(root->left);
    printf("%d ", root->value);
    inOrderTraversal(root->right);
}

int verifyKeyUniqueness(int key, TREE_NODE** cache) {
    // Implement your uniqueness verification mechanism here
    // For this example, let's assume it returns 1 for unique and 0 for duplicate
    return 1;
}

void printTree(TREE_NODE* root) {
    inOrderTraversal(root);
    printf("\n");
}
