    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    // Initialize memory for arrays
    long *offset_values = NULL;
    int *keys = NULL;

    // Read and process file records incrementally
    Record *records = NULL;
    size_t record_count = 0;
    size_t offset_values_size = 0;
    size_t keys_size = 0;

    while (1) {
        // Allocate memory for next record
        records = realloc(records, (record_count + 1) * sizeof(Record));
        if (records == NULL) {
            fprintf(stderr, "Error allocating memory: %s\n", __FILE__);
            return;
        }

        // Read record size from file
        uint32_t record_size;
        fread(&record_size, sizeof(uint32_t), 1, file);
        if (ferror(file)) {
            fprintf(stderr, "Error reading record size: %s\n", __FILE__);
            free(records);
            records = NULL;
            break;
        }

        // Validate record size
        if (record_size > sizeof(Record) || record_size < sizeof(uint32_t)) {
            fprintf(stderr, "Invalid record size: %u\n", record_size);
            free(records);
            records = NULL;
            break;
        }

        // Read and process record fields
        Record *current_record = &records[record_count];
        fread(&current_record->key, sizeof(int), 1, file);

        // Randomly set int field value within a specified range
        current_record->key = (rand() % 100) + 1; // Replace with desired randomization logic

        record_count++;

        // Update offset values and keys arrays
        if (offset_values_size < record_count) {
            offset_values = realloc(offset_values, record_count * sizeof(long));
            keys = realloc(keys, record_count * sizeof(int));

            for (size_t i = 0; i < record_count; i++) {
                offset_values[i] = (long)file.tellg();
                keys[i] = records[i].key;
            }

            offset_values_size = record_count;
        }
    }

    // Close file and free memory
    fclose(file);
    free(records);

    if (offset_values != NULL && offset_values_size > 0) {
        printf("Offset values: ");
        for (size_t i = 0; i < offset_values_size; i++) {
            printf("%ld ", offset_values[i]);
        }
        puts("");
    }

    if (keys != NULL && keys_size > 0) {
        printf("Keys: ");
        for (size_t i = 0; i < keys_size; i++) {
            printf("%d ", keys[i]);
        }
        puts("");
    }
}

