    const size_t TOTAL_ALLOCATED_SIZE = (numRecords + BUFFER_SIZE) * sizeof(record);

    if (TOTAL_ALLOCATED_SIZE > MB) {
        return NULL; // Memory allocation failure
    }

    record* records = malloc(TOTAL_ALLOCATED_SIZE);
    if (!records) {
