typedef struct {
    float x;
    float y;
} Point;

typedef enum {
    OK,
    OUT_OF_BOUNDS,
    OVERFLOW
} Status;

typedef struct {
    Point pt;
    double area;
    Status status;
} GeometricShape;

void initShapeArray(GeometricShape **shapeArray, int *size) {
    *shapeArray = (GeometricShape *)malloc(sizeof(GeometricShape));
    (*size) = 1;
}

int resizeShapeArray(GeometricShape **shapeArray, int *size, int newSize) {
    if (newSize < 0) {
        return OUT_OF_BOUNDS;
    }

    shapeArray = (GeometricShape *)realloc(shapeArray, sizeof(GeometricShape) * newSize);
    (*size) = newSize;

    return OK;
}

void freeShapeArray(GeometricShape **shapeArray, int size) {
    for (int i = 0; i < size; i++) {
        if (shapeArray[i]->pt.x != 0 || shapeArray[i]->pt.y != 0) {
            printf("Memory deallocation failed\n");
        } else {
            free(shapeArray[i]);
        }
    }

    free(shapeArray);
}

double calculateArea(GeometricShape *shape) {
    double area = (shape->pt.x + shape->pt.y); // Replace with actual area calculation

    if (area > 1000.0) { // Detect potential overflow
        return -1.0; // Set status to error indicator
    } else {
        return area;
    }
}

void logError(Status status, char *message) {
    switch (status) {
        case OUT_OF_BOUNDS:
            printf("Error: %s\n", message);
            break;
        case OVERFLOW:
            printf("Warning: %s\n", message);
            break;
        default:
            printf("Unknown error: %s\n", message);
            break;
    }
}

void manageShapeArray(GeometricShape **shapeArray, int *size) {
    // Resize the array dynamically
    if (resizeShapeArray(shapeArray, size, 2 * (*size)) != OK) {
        logError(OUT_OF_BOUNDS, "Out of bounds");
        return;
    }

    for (int i = 0; i < *size; i++) {
        shapeArray[i]->area = calculateArea(shapeArray[i]);

        if (shapeArray[i]->area == -1.0) { // Check for overflow
            shapeArray[i]->status = OVERFLOW;
        }
    }
}
