void* my_malloc(size_t size) {
    return malloc(size);
}

void* my_calloc(size_t num, size_t size) {
    return calloc(num, size);
}

void* my_realloc(void* ptr, size_t size) {
    return realloc(ptr, size);
}

struct node* init_linked_list(int num_nodes, int min_key, int max_key, int initial_child_size, int initial_sibling_size) {
    struct node* head = (struct node*)my_calloc(1, sizeof(struct node));
    if (!head) return NULL;
    head->key = rand() % (max_key - min_key + 1) + min_key;

    // Initialize child and sibling lists
    head->child = NULL;
    head->sibling = NULL;
    head->siblings = (struct node**)my_calloc(initial_sibling_size, sizeof(struct node*));
    for (int i = 0; i < initial_sibling_size; i++) {
        head->siblings[i] = NULL;
    }

    int child_alloc_size = initial_child_size;
    struct node** child_list = (struct node**)my_calloc(1, sizeof(struct node*) * child_alloc_size);
    child_list[0] = NULL;

    for (int i = 0; i < num_nodes - 1; i++) {
        struct node* new_node = (struct node*)my_calloc(1, sizeof(struct node));
        if (!new_node) return NULL;
        new_node->key = rand() % (max_key - min_key + 1) + min_key;

        // Resize child list if necessary
