#include <time.h>

struct record {
    int value;
    long timestamp;
    bool status;
    void* offset;
    char key[20];
};

void* allocate_records(int num_records) {
    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));
    if (!records) return NULL;

    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
        records[i].timestamp = time(NULL);
        records[i].status = true;
        records[i].offset = NULL;
        sprintf(records[i].key, "Key-%d", i + 1);
    }

    return records;
}

void release_records(void* records) {
    if (!records) return;

    free(records);
}

int main() {
    int num_records = 10;
    void* records = allocate_records(num_records);

    // use the allocated records
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: value = %d, timestamp = %ld, status = %s, key = %s\n",
            i + 1, ((struct record*)records)->value,
            ((struct record*)records)->timestamp,
            ((struct record*)records)->status ? "true" : "false", 
            ((struct record*)records)->key);
    }

    release_records(records);

    return 0;
}
