#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
    char status;
    short timestamp;
} record_t;

record_t* processDataPipeline(int argc, char** argv) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    record_t* records = NULL;
    int count = 0;
    long last_offset = 0;

    while (argc--) {
        int key;
        scanf("%d", &key);

        if (!records || records[count].offset != last_offset) {
            // Dynamic memory allocation
            int capacity = count + 100;
            record_t* temp = realloc(records, sizeof(record_t) * capacity);
            if (!temp) return NULL; // Memory allocation failed

            records = temp;

            pthread_mutex_init(&lock, NULL); // Initialize lock for each new block
        }

        records[count].key = key;
        records[count].timestamp = (short)time(NULL);
        count++;

        last_offset++;
    }

    qsort(records, count, sizeof(record_t), recordComparator);

    int max_value = 0;
    for (int i = 0; i < count; i++) {
        if (records[i].value > max_value)
            max_value = records[i].value;
    }

    return records;
}

int recordComparator(const void* a, const void* b) {
    const record_t* r1 = (const record_t*)a;
    const record_t* r2 = (const record_t*)b;

    if (r1->key < r2->key)
        return -1;
    else if (r1->key > r2->key)
        return 1;
    else
        return 0;
}

int main() {
    int argc = 10; // Sample number of records to process

    pthread_t thread;

    record_t* records = processDataPipeline(argc, NULL);

    if (!records) exit(1); // Memory allocation failed

    printf("Maximum value: %d\n", records[0].value);

    free(records);

    return 0;
}
```

