    int* keys = NULL;
    Task* tasks = NULL;
    Record* records = NULL;

    // Initialize variables
    long_offsets = (int**)malloc(sizeof(int*) * 1024);
    for (int i = 0; i < 1024; i++) {
        long_offsets[i] = (int*)malloc(sizeof(int));
    }

