    if (!long_offsets || !keys || !tasks || !records) {
        printf("Error: Memory allocation failed.\n");
        exit(1);
    }

    // Populate each record's 'int' key value with a random integer within a specified range
    for (int i = 0; i < 512; i++) {
        records[i].key = rand() % 91 + 10;
    }

    // Sort the records based on their 'int' key values in ascending order using qsort()
    qsort(records, sizeof(Record), 512);

    // Sort the 'task' structures based on priority and start time
    qsort(tasks, sizeof(Task), 1024);

    // Free allocated memory
    for (int i = 0; i < 1024; i++) {
        free(long_offsets[i]);
    }
    free(long_offsets);
    free(keys);
    for (int i = 0; i < 1024; i++) {
        free(tasks[i].name);
    }
    free(tasks);
    for (int i = 0; i < 512; i++) {
        free(records[i].key);
    }
    free(records);

}

int main() {
    pthread_t thread;
    processAndScheduleTasks();
    return 0;
