void optimizeDataPipeline() {
    // Allocate memory for arrays
    float* values = allocateMemory(sizeof(float) * 4096);
    char* statuses = allocateMemory(sizeof(char) * 4096);

    // Initialize array of Record structures with capacity 2048
    Record* records = (Record*)malloc(sizeof(Record) * 2048);
    if (!records) {
        printf("Memory allocation for records failed!\n");
        exit(1);
    }

    // Read and parse binary file
    FILE* file = fopen("data.bin", "rb");
    if (!file) {
        printf("File not found or unable to open!\n");
        exit(1);
    }

    int i;
    for (i = 0; i < 2048; i++) {
        fread(&records[i], sizeof(Record), 1, file);
    }

    fclose(file);

    // Sort records by timestamp in descending order
    qsort(records, 2048, sizeof(Record), (int(*)(const void*, const void*))cmpRecordsByTimestamp);

    // Clean up memory when exiting the function
    free(values);
    free(statuses);
    free(records);
}

// Thread-safe sorting function for Record structures
int cmpRecordsByTimestamp(const void* a, const void* b) {
    const Record* ra = (const Record*)a;
    const Record* rb = (const Record*)b;

    // Sort based on timestamp in descending order
    if (ra->timestamp > rb->timestamp) {
        return -1;
    } else if (ra->timestamp < rb->timestamp) {
        return 1;
    } else {
        return 0;
    }
}
