                log_entry->log_hash = mktime(timestamp_tm);
            }

            log_entries[i] = log_entry;
            i++;
        }
    }

    fclose(file);

    // Free memory
    for (int j = 0; j < i; j++) {
        free(log_entries[j]);
    }
    free(log_entries);
    free(messages);
    free(timestamps);
}
