        records[i].value = i;
        time_t t = time(NULL);
        records[i].timestamp = t;
        sprintf(records[i].unique_id, "%ld", t);
    }

    // Sort records
    pthread_mutex_lock(&mutex);
    qsort(records, 512, sizeof(Record), compareFunc);
    pthread_mutex_unlock(&mutex);

    // Manage shared resources and scale gracefully under increased load
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, processThread, records);
    }

    // Clean up
    free(offsets);
    free(keys);
    free(records);

    return;
}

// Helper function to compare two records
int compareFunc(const void* a, const void* b) {
    Record* r1 = (Record*)a;
    Record* r2 = (Record*)b;

    if (r1->key < r2->key) {
        return -1;
    }
    else if (r1->key > r2->key) {
        return 1;
    }
    else {
        return 0;
    }
}

// Helper function to process a thread
void* processThread(void* arg) {
    // Process the record array safely under concurrency
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < 512; i++) {
        Record r = *((Record*)arg + i);
        printf("Key: %d, Value: %d\n", r.key, r.value);
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    processAndFindMax();

    return 0;
}
