typedef struct {
    int key;
} record;

void* processAndFindMax(void* arg) {
    int* array = (int*)malloc(MAX_ARRAY_SIZE * sizeof(int));
    long* offsetArray = (long*)malloc(MAX_ARRAY_SIZE * sizeof(long));
    int* keyArray = (int*)malloc(MAX_ARRAY_SIZE * sizeof(int));

    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
    pthread_setcanceltype(PTHREAD_CANCELED, NULL);

    record* records = (record*)malloc(RECORD_COUNT * sizeof(record));

    for (int i = 0; i < RECORD_COUNT; i++) {
        record temp;
        temp.key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        records[i] = temp;
    }

    // Thread-safe sorting algorithm implementation
    qsort(records, RECORD_COUNT, sizeof(record), (int (*)(const void*, const void*))compareRecords);

    int maxKey = -1;

    for (int i = 0; i < RECORD_COUNT; i++) {
        if (records[i].key > maxKey) {
            maxKey = records[i].key;
        }
    }

    printf("Maximum value: %d\n", maxKey);

    // Cleanup mechanism
    free(array);
    free(offsetArray);
    free(keyArray);
    free(records);

    return NULL;
}

