    int array[MAX_ARRAY_SIZE];

    for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
        scanf("%d", &array[i]);
    }

    pthread_create(&thread, NULL, processAndFindMax, NULL);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}

