        // load image
        int width, height;
        // ...
        image* img = createImage(width, height);
        // optimize and cache the image
        pthread_mutex_lock(&cach->mutex);
        cach->images = realloc(cach->images, (cach->images ? (numImages + 1) : 1) * sizeof(image*));
        cach->images[numImages - i - 1] = img;
        pthread_mutex_unlock(&cach->mutex);
    }
}

int findHighestResolutionImage(cache* cach) {
    int maxRes = 0;
    image* highestResImg = NULL;
    for (int i = 0; cach->images[i] != NULL; i++) {
        if (cach->images[i]->meta->resolution > maxRes) {
            maxRes = cach->images[i]->meta->resolution;
            highestResImg = cach->images[i];
        }
    }
    return maxRes;
}

void printHighestResolutionImage(cache* cach) {
