#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <pthread.h>

// Define a structure for sensor data
typedef struct {
    time_t timestamp;
    double temperature;
    float humidity;
    double location[2];
} sensor_data;

// Function to manage and aggregate data
void* manageAndAggregateData(void* args) {
    // Initialize variables
    int sockfd = *(int*)args;
    int i, count = 0;
    time_t timestamp = time(NULL);
    double totalTemp = 0.0, totalHum = 0.0;
    double minTemp = DBL_MAX, maxTemp = DBL_MIN;
    double minHum = FLT_MAX, maxHum = FLT_MIN;
    double stdDev = 0.0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize the rolling window
    sensor_data* window[10000];
    for (i = 0; i < 10000; i++) {
        window[i] = (sensor_data*)malloc(sizeof(sensor_data));
    }

    // Read and aggregate data in a loop
    while (1) {
        char buffer[1024];
        int bytesReceived;
        sensor_data* data;

        // Receive data from the network socket
        bytesReceived = recv(sockfd, buffer, 1024, 0);
        if (bytesReceived < 0) {
            perror("recv");
            return NULL;
        }

        // Parse and store the received data
        data = (sensor_data*)malloc(sizeof(sensor_data));
        sscanf(buffer, "%llu %lf %f %lf %lf", &data->timestamp, &data->temperature, &data->humidity, &data->location[0], &data->location[1]);
        window[count++] = data;

        // Compute statistics
        pthread_mutex_lock(&lock);
        for (i = 0; i < count; i++) {
            totalTemp += window[i]->temperature;
            totalHum += window[i]->humidity;
            if (window[i]->temperature < minTemp) {
                minTemp = window[i]->temperature;
            }
            if (window[i]->temperature > maxTemp) {
                maxTemp = window[i]->temperature;
            }
            if (window[i]->humidity < minHum) {
                minHum = window[i]->humidity;
            }
            if (window[i]->humidity > maxHum) {
                maxHum = window[i]->humidity;
            }
        }

        // Compute the standard deviation
        double sumOfSquares = 0.0;
        for (i = 0; i < count; i++) {
            sumOfSquares += pow(window[i]->temperature - totalTemp / count, 2);
        }
        stdDev = sqrt(sumOfSquares / count);

        pthread_mutex_unlock(&lock);

        // Periodically print statistics
        if (count % 100 == 0) {
            printf("Statistics: avg_temp=%.2f, avg_humidity=%.2f, min_temp=%.2f, max_temp=%.2f, min_humidity=%.2f, max_humidity=%.2f, std_dev=%.2f\n", totalTemp / count, totalHum / count, minTemp, maxTemp, minHum, maxHum, stdDev);
        }
    }

    // Cleanup
    for (i = 0; i < count; i++) {
        free(window[i]);
    }
    free(args);

    return NULL;
}

// Function to extract and print the most frequent location coordinates along with their corresponding count
void extractAndPrintMostFrequentLocations(sensor_data* data, int count) {
    // Initialize a bloom filter to quickly identify unique locations
    unsigned long hashSize = 1024;
    char* bloomFilter = (char*)malloc(hashSize);
    memset(bloomFilter, 0, hashSize);

    for (int i = 0; i < count; i++) {
        unsigned long hash = murmurhash2(data[i].location[0], data[i].location[1], 0x12345678);
        if (!bloomFilter[hash % hashSize]) {
            bloomFilter[hash % hashSize] = 1;
        }
    }

    // Find the most frequent location coordinates
    int maxCount = 0, maxIndex = -1;
    for (int i = 0; i < count; i++) {
        if (!bloomFilter[murmurhash2(data[i].location[0], data[i].location[1], 0x12345678) % hashSize]) {
            int tempCount = 1;
            for (int j = i + 1; j < count; j++) {
                if (murmurhash2(data[j].location[0], data[j].location[1], 0x12345678) % hashSize == murmurhash2(data[i].location[0], data[i].location[1], 0x12345678) % hashSize) {
                    tempCount++;
                } else {
                    break;
                }
            }
            if (tempCount > maxCount) {
                maxCount = tempCount;
                maxIndex = i;
            }
        }
    }

    // Print the most frequent location coordinates
    printf("Most frequent location: %lf, %lf with count=%d\n", data[maxIndex].location[0], data[maxIndex].location[1], maxCount);

    free(bloomFilter);
}

// DNS resolution function
int resolveHostname(char* hostname) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct hostent* host = gethostbyname(hostname);
    if (!host) {
        close(sockfd);
        return -2;
    }

    u_char* ip = inet_ntoa(*((struct in_addr*)host->h_addr));
    printf("%s resolved to %s\n", hostname, ip);

    close(sockfd);
    free(host->h_aliases);
    free(host);
    return 0;
}

int main() {
    // Resolve a given hostname
    char* hostname = "example.com";
    int errorCode = resolveHostname(hostname);

    if (errorCode < 0) {
        printf("Error: %d\n", errorCode);
        return -1;
    }

    // Establish a network connection and receive data
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(8080);
    inet_pton(AF_INET, "192.168.1.100", &serverAddress.sin_addr);

    connect(sockfd, (struct sockaddr*)&serverAddress, sizeof(serverAddress));

    // Manage and aggregate data
    pthread_t thread;
    int* sockfdPtr = &sockfd;
    pthread_create(&thread, NULL, manageAndAggregateData, sockfdPtr);
    pthread_join(thread, NULL);

    return 0;
}
