        node* new_node = create_node(j);
        if (!new_node) {
            return;
        }
        current->next = new_node;
        current = new_node;
    }

    // Validate linked list integrity
    current = *head;
    while (current) {
        if (!current->next || !current->id[0]) {
            printf("Invalid node detected.\n");
            free(current);
            return;
        }
        current = current->next;
    }

    printf("Object %d initialized successfully!\n", i);
}

void print_linked_list(node* head) {
