    int size;
    int capacity;
} RecordPool;

RecordPool* createRecordPool(int initialCapacity) {
    RecordPool* pool = (RecordPool*)malloc(sizeof(RecordPool));
    pool->data = (void**)malloc(initialCapacity * sizeof(void*));
    pool->size = 0;
    pool->capacity = initialCapacity;
    return pool;
}

void freeRecordPool(RecordPool* pool) {
    if (pool != NULL) {
        for (int i = 0; i < pool->size; i++) {
