void init_measurements() {
    measurements = (measurement_t*)malloc(measurements_capacity * sizeof(measurement_t));
    if (!measurements) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(1);
    }
}

void validate_memory() {
    if (!measurements) {
        fprintf(stderr, "Error: Measurements not initialized.\n");
        exit(1);
    }
}

measurement_t* get_measurement(unsigned int idx) {
    if (idx >= measurements_size || idx >= measurements_capacity) {
        return NULL;
    }
    return &measurements[idx];
}

void update_measurements(double a, double b, double c) {
    for (unsigned int i = 0; i < measurements_size; i++) {
        measurement_t* m = get_measurement(i);
        if (!m) continue;

        m->value = a * i*i + b * i + c;
    }
}

void apply_filter(unsigned int filter_window) {
    for (unsigned int i = 0; i < measurements_size - filter_window; i++) {
        measurement_t* m = get_measurement(i);
        if (!m) continue;

        double sum = 0.0;
        for (int j = 0; j < filter_window; j++) {
            sum += m->value;
        }
        m->value = sum / filter_window;
    }
}

void cleanup() {
    free(measurements);
    measurements = NULL;
}

void* threading_safe_function(void* arg) {
    // Thread-safe code goes here
}

int main() {
    init_measurements();
    validate_memory();

    update_measurements(1.0, 2.0, 3.0);

    apply_filter(10);

    cleanup();
    return 0;
}
