#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONCURRENT_PROJECTS 100
#define MIN_PRIORITY 1
#define MAX_PRIORITY 10

typedef struct {
    int priority;
    char* status;
    project** dependencies;
    time_t start_time;
} project;

project* project_queue = NULL;
int queue_size = 0;

// Function to enqueue a new project based on priority
void enqueue_project(project* new_project) {
    // Check if the project is valid (priority within range, non-NULL status)
    if (new_project->priority >= MIN_PRIORITY && new_project->priority <= MAX_PRIORITY 
        && new_project->status != NULL) {
        // Create a new node in the priority queue
        project* node = malloc(sizeof(project));
        node->priority = new_project->priority;
        node->status = strdup(new_project->status);
        node->dependencies = new_project->dependencies;
        node->start_time = new_project->start_time;

        // If the queue is empty, set the new project as the head
        if (queue_size == 0) {
            node->next = NULL;
            project_queue = node;
        } else { 
            // Otherwise, find the correct position for the new project based on priority
            project* current = project_queue;
            while (current->next != NULL && current->next->priority < new_project->priority)
                current = current->next;

            node->next = current->next;
            current->next = node;
        }

        // Update the queue size and free any unnecessary memory
        if (node->next == NULL) {
            free(project_queue);
            project_queue = node;
        }
        queue_size++;
    } else {
        printf("Error: Invalid project!\n");
    }
}

// Function to dequeue a project based on start_time
project* dequeue_project() {
    // Check if the queue is not empty
    if (queue_size > 0) {
        project* node = project_queue;
        project_queue = node->next;
        free(node->status);
        free(node);

        // Update the queue size and return the dequeued project
        queue_size--;
        return node;
    } else {
        printf("Error: Queue is empty!\n");
        return NULL;
    }
}

// Function to log errors and exceeded conditions
void log_error(char* message) {
    FILE* log_file = fopen("project_queue_log.txt", "a+");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        printf("Error: Unable to write to log file!\n");
    }
}

// Function to gracefully shutdown and free dynamically allocated memory
void shutdown() {
    project* current = project_queue;
    while (current != NULL) {
        project* next = current->next;
        free(current->status);
        free(current->dependencies);
        free(current);
        current = next;
    }

    log_error("Project queue shut down successfully!");
}

int main() {
    // Initialize the project_queue and set concurrency limits
    int max_concurrent_projects = MAX_CONCURRENT_PROJECTS;
    project_queue = NULL;
    queue_size = 0;

    while (1) {
        // Implement your logic to enqueue new projects based on priority and dequeue projects based on start_time

        shutdown();
    }
}

