#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
    char* string;
} record_t;

record_t* create_record(int value, size_t length) {
    record_t* record = (record_t*)malloc(sizeof(record_t));
    if (!record) return NULL;

    record->value = value;
    record->string = malloc(length + 1);
    if (!record->string) {
        free(record);
        return NULL;
    }
    strcpy(record->string, "");
    return record;
}

void* allocate_array(size_t length) {
    void* array = valloc(length * sizeof(long));
    if (!array) return NULL;

    // Initialize arrays
    long* offset_values = (long*)array;
    int* keys = (int*)((char*)array + sizeof(long) * length);
    for (size_t i = 0; i < length; i++) {
        offset_values[i] = i;
        keys[i] = i % 2 ? i : -1;
    }
    return array;
}

void fill_records(record_t** records, size_t count) {
    pthread_attr_t attr;
    pthread_mutex_init(&attr, NULL);
    for (size_t i = 0; i < count; i++) {
        record_t* record = *records++;
        int value = rand() % 100;
        char* str = malloc(10 + 1);
        if (!str) break;
        sprintf(str, "%d", value);
        record->value = value;
        record->string = str;
    }
}

void free_records(record_t** records, size_t count) {
    for (size_t i = 0; i < count; i++) {
        record_t* record = *records++;
        free(record->string);
        free(record);
    }
}

record_t* push_record(record_t** head, record_t* new_node) {
    if (!(*head)) {
        *head = new_node;
        return *head;
    }

    record_t* current = *head;
    while (current->next)
        current = current->next;

    current->next = new_node;
    return *head;
}

record_t* pop_record(record_t** head) {
    if (!(*head)) return NULL;

    record_t* current = *head;
    *head = (*head)->next;
    return current;
}

void print_records(record_t* records, size_t count) {
    for (size_t i = 0; i < count; i++) {
        printf("Value: %d, String: %s\n", records[i].value, records[i].string);
    }
}

int main() {
    // Initialize arrays
    void* array = allocate_array(100);

    // Create and fill records
    record_t* records[10];
    for (size_t i = 0; i < 10; i++) {
        records[i] = create_record(i, 5);
        fill_records(records, 10);
    }

    // Construct linked list
    record_t* head = NULL;
    for (size_t i = 0; i < 10; i++)
        push_record(&head, records[i]);

    // Print and free records
    print_records(head, 10);
    record_t* current = head;
    while (current) {
        record_t* next = pop_record(&head);
        free(current->string);
        free(current);
        current = next;
    }

    return 0;
}
