// Define structure to hold measurement data
typedef struct {
    double value;
    unsigned short id;
    char label[16];
} Measurement;

// Define memory pool structure
typedef struct {
    void* buffer;
    size_t capacity;
    size_t usage;
} MemoryPool;

// Function to initialize and allocate a memory pool
MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->buffer = malloc(capacity);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }
    pool->capacity = capacity;
    pool->usage = 0;
    return pool;
}

// Function to validate memory allocation and initialization
void* validate_init(MemoryPool* pool, size_t allocation_size) {
    if (allocation_size > pool->capacity - pool->usage) {
        printf("Error: Insufficient memory for allocation.\n");
        exit(1);
    }
    return (void*)(((char*)pool->buffer) + pool->usage);
}

// Function to populate measurement structures
void populate_measurements(Measurement* measurements, size_t count, double a, double b, double c) {
    for (size_t i = 0; i < count; ++i) {
        measurements[i].value = a * pow(i, 2.0) + b * i + c;
        // Set ID and label based on some logic
        measurements[i].id = i % USHRT_MAX;
        strcpy(measurements[i].label, "Label");
    }
}

// Function to apply moving average filter
void apply_filter(Measurement* measurements, size_t count, int window_size) {
    for (size_t i = 0; i < count; ++i) {
        double sum = 0.0;
        for (int j = -window_size/2; j <= window_size/2; ++j) {
            size_t idx = (i + j) % count;
            sum += measurements[idx].value;
        }
        measurements[i].value = sum / window_size;
    }
}

// Main function to test the code
int main() {
    MemoryPool* pool = init_memory_pool(8192);
    if (!pool) return 1;

    size_t measurement_count = 1024; // configurable
    Measurement* measurements = (Measurement*)validate_init(pool, measurement_count * sizeof(Measurement));

    double a = 0.1, b = 0.3, c = 0.5; // constants from config file
    populate_measurements(measurements, measurement_count, a, b, c);

    int window_size = 11; // configurable filter window size
    apply_filter(measurements, measurement_count, window_size);

    return 0;
}
