void initArrays(int* array1, int* array2, size_t size) {
    for (size_t i = 0; i < size; i++) {
        array1[i] = i;
        array2[i] = i * 10;
    }
}

int populateRecords(Record** records, Record recordTemplate, size_t numRecords) {
    for (size_t i = 0; i < numRecords; i++) {
        (*records)[i].key = rand() % 100 + 10;
        (*records)[i].offset = (long)rand();
    }
    return 1;
}

int sortRecords(Record** records, size_t numRecords) {
    for (size_t i = 0; i < numRecords - 1; i++) {
        for (size_t j = i + 1; j < numRecords; j++) {
            if ((*records)[i].key > (*records)[j].key) {
                Record temp = (*records)[i];
                (*records)[i] = (*records)[j];
                (*records)[j] = temp;
            }
        }
    }
    return 1;
}

int main() {
    size_t arraySize = 1024;
    int* array1 = (int*)malloc(arraySize * sizeof(int));
    int* array2 = (int*)malloc(arraySize * sizeof(long));

    if (!array1 || !array2) {
        printf("Error allocating memory for arrays.\n");
        return -1;
    }

    initArrays(array1, array2, arraySize);

    size_t recordSize = 256;
    Record** records = (Record**)malloc(recordSize * sizeof(Record));
    if (!records) {
        printf("Error allocating memory for records.\n");
        free(array1);
        free(array2);
        return -1;
    }

    Record recordTemplate;
    recordTemplate.key = 0;
    recordTemplate.offset = 0;

    if (populateRecords(&records, recordTemplate, recordSize)) {
        sortRecords(&records, recordSize);

        // Clean up
        for (size_t i = 0; i < recordSize; i++) {
            free(records[i]);
        }
        free(records);
        free(array1);
        free(array2);
    } else {
        printf("Error populating or sorting records.\n");
    }

    return 0;
}

