        (*offsets)[i] = i;
        (*keys)[i] = rand() % 90 + 10;
    }

    for (int i = 0; i < 512; i++) {
        record* rec = &(*records)[i];
        rec->key = rand() % 90 + 10;
        rec->timestamp = time(NULL);
        rec->id = i;
    }

    // Sort records
    pthread_mutex_lock();
    for (int i = 0; i < 512 - 1; i++) {
        for (int j = 0; j < 512 - i - 1; j++) {
            if ((*records)[j].key > (*records)[j + 1].key) {
                record temp = (*records)[j];
                (*records)[j] = (*records)[j + 1];
                (*records)[j + 1] = temp;
            }
        }
    }
    pthread_mutex_unlock();

    return *records;
}
