            events[start:end] = sorted(events[start:end])

        threads = []
        for i in range(0, len(self.events), 32):
            threads.append(threading.Thread(target=thread_sort, args=(i, min(i+32, len(self.events)))))
            threads[-1].start()
        for thread in threads:
            thread.join()

    def populate_events(self):
