void* optimizeDataPipeline(void* arg) {
    LogEntry* log_entries = (LogEntry*)malloc(LOG_ENTRY_SIZE * ARRAY_SIZE);
    float* data_points = (float*)malloc(sizeof(float) * ARRAY_SIZE);
    char* status_flags = (char*)malloc(sizeof(char) * ARRAY_SIZE);

    if (!log_entries || !data_points || !status_flags) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < ARRAY_SIZE; i++) {
        data_points[i] = MIN_FLOAT + (rand() / (RAND_MAX / (MAX_FLOAT - MIN_FLOAT)));
        status_flags[i] = ' ';
    }

    LogEntry* filtered_log_entries = (LogEntry*)malloc(LOG_ENTRY_SIZE * (ARRAY_SIZE / 2));
    int num_filtered_entries = 0;

    for (int i = 0; i < ARRAY_SIZE; i++) {
        if (data_points[i] > THRESHOLD1 && data_points[i] < THRESHOLD2) {
            log_entries[num_filtered_entries].value = data_points[i];
            log_entries[num_filtered_entries].timestamp = time(NULL);
            log_entries[num_filtered_entries++].status = status_flags[i];
        }
    }

    qsort(filtered_log_entries, num_filtered_entries, LOG_ENTRY_SIZE, compareLogEntries);

    free(log_entries);
    free(data_points);
    free(status_flags);

    return NULL;
}

int compareLogEntries(const void* a, const void* b) {
    LogEntry* log_entry_a = (LogEntry*)a;
    LogEntry* log_entry_b = (LogEntry*)b;

    if (log_entry_a->value > log_entry_b->value)
        return -1;
    else if (log_entry_a->value < log_entry_b->value)
        return 1;
    else
        return 0;
}
