// Define a record structure with timestamp, unique id, and int value
typedef struct {
    time_t timestamp;
    unsigned long id;
    int key;
} Record;

// Function to process and find the maximum integer in an array
void* processAndFindMax(void* arg) {
    // Initialize random number generator with current time
    srand(time(NULL));

    // Define the arrays and allocate memory
    Record* records = (Record*) malloc(sizeof(Record) * 512);
    int* longOffsets = (int*) malloc(sizeof(int) * 1024);
    int* intKeys = (int*) malloc(sizeof(int) * 1024);

    // Initialize the arrays
    for (int i = 0; i < 1024; i++) {
        longOffsets[i] = rand() % 100 + 10;
        intKeys[i] = rand() % 90 + 11;
    }

    // Sort the records based on their 'int' key values
    qsort(records, 512, sizeof(Record), compare);

    // Find and print the maximum integer value
    Record maxRecord = *records;
    for (int i = 1; i < 512; i++) {
        if (records[i].key > maxRecord.key) {
            maxRecord = records[i];
        }
    }
    printf("Maximum integer: %d\n", maxRecord.key);

    // Free the allocated memory
    free(records);
    free(longOffsets);
    free(intKeys);

    return NULL;
}

// Comparison function for qsort
int compare(const void* a, const void* b) {
    Record* ra = (Record*) a;
    Record* rb = (Record*) b;
    if (ra->key < rb->key) {
        return -1;
    } else if (ra->key > rb->key) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
