const { mockReset, mockImplementation } = require('jest-mock');

function testModule(moduleName, testConfig, f) {
  const startTime = new Date().getTime();
  console.log(`Testing module: ${moduleName}`);

  try {
    const module = require(moduleName);
    const tests = testConfig[moduleName] || [];

    for (const testName in tests) {
      if (!tests.hasOwnProperty(testName)) continue;

      console.log(`Running test: ${testName}`);
      mockReset();
      const start = new Date().getTime();

      f(module, tests[testName], (err, result) => {
        if (err) {
          console.error(`Test failed: ${testName} - ${err.message}`);
        } else {
          console.log(`Test passed: ${testName} in ${new Date().getTime() - start}ms`);
        }

        mockReset();
      });

      const endTime = new Date().getTime();
      console.log(`Test completed: ${testName} in ${endTime - start}ms`);
    }
  } catch (error) {
    console.error(`Error testing module: ${moduleName} - ${error.message}`);
  }

  const endTime = new Date().getTime();
  console.log(`Module testing completed: ${moduleName} in ${endTime - startTime}ms`);

  if (fs.existsSync('test-report.json')) {
    fs.unlinkSync('test-report.json');
  }

  fs.writeFileSync('test-report.json', JSON.stringify({
    moduleName,
    tests: Object.keys(tests).reduce((acc, testName) => ({
      ...acc,
      [testName]: f(module, tests[testName], (err, result) => (err ? 'failed' : 'passed')),
    }), {}),
  }));

  console.log('Test report saved to test-report.json');
}
