void* processAndFindMax(void* arg) {
    int i, j;
    record* records;
    int* keys;
    long* offsets;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Allocate and initialize arrays
    records = (record*)malloc(sizeof(record)*512);
    keys = (int*)malloc(sizeof(int)*1024);
    offsets = (long*)malloc(sizeof(long)*1024);

    for(i=0; i<512; i++) {
        records[i].key = rand() % 90 + 10;
        records[i].timestamp = time(NULL) % (1L<<31);
        records[i].id = i;
    }

    // Sort the records
    pthread_mutex_lock(&lock);
    for(i=0; i<512-1; i++) {
        for(j=i+1; j>0 && records[j-1].key > records[j].key; j--) {
            record temp = records[j];
            int keyTemp = keys[j];
            long offsetTemp = offsets[j];
            records[j] = records[j-1];
            keys[j] = keyTemp;
            offsets[j] = offsetTemp;
        }
    }
    pthread_mutex_unlock(&lock);

    // Perform other tasks here...

    // Clean up
    free(records);
    free(keys);
    free(offsets);

    return NULL;
}

