const { DataStreamManager } = require('./data-stream-manager');
const { MonitoringToolClient } = require('./monitoring-tool-client');
const { OperationalDashboard } = require('./operational-dashboard');

class RealTimeDataProcessor {
  constructor(dataProviderApi, monitoringToolUrl) {
    this.dataStreamManager = new DataStreamManager();
    this.monitoringToolClient = new MonitoringToolClient(monitoringToolUrl);
    this.operationalDashboard = new OperationalDashboard();

    this.dataIngestionService = () => {
      setInterval(() => {
        const startDelayMs = Math.floor(Math.random() * 10000); // Random delay between 0 and 10 seconds
        setTimeout(() => {
          this.startDataIngestion();
        }, startDelayMs);
      }, 30000); // Start data ingestion service every 30 seconds

      setInterval(() => {
        const stopDelayMs = Math.floor(Math.random() * 10000); // Random delay between 0 and 10 seconds
        setTimeout(() => {
          this.stopDataIngestion();
        }, stopDelayMs);
      }, 60000); // Stop data ingestion service every 1 minute
    };

    this.dataStreamManager.on('data', (data) => {
      if (!this.isPaused()) {
        this.processData(data);
      }
    });

    this.dataStreamManager.on('error', (err) => {
      console.error('Error processing data:', err);
      this.operationalDashboard.updateStatus('ERROR');
    });

    this.monitoringToolClient.on('connected', () => {
      this.operationalDashboard.updateStatus('CONNECTED');
    });

    this.monitoringToolClient.on('disconnected', () => {
      this.operationalDashboard.updateStatus('DISCONNECTED');
    });
  }

  startDataIngestion() {
    this.dataStreamManager.start();
  }

  stopDataIngestion() {
    this.dataStreamManager.stop();
    this.notifyMonitoringTool();
  }

  isPaused() {
    return this.dataStreamManager.isPaused();
  }

  pauseDataIngestion() {
    this.dataStreamManager.pause();
  }

  resumeDataIngestion() {
    this.dataStreamManager.resume();
  }

  processData(data) {
    // Process the data here
  }
}

// Example usage:
const realTimeDataProcessor = new RealTimeDataProcessor('https://api.example.com/data', 'https://monitoring-tool.example.com/api');
realTimeDataProcessor.dataIngestionService();
