import time
from typing import Dict, List
from datetime import datetime

class QuotaManager:
    def __init__(self):
        self.quota_limits: Dict[str, int] = {}
        self.timestamp_storage: Dict[str, int] = {}

    def set_quota_limit(self, resource_name: str, limit: int) -> None:
        self.quota_limits[resource_name] = limit

    def get_quota_limit(self, resource_name: str) -> int:
        return self.quota_limits.get(resource_name)

    def update_timestamp(self, resource_name: str, timestamp: int) -> None:
        self.timestamp_storage[resource_name] = timestamp

    def check_quota(self, resource_name: str) -> bool:
        if self.get_quota_limit(resource_name):
            current_timestamp = int(datetime.utcnow().timestamp())
            time_diff = current_timestamp - self.update_timestamp(resource_name)
            return time_diff < self.get_quota_limit(resource_name)
        return True

class ConnectionManager:
    def __init__(self):
        self.connections: Dict[str, List] = {}

    def create_connection(self) -> None:
        if 'connections' not in self.__dict__:
            self.connections['connections'] = []

    def add_connection(self, connection_id: str) -> None:
        if 'connections' in self.__dict__:
            self.connections['connections'].append(connection_id)

    def close_connections(self) -> None:
        for connection_id in self.connections['connections']:
            # close the connection
            pass

class RequestProcessor:
    def __init__(self, quota_manager: QuotaManager, connection_manager: ConnectionManager):
        self.quota_manager = quota_manager
        self.connection_manager = connection_manager

    def process_request(self, resource_name: str) -> None:
        if not self.quota_manager.check_quota(resource_name):
            print(f"Quota exceeded for {resource_name}")
            return

        try:
            # process the request
            pass
        except Exception as e:
            print(f"Error processing request: {str(e)}")
            self.connection_manager.close_connections()

    def start_processing(self) -> None:
        while True:
            resource_name = input("Enter resource name (or 'quit' to stop): ")
            if resource_name.lower() == 'quit':
                break
            self.process_request(resource_name)
