} record_t;

void* allocateArrays(size_t size) {
    void** arr = (void**)malloc(size * sizeof(void*));
    if (!arr) {
        fprintf(stderr, "Error: Allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return arr;
}

int validateArrays(record_t** records, int* keys, long* offsets, int size) {
    for (int i = 0; i < size; i++) {
        if (!records[i] || !keys[i] || !offsets[i]) {
            fprintf(stderr, "Error: Invalid pointer.\n");
            return -1;
        }
    }
    return 0;
}

void setRecordValues(record_t** records, int size) {
    for (int i = 0; i < size; i++) {
        records[i]->key = rand() % 90 + 10;
    }
}

void* sortRecords(void* arg) {
    record_t** records = (record_t**)arg;
    int n = strlen(*records);
    int i, j;
    for (i = 0; i < n - 1; i++) {
        for (j = i + 1; j < n; j++) {
            if ((*records[i])->key > (*records[j])->key) {
                record_t* temp = *records[i];
                *records[i] = *records[j];
                *records[j] = temp;
            }
        }
    }
}

int main() {
    size_t arraySize = 1024;
    int recordSize = 512;
    srand(time(NULL) ^ (unsigned) getpid());
    pthread_t threads[2];

    long* offsets = (long*)allocateArrays(arraySize);
    int* keys = (int*)malloc(arraySize * sizeof(int));
    record_t** records = (record_t**)malloc(recordSize * sizeof(record_t*));

    // Load data from file
    FILE* fptr;
    fptr = fopen("data.bin", "rb");
    if (!fptr) {
        fprintf(stderr, "Error: File not found.\n");
        exit(EXIT_FAILURE);
    }

    int count;
    fread(&count, sizeof(int), 1, fptr);
    for (int i = 0; i < count; i++) {
        long offset;
        int key;
        fread(&offset, sizeof(long), 1, fptr);
        fread(&key, sizeof(int), 1, fptr);

        // Validate memory allocation and initialization
        if (!validateArrays(records, keys, offsets, arraySize)) {
            for (int j = 0; j < arraySize; j++) {
                if (offsets[j] > offset) {
                    printf("Error: Offset mismatch at index %d.\n", j);
                    return -1;
                }
            }
        }

        // Set the value of each record's int field
        setRecordValues(records, recordSize);

        // Sort the records based on their 'int' key values in ascending order
        pthread_create(&threads[0], NULL, sortRecords, (void*)records);
        pthread_join(threads[0], NULL);

        fclose(fptr);

    return 0;
}
