#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Custom memory pool structure
typedef struct {
    void** blocks;
    size_t num_blocks;
    size_t block_size;
} MemoryPool;

// Record structure for sensor data
typedef struct {
    int sensor_id;
    double reading;
    long timestamp;
} Record;

// Function to initialize the memory pool
MemoryPool* init_memory_pool(size_t block_size, size_t initial_num_blocks) {
    // Initialize the memory pool
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->blocks = (void**)calloc(initial_num_blocks, sizeof(void*));
    pool->num_blocks = initial_num_blocks;
    pool->block_size = block_size;
    return pool;
}

// Function to allocate memory from the pool
void* alloc_memory_from_pool(MemoryPool* pool) {
    // Find a free block in the pool
    for (size_t i = 0; i < pool->num_blocks; i++) {
        if (!pool->blocks[i]) {
            // Allocate memory from the block
            void* ptr = malloc(pool->block_size);
            pool->blocks[i] = ptr;
            return ptr;
        }
    }

    // If no free blocks are found, allocate a new block
    size_t new_num_blocks = pool->num_blocks + 1;
    void** new_blocks = (void**)realloc(pool->blocks, new_num_blocks * sizeof(void*));
    pool->blocks = new_blocks;
    for (size_t i = pool->num_blocks; i < new_num_blocks; i++) {
        pool->blocks[i] = malloc(pool->block_size);
    }
    pool->num_blocks = new_num_blocks;

    // Return the memory from the newly allocated block
    return pool->blocks[pool->num_blocks - 1];
}

// Function to deallocate memory back to the pool
void dealloc_memory_from_pool(MemoryPool* pool, void* ptr) {
    size_t i;
    for (i = 0; i < pool->num_blocks; i++) {
        if (pool->blocks[i] == ptr) {
            free(ptr);
            pool->blocks[i] = NULL;
            return;
        }
    }
}

// Function to initialize the sensor data processing pipeline
void* sensorDataProcessingPipeline(void*) {
    // Initialize the memory pool
    MemoryPool* pool = init_memory_pool(sizeof(Record), 512);

    // Allocate arrays for timestamps, sensor IDs, and records
    long* timestamps = (long*)alloc_memory_from_pool(pool);
    int* sensor_ids = (int*)alloc_memory_from_pool(pool);
    Record* records = (Record*)alloc_memory_from_pool(pool);

    // Initialize the arrays with unique sensor ID values
    for (size_t i = 0; i < 512; i++) {
        sensor_ids[i] = i;
    }

    // Validate memory allocation and initialization
    if (!timestamps || !sensor_ids || !records) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the record array with unique sensor ID values
    for (size_t i = 0; i < 512; i++) {
        records[i].sensor_id = sensor_ids[i];
        records[i].reading = 0.0;
