void* allocate_arrays(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record** records = (record**)malloc(size * sizeof(record*));

    if (!offsets || !keys || !records)
        return NULL;

    // Initialize the keys array with sequential integers
    for (int i = 0; i < size; ++i) {
        keys[i] = i;
    }

    return records;
}

void initialize_records(int size, record** records) {
    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        record* r = records[i];
        int value = rand() % 100;
        long offset = offsets[rand() % size];
        r->value = value;
        r->offset = &offsets[i];
    }
}

void validate_records(int size, record** records) {
    for (int i = 0; i < size; ++i) {
        record* r = records[i];
        long offset = *r->offset;
        for (int j = 0; j < size; ++j) {
            if (i != j && offset == *(records[j]->offset)) {
                printf("Error: Duplicate offset found at index %d\n", i);
                return;
            }
        }
    }
}

void free_arrays(void* data) {
    record** records = (record**)data;

    for (int i = 0; i < size; ++i) {
        if (records[i]) {
            free(records[i]->offset);
            free(records[i]);
        }
    }

    free(records);
    free(offsets);
    free(keys);
}
