    if (!points) {
        printf("Memory allocation failed.\n");
        return -2;
    }

    for (int i = 0; i < num_points; i++) {
        points[i].x = (float)i / (num_points - 1); // Calculate x-coordinate using mathematical formula
        points[i].y = sin(i) * 10.0f; // Calculate y-coordinate using mathematical formula and sine function
    }

    // Periodically re-evaluate and adjust the size of the allocated memory block if the number of points changes significantly during execution
    while (true) {
        printf("Enter new number of points: ");
