void processAndIntegrateLogs(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    // Initialize arrays for timestamps and messages
    time_t *timestamps = malloc(10000000 * sizeof(time_t));
    char **messages = malloc(5000000 * sizeof(char *));
    log_entry *log_entries = malloc(5000000 * sizeof(log_entry));

    if (timestamps == NULL || messages == NULL || log_entries == NULL) {
        printf("Memory allocation failed\n");
        fclose(file);
        return;
    }

    int i = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Parse the log entry
        char *token = strtok(line, ";");
        if (token == NULL) continue;

        time_t timestamp = strtotime(token);
        token = strtok(NULL, ";");
        int log_level = atoi(token);

        token = strtok(NULL, ";");
        strcpy(log_entries[i].source_ip, token);

        token = strtok(NULL, ";");
        strcpy(log_entries[i].destination_ip, token);

        token = strtok(NULL, ";");
        strcpy(log_entries[i].protocol, token);

        token = strtok(NULL, ";");
        strcpy(log_entries[i++], token);

        // Normalize the timestamp
        log_entries[i-1].timestamp = normalizeTimestamp(timestamp);
    }

    fclose(file);

    // Filter out invalid log entries
    for (int j = 0; j < i; j++) {
        if (!validateLogEntry(&log_entries[j])) {
            free(log_entries[j].message);
            memmove(&log_entries[j], &log_entries[j+1], sizeof(log_entry) * (i-j-1));
            i--;
