// Custom memory pool allocator structure
typedef struct {
    void** pools;
    int size;
} MemoryPool;

// Initialize the custom memory pool
MemoryPool* init_memory_pool(int num_pools) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pools = (void**)malloc(num_pools * sizeof(void*));
    mp->size = num_pools;
    return mp;
}

// Allocate memory from the custom pool
void* alloc_memory_pool(MemoryPool* mp, size_t size) {
    void** pools = mp->pools;
    int pool_idx = 0;

    // Find an available memory pool or create a new one if necessary
    while (pool_idx < mp->size && !pools[pool_idx]) {
        pool_idx++;
    }

    if (pool_idx == mp->size) {
        // Create a new memory pool and update the size
        pools = realloc(pools, (mp->size *= 2) * sizeof(void*));
        mp->pools = pools;
    }

    void* result = malloc(size);
    pools[pool_idx] = result;  // Mark the allocated memory as used in this pool

    return result;
}

// Custom buffer management strategy
void* alloc_buffer(MemoryPool* mp, size_t size) {
    void** buffers = (void**)malloc(mp->size * sizeof(void*));

    int idx = 0;
    while (idx < mp->size && !buffers[idx]) {
        idx++;
    }

    if (idx == mp->size) {
        // Create a new buffer and update the size
        buffers = realloc(buffers, (mp->size *= 2) * sizeof(void*));
    }

    void* result = malloc(size);
    buffers[0] = result;  // Mark the allocated memory as used in this buffer

    return result;
}

