                    break;
                default:
                    // log hash and origin thread
                    // ...
            }
        }
    }

    fclose(file);

    // Normalize timestamps
    for (int i = 0; i < 10000000; i++) {
        timestamp_t* timestamp = &timestamps[i];
        normalize_timestamp(timestamp);
    }

    // Filter out invalid log entries
    int j = 0;
    for (i = 0; i < 2000000; i++) {
        log_entry* log = &logs[i];
        if (!is_valid_log(log)) {
            continue;
        }
        logs[j++] = log;
    }

    // Store filtered-out entries for audit
    store_invalid_entries();

    free(timestamps);
    free(messages);
    free(logs);

    printf("Processed %d log entries.\n", j);
}

int main(int argc, char* argv[]) {
